// ============================================================
// MEMORY
// ============================================================

bool IsReadableProtection(
    DWORD protect)
{
    if (protect & PAGE_GUARD)
        return false;

    if (protect & PAGE_NOACCESS)
        return false;

    switch (protect & 0xFF)
    {
        case PAGE_READONLY:
        case PAGE_READWRITE:
        case PAGE_WRITECOPY:
        case PAGE_EXECUTE_READ:
        case PAGE_EXECUTE_READWRITE:
        case PAGE_EXECUTE_WRITECOPY:
            return true;
    }

    return false;
}

template<typename T>
bool SafeRead(
    uintptr_t address,
    T& out)
{
    if (!address)
        return false;

    MEMORY_BASIC_INFORMATION mbi{};

    if (!VirtualQuery(
            reinterpret_cast<void*>(address),
            &mbi,
            sizeof(mbi)))
    {
        return false;
    }

    if (mbi.State != MEM_COMMIT ||
        !IsReadableProtection(mbi.Protect))
    {
        return false;
    }

    uintptr_t begin =
        reinterpret_cast<uintptr_t>(
            mbi.BaseAddress
        );

    uintptr_t end =
        begin +
        mbi.RegionSize;

    if (address < begin ||
        address + sizeof(T) > end)
    {
        return false;
    }

    std::memcpy(
        &out,
        reinterpret_cast<const void*>(
            address
        ),
        sizeof(T)
    );

    return true;
}

uintptr_t ReadPtr(
    uintptr_t address)
{
    uintptr_t value = 0;
    SafeRead(address, value);
    return value;
}

uint32_t ReadU32(
    uintptr_t address)
{
    uint32_t value = 0;
    SafeRead(address, value);
    return value;
}

uint8_t ReadU8(
    uintptr_t address)
{
    uint8_t value = 0;
    SafeRead(address, value);
    return value;
}

// ============================================================
// HELPERS
// ============================================================

std::string HexU64(
    uint64_t value)
{
    std::ostringstream ss;

    ss
        << "0x"
        << std::uppercase
        << std::hex
        << value;

    return ss.str();
}

std::string HexPtr(
    uintptr_t value)
{
    return
        HexU64(
            static_cast<uint64_t>(
                value
            )
        );
}

uintptr_t AbsDistance(
    uintptr_t a,
    uintptr_t b)
{
    return
        a > b
            ? a - b
            : b - a;
}

bool InsideExeImage(
    uintptr_t address)
{
    return
        address >= g_exeBase &&
        address < g_imageEnd;
}

bool SameNumber(
    double a,
    double b)
{
    if (!std::isfinite(a) ||
        !std::isfinite(b))
    {
        return false;
    }

    double scale =
        std::max(
            1.0,
            std::max(
                std::fabs(a),
                std::fabs(b)
            )
        );

    return
        std::fabs(a - b) <=
        scale * 1e-10;
}

const char* StateName(
    FieldState state)
{
    switch (state)
    {
        case FieldState::Unknown:
            return "unknown";

        case FieldState::Unresolved:
            return "unresolved";

        case FieldState::Ambiguous:
            return "ambiguous";

        case FieldState::Collision:
            return "collision";

        case FieldState::StrongCandidate:
            return "strong_candidate";

        case FieldState::Confirmed:
            return "confirmed";

        case FieldState::Skipped:
            return "skipped";
    }

    return "unknown";
}

