// ============================================================
// DISCOVER LOCALPLAYER
// ============================================================

bool DiscoverLocalPlayer(
    const BulkInput& in,
    Candidate& bestCandidate,
    BaseHypothesis& bestBase)
{
    bestCandidate = {};
    bestBase = {};
    const char* stageNames[] = {"Health/MaxHealth", "Mana/MaxMana", "Experience"};
    int bestTotal = std::numeric_limits<int>::min();
    const bool resolved = otclab::player_seed::resolve([&](unsigned stage) {
        auto candidates = stage == 0 ? SeedPair("Health", in.health, "MaxHealth", in.maxHealth)
                        : stage == 1 ? SeedPair("Mana", in.mana, "MaxMana", in.maxMana)
                                     : SeedSingle("Experience", in.experience);
        if (candidates.empty()) {
            std::cout << "[PLAYER] " << stageNames[stage] << ": nenhum seed. Tentando proxima fonte.\n";
            return false;
        }
        std::cout << "\n[BULK] Conferindo " << stageNames[stage]
                  << " e adicionando os outros valores...\n";
        const auto inspect = std::min<std::size_t>(candidates.size(), 4096);
        otclab::player_seed::Selection selection;
        std::size_t noBase = 0;
        BaseHypothesis selectedBase{};
        for (std::size_t i = 0; i < inspect; ++i) {
            AttachBulkEvidence(candidates[i], in);
            const auto base = InferLocalPlayerBase(candidates[i]);
            if (!base.base) ++noBase;
            if (i < 8) {
                std::cout << "[PLAYER] candidato #" << i
                          << " anchor=" << HexPtr(candidates[i].anchor)
                          << " stats=" << candidates[i].evidence.size()
                          << " base=" << (base.base ? HexPtr(base.base) : "NAO ENCONTRADA") << "\n";
            }
            if (selection.consider(i, CandidateTotalScore(candidates[i], base), base.base))
                selectedBase = base;
        }
        std::cout << "[PLAYER] " << stageNames[stage] << ": " << inspect
                  << " candidatos; " << noBase << " sem base estrutural.\n";
        if (!selection.found) {
            std::cout << "[PLAYER] Seeds numericos nao confirmaram LocalPlayer. Tentando proxima fonte.\n";
            return false;
        }
        bestCandidate = std::move(candidates[selection.index]);
        bestBase = selectedBase;
        bestTotal = selection.score;
        return true;
    });
    if (!resolved) {
        std::cout << "[PLAYER] HP, Mana e XP esgotados sem base valida.\n"
                  << "[PLAYER] Estes seeds procuram doubles; outro armazenamento/layout continua pendente.\n";
        return false;
    }

    std::cout
        << "\n============================================================\n"
        << "                  BEST LOCALPLAYER GUESS\n"
        << "============================================================\n"
        << "Runtime Base    : "
        << HexPtr(
            bestBase.base
        )
        << "\n"
        << "VTable          : "
        << HexPtr(
            bestBase.vtable
        )
        << "\n"
        << "VTable RVA      : ";

    if (InsideExeImage(
            bestBase.vtable))
    {
        std::cout
            << HexU64(
                bestBase.vtable -
                g_exeBase
            );
    }
    else
    {
        std::cout
            << "<outside exe>";
    }

    std::cout
        << "\n"
        << "Base score      : "
        << bestBase.score
        << "\n"
        << "Total score     : "
        << bestTotal
        << "\n"
        << "Evidence fields : "
        << bestCandidate.evidence.size()
        << "\n"
        << "Position        : "
        << bestBase.x
        << ","
        << bestBase.y
        << ","
        << static_cast<unsigned>(
            bestBase.z
        )
        << "\n"
        << "ID              : "
        << bestBase.id
        << "\n"
        << "HP%             : "
        << static_cast<unsigned>(
            bestBase.hpPercent
        )
        << "\n"
        << "Direction       : "
        << bestBase.direction
        << "\n";

    return true;
}

// ============================================================
// LOCAL BULK RESOLUTION
// ============================================================

ProfileFields ResolveBulkLocally(
    uintptr_t base,
    const BulkInput& in)
{
    ProfileFields fields{};

    auto cells =
        CaptureLocalDoubles(
            base
        );

    std::cout
        << "\n[LOCAL] "
        << cells.size()
        << " doubles capturados entre +"
        << HexU64(
            LOCAL_SCAN_BEGIN
        )
        << " e +"
        << HexU64(
            LOCAL_SCAN_END
        )
        << "\n";

    PairResult hp =
        ResolveStaticPair(
            "Health",
            "MaxHealth",
            base,
            cells,
            in.health,
            in.maxHealth,
            REF_OFF_HEALTH,
            REF_OFF_MAX_HEALTH
        );

    fields.health =
        hp.current;

    fields.maxHealth =
        hp.maximum;

    PairResult mana =
        ResolveStaticPair(
            "Mana",
            "MaxMana",
            base,
            cells,
            in.mana,
            in.maxMana,
            REF_OFF_MANA,
            REF_OFF_MAX_MANA
        );

    fields.mana =
        mana.current;

    fields.maxMana =
        mana.maximum;

    fields.experience =
        ResolveStaticSingle(
            "Experience",
            base,
            cells,
            in.experience,
            REF_OFF_EXPERIENCE
        );

    fields.level =
        ResolveStaticSingle(
            "Level",
            base,
            cells,
            in.level,
            REF_OFF_LEVEL
        );

    fields.capacity =
        ResolveStaticSingle(
            "Capacity",
            base,
            cells,
            in.capacity,
            REF_OFF_CAPACITY
        );

    return fields;
}

// ============================================================
// RETRY PENDING ONLY
// ============================================================

void RetryPendingFields(
    uintptr_t base,
    ProfileFields& fields)
{
    PrintFields(
        fields
    );

    // --------------------------------------------------------
    // Health pair
    // --------------------------------------------------------

    if (fields.health.pending() ||
        fields.maxHealth.pending())
    {
        std::cout
            << "\n[PENDING] Health/MaxHealth precisam de validacao.\n";

        if (AskYesNo(
                "Consegue alterar a vida atual agora? [S/N]: "))
        {
            PairResult retry =
                RetryPairDynamic(
                    "Health",
                    "MaxHealth",
                    base,
                    REF_OFF_HEALTH,
                    REF_OFF_MAX_HEALTH
                );

            if (retry.current.valid() ||
                !retry.current.pending())
            {
                fields.health =
                    retry.current;
            }

            if (retry.maximum.valid() ||
                !retry.maximum.pending())
            {
                fields.maxHealth =
                    retry.maximum;
            }
        }
        else
        {
            if (fields.health.pending())
                fields.health.state =
                    FieldState::Skipped;

            if (fields.maxHealth.pending())
                fields.maxHealth.state =
                    FieldState::Skipped;
        }
    }

    // --------------------------------------------------------
    // Mana pair
    // --------------------------------------------------------

    if (fields.mana.pending() ||
        fields.maxMana.pending())
    {
        std::cout
            << "\n[PENDING] Mana/MaxMana precisam de validacao.\n";

        if (AskYesNo(
                "Consegue gastar ou regenerar mana agora? [S/N]: "))
        {
            PairResult retry =
                RetryPairDynamic(
                    "Mana",
                    "MaxMana",
                    base,
                    REF_OFF_MANA,
                    REF_OFF_MAX_MANA
                );

            if (retry.current.valid() ||
                !retry.current.pending())
            {
                fields.mana =
                    retry.current;
            }

            if (retry.maximum.valid() ||
                !retry.maximum.pending())
            {
                fields.maxMana =
                    retry.maximum;
            }
        }
        else
        {
            if (fields.mana.pending())
                fields.mana.state =
                    FieldState::Skipped;

            if (fields.maxMana.pending())
                fields.maxMana.state =
                    FieldState::Skipped;
        }
    }

    // --------------------------------------------------------
    // XP
    // --------------------------------------------------------

    if (fields.experience.pending())
    {
        std::cout
            << "\n[PENDING] Experience nao foi localizada com seguranca.\n";

        if (AskYesNo(
                "Consegue ganhar XP agora? [S/N]: "))
        {
            fields.experience =
                RetrySingleDynamic(
                    "Experience",
                    base,
                    REF_OFF_EXPERIENCE,
                    "Ganhe alguma experiencia sem relogar."
                );
        }
        else
        {
            fields.experience.state =
                FieldState::Skipped;
        }
    }

    // --------------------------------------------------------
    // Level
    // --------------------------------------------------------

    if (fields.level.pending())
    {
        std::cout
            << "\n[PENDING] Level nao foi localizado com seguranca.\n";

        if (AskYesNo(
                "Consegue alterar o Level agora? [S/N]: "))
        {
            fields.level =
                RetrySingleDynamic(
                    "Level",
                    base,
                    REF_OFF_LEVEL,
                    "Altere o level mantendo o mesmo personagem."
                );
        }
        else
        {
            fields.level.state =
                FieldState::Skipped;
        }
    }

    // --------------------------------------------------------
    // Capacity
    // --------------------------------------------------------

    if (fields.capacity.pending())
    {
        std::cout
            << "\n[PENDING] Capacity nao foi localizada com seguranca.\n";

        if (AskYesNo(
                "Consegue alterar Capacity agora? [S/N]: "))
        {
            fields.capacity =
                RetrySingleDynamic(
                    "Capacity",
                    base,
                    REF_OFF_CAPACITY,
                    "Pegue/largue peso ou mova itens para alterar Capacity."
                );
        }
        else
        {
            fields.capacity.state =
                FieldState::Skipped;
        }
    }
}


