    READ_DB_FIELD(containerMapSizeOffset);
    READ_DB_FIELD(containerNodeLeftOffset);
    READ_DB_FIELD(containerNodeRightOffset);
    READ_DB_FIELD(containerNodeNilOffset);
    READ_DB_FIELD(containerNodeKeyOffset);
    READ_DB_FIELD(containerNodeValueOffset);
    READ_DB_FIELD(containerIdOffset);
    READ_DB_FIELD(containerCapacityOffset);
    READ_DB_FIELD(containerItemOffset);
    READ_DB_FIELD(containerNameOffset);
    READ_DB_FIELD(containerHasParentOffset);
