bool EnsureProfileDatabase(
    const std::string& path)
{
    std::ifstream existing(
        path,
        std::ios::binary
    );

    if (existing.good())
        return true;

    existing.close();

    std::vector<DbProfile> empty;

    return
        SaveProfileDatabase(
            path,
            empty
        );
}

int FindProfileIndex(
    const BuildInfo& build,
    const std::vector<DbProfile>& profiles)
{
    for (size_t i = 0;
         i < profiles.size();
         ++i)
    {
        const auto& p =
            profiles[i];

        if (p.timestamp !=
            build.timestamp)
        {
            continue;
        }

        if (p.sizeOfImage !=
            build.sizeOfImage)
        {
            continue;
        }

        if (p.textHash !=
            build.textHash)
        {
            continue;
        }

        return
            static_cast<int>(
                i
            );
    }

    return -1;
}

bool DbProfileMonitorReady(
    const DbProfile& p)
{
    bool hasPath =
        p.directGlobalRva != 0 ||
        (
            p.indirectGlobalRva != 0 &&
            p.ownerOffset != 0
        );

    return
        p.vtableRva != 0 &&
        hasPath &&
        p.x != 0 &&
        p.y != 0 &&
        p.z != 0;
}

uintptr_t OffsetOrZero(
    const FieldResult& field)
{
    return
        field.address
            ? field.offset
            : 0;
}

uintptr_t UIntOffsetOrZero(
    const UIntFieldResult& field)
{
    return
        field.address
            ? field.offset
            : 0;
}

DbProfile BuildDatabaseProfile(
    const BuildInfo& build,
    const BaseHypothesis& base,
    const ProfileFields& fields,
    const PositionCalibration& position,
    const PointerDiscovery& pointers)
{
    DbProfile p{};

    std::ostringstream name;

    name
        << "auto_"
        << std::hex
        << std::uppercase
        << build.timestamp
        << "_"
        << build.textHash;

    p.name =
        name.str();

    p.status =
        "player_discovered_runtime";

    p.gameStatus =
        "unknown";

    p.followStatus =
        "unknown";

    p.mapStatus =
        "unknown";

    p.tileRttiName =
        "unknown";

    p.thingStorageMode =
        "unknown";

    p.tileThingsStatus =
        "unknown";

    p.mapTileStorageMode =
        "unknown";

    p.mapTilePathStatus =
        "unknown";

    p.monsterVtableStatus =
        "unknown";

    p.itemVtableStatus =
        "unknown";

    p.playerVtableStatus =
        "unknown";

    p.classificationStatus =
        "unknown";

    p.npcStatus =
        "unknown";

    p.inventoryStorageMode =
        "unknown";

    p.inventoryStatus =
        "unknown";

    p.itemLayoutStatus =
        "unknown";

    p.containerItemStorageMode =
        "unknown";

    p.containersStatus =
        "unknown";

    p.functionsStatus =
        "unknown";

    p.timestamp =
        build.timestamp;

    p.sizeOfImage =
        build.sizeOfImage;

    p.textHash =
        build.textHash;

    if (InsideExeImage(
            base.vtable))
    {
        p.vtableRva =
            base.vtable -
            g_exeBase;
    }

    if (!pointers.direct.empty())
    {
        const PointerPathCandidate* bestDirect =
            &pointers.direct[0];

        for (const auto& c :
             pointers.direct)
        {
            if (c.status ==
                "strong_candidate")
            {
                bestDirect =
                    &c;

                break;
            }
        }

        p.directGlobalRva =
            bestDirect->globalRva;
    }

    if (!pointers.indirect.empty())
    {
        const auto& c =
            pointers.indirect[0];

        p.indirectGlobalRva =
            c.globalRva;

        p.ownerOffset =
            c.ownerOffset;
    }

    p.x =
        UIntOffsetOrZero(
            position.x
        );

    p.y =
        UIntOffsetOrZero(
            position.y
        );

    p.z =
        UIntOffsetOrZero(
            position.z
        );

    p.direction =
        UIntOffsetOrZero(
            position.direction
        );

    // Structural offsets were validated by the LocalPlayer shape.
    p.id =
        REF_OFF_ID;

    p.hpPercent =
        REF_OFF_HP_PERCENT;

    p.health =
        OffsetOrZero(
            fields.health
        );

    p.maxHealth =
        OffsetOrZero(
            fields.maxHealth
        );

    p.capacity =
        OffsetOrZero(
            fields.capacity
        );

    p.experience =
        OffsetOrZero(
            fields.experience
        );

    p.level =
        OffsetOrZero(
            fields.level
        );

    p.mana =
        OffsetOrZero(
            fields.mana
        );

    p.maxMana =
        OffsetOrZero(
            fields.maxMana
        );

    return p;
}

