// ============================================================
// FORWARD DECLARATIONS USED BY GAME DISCOVERY
// Implementations remain in the runtime-monitor section below.
// ============================================================

bool IsReadableMonitorRange(
    uintptr_t address,
    size_t size);

bool ValidateMonitorLocalPlayer(
    uintptr_t localPlayer,
    const DbProfile& p,
    MonitorSample* out);


// ============================================================
// DISCOVERY V2 - GAME / ATTACK TARGET
// ============================================================

struct GameLpReference
{
    uintptr_t address = 0;
    uintptr_t rva = 0;
    std::string section;
    bool writable = false;
};

struct GameAttackCandidate
{
    uintptr_t localPlayerField = 0;
    uintptr_t gameRva = 0;
    uintptr_t attackOffset = 0;
    uintptr_t targetPointer = 0;

    std::string section;

    int score = 0;

    uint32_t targetX = 0;
    uint32_t targetY = 0;
    uint8_t targetZ = 0;
    uint32_t targetId = 0;
    uint8_t targetHp = 0;
};

bool ValidateDiscoveredCreature(
    uintptr_t creature,
    const DbProfile& p,
    GameAttackCandidate* details = nullptr)
{
    if (!creature)
        return false;

    if (!IsReadableMonitorRange(
            creature,
            0x100))
    {
        return false;
    }

    uintptr_t vtable =
        ReadPtr(
            creature
        );

    if (!InsideExeImage(
            vtable))
    {
        return false;
    }

    uint32_t x =
        ReadU32(
            creature +
            p.x
        );

    uint32_t y =
        ReadU32(
            creature +
            p.y
        );

    uint8_t z =
        ReadU8(
            creature +
            p.z
        );

    if (!PositionPlausible(
            x,
            y,
            z))
    {
        return false;
    }

    uint32_t id = 0;

    if (p.id)
    {
        id =
            ReadU32(
                creature +
                p.id
            );

        if (!id ||
            id == 0xFFFFFFFFu)
        {
            return false;
        }
    }

    uint8_t hp = 0;

    if (p.hpPercent)
    {
        hp =
            ReadU8(
                creature +
                p.hpPercent
            );

        if (hp > 100)
            return false;
    }

    if (p.direction)
    {
        uint32_t direction =
            ReadU32(
                creature +
                p.direction
            );

        if (direction > 7)
            return false;
    }

    if (details)
    {
        details->targetX = x;
        details->targetY = y;
        details->targetZ = z;
        details->targetId = id;
        details->targetHp = hp;
    }

    return true;
}

uintptr_t ResolveProfileLocalPlayerForDiscovery(
    const DbProfile& p)
{
    uintptr_t direct = 0;
    uintptr_t indirect = 0;

    if (p.directGlobalRva)
    {
        direct =
            ReadPtr(
                g_exeBase +
                p.directGlobalRva
            );

        if (!ValidateMonitorLocalPlayer(
                direct,
                p,
                nullptr))
        {
            direct = 0;
        }
    }

    if (p.indirectGlobalRva &&
        p.ownerOffset)
    {
        uintptr_t owner =
            ReadPtr(
                g_exeBase +
                p.indirectGlobalRva
            );

        if (owner)
        {
            indirect =
                ReadPtr(
                    owner +
                    p.ownerOffset
                );

            if (!ValidateMonitorLocalPlayer(
                    indirect,
                    p,
                    nullptr))
            {
                indirect = 0;
            }
        }
    }

    if (direct &&
        indirect &&
        direct != indirect)
    {
        return 0;
    }

    return
        direct
            ? direct
            : indirect;
}

std::vector<GameLpReference>
FindModuleReferencesToLocalPlayer(
    uintptr_t localPlayer)
{
    std::vector<GameLpReference> refs;

    if (!localPlayer)
        return refs;

    auto sections =
        GetModuleSections();

    for (const auto& section :
         sections)
    {
        if (!section.readable() ||
            section.executable())
        {
            continue;
        }

        uintptr_t begin =
            (section.begin + 7) &
            ~static_cast<uintptr_t>(7);

        uintptr_t end =
            section.end;

        if (end <= begin ||
            end - begin < 8)
        {
            continue;
        }

        for (uintptr_t p = begin;
             p + 8 <= end;
             p += 8)
        {
            uintptr_t value = 0;

            std::memcpy(
                &value,
                reinterpret_cast<const void*>(
                    p
                ),
                sizeof(value)
            );

            if (value != localPlayer)
                continue;

            GameLpReference ref{};

            ref.address = p;
            ref.rva =
                p -
                g_exeBase;
            ref.section =
                section.name;
            ref.writable =
                section.writable();

            refs.push_back(
                std::move(ref)
            );
        }
    }

    return refs;
}

struct GameCapture
{
    GameLpReference ref;
    std::vector<intptr_t> offsets;
    std::vector<uintptr_t> values;
};

std::vector<GameCapture>
CaptureGameNeighborhoods(
    const std::vector<GameLpReference>& refs,
    intptr_t minOffset = -0x40,
    intptr_t maxOffset = 0x100)
{
    std::vector<GameCapture> captures;

    for (const auto& ref :
         refs)
    {
        GameCapture capture{};
        capture.ref = ref;

        for (intptr_t off = minOffset;
             off <= maxOffset;
             off += 8)
        {
            uintptr_t address =
                static_cast<uintptr_t>(
                    static_cast<intptr_t>(
                        ref.address
                    ) +
                    off
                );

            uintptr_t value = 0;

            if (!SafeRead(
                    address,
                    value))
            {
                continue;
            }

            capture.offsets.push_back(
                off
            );

            capture.values.push_back(
                value
            );
        }

        captures.push_back(
            std::move(capture)
        );
    }

    return captures;
}

bool LookupCapturedValue(
    const GameCapture& capture,
    intptr_t offset,
    uintptr_t& value)
{
    for (size_t i = 0;
         i < capture.offsets.size();
         ++i)
    {
        if (capture.offsets[i] ==
            offset)
        {
            value =
                capture.values[i];

            return true;
        }
    }

    return false;
}

const GameCapture*
FindCaptureByRef(
    const std::vector<GameCapture>& captures,
    uintptr_t refAddress)
{
    for (const auto& c :
         captures)
    {
        if (c.ref.address ==
            refAddress)
        {
            return &c;
        }
    }

    return nullptr;
}

std::vector<GameAttackCandidate>
BuildGameAttackCandidates(
    const DbProfile& p,
    uintptr_t localPlayer,
    const std::vector<GameCapture>& noTargetA,
    const std::vector<GameCapture>& targetB,
    const std::vector<GameCapture>& noTargetC)
{
    std::vector<GameAttackCandidate> out;

    PositionPlausible(
        ReadU32(localPlayer + p.x),
        ReadU32(localPlayer + p.y),
        ReadU8(localPlayer + p.z)
    );

    uint8_t playerZ =
        ReadU8(
            localPlayer +
            p.z
        );

    for (const auto& before :
         noTargetA)
    {
        const GameCapture* during =
            FindCaptureByRef(
                targetB,
                before.ref.address
            );

        const GameCapture* after =
            FindCaptureByRef(
                noTargetC,
                before.ref.address
            );

        if (!during ||
            !after)
        {
            continue;
        }

        // The LocalPlayer reference itself must remain stable in all captures.
        uintptr_t lpA = 0;
        uintptr_t lpB = 0;
        uintptr_t lpC = 0;

        if (!LookupCapturedValue(
                before,
                0,
                lpA) ||
            !LookupCapturedValue(
                *during,
                0,
                lpB) ||
            !LookupCapturedValue(
                *after,
                0,
                lpC))
        {
            continue;
        }

        if (lpA != localPlayer ||
            lpB != localPlayer ||
            lpC != localPlayer)
        {
            continue;
        }

        for (intptr_t off = -0x40;
             off <= 0x100;
             off += 8)
        {
            if (off == 0)
                continue;

            uintptr_t a = 0;
            uintptr_t b = 0;
            uintptr_t c = 0;

            if (!LookupCapturedValue(
                    before,
                    off,
                    a) ||
                !LookupCapturedValue(
                    *during,
                    off,
                    b) ||
                !LookupCapturedValue(
                    *after,
                    off,
                    c))
            {
                continue;
            }

            // Strong behavioral signature:
            // no target -> Creature* -> no target
            if (a != 0 ||
                b == 0 ||
                c != 0 ||
                b == localPlayer)
            {
                continue;
            }

            GameAttackCandidate candidate{};

            if (!ValidateDiscoveredCreature(
                    b,
                    p,
                    &candidate))
            {
                continue;
            }

            candidate.localPlayerField =
                before.ref.address;

            candidate.gameRva =
                before.ref.rva;

            candidate.attackOffset =
                static_cast<uintptr_t>(
                    off >= 0
                        ? off
                        : 0
                );

            candidate.targetPointer =
                b;

            candidate.section =
                before.ref.section;

            int score = 100;

            if (before.ref.writable)
                score += 40;

            if (off > 0 &&
                off <= 0x40)
            {
                score += 50;
            }
            else if (off > 0 &&
                     off <= 0x100)
            {
                score += 20;
            }
            else
            {
                score -= 20;
            }

            if (candidate.targetZ ==
                playerZ)
            {
                score += 15;
            }

            if (candidate.targetHp > 0 &&
                candidate.targetHp <= 100)
            {
                score += 10;
            }

            candidate.score =
                score;

            out.push_back(
                std::move(candidate)
            );
        }
    }

    std::sort(
        out.begin(),
        out.end(),
        [](
            const GameAttackCandidate& a,
            const GameAttackCandidate& b)
        {
            if (a.score != b.score)
                return a.score > b.score;

            if (a.gameRva != b.gameRva)
                return a.gameRva < b.gameRva;

            return
                a.attackOffset <
                b.attackOffset;
        }
    );

    return out;
}

void PrintGameAttackCandidates(
    const std::vector<GameAttackCandidate>& candidates)
{
    std::cout
        << "\n============================================================\n"
        << "                 GAME DISCOVERY CANDIDATES\n"
        << "============================================================\n";

    if (candidates.empty())
    {
        std::cout
            << "Nenhum candidato passou a assinatura 0 -> Creature* -> 0.\n";

        return;
    }

    size_t limit =
        std::min<size_t>(
            candidates.size(),
            20
        );

    for (size_t i = 0;
         i < limit;
         ++i)
    {
        const auto& c =
            candidates[i];

        std::cout
            << "#"
            << i
            << " score="
            << c.score
            << " section="
            << c.section
            << " gameAnchorRva="
            << HexU64(
                c.gameRva
            )
            << " localPlayer=+0x0"
            << " attackTarget=+"
            << HexU64(
                c.attackOffset
            )
            << " target="
            << HexPtr(
                c.targetPointer
            )
            << " id="
            << c.targetId
            << " pos="
            << c.targetX
            << ","
            << c.targetY
            << ","
            << static_cast<unsigned>(
                c.targetZ
            )
            << " hp="
            << static_cast<unsigned>(
                c.targetHp
            )
            << "%\n";
    }
}

bool DiscoverGameAndAttackTarget(
    DbProfile& profile)
{
    std::cout
        << "\n============================================================\n"
        << "              STAGE 2 - GAME DISCOVERY\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "[NO HOOK] Nenhum hook\n"
        << "[NO CALL] Nenhuma funcao interna do jogo\n"
        << "\n"
        << "Objetivo:\n"
        << "  1. encontrar referencias estaveis ao LocalPlayer no modulo\n"
        << "  2. observar campos vizinhos\n"
        << "  3. detectar AttackTarget por 0 -> Creature* -> 0\n";

    uintptr_t localPlayer =
        ResolveProfileLocalPlayerForDiscovery(
            profile
        );

    if (!localPlayer)
    {
        std::cout
            << "[STOP] LocalPlayer do profile nao esta valido agora.\n";

        return false;
    }

    std::cout
        << "LocalPlayer          : "
        << HexPtr(
            localPlayer
        )
        << "\n";

    auto refs =
        FindModuleReferencesToLocalPlayer(
            localPlayer
        );

    std::cout
        << "Referencias diretas  : "
        << refs.size()
        << "\n";

    if (refs.empty())
    {
        std::cout
            << "[STOP] Nenhuma referencia direta ao LocalPlayer em secoes de dados.\n";

        return false;
    }

    size_t shown =
        std::min<size_t>(
            refs.size(),
            24
        );

    for (size_t i = 0;
         i < shown;
         ++i)
    {
        std::cout
            << "  ref["
            << i
            << "] RVA "
            << HexU64(
                refs[i].rva
            )
            << " section="
            << refs[i].section
            << (
                refs[i].writable
                    ? " writable"
                    : ""
            )
            << "\n";
    }

    std::cout
        << "\nPASSO A - SEM ALVO\n"
        << "Pressione ESC no jogo e confirme que nao existe monstro selecionado.\n";

    WaitEnter(
        "Quando estiver SEM TARGET, pressione ENTER..."
    );

    auto noTargetA =
        CaptureGameNeighborhoods(
            refs
        );

    std::cout
        << "\nPASSO B - COM ALVO\n"
        << "Selecione/ataque UM MONSTRO visivel e mantenha-o como target.\n";

    WaitEnter(
        "Quando o MONSTRO estiver selecionado, pressione ENTER..."
    );

    auto targetB =
        CaptureGameNeighborhoods(
            refs
        );

    std::cout
        << "\nPASSO C - LIMPAR ALVO\n"
        << "Cancele o target com ESC e espere o alvo desaparecer.\n";

    WaitEnter(
        "Quando estiver novamente SEM TARGET, pressione ENTER..."
    );

    auto noTargetC =
        CaptureGameNeighborhoods(
            refs
        );

    auto candidates =
        BuildGameAttackCandidates(
            profile,
            localPlayer,
            noTargetA,
            targetB,
            noTargetC
        );

    PrintGameAttackCandidates(
        candidates
    );

    if (candidates.empty())
    {
        profile.gameStatus =
            "unresolved";

        std::cout
            << "\n[RESULT] GAME/ATTACKTARGET ainda nao resolvido.\n"
            << "Nenhum RVA sera inventado.\n";

        return false;
    }

    const GameAttackCandidate* best =
        &candidates[0];

    bool uniqueStrong =
        candidates.size() == 1 ||
        (
            candidates[0].score >=
                candidates[1].score + 25
        );

    // If ambiguous, use a second monster as an extra discriminator.
    if (!uniqueStrong)
    {
        std::cout
            << "\n[AMBIGUOUS] Ha mais de um candidato forte.\n"
            << "Vamos usar um SEGUNDO monstro para desempatar.\n";

        WaitEnter(
            "Selecione OUTRO monstro diferente e pressione ENTER..."
        );

        auto targetD =
            CaptureGameNeighborhoods(
                refs
            );

        std::vector<GameAttackCandidate> refined;

        for (const auto& candidate :
             candidates)
        {
            const GameCapture* d =
                FindCaptureByRef(
                    targetD,
                    candidate.localPlayerField
                );

            if (!d)
                continue;

            uintptr_t value = 0;

            if (!LookupCapturedValue(
                    *d,
                    static_cast<intptr_t>(
                        candidate.attackOffset
                    ),
                    value))
            {
                continue;
            }

            if (!value ||
                value ==
                    candidate.targetPointer)
            {
                continue;
            }

            GameAttackCandidate copy =
                candidate;

            if (!ValidateDiscoveredCreature(
                    value,
                    profile,
                    &copy))
            {
                continue;
            }

            copy.targetPointer =
                value;

            copy.score += 80;

            refined.push_back(
                std::move(copy)
            );
        }

        if (!refined.empty())
        {
            std::sort(
                refined.begin(),
                refined.end(),
                [](
                    const GameAttackCandidate& a,
                    const GameAttackCandidate& b)
                {
                    return
                        a.score >
                        b.score;
                }
            );

            candidates =
                std::move(
                    refined
                );

            PrintGameAttackCandidates(
                candidates
            );

            best =
                &candidates[0];

            uniqueStrong =
                candidates.size() == 1 ||
                (
                    candidates[0].score >=
                        candidates[1].score + 25
                );
        }
    }

    if (!uniqueStrong)
    {
        profile.gameStatus =
            "strong_candidate_ambiguous";

        std::cout
            << "\n[RESULT] Candidatos fortes permaneceram ambiguos.\n"
            << "Nada sera promovido automaticamente.\n";

        return false;
    }

    profile.gameRva =
        best->gameRva;

    // At this stage the LocalPlayer field itself is our Game anchor.
    // Follow/Containers stages will later corroborate whether this is the
    // true Game object base across the client family.
    profile.gameLocalPlayer =
        0;

    profile.gameAttackTarget =
        best->attackOffset;

    profile.gameStatus =
        "confirmed_runtime_attack_cycle";

    std::cout
        << "\n============================================================\n"
        << "                    GAME DISCOVERED\n"
        << "============================================================\n"
        << "Game anchor RVA      : "
        << HexU64(
            profile.gameRva
        )
        << "\n"
        << "LocalPlayer offset   : +"
        << HexU64(
            profile.gameLocalPlayer
        )
        << "\n"
        << "AttackTarget offset  : +"
        << HexU64(
            profile.gameAttackTarget
        )
        << "\n"
        << "Evidence             : 0 -> Creature* -> 0\n"
        << "Status               : "
        << profile.gameStatus
        << "\n";

    return true;
}

uintptr_t WaitForDiscoveryLocalPlayer(
    const DbProfile& profile,
    const char* stageName)
{
    std::cout
        << "\n============================================================\n"
        << "                 WAIT LOGIN FOR DISCOVERY\n"
        << "============================================================\n"
        << "Stage                 : "
        << (stageName ? stageName : "UNKNOWN")
        << "\n"
        << "Aguardando LocalPlayer valido usando o Player Discovery ja salvo.\n"
        << "Pode injetar deslogado e fazer login normalmente.\n"
        << "Somente os dados ja descobertos do Player sao usados nesta espera.\n";

    uintptr_t lastShown = 0;

    while (true)
    {
        if (GetAsyncKeyState(VK_END) & 0x8000)
            return 0;

        uintptr_t localPlayer =
            ResolveProfileLocalPlayerForDiscovery(
                profile
            );

        if (localPlayer)
        {
            std::cout
                << "[LOGIN READY] LocalPlayer = "
                << HexPtr(
                    localPlayer
                )
                << "\n";

            return localPlayer;
        }

        uintptr_t directRaw = 0;

        if (profile.directGlobalRva)
        {
            directRaw =
                ReadPtr(
                    g_exeBase +
                    profile.directGlobalRva
                );
        }

        if (directRaw != lastShown)
        {
            lastShown =
                directRaw;

            if (directRaw)
            {
                std::cout
                    << "[WAIT] Direct raw mudou para "
                    << HexPtr(
                        directRaw
                    )
                    << " mas ainda nao validou como LocalPlayer.\n";
            }
        }

        Sleep(250);
    }
}


bool EnsureGameDiscovery(
    DbProfile& profile,
    std::vector<DbProfile>& database,
    int profileIndex,
    const std::string& databasePath)
{
    if (profile.gameRva &&
        profile.gameAttackTarget &&
        (
            profile.gameStatus ==
                "discovered_runtime_selfcheck_pass" ||
            profile.gameStatus ==
                "discovered_runtime_new_build" ||
            profile.gameStatus ==
                "confirmed_runtime_attack_cycle"
        ))
    {
        std::cout
            << "\n[FEITO] STAGE 2 - Game + AttackTarget ja passaram self-check.\n"
            << "Game RVA       : "
            << HexU64(profile.gameRva)
            << "\nAttackTarget   : +"
            << HexU64(profile.gameAttackTarget)
            << "\n";

        return true;
    }

    // Discovery V2.0.2 benchmark rule:
    // even if an older profile already contains Game/AttackTarget,
    // DO NOT use those values to skip Stage 2. Keep them only as
    // post-discovery ground truth for comparison.
    const uintptr_t knownGameRva =
        profile.gameRva;

    const uintptr_t knownGameLocalPlayer =
        profile.gameLocalPlayer;

    const uintptr_t knownGameAttackTarget =
        profile.gameAttackTarget;

    const std::string knownGameStatus =
        profile.gameStatus;

    const bool hadKnownGame =
        knownGameRva != 0;

    // Stage 2 depends on a live LocalPlayer. In V2.0.2 this function
    // was called while the client was still logged out, so discovery
    // aborted before doing any work. Wait here first.
    uintptr_t liveLocalPlayer =
        WaitForDiscoveryLocalPlayer(
            profile,
            "STAGE 2 - GAME / ATTACKTARGET"
        );

    if (!liveLocalPlayer)
    {
        std::cout
            << "\n[STAGE 2] Cancelada antes do login.\n";

        return false;
    }

    if (hadKnownGame)
    {
        std::cout
            << "\n============================================================\n"
            << "              STAGE 2 - BENCHMARK MODE\n"
            << "============================================================\n"
            << "O profile antigo JA possui Game/AttackTarget.\n"
            << "Esses valores NAO serao usados pelo algoritmo de descoberta.\n"
            << "Eles ficam guardados apenas para comparar DEPOIS.\n";
    }

    // Hide old Game answers from the discovery result state.
    // Player discovery fields remain available and are the only anchors.
    profile.gameRva = 0;
    profile.gameLocalPlayer = 0;
    profile.gameAttackTarget = 0;
    profile.gameStatus = "rediscovery_running";

    bool ok =
        DiscoverGameAndAttackTarget(
            profile
        );

    if (ok)
    {
        std::cout
            << "\n============================================================\n"
            << "                 STAGE 2 SELF-CHECK\n"
            << "============================================================\n"
            << "Discovered Game RVA  : "
            << HexU64(
                profile.gameRva
            )
            << "\n"
            << "Discovered LP offset : +"
            << HexU64(
                profile.gameLocalPlayer
            )
            << "\n"
            << "Discovered Attack    : +"
            << HexU64(
                profile.gameAttackTarget
            )
            << "\n";

        if (hadKnownGame)
        {
            const bool gameMatch =
                profile.gameRva ==
                knownGameRva;

            const bool lpMatch =
                profile.gameLocalPlayer ==
                knownGameLocalPlayer;

            const bool attackMatch =
                profile.gameAttackTarget ==
                knownGameAttackTarget;

            std::cout
                << "\n[GROUND TRUTH COMPARISON]\n"
                << "Known Game RVA       : "
                << HexU64(
                    knownGameRva
                )
                << "\n"
                << "Known LP offset      : +"
                << HexU64(
                    knownGameLocalPlayer
                )
                << "\n"
                << "Known Attack offset  : +"
                << HexU64(
                    knownGameAttackTarget
                )
                << "\n"
                << "Game match           : "
                << (
                    gameMatch
                        ? "PASS"
                        : "FAIL"
                )
                << "\n"
                << "LocalPlayer match    : "
                << (
                    lpMatch
                        ? "PASS"
                        : "FAIL"
                )
                << "\n"
                << "AttackTarget match   : "
                << (
                    attackMatch
                        ? "PASS"
                        : "FAIL"
                )
                << "\n";

            if (gameMatch &&
                lpMatch &&
                attackMatch)
            {
                profile.gameStatus =
                    "discovered_runtime_selfcheck_pass";

                std::cout
                    << "\n[FEITO] STAGE 2 redescobriu o Game sem usar a resposta antiga.\n";
            }
            else
            {
                profile.gameStatus =
                    "discovered_runtime_selfcheck_mismatch";

                std::cout
                    << "\n[CHECK] Discovery encontrou resultado diferente do profile antigo.\n";
            }
        }
        else
        {
            profile.gameStatus =
                "discovered_runtime_new_build";
        }
    }
    else
    {
        std::cout
            << "\n[STAGE 2] Rediscovery nao fechou com seguranca.\n";

        if (hadKnownGame)
        {
            // Do not destroy previously known profile data just because
            // a benchmark run was inconclusive.
            profile.gameRva =
                knownGameRva;

            profile.gameLocalPlayer =
                knownGameLocalPlayer;

            profile.gameAttackTarget =
                knownGameAttackTarget;

            profile.gameStatus =
                knownGameStatus;

            std::cout
                << "[PRESERVE] Valores antigos de Game foram restaurados.\n";
        }
        else
        {
            profile.gameStatus =
                "unresolved";
        }
    }

    if (profileIndex >= 0 &&
        profileIndex <
            static_cast<int>(
                database.size()
            ))
    {
        database[
            static_cast<size_t>(
                profileIndex
            )
        ] = profile;

        SaveProfileDatabase(
            databasePath,
            database
        );
    }

    return ok;
}


// ============================================================
// DISCOVERY V2.1 - FOLLOW TARGET
// ============================================================

struct FollowCapture
{
    std::vector<intptr_t> offsets;
    std::vector<uintptr_t> values;
};

struct FollowCandidate
{
    uintptr_t offset = 0;
    uintptr_t pointer = 0;
    int score = 0;

    uint32_t x = 0;
    uint32_t y = 0;
    uint8_t z = 0;
    uint32_t id = 0;
    uint8_t hp = 0;
};

FollowCapture CaptureGameObjectWindow(
    uintptr_t gameAddress,
    intptr_t minOffset = 0,
    intptr_t maxOffset = 0x100)
{
    FollowCapture capture{};

    for (intptr_t off = minOffset;
         off <= maxOffset;
         off += 8)
    {
        uintptr_t value = 0;

        if (!SafeRead(
                gameAddress +
                    static_cast<uintptr_t>(off),
                value))
        {
            continue;
        }

        capture.offsets.push_back(
            off
        );

        capture.values.push_back(
            value
        );
    }

    return capture;
}

bool LookupFollowValue(
    const FollowCapture& capture,
    intptr_t offset,
    uintptr_t& value)
{
    for (size_t i = 0;
         i < capture.offsets.size();
         ++i)
    {
        if (capture.offsets[i] ==
            offset)
        {
            value =
                capture.values[i];

            return true;
        }
    }

    return false;
}

std::vector<FollowCandidate>
BuildFollowCandidates(
    const DbProfile& profile,
    uintptr_t localPlayer,
    const FollowCapture& noFollowA,
    const FollowCapture& followB,
    const FollowCapture& noFollowC)
{
    std::vector<FollowCandidate> out;

    uint8_t playerZ =
        ReadU8(
            localPlayer +
            profile.z
        );

    for (intptr_t off = 0;
         off <= 0x100;
         off += 8)
    {
        if (static_cast<uintptr_t>(off) ==
                profile.gameLocalPlayer ||
            static_cast<uintptr_t>(off) ==
                profile.gameAttackTarget)
        {
            continue;
        }

        uintptr_t a = 0;
        uintptr_t b = 0;
        uintptr_t c = 0;

        if (!LookupFollowValue(
                noFollowA,
                off,
                a) ||
            !LookupFollowValue(
                followB,
                off,
                b) ||
            !LookupFollowValue(
                noFollowC,
                off,
                c))
        {
            continue;
        }

        if (a != 0 ||
            b == 0 ||
            c != 0 ||
            b == localPlayer)
        {
            continue;
        }

        GameAttackCandidate details{};

        if (!ValidateDiscoveredCreature(
                b,
                profile,
                &details))
        {
            continue;
        }

        FollowCandidate candidate{};

        candidate.offset =
            static_cast<uintptr_t>(
                off
            );

        candidate.pointer = b;
        candidate.x = details.targetX;
        candidate.y = details.targetY;
        candidate.z = details.targetZ;
        candidate.id = details.targetId;
        candidate.hp = details.targetHp;

        int score = 100;

        if (off > 0 &&
            off <= 0x40)
        {
            score += 60;
        }
        else if (off <= 0x80)
        {
            score += 30;
        }

        if (candidate.z ==
            playerZ)
        {
            score += 15;
        }

        if (candidate.hp <= 100)
            score += 10;

        candidate.score =
            score;

        out.push_back(
            std::move(candidate)
        );
    }

    std::sort(
        out.begin(),
        out.end(),
        [](
            const FollowCandidate& a,
            const FollowCandidate& b)
        {
            if (a.score != b.score)
                return a.score > b.score;

            return a.offset < b.offset;
        }
    );

    return out;
}

void PrintFollowCandidates(
    const std::vector<FollowCandidate>& candidates)
{
    std::cout
        << "\n============================================================\n"
        << "               FOLLOW DISCOVERY CANDIDATES\n"
        << "============================================================\n";

    if (candidates.empty())
    {
        std::cout
            << "Nenhum campo passou a assinatura 0 -> Creature* -> 0.\n";

        return;
    }

    for (size_t i = 0;
         i < candidates.size() &&
         i < 16;
         ++i)
    {
        const auto& c =
            candidates[i];

        std::cout
            << "#"
            << i
            << " score="
            << c.score
            << " offset=+"
            << HexU64(
                c.offset
            )
            << " target="
            << HexPtr(
                c.pointer
            )
            << " id="
            << c.id
            << " pos="
            << c.x
            << ","
            << c.y
            << ","
            << static_cast<unsigned>(
                c.z
            )
            << " hp="
            << static_cast<unsigned>(
                c.hp
            )
            << "%\n";
    }
}

bool DiscoverFollowTarget(
    DbProfile& profile)
{
    std::cout
        << "\n============================================================\n"
        << "            STAGE 3 - FOLLOWTARGET DISCOVERY\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "[NO HOOK] Nenhum hook\n"
        << "[NO CALL] Nenhuma funcao interna do jogo\n"
        << "\n"
        << "Objetivo:\n"
        << "  detectar um campo Game que faca 0 -> Creature* -> 0\n"
        << "  enquanto AttackTarget permanece zerado.\n";

    uintptr_t localPlayer =
        ResolveProfileLocalPlayerForDiscovery(
            profile
        );

    if (!localPlayer)
    {
        std::cout
            << "[STOP] LocalPlayer invalido para Stage 3.\n";

        return false;
    }

    if (!profile.gameRva)
    {
        std::cout
            << "[STOP] Game ainda nao foi descoberto.\n";

        return false;
    }

    uintptr_t gameAddress =
        g_exeBase +
        profile.gameRva;

    std::cout
        << "Game address         : "
        << HexPtr(
            gameAddress
        )
        << "\n"
        << "AttackTarget offset  : +"
        << HexU64(
            profile.gameAttackTarget
        )
        << "\n";

    // ========================================================
    // CLEAN BASELINE
    // ========================================================

    FollowCapture a{};

    while (true)
    {
        std::cout
            << "\nPASSO A - SEM ATTACK / SEM FOLLOW\n"
            << "Cancele qualquer ataque e qualquer follow no cliente.\n";

        WaitEnter(
            "Quando NAO houver attack nem follow, pressione ENTER..."
        );

        a =
            CaptureGameObjectWindow(
                gameAddress
            );

        uintptr_t attackA = 0;

        LookupFollowValue(
            a,
            static_cast<intptr_t>(
                profile.gameAttackTarget
            ),
            attackA
        );

        if (!attackA)
            break;

        std::cout
            << "\n[RETRY] Ainda existe ATTACK ativo: "
            << HexPtr(
                attackA
            )
            << "\n"
            << "Cancele o ataque e repita o PASSO A.\n";
    }

    // ========================================================
    // FOLLOW RISING EDGE
    // ========================================================

    FollowCapture b{};

    while (true)
    {
        std::cout
            << "\nPASSO B - FOLLOW MANUAL\n"
            << "IMPORTANTE: NAO clique para atacar.\n"
            << "Use a opcao FOLLOW do proprio cliente na criatura.\n"
            << "Se houver menu de contexto, escolha Follow e NAO Attack.\n";

        WaitEnter(
            "Quando a criatura estiver realmente em FOLLOW, pressione ENTER..."
        );

        b =
            CaptureGameObjectWindow(
                gameAddress
            );

        uintptr_t attackB = 0;

        LookupFollowValue(
            b,
            static_cast<intptr_t>(
                profile.gameAttackTarget
            ),
            attackB
        );

        if (attackB)
        {
            std::cout
                << "\n============================================================\n"
                << "                 ATTACK DETECTED - RETRY\n"
                << "============================================================\n"
                << "AttackTarget ficou ativo: "
                << HexPtr(
                    attackB
                )
                << "\n"
                << "Isso significa que o cliente entrou em ATTACK, nao Follow.\n"
                << "Nao precisa reinjetar a DLL.\n"
                << "Cancele o ataque e vamos repetir o teste.\n";

            WaitEnter(
                "Depois de cancelar o ATTACK, pressione ENTER..."
            );

            // Refresh the clean baseline after the wrong interaction.
            FollowCapture clean =
                CaptureGameObjectWindow(
                    gameAddress
                );

            uintptr_t attackClean = 0;

            LookupFollowValue(
                clean,
                static_cast<intptr_t>(
                    profile.gameAttackTarget
                ),
                attackClean
            );

            if (attackClean)
            {
                std::cout
                    << "[RETRY] Attack ainda esta ativo. Cancele antes de continuar.\n";

                continue;
            }

            a =
                std::move(
                    clean
                );

            continue;
        }

        // Before asking the user to cancel Follow, verify that at least one
        // non-Attack field rose from zero to a semantically valid Creature*.
        size_t risingCreatureFields = 0;

        for (intptr_t off = 0;
             off <= 0x100;
             off += 8)
        {
            if (static_cast<uintptr_t>(off) ==
                    profile.gameLocalPlayer ||
                static_cast<uintptr_t>(off) ==
                    profile.gameAttackTarget)
            {
                continue;
            }

            uintptr_t va = 0;
            uintptr_t vb = 0;

            if (!LookupFollowValue(
                    a,
                    off,
                    va) ||
                !LookupFollowValue(
                    b,
                    off,
                    vb))
            {
                continue;
            }

            if (va != 0 ||
                vb == 0 ||
                vb == localPlayer)
            {
                continue;
            }

            if (ValidateDiscoveredCreature(
                    vb,
                    profile,
                    nullptr))
            {
                ++risingCreatureFields;
            }
        }

        if (!risingCreatureFields)
        {
            std::cout
                << "\n[RETRY] AttackTarget esta zerado, mas nenhum novo Creature* "
                << "apareceu no Game.\n"
                << "O Follow provavelmente nao foi ativado.\n"
                << "Tente novamente sem reinjetar.\n";

            continue;
        }

        std::cout
            << "[FOLLOW SIGNAL] "
            << risingCreatureFields
            << " campo(s) candidato(s) subiram de 0 para Creature*.\n";

        break;
    }

    // ========================================================
    // FOLLOW FALLING EDGE
    // ========================================================

    FollowCapture c{};

    while (true)
    {
        std::cout
            << "\nPASSO C - CANCELAR FOLLOW\n"
            << "Cancele somente o follow e espere a marcacao desaparecer.\n";

        WaitEnter(
            "Quando estiver novamente SEM FOLLOW, pressione ENTER..."
        );

        c =
            CaptureGameObjectWindow(
                gameAddress
            );

        uintptr_t attackC = 0;

        LookupFollowValue(
            c,
            static_cast<intptr_t>(
                profile.gameAttackTarget
            ),
            attackC
        );

        if (!attackC)
            break;

        std::cout
            << "\n[RETRY] Um ATTACK apareceu durante o cancelamento: "
            << HexPtr(
                attackC
            )
            << "\n"
            << "Cancele o ataque e pressione ENTER novamente.\n";
    }

    auto candidates =
        BuildFollowCandidates(
            profile,
            localPlayer,
            a,
            b,
            c
        );

    PrintFollowCandidates(
        candidates
    );

    if (candidates.empty())
    {
        profile.followStatus =
            "unresolved";

        std::cout
            << "\n[RESULT] Nenhum FollowTarget fechou 0 -> Creature* -> 0.\n"
            << "O profile nao sera alterado com valor inventado.\n";

        return false;
    }

    bool uniqueStrong =
        candidates.size() == 1 ||
        candidates[0].score >=
            candidates[1].score + 25;

    if (!uniqueStrong)
    {
        std::cout
            << "\n[AMBIGUOUS] Mais de um candidato forte.\n"
            << "Vamos seguir uma SEGUNDA criatura diferente.\n";

        FollowCapture d{};

        while (true)
        {
            WaitEnter(
                "Ative FOLLOW em outra criatura (sem atacar) e pressione ENTER..."
            );

            d =
                CaptureGameObjectWindow(
                    gameAddress
                );

            uintptr_t attackD = 0;

            LookupFollowValue(
                d,
                static_cast<intptr_t>(
                    profile.gameAttackTarget
                ),
                attackD
            );

            if (!attackD)
                break;

            std::cout
                << "[RETRY] Isso ativou AttackTarget "
                << HexPtr(
                    attackD
                )
                << ". Cancele e use FOLLOW.\n";
        }

        std::vector<FollowCandidate> refined;

        for (const auto& old :
             candidates)
        {
            uintptr_t value = 0;

            if (!LookupFollowValue(
                    d,
                    static_cast<intptr_t>(
                        old.offset
                    ),
                    value))
            {
                continue;
            }

            if (!value ||
                value ==
                    old.pointer)
            {
                continue;
            }

            GameAttackCandidate details{};

            if (!ValidateDiscoveredCreature(
                    value,
                    profile,
                    &details))
            {
                continue;
            }

            FollowCandidate copy =
                old;

            copy.pointer = value;
            copy.x = details.targetX;
            copy.y = details.targetY;
            copy.z = details.targetZ;
            copy.id = details.targetId;
            copy.hp = details.targetHp;
            copy.score += 80;

            refined.push_back(
                std::move(copy)
            );
        }

        if (!refined.empty())
        {
            std::sort(
                refined.begin(),
                refined.end(),
                [](
                    const FollowCandidate& x,
                    const FollowCandidate& y)
                {
                    return x.score > y.score;
                }
            );

            candidates =
                std::move(
                    refined
                );

            PrintFollowCandidates(
                candidates
            );

            uniqueStrong =
                candidates.size() == 1 ||
                candidates[0].score >=
                    candidates[1].score + 25;
        }
    }

    if (!uniqueStrong)
    {
        profile.followStatus =
            "strong_candidate_ambiguous";

        std::cout
            << "\n[RESULT] FollowTarget permaneceu ambiguo.\n";

        return false;
    }

    profile.gameFollowTarget =
        candidates[0].offset;

    profile.followStatus =
        "confirmed_runtime_follow_cycle";

    std::cout
        << "\n============================================================\n"
        << "                 FOLLOWTARGET DISCOVERED\n"
        << "============================================================\n"
        << "FollowTarget offset : +"
        << HexU64(
            profile.gameFollowTarget
        )
        << "\n"
        << "Evidence            : 0 -> Creature* -> 0\n"
        << "AttackTarget        : permaneceu 0 durante o teste valido\n"
        << "Status              : "
        << profile.followStatus
        << "\n";

    // Ground truth only AFTER discovery; never used to locate the field.
    const bool knownBenchmarkBuild =
        profile.timestamp == 0x6AA9FA57ULL &&
        profile.sizeOfImage == 0x17BF000ULL &&
        profile.textHash == 0x89D3D35243890EA2ULL;

    if (knownBenchmarkBuild)
    {
        constexpr uintptr_t expectedFollow =
            0x10;

        bool match =
            profile.gameFollowTarget ==
            expectedFollow;

        std::cout
            << "\n[GROUND TRUTH COMPARISON]\n"
            << "Known Follow offset  : +"
            << HexU64(
                expectedFollow
            )
            << "\n"
            << "FollowTarget match   : "
            << (
                match
                    ? "PASS"
                    : "FAIL"
            )
            << "\n";

        if (match)
        {
            profile.followStatus =
                "discovered_runtime_selfcheck_pass";

            std::cout
                << "\n[FEITO] STAGE 3 redescobriu FollowTarget sem usar a resposta antiga.\n";
        }
        else
        {
            profile.followStatus =
                "discovered_runtime_selfcheck_mismatch";
        }
    }

    return
        profile.followStatus ==
            "discovered_runtime_selfcheck_pass" ||
        profile.followStatus ==
            "confirmed_runtime_follow_cycle";
}

bool EnsureFollowDiscovery(
    DbProfile& profile,
    std::vector<DbProfile>& database,
    int profileIndex,
    const std::string& databasePath)
{
    if (profile.gameFollowTarget &&
        (
            profile.followStatus ==
                "discovered_runtime_selfcheck_pass" ||
            profile.followStatus ==
                "confirmed_runtime_follow_cycle"
        ))
    {
        std::cout
            << "\n[FEITO] STAGE 3 - FollowTarget ja passou self-check.\n"
            << "FollowTarget   : +"
            << HexU64(
                profile.gameFollowTarget
            )
            << "\n";

        return true;
    }

    uintptr_t liveLocalPlayer =
        WaitForDiscoveryLocalPlayer(
            profile,
            "STAGE 3 - FOLLOWTARGET"
        );

    if (!liveLocalPlayer)
    {
        std::cout
            << "\n[STAGE 3] Cancelada antes do login.\n";

        return false;
    }

    bool ok =
        DiscoverFollowTarget(
            profile
        );

    if (profileIndex >= 0 &&
        profileIndex <
            static_cast<int>(
                database.size()
            ))
    {
        database[
            static_cast<size_t>(
                profileIndex
            )
        ] = profile;

        SaveProfileDatabase(
            databasePath,
            database
        );
    }

    return ok;
}


// ============================================================
// DISCOVERY V2.2 - MAP
// ============================================================

struct MapPosition
{
    uint32_t x = 0;
    uint32_t y = 0;
    uint8_t z = 0;
};

struct MapCenterCandidate
{
    uintptr_t address = 0;
    uintptr_t rva = 0;
    std::string section;

    int movementHits = 0;
};

struct MapAwareCandidate
{
    uintptr_t northAddress = 0;
    uintptr_t northOffsetFromCenter = 0;

    uint32_t north = 0;
    uint32_t east = 0;
    uint32_t south = 0;
    uint32_t west = 0;

    int score = 0;
};

struct MapRipRefSummary
{
    uintptr_t target = 0;
    int leaRefs = 0;
    int movRefs = 0;
};

struct MapBaseCandidate
{
    uintptr_t address = 0;
    uintptr_t rva = 0;
    uintptr_t centerOffset = 0;

    int leaRefs = 0;
    int movRefs = 0;
    int score = 0;
};

MapPosition ReadDiscoveredPlayerPosition(
    uintptr_t localPlayer,
    const DbProfile& profile)
{
    MapPosition p{};

    if (!localPlayer)
        return p;

    p.x =
        ReadU32(
            localPlayer +
            profile.x
        );

    p.y =
        ReadU32(
            localPlayer +
            profile.y
        );

    p.z =
        ReadU8(
            localPlayer +
            profile.z
        );

    return p;
}

bool SameMapPosition(
    const MapPosition& a,
    const MapPosition& b)
{
    return
        a.x == b.x &&
        a.y == b.y &&
        a.z == b.z;
}

bool MapPositionPlausible(
    const MapPosition& p)
{
    return
        PositionPlausible(
            p.x,
            p.y,
            p.z
        );
}

std::vector<MapCenterCandidate>
FindModulePositionTriples(
    const MapPosition& position)
{
    std::vector<MapCenterCandidate> out;

    auto sections =
        GetModuleSections();

    for (const auto& section :
         sections)
    {
        if (!section.readable() ||
            !section.writable() ||
            section.executable())
        {
            continue;
        }

        uintptr_t begin =
            (section.begin + 3) &
            ~static_cast<uintptr_t>(3);

        uintptr_t end =
            section.end;

        if (end <= begin ||
            end - begin < 12)
        {
            continue;
        }

        for (uintptr_t address = begin;
             address + 12 <= end;
             address += 4)
        {
            uint32_t x = 0;
            uint32_t y = 0;
            uint8_t z = 0;

            if (!SafeRead(
                    address,
                    x) ||
                x != position.x)
            {
                continue;
            }

            if (!SafeRead(
                    address + 4,
                    y) ||
                y != position.y)
            {
                continue;
            }

            if (!SafeRead(
                    address + 8,
                    z) ||
                z != position.z)
            {
                continue;
            }

            MapCenterCandidate candidate{};

            candidate.address =
                address;

            candidate.rva =
                address -
                g_exeBase;

            candidate.section =
                section.name;

            candidate.movementHits =
                1;

            out.push_back(
                std::move(candidate)
            );
        }
    }

    return out;
}

void FilterMapCenterCandidatesByPosition(
    std::vector<MapCenterCandidate>& candidates,
    const MapPosition& position)
{
    candidates.erase(
        std::remove_if(
            candidates.begin(),
            candidates.end(),
            [&](
                const MapCenterCandidate& candidate)
            {
                uint32_t x = 0;
                uint32_t y = 0;
                uint8_t z = 0;

                if (!SafeRead(
                        candidate.address,
                        x) ||
                    !SafeRead(
                        candidate.address + 4,
                        y) ||
                    !SafeRead(
                        candidate.address + 8,
                        z))
                {
                    return true;
                }

                return
                    x != position.x ||
                    y != position.y ||
                    z != position.z;
            }
        ),
        candidates.end()
    );

    for (auto& candidate :
         candidates)
    {
        ++candidate.movementHits;
    }
}

MapPosition WaitForPlayerPositionChange(
    uintptr_t localPlayer,
    const DbProfile& profile,
    const MapPosition& previous,
    const char* prompt)
{
    while (true)
    {
        WaitEnter(
            prompt
        );

        MapPosition now =
            ReadDiscoveredPlayerPosition(
                localPlayer,
                profile
            );

        if (!MapPositionPlausible(
                now))
        {
            std::cout
                << "[RETRY] Player Position ficou implausivel. Tente novamente.\n";

            continue;
        }

        if (SameMapPosition(
                now,
                previous))
        {
            std::cout
                << "[RETRY] A Position nao mudou. Ande para outro SQM e pressione ENTER.\n";

            continue;
        }

        return now;
    }
}

std::vector<MapAwareCandidate>
FindAwareCandidatesAroundCenter(
    uintptr_t centerAddress)
{
    std::vector<MapAwareCandidate> out;

    // Search near the confirmed center triple.
    // We know the semantics are four consecutive directional extents,
    // but we do NOT assume their exact offsets.
    for (uintptr_t rel = 0x0C;
         rel <= 0x100;
         rel += 4)
    {
        uint32_t n = 0;
        uint32_t e = 0;
        uint32_t s = 0;
        uint32_t w = 0;

        if (!SafeRead(
                centerAddress + rel,
                n) ||
            !SafeRead(
                centerAddress + rel + 4,
                e) ||
            !SafeRead(
                centerAddress + rel + 8,
                s) ||
            !SafeRead(
                centerAddress + rel + 12,
                w))
        {
            continue;
        }

        if (!n || !e || !s || !w)
            continue;

        if (n > 64 ||
            e > 64 ||
            s > 64 ||
            w > 64)
        {
            continue;
        }

        uint32_t height =
            n + 1 + s;

        uint32_t width =
            e + 1 + w;

        if (height < 8 ||
            height > 64 ||
            width < 8 ||
            width > 64)
        {
            continue;
        }

        int nsDiff =
            std::abs(
                static_cast<int>(n) -
                static_cast<int>(s)
            );

        int ewDiff =
            std::abs(
                static_cast<int>(e) -
                static_cast<int>(w)
            );

        int score = 80;

        if (height >= 12 &&
            height <= 32)
        {
            score += 25;
        }

        if (width >= 12 &&
            width <= 40)
        {
            score += 25;
        }

        if (nsDiff <= 4)
            score += 20;

        if (ewDiff <= 4)
            score += 20;

        if (rel >= 0x20 &&
            rel <= 0x60)
        {
            score += 15;
        }

        MapAwareCandidate candidate{};

        candidate.northAddress =
            centerAddress +
            rel;

        candidate.northOffsetFromCenter =
            rel;

        candidate.north = n;
        candidate.east = e;
        candidate.south = s;
        candidate.west = w;
        candidate.score = score;

        out.push_back(
            std::move(candidate)
        );
    }

    std::sort(
        out.begin(),
        out.end(),
        [](
            const MapAwareCandidate& a,
            const MapAwareCandidate& b)
        {
            if (a.score != b.score)
                return a.score > b.score;

            return
                a.northOffsetFromCenter <
                b.northOffsetFromCenter;
        }
    );

    return out;
}

void AddMapRipRef(
    std::unordered_map<uintptr_t, MapRipRefSummary>& refs,
    uintptr_t target,
    bool lea)
{
    auto it =
        refs.find(
            target
        );

    if (it ==
        refs.end())
    {
        MapRipRefSummary summary{};
        summary.target = target;

        it =
            refs.emplace(
                target,
                summary
            ).first;
    }

    if (lea)
        ++it->second.leaRefs;
    else
        ++it->second.movRefs;
}

std::vector<MapRipRefSummary>
CollectRipRefsToWindow(
    uintptr_t targetBegin,
    uintptr_t targetEnd)
{
    std::unordered_map<uintptr_t, MapRipRefSummary> byTarget;

    auto sections =
        GetModuleSections();

    for (const auto& section :
         sections)
    {
        if (!section.readable() ||
            !section.executable())
        {
            continue;
        }

        if (section.end <=
            section.begin + 8)
        {
            continue;
        }

        const uint8_t* bytes =
            reinterpret_cast<const uint8_t*>(
                section.begin
            );

        size_t size =
            static_cast<size_t>(
                section.end -
                section.begin
            );

        for (size_t i = 0;
             i + 7 <= size;
             ++i)
        {
            size_t rex = 0;

            if (bytes[i] >= 0x40 &&
                bytes[i] <= 0x4F)
            {
                rex = 1;
            }

            if (i + rex + 6 >
                size)
            {
                continue;
            }

            uint8_t opcode =
                bytes[
                    i + rex
                ];

            if (opcode != 0x8D &&
                opcode != 0x8B &&
                opcode != 0x89)
            {
                continue;
            }

            uint8_t modrm =
                bytes[
                    i + rex + 1
                ];

            // mod=00, r/m=101 -> RIP-relative disp32.
            if ((modrm & 0xC7) != 0x05)
                continue;

            int32_t disp = 0;

            std::memcpy(
                &disp,
                bytes +
                    i +
                    rex +
                    2,
                sizeof(disp)
            );

            size_t instructionLength =
                rex
                    ? 7
                    : 6;

            uintptr_t instruction =
                section.begin +
                i;

            int64_t next =
                static_cast<int64_t>(
                    instruction +
                    instructionLength
                );

            int64_t targetSigned =
                next +
                static_cast<int64_t>(
                    disp
                );

            if (targetSigned <= 0)
                continue;

            uintptr_t target =
                static_cast<uintptr_t>(
                    targetSigned
                );

            if (target <
                    targetBegin ||
                target >
                    targetEnd)
            {
                continue;
            }

            AddMapRipRef(
                byTarget,
                target,
                opcode == 0x8D
            );

            i +=
                instructionLength -
                1;
        }
    }

    std::vector<MapRipRefSummary> out;

    out.reserve(
        byTarget.size()
    );

    for (const auto& kv :
         byTarget)
    {
        out.push_back(
            kv.second
        );
    }

    std::sort(
        out.begin(),
        out.end(),
        [](
            const MapRipRefSummary& a,
            const MapRipRefSummary& b)
        {
            int aScore =
                a.leaRefs * 20 +
                a.movRefs;

            int bScore =
                b.leaRefs * 20 +
                b.movRefs;

            if (aScore != bScore)
                return aScore > bScore;

            return a.target < b.target;
        }
    );

    return out;
}

std::vector<MapBaseCandidate>
BuildMapBaseCandidates(
    uintptr_t centerAddress,
    const std::string& centerSection)
{
    std::vector<MapBaseCandidate> out;

    uintptr_t windowBegin =
        centerAddress > 0x1000
            ? centerAddress - 0x1000
            : g_exeBase;

    uintptr_t windowEnd =
        centerAddress +
        0x100;

    auto refs =
        CollectRipRefsToWindow(
            windowBegin,
            windowEnd
        );

    auto sections =
        GetModuleSections();

    for (const auto& ref :
         refs)
    {
        if (ref.target >=
            centerAddress)
        {
            continue;
        }

        uintptr_t centerOffset =
            centerAddress -
            ref.target;

        if (centerOffset < 0x80 ||
            centerOffset > 0x1000 ||
            (centerOffset & 3) != 0)
        {
            continue;
        }

        const ModuleSection* owner =
            nullptr;

        for (const auto& section :
             sections)
        {
            if (ref.target >=
                    section.begin &&
                ref.target <
                    section.end)
            {
                owner =
                    &section;

                break;
            }
        }

        if (!owner ||
            !owner->writable() ||
            owner->executable())
        {
            continue;
        }

        if (!centerSection.empty() &&
            owner->name !=
                centerSection)
        {
            continue;
        }

        int score =
            ref.leaRefs * 120 +
            ref.movRefs * 12;

        if ((ref.target & 0xF) == 0)
            score += 25;

        if ((centerOffset & 0xF) == 0)
            score += 10;

        if (centerOffset >= 0x100 &&
            centerOffset <= 0x800)
        {
            score += 20;
        }

        if (ref.leaRefs > 0)
            score += 30;

        MapBaseCandidate candidate{};

        candidate.address =
            ref.target;

        candidate.rva =
            ref.target -
            g_exeBase;

        candidate.centerOffset =
            centerOffset;

        candidate.leaRefs =
            ref.leaRefs;

        candidate.movRefs =
            ref.movRefs;

        candidate.score =
            score;

        out.push_back(
            std::move(candidate)
        );
    }

    std::sort(
        out.begin(),
        out.end(),
        [](
            const MapBaseCandidate& a,
            const MapBaseCandidate& b)
        {
            if (a.score != b.score)
                return a.score > b.score;

            if (a.leaRefs != b.leaRefs)
                return a.leaRefs > b.leaRefs;

            return a.rva < b.rva;
        }
    );

    return out;
}


struct MapOwnerDecision
{
    bool resolved = false;
    MapBaseCandidate selected{};
    std::vector<MapBaseCandidate> eligible;
    int maxLeaRefs = 0;
    int strongLeaThreshold = 0;
    std::string reason;
};

MapOwnerDecision ResolveMapOwnerCandidate(
    const DbProfile& profile,
    const std::vector<MapBaseCandidate>& candidates)
{
    MapOwnerDecision decision{};

    // A position field can be expressed relative to ANY earlier address in
    // .data. Therefore raw xref count alone is insufficient.
    //
    // First semantic rule:
    //   an already-confirmed Game object cannot be promoted again as Map.
    // If a future client really embeds Map inside Game, this resolver will
    // fail safely instead of silently relabeling Game as Map.
    for (const auto& candidate :
         candidates)
    {
        if (profile.gameRva &&
            candidate.rva ==
                profile.gameRva)
        {
            continue;
        }

        if (profile.directGlobalRva &&
            candidate.rva ==
                profile.directGlobalRva)
        {
            continue;
        }

        decision.eligible.push_back(
            candidate
        );

        decision.maxLeaRefs =
            std::max(
                decision.maxLeaRefs,
                candidate.leaRefs
            );
    }

    if (decision.eligible.empty())
    {
        decision.reason =
            "no eligible base after excluding confirmed semantic objects";

        return decision;
    }

    // Build a strong-reference cohort instead of letting a very popular,
    // unrelated global dominate merely by raw reference count.
    //
    // 35% of the strongest remaining LEA count, with a minimum of 8,
    // is intentionally conservative. It is not a Map offset assumption.
    decision.strongLeaThreshold =
        std::max(
            8,
            (
                decision.maxLeaRefs *
                35 +
                99
            ) /
            100
        );

    std::vector<MapBaseCandidate> strong;

    for (const auto& candidate :
         decision.eligible)
    {
        if (candidate.leaRefs >=
            decision.strongLeaThreshold)
        {
            strong.push_back(
                candidate
            );
        }
    }

    if (strong.empty())
    {
        decision.reason =
            "no base survived strong-reference cohort";

        return decision;
    }

    std::sort(
        strong.begin(),
        strong.end(),
        [](
            const MapBaseCandidate& a,
            const MapBaseCandidate& b)
        {
            // Once anchors are all strongly referenced, prefer the nearest
            // preceding object anchor to the confirmed center fields.
            // This prevents distant unrelated globals from winning simply
            // because they are referenced more often.
            if (a.centerOffset !=
                b.centerOffset)
            {
                return
                    a.centerOffset <
                    b.centerOffset;
            }

            if (a.leaRefs !=
                b.leaRefs)
            {
                return
                    a.leaRefs >
                    b.leaRefs;
            }

            return a.rva < b.rva;
        }
    );

    if (strong.size() == 1)
    {
        decision.resolved = true;
        decision.selected =
            strong[0];

        decision.reason =
            "single strong semantic owner";

        return decision;
    }

    const auto& best =
        strong[0];

    const auto& second =
        strong[1];

    // Require a meaningful structural gap before selecting the nearest owner.
    // Otherwise remain ambiguous and do not invent a Map base.
    const uintptr_t offsetGap =
        second.centerOffset >
                best.centerOffset
            ? second.centerOffset -
                best.centerOffset
            : 0;

    if (offsetGap >= 0x40)
    {
        decision.resolved = true;
        decision.selected =
            best;

        decision.reason =
            "nearest strong owner with structural separation";

        return decision;
    }

    decision.reason =
        "multiple strong owners remain too close";

    return decision;
}

void PrintMapBaseCandidates(
    const DbProfile& profile,
    const std::vector<MapBaseCandidate>& candidates)
{
    std::cout
        << "\n============================================================\n"
        << "                 MAP BASE CANDIDATES\n"
        << "============================================================\n";

    if (candidates.empty())
    {
        std::cout
            << "Nenhum owner/base forte encontrado por RIP-relative xrefs.\n";

        return;
    }

    for (size_t i = 0;
         i < candidates.size() &&
         i < 20;
         ++i)
    {
        const auto& c =
            candidates[i];

        std::cout
            << "#"
            << i
            << " score="
            << c.score
            << " baseRva="
            << HexU64(
                c.rva
            )
            << " centerOffset=+"
            << HexU64(
                c.centerOffset
            )
            << " LEA="
            << c.leaRefs
            << " MOV="
            << c.movRefs;

        if (c.rva ==
                profile.gameRva)
        {
            std::cout
                << "  <REJECT: CONFIRMED GAME>";
        }

        std::cout
            << "\n";
    }
}

bool DiscoverMap(
    DbProfile& profile)
{
    if (profile.mapStatus !=
            "discovered_runtime_selfcheck_pass")
    {
        profile.mapRva = 0;
        profile.mapCenterX = 0;
        profile.mapCenterY = 0;
        profile.mapCenterZ = 0;
        profile.mapNorth = 0;
        profile.mapEast = 0;
        profile.mapSouth = 0;
        profile.mapWest = 0;
        profile.mapStatus =
            "rediscovery_running";
    }

    std::cout
        << "\n============================================================\n"
        << "                 STAGE 4 - MAP DISCOVERY\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "[NO HOOK] Nenhum hook\n"
        << "[NO CALL] Nenhuma funcao interna do jogo\n"
        << "\n"
        << "Metodo:\n"
        << "  1. usa somente Position do LocalPlayer ja descoberta\n"
        << "  2. procura a mesma Position em secoes writable do modulo\n"
        << "  3. exige que o candidato acompanhe 2 mudancas reais de Position\n"
        << "  4. descobre Aware N/E/S/W por estrutura, sem offset fixo\n"
        << "  5. tenta resolver o inicio do objeto Map por RIP-relative xrefs\n";

    uintptr_t localPlayer =
        ResolveProfileLocalPlayerForDiscovery(
            profile
        );

    if (!localPlayer)
    {
        std::cout
            << "[STOP] LocalPlayer invalido para Stage 4.\n";

        return false;
    }

    MapPosition p0 =
        ReadDiscoveredPlayerPosition(
            localPlayer,
            profile
        );

    if (!MapPositionPlausible(
            p0))
    {
        std::cout
            << "[STOP] Player Position inicial implausivel.\n";

        return false;
    }

    std::cout
        << "Player Position #0   : "
        << p0.x
        << ","
        << p0.y
        << ","
        << static_cast<unsigned>(
            p0.z
        )
        << "\n";

    auto centers =
        FindModulePositionTriples(
            p0
        );

    std::cout
        << "Position triples #0  : "
        << centers.size()
        << "\n";

    if (centers.empty())
    {
        profile.mapStatus =
            "unresolved_no_position_triple";

        return false;
    }

    std::cout
        << "\nPASSO A - MOVIMENTO 1\n"
        << "Ande para outro SQM no MESMO andar. Pode andar varios SQMs.\n";

    MapPosition p1 =
        WaitForPlayerPositionChange(
            localPlayer,
            profile,
            p0,
            "Depois de andar, pressione ENTER..."
        );

    FilterMapCenterCandidatesByPosition(
        centers,
        p1
    );

    std::cout
        << "Player Position #1   : "
        << p1.x
        << ","
        << p1.y
        << ","
        << static_cast<unsigned>(
            p1.z
        )
        << "\n"
        << "Candidates after #1  : "
        << centers.size()
        << "\n";

    if (centers.empty())
    {
        profile.mapStatus =
            "unresolved_after_movement_1";

        return false;
    }

    std::cout
        << "\nPASSO B - MOVIMENTO 2\n"
        << "Ande novamente para OUTRO SQM, ainda no mesmo andar.\n";

    MapPosition p2 =
        WaitForPlayerPositionChange(
            localPlayer,
            profile,
            p1,
            "Depois do segundo movimento, pressione ENTER..."
        );

    FilterMapCenterCandidatesByPosition(
        centers,
        p2
    );

    std::cout
        << "Player Position #2   : "
        << p2.x
        << ","
        << p2.y
        << ","
        << static_cast<unsigned>(
            p2.z
        )
        << "\n"
        << "Candidates after #2  : "
        << centers.size()
        << "\n";

    if (centers.empty())
    {
        profile.mapStatus =
            "unresolved_after_movement_2";

        return false;
    }

    std::sort(
        centers.begin(),
        centers.end(),
        [](
            const MapCenterCandidate& a,
            const MapCenterCandidate& b)
        {
            if (a.movementHits !=
                b.movementHits)
            {
                return
                    a.movementHits >
                    b.movementHits;
            }

            return a.rva < b.rva;
        }
    );

    for (size_t i = 0;
         i < centers.size() &&
         i < 16;
         ++i)
    {
        std::cout
            << "  center["
            << i
            << "] RVA "
            << HexU64(
                centers[i].rva
            )
            << " section="
            << centers[i].section
            << " movementHits="
            << centers[i].movementHits
            << "\n";
    }

    if (centers.size() != 1)
    {
        profile.mapStatus =
            "center_anchor_ambiguous";

        std::cout
            << "\n[CHECK] Mais de um center anchor sobreviveu.\n"
            << "Nenhum mapRva sera inventado.\n";

        return false;
    }

    const MapCenterCandidate center =
        centers[0];

    std::cout
        << "\n[MAP CENTER ANCHOR]\n"
        << "Center RVA           : "
        << HexU64(
            center.rva
        )
        << "\n"
        << "Section              : "
        << center.section
        << "\n";

    auto aware =
        FindAwareCandidatesAroundCenter(
            center.address
        );

    std::cout
        << "\n============================================================\n"
        << "                  AWARE CANDIDATES\n"
        << "============================================================\n";

    for (size_t i = 0;
         i < aware.size() &&
         i < 12;
         ++i)
    {
        const auto& a =
            aware[i];

        std::cout
            << "#"
            << i
            << " score="
            << a.score
            << " relCenter=+"
            << HexU64(
                a.northOffsetFromCenter
            )
            << " N/E/S/W="
            << a.north
            << "/"
            << a.east
            << "/"
            << a.south
            << "/"
            << a.west
            << "\n";
    }

    if (aware.empty())
    {
        profile.mapStatus =
            "center_confirmed_aware_unresolved";

        return false;
    }

    bool awareStrong =
        aware.size() == 1 ||
        aware[0].score >=
            aware[1].score + 20;

    if (!awareStrong)
    {
        profile.mapStatus =
            "center_confirmed_aware_ambiguous";

        std::cout
            << "[CHECK] Aware range permaneceu ambiguo.\n";

        return false;
    }

    auto bases =
        BuildMapBaseCandidates(
            center.address,
            center.section
        );

    PrintMapBaseCandidates(
        profile,
        bases
    );

    if (bases.empty())
    {
        profile.mapStatus =
            "center_aware_confirmed_base_unresolved";

        std::cout
            << "\n[CHECK] Center + Aware encontrados, mas o inicio do objeto Map "
            << "ainda nao fechou por xref.\n";

        return false;
    }

    MapOwnerDecision owner =
        ResolveMapOwnerCandidate(
            profile,
            bases
        );

    std::cout
        << "\n============================================================\n"
        << "                 MAP OWNER RESOLUTION\n"
        << "============================================================\n"
        << "Confirmed Game RVA   : "
        << HexU64(
            profile.gameRva
        )
        << "\n"
        << "Eligible candidates  : "
        << owner.eligible.size()
        << "\n"
        << "Max LEA refs         : "
        << owner.maxLeaRefs
        << "\n"
        << "Strong threshold     : "
        << owner.strongLeaThreshold
        << "\n"
        << "Decision             : "
        << owner.reason
        << "\n";

    if (!owner.resolved)
    {
        profile.mapStatus =
            "center_aware_confirmed_base_ambiguous";

        std::cout
            << "[CHECK] Map owner ainda nao pode ser promovido com seguranca.\n";

        return false;
    }

    const MapBaseCandidate base =
        owner.selected;

    std::cout
        << "Selected Map base    : "
        << HexU64(
            base.rva
        )
        << "\n"
        << "Selected center off  : +"
        << HexU64(
            base.centerOffset
        )
        << "\n"
        << "Selected LEA/MOV     : "
        << base.leaRefs
        << "/"
        << base.movRefs
        << "\n";

    const MapAwareCandidate awareBest =
        aware[0];

    profile.mapRva =
        base.rva;

    profile.mapCenterX =
        base.centerOffset;

    profile.mapCenterY =
        base.centerOffset +
        4;

    profile.mapCenterZ =
        base.centerOffset +
        8;

    profile.mapNorth =
        base.centerOffset +
        awareBest.northOffsetFromCenter;

    profile.mapEast =
        profile.mapNorth +
        4;

    profile.mapSouth =
        profile.mapNorth +
        8;

    profile.mapWest =
        profile.mapNorth +
        12;

    profile.mapStatus =
        "confirmed_runtime_position_transitions";

    std::cout
        << "\n============================================================\n"
        << "                     MAP DISCOVERED\n"
        << "============================================================\n"
        << "Map RVA              : "
        << HexU64(
            profile.mapRva
        )
        << "\n"
        << "Center X/Y/Z         : +"
        << HexU64(
            profile.mapCenterX
        )
        << " / +"
        << HexU64(
            profile.mapCenterY
        )
        << " / +"
        << HexU64(
            profile.mapCenterZ
        )
        << "\n"
        << "Aware N/E/S/W        : +"
        << HexU64(
            profile.mapNorth
        )
        << " / +"
        << HexU64(
            profile.mapEast
        )
        << " / +"
        << HexU64(
            profile.mapSouth
        )
        << " / +"
        << HexU64(
            profile.mapWest
        )
        << "\n"
        << "Aware values         : "
        << awareBest.north
        << "/"
        << awareBest.east
        << "/"
        << awareBest.south
        << "/"
        << awareBest.west
        << "\n"
        << "Evidence             : Player Position followed twice + static owner xrefs\n"
        << "Status               : "
        << profile.mapStatus
        << "\n";

    // Benchmark only AFTER discovery.
    const bool knownBenchmarkBuild =
        profile.timestamp == 0x6AA9FA57ULL &&
        profile.sizeOfImage == 0x17BF000ULL &&
        profile.textHash == 0x89D3D35243890EA2ULL;

    if (knownBenchmarkBuild)
    {
        const bool rvaMatch =
            profile.mapRva ==
            0x169A860;

        const bool centerMatch =
            profile.mapCenterX == 0x340 &&
            profile.mapCenterY == 0x344 &&
            profile.mapCenterZ == 0x348;

        const bool awareMatch =
            profile.mapNorth == 0x368 &&
            profile.mapEast == 0x36C &&
            profile.mapSouth == 0x370 &&
            profile.mapWest == 0x374;

        std::cout
            << "\n[GROUND TRUTH COMPARISON]\n"
            << "Known Map RVA        : 0x169A860\n"
            << "Map RVA match        : "
            << (
                rvaMatch
                    ? "PASS"
                    : "FAIL"
            )
            << "\n"
            << "Center offsets match : "
            << (
                centerMatch
                    ? "PASS"
                    : "FAIL"
            )
            << "\n"
            << "Aware offsets match  : "
            << (
                awareMatch
                    ? "PASS"
                    : "FAIL"
            )
            << "\n";

        if (rvaMatch &&
            centerMatch &&
            awareMatch)
        {
            profile.mapStatus =
                "discovered_runtime_selfcheck_pass";

            std::cout
                << "\n[FEITO] STAGE 4 redescobriu Map sem usar a resposta antiga.\n";
        }
        else
        {
            profile.mapStatus =
                "discovered_runtime_selfcheck_mismatch";

            std::cout
                << "[PRESERVE] Self-check falhou; candidato Map nao sera promovido no profile.\n";

            profile.mapRva = 0;
            profile.mapCenterX = 0;
            profile.mapCenterY = 0;
            profile.mapCenterZ = 0;
            profile.mapNorth = 0;
            profile.mapEast = 0;
            profile.mapSouth = 0;
            profile.mapWest = 0;
        }
    }

    return
        profile.mapStatus ==
            "discovered_runtime_selfcheck_pass" ||
        profile.mapStatus ==
            "confirmed_runtime_position_transitions";
}

bool EnsureMapDiscovery(
    DbProfile& profile,
    std::vector<DbProfile>& database,
    int profileIndex,
    const std::string& databasePath)
{
    if (profile.mapRva &&
        (
            profile.mapStatus ==
                "discovered_runtime_selfcheck_pass" ||
            profile.mapStatus ==
                "confirmed_runtime_position_transitions"
        ))
    {
        std::cout
            << "\n[FEITO] STAGE 4 - Map ja passou self-check.\n"
            << "Map RVA        : "
            << HexU64(
                profile.mapRva
            )
            << "\n";

        return true;
    }

    uintptr_t localPlayer =
        WaitForDiscoveryLocalPlayer(
            profile,
            "STAGE 4 - MAP"
        );

    if (!localPlayer)
    {
        std::cout
            << "\n[STAGE 4] Cancelada antes do login.\n";

        return false;
    }

    bool ok =
        DiscoverMap(
            profile
        );

    if (profileIndex >= 0 &&
        profileIndex <
            static_cast<int>(
                database.size()
            ))
    {
        database[
            static_cast<size_t>(
                profileIndex
            )
        ] = profile;

        SaveProfileDatabase(
            databasePath,
            database
        );
    }

    return ok;
}


// ============================================================
// DISCOVERY V2.3 - TILE::THINGS (STRICT READ-ONLY)
// ============================================================

struct TileScanRegion
{
    uintptr_t base = 0;
    size_t size = 0;
};

struct TileVectorCandidate
{
    uintptr_t objectBase = 0;
    uintptr_t vectorHeader = 0;
    uintptr_t vectorOffset = 0;

    uintptr_t begin = 0;
    uintptr_t end = 0;
    uintptr_t cap = 0;

    uintptr_t vtable = 0;

    size_t count = 0;
    size_t capacity = 0;

    int score = 0;
};


std::string ReadBoundedAscii(
    uintptr_t address,
    size_t maxLength)
{
    std::string out;

    if (!address ||
        !maxLength)
    {
        return out;
    }

    out.reserve(
        std::min<size_t>(
            maxLength,
            128
        )
    );

    for (size_t i = 0;
         i < maxLength;
         ++i)
    {
        char c = 0;

        if (!SafeRead(
                address + i,
                c))
        {
            break;
        }

        if (!c)
            break;

        unsigned char uc =
            static_cast<unsigned char>(
                c
            );

        if (uc < 0x20 ||
            uc > 0x7E)
        {
            return std::string();
        }

        out.push_back(
            c
        );
    }

    return out;
}

std::string TryReadMsvcRttiTypeName(
    uintptr_t vtable)
{
    if (!vtable ||
        vtable < sizeof(uintptr_t))
    {
        return std::string();
    }

    uintptr_t col =
        ReadPtr(
            vtable -
            sizeof(uintptr_t)
        );

    if (!col ||
        !InsideExeImage(
            col))
    {
        return std::string();
    }

    uint32_t signature = 0;
    uint32_t objectOffset = 0;
    uint32_t cdOffset = 0;
    int32_t typeDescriptorRva = 0;
    int32_t classDescriptorRva = 0;
    int32_t selfRva = 0;

    if (!SafeRead(
            col + 0x00,
            signature) ||
        !SafeRead(
            col + 0x04,
            objectOffset) ||
        !SafeRead(
            col + 0x08,
            cdOffset) ||
        !SafeRead(
            col + 0x0C,
            typeDescriptorRva) ||
        !SafeRead(
            col + 0x10,
            classDescriptorRva) ||
        !SafeRead(
            col + 0x14,
            selfRva))
    {
        return std::string();
    }

    // MSVC x64 CompleteObjectLocator normally uses signature 1 and
    // image-relative references. Some builds may expose signature 0;
    // in that case we do not guess.
    if (signature != 1)
    {
        return std::string();
    }

    if (selfRva <= 0 ||
        g_exeBase +
            static_cast<uintptr_t>(
                static_cast<uint32_t>(
                    selfRva
                )
            ) != col)
    {
        return std::string();
    }

    if (typeDescriptorRva <= 0)
    {
        return std::string();
    }

    uintptr_t typeDescriptor =
        g_exeBase +
        static_cast<uintptr_t>(
            static_cast<uint32_t>(
                typeDescriptorRva
            )
        );

    if (!InsideExeImage(
            typeDescriptor))
    {
        return std::string();
    }

    // MSVC TypeDescriptor on x64:
    //   +0x00 pVFTable
    //   +0x08 spare
    //   +0x10 decorated class name
    return
        ReadBoundedAscii(
            typeDescriptor +
            0x10,
            160
        );
}


bool IsReadableMonitorRange(
    uintptr_t address,
    size_t size);

struct V35MsvcObjectIdentity
{
    uintptr_t pointer = 0;
    uintptr_t vtable = 0;
    uintptr_t completeObject = 0;
    uint32_t subobjectOffset = 0;
    std::string rttiName;
    bool valid = false;
};

bool V35DescribeMsvcObject(
    uintptr_t pointer,
    V35MsvcObjectIdentity& out)
{
    out = {};

    if (!pointer ||
        !IsReadableMonitorRange(
            pointer,
            sizeof(uintptr_t)))
    {
        return false;
    }

    uintptr_t vtable =
        ReadPtr(
            pointer
        );

    if (!InsideExeImage(
            vtable) ||
        vtable < sizeof(uintptr_t))
    {
        return false;
    }

    uintptr_t col =
        ReadPtr(
            vtable -
            sizeof(uintptr_t)
        );

    if (!col ||
        !InsideExeImage(
            col))
    {
        return false;
    }

    uint32_t signature = 0;
    uint32_t objectOffset = 0;
    int32_t selfRva = 0;

    if (!SafeRead(
            col + 0x00,
            signature) ||
        !SafeRead(
            col + 0x04,
            objectOffset) ||
        !SafeRead(
            col + 0x14,
            selfRva))
    {
        return false;
    }

    if (signature != 1 ||
        selfRva <= 0 ||
        g_exeBase +
            static_cast<uintptr_t>(
                static_cast<uint32_t>(
                    selfRva
                )
            ) != col)
    {
        return false;
    }

    if (pointer <
        static_cast<uintptr_t>(
            objectOffset))
    {
        return false;
    }

    uintptr_t complete =
        pointer -
        static_cast<uintptr_t>(
            objectOffset);

    if (!IsReadableMonitorRange(
            complete,
            sizeof(uintptr_t)))
    {
        return false;
    }

    out.pointer =
        pointer;

    out.vtable =
        vtable;

    out.completeObject =
        complete;

    out.subobjectOffset =
        objectOffset;

    out.rttiName =
        TryReadMsvcRttiTypeName(
            vtable
        );

    if (out.rttiName.empty())
        out.rttiName = "<unavailable>";

    out.valid =
        true;

    return true;
}

uintptr_t V35CompleteObjectPointer(
    uintptr_t pointer)
{
    V35MsvcObjectIdentity id{};

    if (V35DescribeMsvcObject(
            pointer,
            id))
    {
        return
            id.completeObject;
    }

    return pointer;
}

bool V35SameCompleteObject(
    uintptr_t a,
    uintptr_t b)
{
    if (!a ||
        !b)
    {
        return false;
    }

    return
        V35CompleteObjectPointer(
            a) ==
        V35CompleteObjectPointer(
            b);
}

bool V35RttiHasToken(
    uintptr_t pointer,
    const std::string& token)
{
    V35MsvcObjectIdentity id{};

    if (!V35DescribeMsvcObject(
            pointer,
            id))
    {
        return false;
    }

    std::string rtti =
        id.rttiName;

    std::string wanted =
        token;

    std::transform(
        rtti.begin(),
        rtti.end(),
        rtti.begin(),
        [](
            unsigned char c)
        {
            return
                static_cast<char>(
                    std::tolower(c)
                );
        }
    );

    std::transform(
        wanted.begin(),
        wanted.end(),
        wanted.begin(),
        [](
            unsigned char c)
        {
            return
                static_cast<char>(
                    std::tolower(c)
                );
        }
    );

    // A shared_ptr control block can have RTTI such as
    // _Ref_count_obj2<VItem>. The class token "item" is present there,
    // but the pointer is NOT an Item object. Never promote those wrappers
    // as semantic objects.
    if (rtti.find(
            "_ref_count") !=
            std::string::npos ||
        rtti.find(
            "shared_ptr") !=
            std::string::npos)
    {
        return false;
    }

    return
        rtti.find(
            wanted) !=
        std::string::npos;
}


std::string LowerAscii(
    const std::string& value)
{
    std::string out =
        value;

    std::transform(
        out.begin(),
        out.end(),
        out.begin(),
        [](
            unsigned char c)
        {
            return
                static_cast<char>(
                    std::tolower(c)
                );
        }
    );

    return out;
}

bool RttiLooksExactlyLikeTileClass(
    const std::string& rtti)
{
    if (rtti.empty())
        return false;

    // Common MSVC decorated class/struct forms:
    //   .?AVTile@@
    //   .?AVTile@namespace@@
    //   .?AUTile@@
    //   .?AUTile@namespace@@
    //
    // This is semantic class-name evidence, not an offset/vtable seed.
    return
        rtti.find("?AVTile@") !=
            std::string::npos ||
        rtti.find("?AUTile@") !=
            std::string::npos;
}


// V3.4.1 - forward declarations.
// The RTTI-first resolver is intentionally located before the legacy
// heap helpers, so declare the two read-only helpers it reuses here.
bool ReadProcessChunk(
    uintptr_t address,
    void* buffer,
    size_t size,
    size_t& bytesRead);

bool LooksLikeObjectVtable(
    uintptr_t vtable);


std::vector<uintptr_t>
FindMsvcVtablesByExactRttiName(
    const std::string& exactName)
{
    std::vector<uintptr_t> result;

    if (exactName.empty() ||
        !g_exeBase ||
        !g_imageEnd ||
        g_imageEnd <= g_exeBase)
    {
        return result;
    }

    auto sections =
        GetModuleSections();

    std::vector<uintptr_t>
        typeDescriptors;

    const std::string needle =
        exactName +
        std::string(
            1,
            '\0'
        );

    const size_t chunkSize =
        2 * 1024 * 1024;

    std::vector<uint8_t>
        buffer(
            chunkSize +
            needle.size()
        );

    // --------------------------------------------------------
    // 1. Find TypeDescriptor decorated names.
    // --------------------------------------------------------
    for (const auto& section :
         sections)
    {
        if (!section.readable())
            continue;

        uintptr_t cursor =
            section.begin;

        while (cursor <
               section.end)
        {
            size_t want =
                static_cast<size_t>(
                    std::min<uintptr_t>(
                        chunkSize,
                        section.end -
                        cursor
                    )
                );

            size_t got = 0;

            if (!ReadProcessChunk(
                    cursor,
                    buffer.data(),
                    want,
                    got))
            {
                cursor += want;
                continue;
            }

            if (got >=
                needle.size())
            {
                for (size_t off = 0;
                     off + needle.size() <= got;
                     ++off)
                {
                    if (std::memcmp(
                            buffer.data() + off,
                            needle.data(),
                            needle.size()) != 0)
                    {
                        continue;
                    }

                    uintptr_t nameAddress =
                        cursor +
                        off;

                    if (nameAddress <
                        g_exeBase + 0x10)
                    {
                        continue;
                    }

                    uintptr_t typeDescriptor =
                        nameAddress -
                        0x10;

                    if (InsideExeImage(
                            typeDescriptor))
                    {
                        typeDescriptors.push_back(
                            typeDescriptor
                        );
                    }
                }
            }

            cursor += got;
        }
    }

    std::sort(
        typeDescriptors.begin(),
        typeDescriptors.end()
    );

    typeDescriptors.erase(
        std::unique(
            typeDescriptors.begin(),
            typeDescriptors.end()
        ),
        typeDescriptors.end()
    );

    if (typeDescriptors.empty())
        return result;

    std::vector<uintptr_t>
        completeObjectLocators;

    // --------------------------------------------------------
    // 2. Find MSVC x64 CompleteObjectLocator structures whose
    //    pTypeDescriptor RVA points to the exact Tile TypeDescriptor.
    // --------------------------------------------------------
    for (uintptr_t td :
         typeDescriptors)
    {
        const uint32_t tdRva =
            static_cast<uint32_t>(
                td -
                g_exeBase
            );

        for (const auto& section :
             sections)
        {
            if (!section.readable())
                continue;

            uintptr_t cursor =
                section.begin;

            while (cursor <
                   section.end)
            {
                size_t want =
                    static_cast<size_t>(
                        std::min<uintptr_t>(
                            chunkSize,
                            section.end -
                            cursor
                        )
                    );

                size_t got = 0;

                if (!ReadProcessChunk(
                        cursor,
                        buffer.data(),
                        want,
                        got))
                {
                    cursor += want;
                    continue;
                }

                for (size_t off = 0;
                     off + sizeof(uint32_t) <= got;
                     off += 4)
                {
                    uint32_t value = 0;

                    std::memcpy(
                        &value,
                        buffer.data() + off,
                        sizeof(value)
                    );

                    if (value !=
                        tdRva)
                    {
                        continue;
                    }

                    uintptr_t fieldAddress =
                        cursor +
                        off;

                    if (fieldAddress <
                        g_exeBase + 0x0C)
                    {
                        continue;
                    }

                    uintptr_t col =
                        fieldAddress -
                        0x0C;

                    uint32_t signature = 0;
                    int32_t typeRva = 0;
                    int32_t selfRva = 0;

                    if (!SafeRead(
                            col + 0x00,
                            signature) ||
                        !SafeRead(
                            col + 0x0C,
                            typeRva) ||
                        !SafeRead(
                            col + 0x14,
                            selfRva))
                    {
                        continue;
                    }

                    if (signature != 1 ||
                        static_cast<uint32_t>(
                            typeRva) !=
                            tdRva ||
                        selfRva <= 0 ||
                        g_exeBase +
                            static_cast<uintptr_t>(
                                static_cast<uint32_t>(
                                    selfRva
                                )
                            ) != col)
                    {
                        continue;
                    }

                    completeObjectLocators.push_back(
                        col
                    );
                }

                cursor += got;
            }
        }
    }

    std::sort(
        completeObjectLocators.begin(),
        completeObjectLocators.end()
    );

    completeObjectLocators.erase(
        std::unique(
            completeObjectLocators.begin(),
            completeObjectLocators.end()
        ),
        completeObjectLocators.end()
    );

    if (completeObjectLocators.empty())
        return result;

    // --------------------------------------------------------
    // 3. vtable[-1] contains the absolute COL pointer.
    // --------------------------------------------------------
    for (uintptr_t col :
         completeObjectLocators)
    {
        for (const auto& section :
             sections)
        {
            if (!section.readable())
                continue;

            uintptr_t cursor =
                section.begin;

            while (cursor <
                   section.end)
            {
                size_t want =
                    static_cast<size_t>(
                        std::min<uintptr_t>(
                            chunkSize,
                            section.end -
                            cursor
                        )
                    );

                size_t got = 0;

                if (!ReadProcessChunk(
                        cursor,
                        buffer.data(),
                        want,
                        got))
                {
                    cursor += want;
                    continue;
                }

                uintptr_t aligned =
                    (cursor + 7) &
                    ~static_cast<uintptr_t>(7);

                size_t start =
                    static_cast<size_t>(
                        aligned -
                        cursor
                    );

                for (size_t off = start;
                     off + sizeof(uintptr_t) <= got;
                     off += 8)
                {
                    uintptr_t value = 0;

                    std::memcpy(
                        &value,
                        buffer.data() + off,
                        sizeof(value)
                    );

                    if (value !=
                        col)
                    {
                        continue;
                    }

                    uintptr_t vtable =
                        cursor +
                        off +
                        sizeof(uintptr_t);

                    if (!InsideExeImage(
                            vtable) ||
                        !LooksLikeObjectVtable(
                            vtable))
                    {
                        continue;
                    }

                    std::string rtti =
                        TryReadMsvcRttiTypeName(
                            vtable
                        );

                    if (rtti ==
                        exactName)
                    {
                        result.push_back(
                            vtable
                        );
                    }
                }

                cursor += got;
            }
        }
    }

    std::sort(
        result.begin(),
        result.end()
    );

    result.erase(
        std::unique(
            result.begin(),
            result.end()
        ),
        result.end()
    );

    return result;
}

std::vector<TileVectorCandidate>
FindTileCandidatesByExactRttiAnchor(
    uintptr_t localPlayer,
    const std::vector<TileScanRegion>& regions)
{
    std::vector<TileVectorCandidate>
        out;

    auto tileVtables =
        FindMsvcVtablesByExactRttiName(
            ".?AVTile@@"
        );

    std::cout
        << "[RTTI TILE ANCHOR] exact Tile vtables="
        << tileVtables.size()
        << "\n";

    for (uintptr_t vt :
         tileVtables)
    {
        std::cout
            << "  vtableRva="
            << HexU64(
                vt -
                g_exeBase
            )
            << " rtti=\\\""
            << TryReadMsvcRttiTypeName(
                vt
            )
            << "\\\"\n";
    }

    if (tileVtables.empty())
        return out;

    std::unordered_set<uintptr_t>
        wantedVtables(
            tileVtables.begin(),
            tileVtables.end()
        );

    const size_t chunkSize =
        4 * 1024 * 1024;

    std::vector<uint8_t>
        buffer(
            chunkSize
        );

    size_t objectHits = 0;

    for (const auto& region :
         regions)
    {
        uintptr_t cursor =
            region.base;

        uintptr_t regionEnd =
            region.base +
            region.size;

        while (cursor <
               regionEnd)
        {
            size_t want =
                static_cast<size_t>(
                    std::min<uintptr_t>(
                        chunkSize,
                        regionEnd -
                        cursor
                    )
                );

            size_t got = 0;

            if (!ReadProcessChunk(
                    cursor,
                    buffer.data(),
                    want,
                    got))
            {
                cursor += want;
                continue;
            }

            uintptr_t aligned =
                (cursor + 7) &
                ~static_cast<uintptr_t>(7);

            size_t start =
                static_cast<size_t>(
                    aligned -
                    cursor
                );

            for (size_t off = start;
                 off + sizeof(uintptr_t) <= got;
                 off += 8)
            {
                uintptr_t value = 0;

                std::memcpy(
                    &value,
                    buffer.data() + off,
                    sizeof(value)
                );

                if (wantedVtables.find(
                        value) ==
                    wantedVtables.end())
                {
                    continue;
                }

                uintptr_t object =
                    cursor +
                    off;

                ++objectHits;

                for (uintptr_t vectorOffset = 0x10;
                     vectorOffset <= 0xC0;
                     vectorOffset += 8)
                {
                    uintptr_t header =
                        object +
                        vectorOffset;

                    uintptr_t begin = 0;
                    uintptr_t end = 0;
                    uintptr_t cap = 0;

                    if (!SafeRead(
                            header,
                            begin) ||
                        !SafeRead(
                            header + 8,
                            end) ||
                        !SafeRead(
                            header + 16,
                            cap))
                    {
                        continue;
                    }

                    if (!begin ||
                        end < begin ||
                        cap < end ||
                        (begin & 7) ||
                        (end & 7) ||
                        (cap & 7))
                    {
                        continue;
                    }

                    uintptr_t used =
                        end -
                        begin;

                    uintptr_t capacityBytes =
                        cap -
                        begin;

                    if (used % 8 != 0 ||
                        capacityBytes % 8 != 0)
                    {
                        continue;
                    }

                    size_t count =
                        static_cast<size_t>(
                            used / 8
                        );

                    size_t capacity =
                        static_cast<size_t>(
                            capacityBytes / 8
                        );

                    if (!count ||
                        count > 128 ||
                        capacity < count ||
                        capacity > 256)
                    {
                        continue;
                    }

                    if (!IsReadableMonitorRange(
                            begin,
                            used))
                    {
                        continue;
                    }

                    bool containsLocal =
                        false;

                    for (size_t i = 0;
                         i < count;
                         ++i)
                    {
                        if (ReadPtr(
                                begin +
                                i * 8) ==
                            localPlayer)
                        {
                            containsLocal =
                                true;

                            break;
                        }
                    }

                    if (!containsLocal)
                        continue;

                    TileVectorCandidate c{};

                    c.objectBase =
                        object;

                    c.vectorHeader =
                        header;

                    c.vectorOffset =
                        vectorOffset;

                    c.begin =
                        begin;

                    c.end =
                        end;

                    c.cap =
                        cap;

                    c.vtable =
                        value;

                    c.count =
                        count;

                    c.capacity =
                        capacity;

                    c.score =
                        3000;

                    out.push_back(
                        c
                    );
                }
            }

            cursor += got;
        }
    }

    std::cout
        << "[RTTI TILE ANCHOR] heap Tile objects="
        << objectHits
        << " vectors containing LocalPlayer="
        << out.size()
        << "\n";

    return out;
}


bool RttiContainsTileToken(
    const std::string& rtti)
{
    if (rtti.empty())
        return false;

    std::string lower =
        LowerAscii(
            rtti
        );

    return
        lower.find("tile") !=
        std::string::npos;
}

struct TileLayoutAggregate
{
    uintptr_t vectorOffset = 0;
    uintptr_t vtable = 0;

    int pairCount = 0;
    int score = 0;

    uintptr_t localTile = 0;
    uintptr_t targetTile = 0;
};

bool TileScanReadableProtection(
    DWORD protect)
{
    if (protect & PAGE_GUARD)
        return false;

    if (protect & PAGE_NOACCESS)
        return false;

    DWORD base =
        protect & 0xFF;

    return
        base == PAGE_READWRITE ||
        base == PAGE_WRITECOPY;
}

std::vector<TileScanRegion>
EnumerateTileHeapRegions()
{
    std::vector<TileScanRegion> out;

    SYSTEM_INFO si{};
    GetSystemInfo(
        &si
    );

    uintptr_t cursor =
        reinterpret_cast<uintptr_t>(
            si.lpMinimumApplicationAddress
        );

    uintptr_t maxAddress =
        reinterpret_cast<uintptr_t>(
            si.lpMaximumApplicationAddress
        );

    size_t total =
        0;

    const size_t maxTotal =
        static_cast<size_t>(
            2ULL *
            1024ULL *
            1024ULL *
            1024ULL
        );

    while (cursor <
           maxAddress)
    {
        MEMORY_BASIC_INFORMATION mbi{};

        if (!VirtualQuery(
                reinterpret_cast<const void*>(
                    cursor
                ),
                &mbi,
                sizeof(mbi)))
        {
            break;
        }

        uintptr_t base =
            reinterpret_cast<uintptr_t>(
                mbi.BaseAddress
            );

        size_t size =
            static_cast<size_t>(
                mbi.RegionSize
            );

        uintptr_t next =
            base +
            size;

        if (next <= cursor)
            break;

        bool suitable =
            mbi.State == MEM_COMMIT &&
            mbi.Type == MEM_PRIVATE &&
            TileScanReadableProtection(
                mbi.Protect
            );

        if (suitable &&
            size >= 0x1000)
        {
            if (total + size >
                maxTotal)
            {
                size =
                    maxTotal -
                    total;
            }

            if (size)
            {
                out.push_back(
                    {
                        base,
                        size
                    }
                );

                total +=
                    size;
            }

            if (total >=
                maxTotal)
            {
                break;
            }
        }

        cursor =
            next;
    }

    return out;
}

bool ReadProcessChunk(
    uintptr_t address,
    void* buffer,
    size_t size,
    size_t& bytesRead)
{
    bytesRead = 0;

    SIZE_T got = 0;

    BOOL ok =
        ReadProcessMemory(
            GetCurrentProcess(),
            reinterpret_cast<const void*>(
                address
            ),
            buffer,
            size,
            &got
        );

    bytesRead =
        static_cast<size_t>(
            got
        );

    return
        ok != FALSE &&
        bytesRead != 0;
}

std::vector<uintptr_t>
FindNeedleOccurrencesInTileHeap(
    uintptr_t needle,
    const std::vector<TileScanRegion>& regions,
    size_t maxOccurrences = 4096)
{
    std::vector<uintptr_t> out;

    if (!needle)
        return out;

    const size_t chunkSize =
        4 * 1024 * 1024;

    std::vector<uint8_t> buffer(
        chunkSize
    );

    size_t scannedBytes = 0;

    for (const auto& region :
         regions)
    {
        uintptr_t cursor =
            region.base;

        uintptr_t end =
            region.base +
            region.size;

        while (cursor <
               end)
        {
            size_t want =
                static_cast<size_t>(
                    std::min<uintptr_t>(
                        chunkSize,
                        end -
                        cursor
                    )
                );

            size_t got = 0;

            if (!ReadProcessChunk(
                    cursor,
                    buffer.data(),
                    want,
                    got))
            {
                cursor +=
                    want;

                continue;
            }

            scannedBytes +=
                got;

            uintptr_t aligned =
                (cursor + 7) &
                ~static_cast<uintptr_t>(7);

            size_t start =
                static_cast<size_t>(
                    aligned -
                    cursor
                );

            for (size_t off = start;
                 off + sizeof(uintptr_t) <= got;
                 off += 8)
            {
                uintptr_t value = 0;

                std::memcpy(
                    &value,
                    buffer.data() +
                        off,
                    sizeof(value)
                );

                if (value ==
                    needle)
                {
                    out.push_back(
                        cursor +
                        off
                    );

                    if (out.size() >=
                        maxOccurrences)
                    {
                        std::cout
                            << "[SCAN] Needle occurrence limit reached: "
                            << maxOccurrences
                            << "\n";

                        std::fill(
                            buffer.begin(),
                            buffer.end(),
                            0
                        );

                        return out;
                    }
                }
            }

            cursor +=
                got;
        }
    }

    std::cout
        << "[SCAN] Private heap scanned: "
        << (
            scannedBytes /
            (1024 * 1024)
        )
        << " MB"
        << " | needle occurrences="
        << out.size()
        << "\n";

    std::fill(
        buffer.begin(),
        buffer.end(),
        0
    );

    return out;
}

bool AddressInExecutableModuleSection(
    uintptr_t address)
{
    if (!InsideExeImage(
            address))
    {
        return false;
    }

    auto sections =
        GetModuleSections();

    for (const auto& section :
         sections)
    {
        if (address >=
                section.begin &&
            address <
                section.end)
        {
            return
                section.executable();
        }
    }

    return false;
}

bool AddressInReadOnlyModuleSection(
    uintptr_t address)
{
    if (!InsideExeImage(
            address))
    {
        return false;
    }

    auto sections =
        GetModuleSections();

    for (const auto& section :
         sections)
    {
        if (address >=
                section.begin &&
            address <
                section.end)
        {
            return
                section.readable() &&
                !section.writable() &&
                !section.executable();
        }
    }

    return false;
}

bool LooksLikeObjectVtable(
    uintptr_t vtable)
{
    if (!vtable ||
        !AddressInReadOnlyModuleSection(
            vtable))
    {
        return false;
    }

    int executableSlots = 0;

    for (uintptr_t off = 0;
         off < 5 * sizeof(uintptr_t);
         off += sizeof(uintptr_t))
    {
        uintptr_t fn =
            ReadPtr(
                vtable +
                off
            );

        if (AddressInExecutableModuleSection(
                fn))
        {
            ++executableSlots;
        }
    }

    return
        executableSlots >= 3;
}

bool VectorContainsNeedleOccurrence(
    uintptr_t begin,
    uintptr_t end,
    uintptr_t needle,
    const std::vector<uintptr_t>& occurrences)
{
    if (!begin ||
        end <= begin)
    {
        return false;
    }

    for (uintptr_t occurrence :
         occurrences)
    {
        if (occurrence <
                begin ||
            occurrence >=
                end)
        {
            continue;
        }

        if ((occurrence - begin) %
                sizeof(uintptr_t) !=
            0)
        {
            continue;
        }

        uintptr_t value =
            ReadPtr(
                occurrence
            );

        if (value ==
            needle)
        {
            return true;
        }
    }

    return false;
}

std::vector<TileVectorCandidate>
FindTileVectorCandidatesForNeedle(
    uintptr_t needle,
    const std::vector<TileScanRegion>& regions)
{
    std::vector<TileVectorCandidate> out;

    size_t rawVectorHeaders = 0;
    size_t polymorphicOwnerHits = 0;

    auto occurrences =
        FindNeedleOccurrencesInTileHeap(
            needle,
            regions
        );

    if (occurrences.empty())
        return out;

    std::unordered_set<uintptr_t>
        possibleBegins;

    for (uintptr_t occurrence :
         occurrences)
    {
        for (size_t index = 0;
             index < 64;
             ++index)
        {
            uintptr_t delta =
                index *
                sizeof(uintptr_t);

            if (occurrence <
                delta)
            {
                break;
            }

            possibleBegins.insert(
                occurrence -
                delta
            );
        }
    }

    std::unordered_set<uintptr_t>
        seenHeaders;

    const size_t chunkSize =
        4 * 1024 * 1024;

    std::vector<uint8_t> buffer(
        chunkSize
    );

    for (const auto& region :
         regions)
    {
        uintptr_t cursor =
            region.base;

        uintptr_t regionEnd =
            region.base +
            region.size;

        while (cursor <
               regionEnd)
        {
            size_t want =
                static_cast<size_t>(
                    std::min<uintptr_t>(
                        chunkSize,
                        regionEnd -
                        cursor
                    )
                );

            size_t got = 0;

            if (!ReadProcessChunk(
                    cursor,
                    buffer.data(),
                    want,
                    got))
            {
                cursor +=
                    want;

                continue;
            }

            uintptr_t aligned =
                (cursor + 7) &
                ~static_cast<uintptr_t>(7);

            size_t start =
                static_cast<size_t>(
                    aligned -
                    cursor
                );

            for (size_t off = start;
                 off + sizeof(uintptr_t) <= got;
                 off += 8)
            {
                uintptr_t begin = 0;

                std::memcpy(
                    &begin,
                    buffer.data() +
                        off,
                    sizeof(begin)
                );

                if (possibleBegins.find(
                        begin) ==
                    possibleBegins.end())
                {
                    continue;
                }

                uintptr_t header =
                    cursor +
                    off;

                if (!seenHeaders.insert(
                        header).second)
                {
                    continue;
                }

                uintptr_t end = 0;
                uintptr_t cap = 0;

                if (!SafeRead(
                        header + 8,
                        end) ||
                    !SafeRead(
                        header + 16,
                        cap))
                {
                    continue;
                }

                if (!begin ||
                    end < begin ||
                    cap < end)
                {
                    continue;
                }

                if ((begin & 7) ||
                    (end & 7) ||
                    (cap & 7))
                {
                    continue;
                }

                uintptr_t usedBytes =
                    end -
                    begin;

                uintptr_t capBytes =
                    cap -
                    begin;

                if (usedBytes %
                        sizeof(uintptr_t) !=
                    0 ||
                    capBytes %
                        sizeof(uintptr_t) !=
                    0)
                {
                    continue;
                }

                size_t count =
                    static_cast<size_t>(
                        usedBytes /
                        sizeof(uintptr_t)
                    );

                size_t capacity =
                    static_cast<size_t>(
                        capBytes /
                        sizeof(uintptr_t)
                    );

                if (!count ||
                    count > 128 ||
                    capacity < count ||
                    capacity > 256)
                {
                    continue;
                }

                if (!VectorContainsNeedleOccurrence(
                        begin,
                        end,
                        needle,
                        occurrences))
                {
                    continue;
                }

                ++rawVectorHeaders;

                // Recover an enclosing polymorphic object by scanning
                // backward from the vector header. We do not assume the
                // Tile::things offset here.
                for (uintptr_t vectorOffset = 0x10;
                     vectorOffset <= 0xC0;
                     vectorOffset += 8)
                {
                    if (header <
                        vectorOffset)
                    {
                        break;
                    }

                    uintptr_t objectBase =
                        header -
                        vectorOffset;

                    if (!IsReadableMonitorRange(
                            objectBase,
                            0x80))
                    {
                        continue;
                    }

                    uintptr_t vtable =
                        ReadPtr(
                            objectBase
                        );

                    if (!LooksLikeObjectVtable(
                            vtable))
                    {
                        continue;
                    }

                    int score = 100;

                    if (vectorOffset >= 0x20 &&
                        vectorOffset <= 0x90)
                    {
                        score += 40;
                    }

                    if (count <= 16)
                        score += 30;
                    else if (count <= 32)
                        score += 15;

                    if (capacity <= 32)
                        score += 20;

                    TileVectorCandidate candidate{};

                    candidate.objectBase =
                        objectBase;

                    candidate.vectorHeader =
                        header;

                    candidate.vectorOffset =
                        vectorOffset;

                    candidate.begin =
                        begin;

                    candidate.end =
                        end;

                    candidate.cap =
                        cap;

                    candidate.vtable =
                        vtable;

                    candidate.count =
                        count;

                    candidate.capacity =
                        capacity;

                    candidate.score =
                        score;

                    out.push_back(
                        std::move(candidate)
                    );

                    ++polymorphicOwnerHits;
                }
            }

            cursor +=
                got;
        }
    }

    std::cout
        << "[VECTOR DIAG] raw headers containing needle="
        << rawVectorHeaders
        << " | polymorphic owner hits="
        << polymorphicOwnerHits
        << "\n";

    std::fill(
        buffer.begin(),
        buffer.end(),
        0
    );

    std::sort(
        out.begin(),
        out.end(),
        [](
            const TileVectorCandidate& a,
            const TileVectorCandidate& b)
        {
            if (a.score != b.score)
                return a.score > b.score;

            if (a.vectorOffset !=
                b.vectorOffset)
            {
                return
                    a.vectorOffset <
                    b.vectorOffset;
            }

            return
                a.objectBase <
                b.objectBase;
        }
    );

    return out;
}

void PrintTileVectorCandidates(
    const char* label,
    const std::vector<TileVectorCandidate>& candidates)
{
    std::cout
        << "\n============================================================\n"
        << "              TILE VECTOR CANDIDATES - "
        << label
        << "\n"
        << "============================================================\n";

    if (candidates.empty())
    {
        std::cout
            << "Nenhum candidato vetorial polimorfico encontrado.\n";

        return;
    }

    for (size_t i = 0;
         i < candidates.size() &&
         i < 24;
         ++i)
    {
        const auto& c =
            candidates[i];

        std::cout
            << "#"
            << i
            << " score="
            << c.score
            << " object="
            << HexPtr(
                c.objectBase
            )
            << " vectorOff=+"
            << HexU64(
                c.vectorOffset
            )
            << " count="
            << c.count
            << " cap="
            << c.capacity
            << " vtableRva=";

        if (InsideExeImage(
                c.vtable))
        {
            std::cout
                << HexU64(
                    c.vtable -
                    g_exeBase
                );
        }
        else
        {
            std::cout
                << HexPtr(
                    c.vtable
                );
        }

        std::string rtti =
            TryReadMsvcRttiTypeName(
                c.vtable
            );

        if (!rtti.empty())
        {
            std::cout
                << " rtti=\""
                << rtti
                << "\"";
        }

        std::cout
            << "\n";
    }
}


struct TileSemanticStats
{
    bool localFound = false;
    size_t readableEntries = 0;
    size_t plausibleThings = 0;
    size_t matchingPosition = 0;
    size_t mismatchingPosition = 0;
};

TileSemanticStats EvaluateTileCandidatePosition(
    const TileVectorCandidate& candidate,
    const MapPosition& expected,
    const DbProfile& profile,
    uintptr_t localPlayer)
{
    TileSemanticStats stats{};

    size_t limit =
        std::min<size_t>(
            candidate.count,
            64
        );

    for (size_t i = 0;
         i < limit;
         ++i)
    {
        uintptr_t thing =
            ReadPtr(
                candidate.begin +
                i * sizeof(uintptr_t)
            );

        if (!thing)
            continue;

        if (thing ==
            localPlayer)
        {
            stats.localFound = true;
        }

        uintptr_t need =
            std::max<uintptr_t>(
                profile.z + 1,
                0x28
            );

        if (!IsReadableMonitorRange(
                thing,
                need))
        {
            continue;
        }

        ++stats.readableEntries;

        uint32_t x =
            ReadU32(
                thing +
                profile.x
            );

        uint32_t y =
            ReadU32(
                thing +
                profile.y
            );

        uint8_t z =
            ReadU8(
                thing +
                profile.z
            );

        MapPosition p{};
        p.x = x;
        p.y = y;
        p.z = z;

        if (!MapPositionPlausible(
                p))
        {
            continue;
        }

        ++stats.plausibleThings;

        if (SameMapPosition(
                p,
                expected))
        {
            ++stats.matchingPosition;
        }
        else
        {
            ++stats.mismatchingPosition;
        }
    }

    return stats;
}

std::vector<TileVectorCandidate>
FilterTileCandidatesByPosition(
    const char* label,
    const std::vector<TileVectorCandidate>& candidates,
    const MapPosition& expected,
    const DbProfile& profile,
    uintptr_t localPlayer)
{
    std::vector<TileVectorCandidate> out;

    std::cout
        << "\n============================================================\n"
        << "             TILE SEMANTIC FILTER - "
        << label
        << "\n"
        << "============================================================\n"
        << "Expected Position     : "
        << expected.x
        << ","
        << expected.y
        << ","
        << static_cast<unsigned>(
            expected.z
        )
        << "\n";

    for (size_t i = 0;
         i < candidates.size();
         ++i)
    {
        const auto& candidate =
            candidates[i];

        TileSemanticStats stats =
            EvaluateTileCandidatePosition(
                candidate,
                expected,
                profile,
                localPlayer
            );

        bool smallVector =
            candidate.count <= 16 &&
            candidate.capacity <= 64;

        bool positionCoherent =
            stats.localFound &&
            stats.matchingPosition >= 1 &&
            stats.mismatchingPosition == 0;

        const std::string candidateRtti =
            TryReadMsvcRttiTypeName(
                candidate.vtable
            );

        const bool exactTileRtti =
            RttiLooksExactlyLikeTileClass(
                candidateRtti
            );

        // Legacy heuristic: for larger vectors require two matching Things.
        // Semantic exception: when MSVC RTTI proves the owner is exactly
        // Tile, LocalPlayer + exact current Position is already a stronger
        // anchor than guessing another Thing layout.
        if (candidate.count > 8 &&
            stats.matchingPosition < 2 &&
            !exactTileRtti)
        {
            positionCoherent = false;
        }

        bool accepted =
            smallVector &&
            positionCoherent;

        if (i < 32 ||
            accepted)
        {
            std::cout
                << "#"
                << i
                << " off=+"
                << HexU64(
                    candidate.vectorOffset
                )
                << " count="
                << candidate.count
                << " cap="
                << candidate.capacity
                << " local="
                << (
                    stats.localFound
                        ? "YES"
                        : "NO"
                )
                << " plausible="
                << stats.plausibleThings
                << " match="
                << stats.matchingPosition
                << " mismatch="
                << stats.mismatchingPosition
                << " rtti=";

            if (candidateRtti.empty())
                std::cout << "<none>";
            else
                std::cout << "\"" << candidateRtti << "\"";

            std::cout
                << " => "
                << (
                    accepted
                        ? "ACCEPT"
                        : "REJECT"
                )
                << "\n";
        }

        if (!accepted)
            continue;

        TileVectorCandidate copy =
            candidate;

        copy.score += 500;

        if (exactTileRtti)
            copy.score += 1200;

        if (stats.matchingPosition >= 2)
            copy.score += 300;

        if (candidate.count <= 8)
            copy.score += 200;

        if (candidate.count <= 4)
            copy.score += 100;

        copy.score +=
            static_cast<int>(
                stats.matchingPosition *
                50
            );

        out.push_back(
            std::move(copy)
        );
    }

    std::sort(
        out.begin(),
        out.end(),
        [](
            const TileVectorCandidate& a,
            const TileVectorCandidate& b)
        {
            if (a.score != b.score)
                return a.score > b.score;

            if (a.count != b.count)
                return a.count < b.count;

            if (a.vectorOffset !=
                b.vectorOffset)
            {
                return
                    a.vectorOffset <
                    b.vectorOffset;
            }

            return
                a.objectBase <
                b.objectBase;
        }
    );

    std::cout
        << "[SEMANTIC] Accepted "
        << out.size()
        << " / "
        << candidates.size()
        << " candidate(s).\n";

    return out;
}

std::vector<TileLayoutAggregate>
CrossValidateTileVectorLayouts(
    const std::vector<TileVectorCandidate>& localCandidates,
    const std::vector<TileVectorCandidate>& targetCandidates)
{
    std::vector<TileLayoutAggregate> out;

    struct Key
    {
        uintptr_t offset = 0;
        uintptr_t vtable = 0;

        bool operator==(
            const Key& other) const
        {
            return
                offset == other.offset &&
                vtable == other.vtable;
        }
    };

    struct KeyHash
    {
        size_t operator()(
            const Key& key) const
        {
            size_t a =
                std::hash<uintptr_t>{}(
                    key.offset
                );

            size_t b =
                std::hash<uintptr_t>{}(
                    key.vtable
                );

            return
                a ^
                (
                    b +
                    0x9E3779B97F4A7C15ULL +
                    (a << 6) +
                    (a >> 2)
                );
        }
    };

    std::unordered_map<
        Key,
        TileLayoutAggregate,
        KeyHash
    > aggregates;

    for (const auto& local :
         localCandidates)
    {
        for (const auto& target :
             targetCandidates)
        {
            if (local.vectorOffset !=
                target.vectorOffset)
            {
                continue;
            }

            if (local.vtable !=
                target.vtable)
            {
                continue;
            }

            // A global vector containing every Creature would produce the
            // same owner object for both needles. Tile evidence must come
            // from two distinct enclosing objects.
            if (local.objectBase ==
                target.objectBase)
            {
                continue;
            }

            Key key{
                local.vectorOffset,
                local.vtable
            };

            auto& agg =
                aggregates[
                    key
                ];

            if (!agg.pairCount)
            {
                agg.vectorOffset =
                    key.offset;

                agg.vtable =
                    key.vtable;

                agg.localTile =
                    local.objectBase;

                agg.targetTile =
                    target.objectBase;
            }

            ++agg.pairCount;

            agg.score +=
                local.score +
                target.score +
                200;
        }
    }

    for (const auto& kv :
         aggregates)
    {
        out.push_back(
            kv.second
        );
    }

    std::sort(
        out.begin(),
        out.end(),
        [](
            const TileLayoutAggregate& a,
            const TileLayoutAggregate& b)
        {
            // Candidates reaching this stage already passed the semantic
            // position filter. Prefer evidence quality, not combinatorial
            // pair count from a large unrelated vector family.
            if (a.score !=
                b.score)
            {
                return
                    a.score >
                    b.score;
            }

            if (a.pairCount !=
                b.pairCount)
            {
                return
                    a.pairCount >
                    b.pairCount;
            }

            return
                a.vectorOffset <
                b.vectorOffset;
        }
    );

    return out;
}

bool WaitForTileWorldReady(
    const DbProfile& profile,
    uintptr_t localPlayer)
{
    std::cout
        << "\n============================================================\n"
        << "                 WORLD READY GATE\n"
        << "============================================================\n"
        << "A Stage 5A so inicia quando:\n"
        << "  - LocalPlayer Position for valida\n"
        << "  - Map Center for valida\n"
        << "  - Map Center == LocalPlayer Position\n"
        << "  - isso permanecer estavel por varias amostras\n"
        << "\n"
        << "Nenhuma chamada interna sera executada.\n";

    if (!profile.mapRva ||
        !profile.mapCenterX ||
        !profile.mapCenterY ||
        !profile.mapCenterZ)
    {
        std::cout
            << "[STOP] Map profile incompleto para World Ready gate.\n";

        return false;
    }

    uintptr_t mapAddress =
        g_exeBase +
        profile.mapRva;

    int stableSamples = 0;
    MapPosition last{};

    while (true)
    {
        if (GetAsyncKeyState(VK_END) & 0x8000)
            return false;

        uintptr_t currentLocal =
            ResolveProfileLocalPlayerForDiscovery(
                profile
            );

        if (!currentLocal)
        {
            stableSamples = 0;
            Sleep(250);
            continue;
        }

        localPlayer =
            currentLocal;

        MapPosition player =
            ReadDiscoveredPlayerPosition(
                localPlayer,
                profile
            );

        MapPosition center{};

        center.x =
            ReadU32(
                mapAddress +
                profile.mapCenterX
            );

        center.y =
            ReadU32(
                mapAddress +
                profile.mapCenterY
            );

        center.z =
            ReadU8(
                mapAddress +
                profile.mapCenterZ
            );

        bool playerOk =
            MapPositionPlausible(
                player
            );

        bool centerOk =
            MapPositionPlausible(
                center
            );

        bool agree =
            playerOk &&
            centerOk &&
            SameMapPosition(
                player,
                center
            );

        bool sameAsLast =
            agree &&
            stableSamples > 0 &&
            SameMapPosition(
                player,
                last
            );

        if (agree)
        {
            if (stableSamples == 0 ||
                sameAsLast)
            {
                ++stableSamples;
            }
            else
            {
                stableSamples = 1;
            }

            last =
                player;

            std::cout
                << "\r[WORLD] Player/Center="
                << player.x
                << ","
                << player.y
                << ","
                << static_cast<unsigned>(
                    player.z
                )
                << " stable="
                << stableSamples
                << "/4      "
                << std::flush;

            if (stableSamples >= 4)
            {
                std::cout
                    << "\n[WORLD READY] Map Center == LocalPlayer Position estavel.\n"
                    << "[WORLD READY] Aguardando 750ms para estruturas de Tile assentarem...\n";

                Sleep(750);

                // Final confirmation after the settling delay.
                MapPosition playerFinal =
                    ReadDiscoveredPlayerPosition(
                        localPlayer,
                        profile
                    );

                MapPosition centerFinal{};

                centerFinal.x =
                    ReadU32(
                        mapAddress +
                        profile.mapCenterX
                    );

                centerFinal.y =
                    ReadU32(
                        mapAddress +
                        profile.mapCenterY
                    );

                centerFinal.z =
                    ReadU8(
                        mapAddress +
                        profile.mapCenterZ
                    );

                if (MapPositionPlausible(
                        playerFinal) &&
                    MapPositionPlausible(
                        centerFinal) &&
                    SameMapPosition(
                        playerFinal,
                        centerFinal))
                {
                    std::cout
                        << "[WORLD READY] FINAL PASS.\n";

                    return true;
                }

                std::cout
                    << "[WORLD READY] Position mudou durante settle; aguardando novamente.\n";

                stableSamples = 0;
            }
        }
        else
        {
            if (stableSamples != 0)
            {
                std::cout
                    << "\n[WORLD] Player/Center divergiram; resetando estabilidade.\n";
            }

            stableSamples = 0;
        }

        Sleep(250);
    }
}

bool DiscoverTileThings(
    DbProfile& profile)
{
    std::cout
        << "\n============================================================\n"
        << "           STAGE 5A - TILE::THINGS DISCOVERY V5\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "[NO WRITE] Nenhuma escrita em memoria do jogo\n"
        << "[NO HOOK] Nenhum hook\n"
        << "[NO CALL] Nenhuma funcao interna do jogo\n"
        << "\n"
        << "Metodo corrigido:\n"
        << "  1. usa SOMENTE LocalPlayer* como agulha estavel\n"
        << "  2. captura Player parado no SQM A\n"
        << "  3. voce muda para outro SQM no MESMO andar\n"
        << "  4. captura Player parado no SQM B\n"
        << "  5. reenumera heaps em CADA snapshot\n"
        << "  6. valida que os Thing-like entries pertencem ao SQM atual\n"
        << "  7. exige mesmo vectorOffset + mesma vtable em DOIS objetos diferentes\n"
        << "  8. se houver empate, usa RTTI MSVC para identificar classe Tile\n"
        << "\n"
        << "Isso evita escolher estrutura espelho apenas porque contem os mesmos Things.\n"
        << "Map::getTile NAO sera chamado.\n";

    uintptr_t localPlayer =
        ResolveProfileLocalPlayerForDiscovery(
            profile
        );

    if (!localPlayer)
    {
        std::cout
            << "[STOP] LocalPlayer invalido para Stage 5A.\n";

        return false;
    }

    std::cout
        << "LocalPlayer          : "
        << HexPtr(
            localPlayer
        )
        << "\n";

    std::cout
        << "\n[SCAN] Cada snapshot vai reenumerar os heaps para evitar lista stale apos movimento.\n";

    auto captureStableLocalPlayerCandidates =
        [&](
            const char* label,
            MapPosition& stablePosition)
            -> std::vector<TileVectorCandidate>
        {
            while (true)
            {
                MapPosition before =
                    ReadDiscoveredPlayerPosition(
                        localPlayer,
                        profile
                    );

                if (!MapPositionPlausible(
                        before))
                {
                    std::cout
                        << "[RETRY] Position antes do scan e invalida.\n";

                    Sleep(250);
                    continue;
                }

                std::cout
                    << "\n============================================================\n"
                    << "               TILE SNAPSHOT "
                    << label
                    << "\n"
                    << "============================================================\n"
                    << "Position before      : "
                    << before.x
                    << ","
                    << before.y
                    << ","
                    << static_cast<unsigned>(
                        before.z
                    )
                    << "\n"
                    << "IMPORTANTE: fique PARADO ate o scan terminar.\n";

                auto snapshotRegions =
                    EnumerateTileHeapRegions();

                size_t snapshotBytes = 0;

                for (const auto& region :
                     snapshotRegions)
                {
                    snapshotBytes +=
                        region.size;
                }

                std::cout
                    << "[SCAN] Fresh regions="
                    << snapshotRegions.size()
                    << " total="
                    << (
                        snapshotBytes /
                        (1024 * 1024)
                    )
                    << " MB\n";

                if (snapshotRegions.empty())
                {
                    std::cout
                        << "[RETRY] Nenhuma heap region legivel neste snapshot.\n";

                    Sleep(250);
                    continue;
                }

                auto candidates =
                    FindTileCandidatesByExactRttiAnchor(
                        localPlayer,
                        snapshotRegions
                    );

                if (!candidates.empty())
                {
                    std::cout
                        << "[TILE DISCOVERY] Resolver=exact_rtti_tile_anchor\n";
                }
                else
                {
                    std::cout
                        << "[TILE DISCOVERY] Exact RTTI anchor unavailable; "
                        << "falling back to LocalPlayer needle scan.\n";

                    candidates =
                        FindTileVectorCandidatesForNeedle(
                            localPlayer,
                            snapshotRegions
                        );
                }

                MapPosition after =
                    ReadDiscoveredPlayerPosition(
                        localPlayer,
                        profile
                    );

                std::cout
                    << "Position after       : "
                    << after.x
                    << ","
                    << after.y
                    << ","
                    << static_cast<unsigned>(
                        after.z
                    )
                    << "\n";

                if (!MapPositionPlausible(
                        after))
                {
                    std::cout
                        << "[RETRY] Position depois do scan ficou invalida.\n";

                    continue;
                }

                if (!SameMapPosition(
                        before,
                        after))
                {
                    std::cout
                        << "\n============================================================\n"
                        << "              MOVEMENT DURING SCAN - RETRY\n"
                        << "============================================================\n"
                        << "O Player mudou de Position durante a varredura.\n"
                        << "Esse snapshot foi descartado para evitar misturar Tiles.\n"
                        << "Fique parado durante o proximo scan.\n";

                    WaitEnter(
                        "Quando estiver parado, pressione ENTER para repetir..."
                    );

                    continue;
                }

                stablePosition =
                    after;

                PrintTileVectorCandidates(
                    label,
                    candidates
                );

                auto semantic =
                    FilterTileCandidatesByPosition(
                        label,
                        candidates,
                        after,
                        profile,
                        localPlayer
                    );

                std::cout
                    << "\n[SEMANTIC CANDIDATES] "
                    << semantic.size()
                    << " candidate(s) survived for "
                    << label
                    << ".\n";

                return semantic;
            }
        };

    // --------------------------------------------------------
    // Snapshot A
    // --------------------------------------------------------

    std::cout
        << "\nPASSO A - SQM A\n"
        << "Fique parado em um SQM e nao mude de andar.\n";

    WaitEnter(
        "Quando estiver PARADO no SQM A, pressione ENTER..."
    );

    MapPosition posA{};

    auto candidatesA =
        captureStableLocalPlayerCandidates(
            "LOCALPLAYER / SQM A",
            posA
        );

    if (candidatesA.empty())
    {
        std::cout
            << "\n[RETRY] Nenhum candidato polimorfico no primeiro scan.\n"
            << "Vamos confirmar World Ready novamente e repetir UMA vez.\n";

        if (!WaitForTileWorldReady(
                profile,
                localPlayer))
        {
            profile.tileThingsStatus =
                "unresolved_world_not_ready_retry";

            return false;
        }

        WaitEnter(
            "Fique PARADO no mesmo SQM A e pressione ENTER para o retry..."
        );

        candidatesA =
            captureStableLocalPlayerCandidates(
                "LOCALPLAYER / SQM A RETRY",
                posA
            );

        if (candidatesA.empty())
        {
            profile.tileThingsStatus =
                "unresolved_no_localplayer_vector_A";

            std::cout
                << "[CHECK] Retry tambem nao encontrou owner polimorfico.\n"
                << "Use o [VECTOR DIAG] para separar vector-scan de owner-recovery.\n";

            return false;
        }
    }

    // --------------------------------------------------------
    // Move to B on SAME floor.
    // --------------------------------------------------------

    MapPosition posB{};

    while (true)
    {
        std::cout
            << "\nPASSO B - MUDAR PARA SQM B\n"
            << "Agora ande para OUTRO SQM, mas permanea no MESMO andar Z="
            << static_cast<unsigned>(
                posA.z
            )
            << ".\n"
            << "Depois pare completamente.\n";

        WaitEnter(
            "Quando estiver PARADO no SQM B, pressione ENTER..."
        );

        posB =
            ReadDiscoveredPlayerPosition(
                localPlayer,
                profile
            );

        if (!MapPositionPlausible(
                posB))
        {
            std::cout
                << "[RETRY] Position B invalida.\n";

            continue;
        }

        if (posB.z !=
            posA.z)
        {
            std::cout
                << "[RETRY] Voce mudou de andar: Z A="
                << static_cast<unsigned>(
                    posA.z
                )
                << " Z B="
                << static_cast<unsigned>(
                    posB.z
                )
                << ".\n"
                << "Volte ao mesmo andar do SQM A antes de continuar.\n";

            continue;
        }

        if (SameMapPosition(
                posA,
                posB))
        {
            std::cout
                << "[RETRY] Voce ainda esta no mesmo SQM.\n";

            continue;
        }

        break;
    }

    std::cout
        << "\n[SYNC] Confirmando World Ready novamente depois do movimento A -> B...\n";

    if (!WaitForTileWorldReady(
            profile,
            localPlayer))
    {
        profile.tileThingsStatus =
            "unresolved_world_not_ready_B";

        return false;
    }

    Sleep(500);

    // --------------------------------------------------------
    // Snapshot B
    // --------------------------------------------------------

    auto candidatesB =
        captureStableLocalPlayerCandidates(
            "LOCALPLAYER / SQM B",
            posB
        );

    if (candidatesB.empty())
    {
        profile.tileThingsStatus =
            "unresolved_no_localplayer_vector_B";

        std::cout
            << "[CHECK] Nenhum candidato encontrado no SQM B.\n";

        return false;
    }

    std::cout
        << "\n[POSITION TRANSITION]\n"
        << "SQM A                : "
        << posA.x
        << ","
        << posA.y
        << ","
        << static_cast<unsigned>(
            posA.z
        )
        << "\n"
        << "SQM B                : "
        << posB.x
        << ","
        << posB.y
        << ","
        << static_cast<unsigned>(
            posB.z
        )
        << "\n";

    // The existing cross-validator already requires:
    // - same vector offset
    // - same vtable
    // - two DIFFERENT enclosing objects.
    auto layouts =
        CrossValidateTileVectorLayouts(
            candidatesA,
            candidatesB
        );

    std::cout
        << "\n============================================================\n"
        << "          TILE LAYOUT CROSS-VALIDATION A -> B\n"
        << "============================================================\n";

    for (size_t i = 0;
         i < layouts.size() &&
         i < 16;
         ++i)
    {
        const auto& layout =
            layouts[i];

        std::cout
            << "#"
            << i
            << " pairs="
            << layout.pairCount
            << " score="
            << layout.score
            << " vectorOffset=+"
            << HexU64(
                layout.vectorOffset
            )
            << " vtableRva=";

        if (InsideExeImage(
                layout.vtable))
        {
            std::cout
                << HexU64(
                    layout.vtable -
                    g_exeBase
                );
        }
        else
        {
            std::cout
                << HexPtr(
                    layout.vtable
                );
        }

        std::string rttiName =
            TryReadMsvcRttiTypeName(
                layout.vtable
            );

        std::cout
            << " objectA="
            << HexPtr(
                layout.localTile
            )
            << " objectB="
            << HexPtr(
                layout.targetTile
            )
            << " rtti=";

        if (rttiName.empty())
        {
            std::cout
                << "<unavailable>";
        }
        else
        {
            std::cout
                << "\""
                << rttiName
                << "\"";
        }

        std::cout
            << "\n";
    }

    if (layouts.empty())
    {
        profile.tileThingsStatus =
            "unresolved_no_cross_validated_layout";

        std::cout
            << "[CHECK] Nenhum layout comum apareceu nos dois SQMs.\n"
            << "Nao vamos promover offset por palpite.\n";

        return false;
    }

    size_t selectedLayout =
        0;

    bool uniqueStrong =
        layouts.size() == 1 ||
        layouts[0].score >=
            layouts[1].score + 150;

    if (!uniqueStrong)
    {
        std::cout
            << "\n============================================================\n"
            << "                 RTTI SEMANTIC RESOLUTION\n"
            << "============================================================\n"
            << "Mais de um layout estrutural permaneceu.\n"
            << "Tentando identificar semanticamente a classe owner pela RTTI MSVC.\n";

        std::vector<size_t>
            exactTileMatches;

        std::vector<size_t>
            anyTileTokenMatches;

        for (size_t i = 0;
             i < layouts.size();
             ++i)
        {
            std::string rtti =
                TryReadMsvcRttiTypeName(
                    layouts[i].vtable
                );

            std::cout
                << "#"
                << i
                << " off=+"
                << HexU64(
                    layouts[i].vectorOffset
                )
                << " vtableRva=";

            if (InsideExeImage(
                    layouts[i].vtable))
            {
                std::cout
                    << HexU64(
                        layouts[i].vtable -
                        g_exeBase
                    );
            }
            else
            {
                std::cout
                    << HexPtr(
                        layouts[i].vtable
                    );
            }

            std::cout
                << " rtti=";

            if (rtti.empty())
                std::cout << "<unavailable>";
            else
                std::cout << "\"" << rtti << "\"";

            bool exactTile =
                RttiLooksExactlyLikeTileClass(
                    rtti
                );

            bool tileToken =
                RttiContainsTileToken(
                    rtti
                );

            if (exactTile)
            {
                exactTileMatches.push_back(
                    i
                );

                std::cout
                    << "  <EXACT TILE CLASS>";
            }
            else if (tileToken)
            {
                anyTileTokenMatches.push_back(
                    i
                );

                std::cout
                    << "  <TILE TOKEN ONLY>";
            }

            std::cout
                << "\n";
        }

        if (exactTileMatches.size() == 1)
        {
            selectedLayout =
                exactTileMatches[0];

            uniqueStrong = true;

            std::cout
                << "[RTTI] UNIQUE exact Tile class -> candidate #"
                << selectedLayout
                << "\n";
        }
        else
        {
            profile.tileThingsStatus =
                "ambiguous_cross_validated_layout_rtti";

            std::cout
                << "[CHECK] RTTI nao produziu uma unica classe Tile exata.\n"
                << "Nenhum offset sera promovido por nome parcial ou ranking.\n";

            return false;
        }
    }

    const TileLayoutAggregate&
        selected =
            layouts[
                selectedLayout
            ];

    profile.tileThingsBegin =
        selected.vectorOffset;

    profile.tileThingsEnd =
        selected.vectorOffset +
        sizeof(uintptr_t);

    profile.tileThingsCap =
        selected.vectorOffset +
        2 * sizeof(uintptr_t);

    if (InsideExeImage(
            selected.vtable))
    {
        profile.tileVtableRva =
            selected.vtable -
            g_exeBase;

        profile.tileRttiName =
            TryReadMsvcRttiTypeName(
                selected.vtable
            );

        if (profile.tileRttiName.empty())
            profile.tileRttiName = "unavailable";
    }

    profile.tileThingsStatus =
        "confirmed_runtime_localplayer_two_tiles";

    std::cout
        << "\n============================================================\n"
        << "               TILE::THINGS DISCOVERED\n"
        << "============================================================\n"
        << "Things begin offset : +"
        << HexU64(
            profile.tileThingsBegin
        )
        << "\n"
        << "Things end offset   : +"
        << HexU64(
            profile.tileThingsEnd
        )
        << "\n"
        << "Things cap offset   : +"
        << HexU64(
            profile.tileThingsCap
        )
        << "\n"
        << "Tile VTable RVA     : "
        << HexU64(
            profile.tileVtableRva
        )
        << "\n"
        << "Tile RTTI           : "
        << profile.tileRttiName
        << "\n"
        << "Evidence            : mesmo LocalPlayer* em dois Tile-like objects distintos\n"
        << "                      mesmo vectorOffset + mesma vtable\n"
        << "Status              : "
        << profile.tileThingsStatus
        << "\n";

    // Ground truth is used ONLY after discovery.
    const bool knownBenchmarkBuild =
        profile.timestamp == 0x6AA9FA57ULL &&
        profile.sizeOfImage == 0x17BF000ULL &&
        profile.textHash == 0x89D3D35243890EA2ULL;

    if (knownBenchmarkBuild)
    {
        const bool beginMatch =
            profile.tileThingsBegin ==
            0x48;

        const bool endMatch =
            profile.tileThingsEnd ==
            0x50;

        const bool capMatch =
            profile.tileThingsCap ==
            0x58;

        std::cout
            << "\n[GROUND TRUTH COMPARISON]\n"
            << "Known B/E/C         : +0x48 / +0x50 / +0x58\n"
            << "Begin match         : "
            << (
                beginMatch
                    ? "PASS"
                    : "FAIL"
            )
            << "\n"
            << "End match           : "
            << (
                endMatch
                    ? "PASS"
                    : "FAIL"
            )
            << "\n"
            << "Cap match           : "
            << (
                capMatch
                    ? "PASS"
                    : "FAIL"
            )
            << "\n";

        if (beginMatch &&
            endMatch &&
            capMatch)
        {
            profile.tileThingsStatus =
                "discovered_runtime_selfcheck_pass";

            std::cout
                << "\n[FEITO] STAGE 5A redescobriu Tile::things usando LocalPlayer em dois SQMs.\n";
        }
        else
        {
            profile.tileThingsStatus =
                "discovered_runtime_selfcheck_mismatch";

            profile.tileThingsBegin = 0;
            profile.tileThingsEnd = 0;
            profile.tileThingsCap = 0;

            std::cout
                << "[PRESERVE] Self-check falhou; layout Tile nao sera promovido.\n";
        }
    }

    return
        profile.tileThingsStatus ==
            "discovered_runtime_selfcheck_pass" ||
        profile.tileThingsStatus ==
            "confirmed_runtime_localplayer_two_tiles";
}

bool EnsureTileThingsDiscovery(
    DbProfile& profile,
    std::vector<DbProfile>& database,
    int profileIndex,
    const std::string& databasePath)
{
    if (profile.tileThingsBegin &&
        profile.tileThingsEnd &&
        profile.tileThingsCap &&
        profile.tileVtableRva &&
        (
            profile.tileThingsStatus ==
                "discovered_runtime_selfcheck_pass" ||
            profile.tileThingsStatus ==
                "confirmed_runtime_localplayer_two_tiles"
        ))
    {
        std::cout
            << "\n[FEITO] STAGE 5A - Tile::things ja passou self-check.\n"
            << "B/E/C         : +"
            << HexU64(
                profile.tileThingsBegin
            )
            << " / +"
            << HexU64(
                profile.tileThingsEnd
            )
            << " / +"
            << HexU64(
                profile.tileThingsCap
            )
            << "\n";

        return true;
    }

    uintptr_t localPlayer =
        WaitForDiscoveryLocalPlayer(
            profile,
            "STAGE 5A - TILE::THINGS"
        );

    if (!localPlayer)
    {
        std::cout
            << "\n[STAGE 5A] Cancelada antes do login.\n";

        return false;
    }

    if (!WaitForTileWorldReady(
            profile,
            localPlayer))
    {
        std::cout
            << "\n[STAGE 5A] World Ready gate nao fechou.\n";

        return false;
    }

    if (profile.tileThingsStatus !=
            "discovered_runtime_selfcheck_pass")
    {
        profile.tileThingsBegin = 0;
        profile.tileThingsEnd = 0;
        profile.tileThingsCap = 0;
        profile.tileThingsStatus =
            "rediscovery_running";
    }

    bool ok =
        DiscoverTileThings(
            profile
        );

    if (profileIndex >= 0 &&
        profileIndex <
            static_cast<int>(
                database.size()
            ))
    {
        database[
            static_cast<size_t>(
                profileIndex
            )
        ] = profile;

        SaveProfileDatabase(
            databasePath,
            database
        );
    }

    return ok;
}


// ============================================================
// DISCOVERY V2.4 - MAP -> TILE PROVENANCE RECON
// Strict read-only. No Map::getTile call.
// ============================================================

struct TilePathNode
{
    uintptr_t address = 0;
    int depth = 0;
    std::vector<uintptr_t> offsets;
};

struct TilePathHit
{
    std::vector<uintptr_t> offsets;
    uintptr_t holderAddress = 0;
    uintptr_t slotAddress = 0;
};


std::vector<TileVectorCandidate>
FindTileCandidatesByKnownVtableReadOnly(
    const DbProfile& profile,
    uintptr_t localPlayer,
    const MapPosition& expectedPosition)
{
    std::vector<TileVectorCandidate>
        candidates;

    if (!profile.tileVtableRva ||
        !profile.tileThingsBegin ||
        !profile.tileThingsEnd ||
        !profile.tileThingsCap)
    {
        return candidates;
    }

    uintptr_t tileVtable =
        g_exeBase +
        profile.tileVtableRva;

    if (!InsideExeImage(
            tileVtable))
    {
        return candidates;
    }

    std::string rtti =
        TryReadMsvcRttiTypeName(
            tileVtable
        );

    std::cout
        << "[TYPED TILE SCAN] VTable RVA="
        << HexU64(
            profile.tileVtableRva
        )
        << " RTTI=";

    if (rtti.empty())
        std::cout << "<unavailable>";
    else
        std::cout << "\"" << rtti << "\"";

    std::cout
        << "\n";

    auto regions =
        EnumerateTileHeapRegions();

    const size_t chunkSize =
        4 * 1024 * 1024;

    std::vector<uint8_t>
        buffer(
            chunkSize
        );

    size_t rawVtableHits = 0;

    for (const auto& region :
         regions)
    {
        uintptr_t cursor =
            region.base;

        uintptr_t regionEnd =
            region.base +
            region.size;

        while (cursor <
               regionEnd)
        {
            size_t want =
                static_cast<size_t>(
                    std::min<uintptr_t>(
                        chunkSize,
                        regionEnd -
                        cursor
                    )
                );

            size_t got = 0;

            if (!ReadProcessChunk(
                    cursor,
                    buffer.data(),
                    want,
                    got))
            {
                cursor += want;
                continue;
            }

            uintptr_t aligned =
                (cursor + 7) &
                ~static_cast<uintptr_t>(7);

            size_t start =
                static_cast<size_t>(
                    aligned -
                    cursor
                );

            for (size_t off = start;
                 off + sizeof(uintptr_t) <= got;
                 off += sizeof(uintptr_t))
            {
                uintptr_t value = 0;

                std::memcpy(
                    &value,
                    buffer.data() +
                        off,
                    sizeof(value)
                );

                if (value !=
                    tileVtable)
                {
                    continue;
                }

                ++rawVtableHits;

                uintptr_t object =
                    cursor +
                    off;

                if (!IsReadableMonitorRange(
                        object,
                        profile.tileThingsCap +
                            sizeof(uintptr_t)))
                {
                    continue;
                }

                uintptr_t begin =
                    ReadPtr(
                        object +
                        profile.tileThingsBegin
                    );

                uintptr_t end =
                    ReadPtr(
                        object +
                        profile.tileThingsEnd
                    );

                uintptr_t cap =
                    ReadPtr(
                        object +
                        profile.tileThingsCap
                    );

                if (!begin ||
                    !end ||
                    !cap ||
                    end < begin ||
                    cap < end ||
                    (begin & 7) ||
                    (end & 7) ||
                    (cap & 7))
                {
                    continue;
                }

                uintptr_t used =
                    end -
                    begin;

                uintptr_t capacityBytes =
                    cap -
                    begin;

                if (used %
                        sizeof(uintptr_t) !=
                    0 ||
                    capacityBytes %
                        sizeof(uintptr_t) !=
                    0)
                {
                    continue;
                }

                size_t count =
                    static_cast<size_t>(
                        used /
                        sizeof(uintptr_t)
                    );

                size_t capacity =
                    static_cast<size_t>(
                        capacityBytes /
                        sizeof(uintptr_t)
                    );

                if (count == 0 ||
                    count > 256 ||
                    capacity < count ||
                    capacity > 512)
                {
                    continue;
                }

                bool hasLocalPlayer =
                    false;

                for (size_t i = 0;
                     i < count;
                     ++i)
                {
                    uintptr_t thing =
                        ReadPtr(
                            begin +
                            i *
                            sizeof(uintptr_t)
                        );

                    if (thing ==
                        localPlayer)
                    {
                        hasLocalPlayer =
                            true;

                        break;
                    }
                }

                if (!hasLocalPlayer)
                    continue;

                TileVectorCandidate c{};

                c.objectBase =
                    object;

                c.vectorHeader =
                    object +
                    profile.tileThingsBegin;

                c.vectorOffset =
                    profile.tileThingsBegin;

                c.begin =
                    begin;

                c.end =
                    end;

                c.cap =
                    cap;

                c.vtable =
                    tileVtable;

                c.count =
                    count;

                c.capacity =
                    capacity;

                c.score =
                    3000 -
                    static_cast<int>(
                        capacity -
                        count
                    );

                candidates.push_back(
                    c
                );
            }

            cursor += got;
        }
    }

    std::cout
        << "[TYPED TILE SCAN] raw vtable hits="
        << rawVtableHits
        << " local-containing objects="
        << candidates.size()
        << "\n";

    if (candidates.empty())
        return candidates;

    return
        FilterTileCandidatesByPosition(
            "CURRENT TILE / KNOWN RTTI+VTABLE",
            candidates,
            expectedPosition,
            profile,
            localPlayer
        );
}

uintptr_t FindCurrentTileByKnownTypeReadOnly(
    const DbProfile& profile,
    uintptr_t localPlayer,
    const MapPosition& expectedPosition)
{
    if (!profile.tileVtableRva)
        return 0;

    auto semantic =
        FindTileCandidatesByKnownVtableReadOnly(
            profile,
            localPlayer,
            expectedPosition
        );

    std::vector<TileVectorCandidate>
        exact;

    for (const auto& c :
         semantic)
    {
        if (c.vectorOffset !=
            profile.tileThingsBegin)
        {
            continue;
        }

        if (ReadPtr(
                c.objectBase) !=
            g_exeBase +
                profile.tileVtableRva)
        {
            continue;
        }

        exact.push_back(
            c
        );
    }

    if (exact.empty())
        return 0;

    std::sort(
        exact.begin(),
        exact.end(),
        [](
            const TileVectorCandidate& a,
            const TileVectorCandidate& b)
        {
            if (a.score != b.score)
                return a.score > b.score;

            if (a.count != b.count)
                return a.count < b.count;

            return
                a.objectBase <
                b.objectBase;
        }
    );

    if (exact.size() > 1)
    {
        bool clear =
            exact[0].score >=
                exact[1].score + 100 ||
            exact[0].count <
                exact[1].count;

        if (!clear)
        {
            std::cout
                << "[TYPED TILE SCAN] "
                << exact.size()
                << " current-Tile candidates remain; not guessing.\n";

            return 0;
        }
    }

    const auto& best =
        exact[0];

    std::cout
        << "[TYPED TILE SCAN] CURRENT TILE CONFIRMED object="
        << HexPtr(
            best.objectBase
        )
        << " things="
        << best.count
        << " vtableRva="
        << HexU64(
            profile.tileVtableRva
        )
        << "\n";

    return
        best.objectBase;
}


uintptr_t FindCurrentTileObjectReadOnly(
    const DbProfile& profile,
    uintptr_t localPlayer,
    MapPosition& positionOut)
{
    positionOut =
        ReadDiscoveredPlayerPosition(
            localPlayer,
            profile
        );

    if (!MapPositionPlausible(
            positionOut))
    {
        return 0;
    }

    if (profile.tileVtableRva)
    {
        uintptr_t typedTile =
            FindCurrentTileByKnownTypeReadOnly(
                profile,
                localPlayer,
                positionOut
            );

        if (typedTile)
        {
            std::cout
                << "[TILE SEED] Resolver=known_tile_vtable_rtti\n";

            return
                typedTile;
        }

        std::cout
            << "[TILE SEED] Typed resolver did not close uniquely; "
            << "falling back to legacy LocalPlayer needle scan.\n";
    }

    auto regions =
        EnumerateTileHeapRegions();

    if (regions.empty())
        return 0;

    auto candidates =
        FindTileVectorCandidatesForNeedle(
            localPlayer,
            regions
        );

    auto semantic =
        FilterTileCandidatesByPosition(
            "CURRENT TILE PATH SEED",
            candidates,
            positionOut,
            profile,
            localPlayer
        );

    std::vector<TileVectorCandidate>
        exactLayout;

    for (const auto& candidate :
         semantic)
    {
        if (candidate.vectorOffset !=
            profile.tileThingsBegin)
        {
            continue;
        }

        if (candidate.end !=
            candidate.begin +
            candidate.count *
                sizeof(uintptr_t))
        {
            continue;
        }

        exactLayout.push_back(
            candidate
        );
    }

    if (exactLayout.empty())
    {
        std::cout
            << "[TILE SEED] Nenhum Tile atual fechou com o layout aprendido.\n";

        return 0;
    }

    std::sort(
        exactLayout.begin(),
        exactLayout.end(),
        [](
            const TileVectorCandidate& a,
            const TileVectorCandidate& b)
        {
            if (a.count != b.count)
                return a.count < b.count;

            if (a.capacity != b.capacity)
                return a.capacity < b.capacity;

            return a.score > b.score;
        }
    );

    // If several objects with the exact same learned layout survive,
    // do not silently pick by address. Require the best to be structurally
    // tighter than the next one, or the list to be unique.
    if (exactLayout.size() > 1)
    {
        const auto& a =
            exactLayout[0];

        const auto& b =
            exactLayout[1];

        bool clear =
            a.count < b.count ||
            a.capacity < b.capacity ||
            a.score >= b.score + 200;

        if (!clear)
        {
            std::cout
                << "[TILE SEED] Mais de um Tile-like exato permaneceu.\n";

            for (size_t i = 0;
                 i < exactLayout.size() &&
                 i < 8;
                 ++i)
            {
                std::cout
                    << "  #"
                    << i
                    << " object="
                    << HexPtr(
                        exactLayout[i].objectBase
                    )
                    << " off=+"
                    << HexU64(
                        exactLayout[i].vectorOffset
                    )
                    << " count="
                    << exactLayout[i].count
                    << " cap="
                    << exactLayout[i].capacity
                    << "\n";
            }

            return 0;
        }
    }

    const auto& best =
        exactLayout[0];

    std::cout
        << "\n[TILE SEED]\n"
        << "Position             : "
        << positionOut.x
        << ","
        << positionOut.y
        << ","
        << static_cast<unsigned>(
            positionOut.z
        )
        << "\n"
        << "Tile object          : "
        << HexPtr(
            best.objectBase
        )
        << "\n"
        << "Tile vtable RVA      : ";

    if (InsideExeImage(
            best.vtable))
    {
        std::cout
            << HexU64(
                best.vtable -
                g_exeBase
            );
    }
    else
    {
        std::cout
            << HexPtr(
                best.vtable
            );
    }

    std::cout
        << "\n"
        << "Things B/E/C         : +"
        << HexU64(
            profile.tileThingsBegin
        )
        << " / +"
        << HexU64(
            profile.tileThingsEnd
        )
        << " / +"
        << HexU64(
            profile.tileThingsCap
        )
        << "\n"
        << "Thing count          : "
        << best.count
        << "\n";

    uintptr_t tileResult =
        best.objectBase;

    auto scrubCandidates =
        [](
            std::vector<TileVectorCandidate>& values)
        {
            for (auto& c :
                 values)
            {
                c.objectBase = 0;
                c.vectorHeader = 0;
                c.vectorOffset = 0;
                c.begin = 0;
                c.end = 0;
                c.cap = 0;
                c.vtable = 0;
                c.count = 0;
                c.capacity = 0;
                c.score = 0;
            }

            values.clear();
            values.shrink_to_fit();
        };

    scrubCandidates(
        exactLayout
    );

    scrubCandidates(
        semantic
    );

    scrubCandidates(
        candidates
    );

    return
        tileResult;
}

// Legacy exact-reference scanner kept below for comparison.
// V2.4.2 uses the clean scanner further down.
std::vector<uintptr_t>
FindExactPointerOccurrencesReadOnly(
    uintptr_t needle,
    size_t maxHits = 4096)
{
    std::vector<uintptr_t> hits;

    if (!needle)
        return hits;

    auto regions =
        EnumerateTileHeapRegions();

    const size_t chunkSize =
        4 * 1024 * 1024;

    std::vector<uint8_t> buffer(
        chunkSize
    );

    for (const auto& region :
         regions)
    {
        uintptr_t cursor =
            region.base;

        uintptr_t end =
            region.base +
            region.size;

        while (cursor <
               end)
        {
            size_t want =
                static_cast<size_t>(
                    std::min<uintptr_t>(
                        chunkSize,
                        end -
                        cursor
                    )
                );

            size_t got = 0;

            if (!ReadProcessChunk(
                    cursor,
                    buffer.data(),
                    want,
                    got))
            {
                cursor += want;
                continue;
            }

            uintptr_t aligned =
                (cursor + 7) &
                ~static_cast<uintptr_t>(7);

            size_t start =
                static_cast<size_t>(
                    aligned -
                    cursor
                );

            for (size_t off = start;
                 off + sizeof(uintptr_t) <= got;
                 off += sizeof(uintptr_t))
            {
                uintptr_t value = 0;

                std::memcpy(
                    &value,
                    buffer.data() +
                        off,
                    sizeof(value)
                );

                if (value !=
                    needle)
                {
                    continue;
                }

                hits.push_back(
                    cursor +
                    off
                );

                if (hits.size() >=
                    maxHits)
                {
                    return hits;
                }
            }

            cursor += got;
        }
    }

    return hits;
}

void PrintTileReferenceNeighborhood(
    uintptr_t occurrence,
    uintptr_t tile)
{
    uintptr_t begin =
        occurrence >= 0x30
            ? occurrence - 0x30
            : occurrence;

    begin &=
        ~static_cast<uintptr_t>(7);

    std::cout
        << "  ref@"
        << HexPtr(
            occurrence
        )
        << " neighborhood:";

    for (uintptr_t p = begin;
         p <= occurrence + 0x30;
         p += 8)
    {
        uintptr_t q =
            ReadPtr(
                p
            );

        std::cout
            << " ["
            << (
                static_cast<long long>(
                    p
                ) -
                static_cast<long long>(
                    occurrence
                )
            )
            << "]="
            << HexPtr(
                q
            );

        if (q ==
            tile)
        {
            std::cout
                << "<TILE>";
        }
    }

    std::cout
        << "\n";
}

std::vector<TilePathHit>
FindMapToTilePointerPaths(
    uintptr_t map,
    uintptr_t tile)
{
    std::vector<TilePathHit> hits;

    if (!map ||
        !tile)
    {
        return hits;
    }

    const int maxDepth = 5;
    const size_t maxNodes = 6000;
    const uintptr_t rootScanBytes = 0x340;
    const uintptr_t childScanBytes = 0x180;

    std::vector<TilePathNode> queue;
    queue.reserve(
        maxNodes
    );

    std::unordered_set<uintptr_t>
        visited;

    TilePathNode root{};
    root.address = map;
    root.depth = 0;

    queue.push_back(
        root
    );

    visited.insert(
        map
    );

    size_t cursor = 0;

    while (cursor <
               queue.size() &&
           queue.size() <=
               maxNodes)
    {
        TilePathNode node =
            queue[
                cursor++
            ];

        uintptr_t scanBytes =
            node.depth == 0
                ? rootScanBytes
                : childScanBytes;

        for (uintptr_t off = 0;
             off + sizeof(uintptr_t) <=
                 scanBytes;
             off += 8)
        {
            uintptr_t slot =
                node.address +
                off;

            uintptr_t value =
                ReadPtr(
                    slot
                );

            if (!value)
                continue;

            if (value ==
                tile)
            {
                TilePathHit hit{};

                hit.offsets =
                    node.offsets;

                hit.offsets.push_back(
                    off
                );

                hit.holderAddress =
                    node.address;

                hit.slotAddress =
                    slot;

                hits.push_back(
                    std::move(hit)
                );

                continue;
            }

            if (node.depth >=
                maxDepth)
            {
                continue;
            }

            if (!IsReadablePrivatePointer(
                    value))
            {
                continue;
            }

            if (value ==
                    node.address ||
                value ==
                    map)
            {
                continue;
            }

            if (!visited.insert(
                    value).second)
            {
                continue;
            }

            if (queue.size() >=
                maxNodes)
            {
                break;
            }

            TilePathNode next{};

            next.address =
                value;

            next.depth =
                node.depth + 1;

            next.offsets =
                node.offsets;

            next.offsets.push_back(
                off
            );

            queue.push_back(
                std::move(next)
            );
        }
    }

    std::cout
        << "[GRAPH] visited nodes="
        << visited.size()
        << " queued="
        << queue.size()
        << " hits="
        << hits.size()
        << "\n";

    return hits;
}

void PrintMapTilePath(
    const TilePathHit& hit,
    size_t index)
{
    std::cout
        << "Path #"
        << index
        << " : Map";

    for (size_t i = 0;
         i < hit.offsets.size();
         ++i)
    {
        std::cout
            << " -> [+"
            << HexU64(
                hit.offsets[i]
            )
            << "]";

        if (i + 1 <
            hit.offsets.size())
        {
            std::cout
                << "*";
        }
    }

    std::cout
        << " -> Tile*"
        << " | holder="
        << HexPtr(
            hit.holderAddress
        )
        << " slot="
        << HexPtr(
            hit.slotAddress
        )
        << "\n";
}


struct CleanScanRange
{
    uintptr_t begin = 0;
    uintptr_t end = 0;
};

struct TilePointerRun
{
    uintptr_t begin = 0;
    uintptr_t end = 0;
    uintptr_t occurrence = 0;
    size_t slotIndex = 0;
    size_t tileCount = 0;

    size_t stride = sizeof(uintptr_t);
    size_t companionMatches = 0;

    std::string storageMode =
        "raw_pointer_array";
};

struct TileArrayHeaderCandidate
{
    uintptr_t header = 0;
    uintptr_t begin = 0;
    uintptr_t end = 0;
    uintptr_t cap = 0;
    size_t count = 0;
    size_t capacity = 0;
};

struct MapArrayProvenanceCandidate
{
    int depth = 0;

    uintptr_t mapOffset = 0;
    uintptr_t childOffset = 0;

    uintptr_t owner = 0;
    uintptr_t header = 0;
    uintptr_t headerOffset = 0;

    size_t count = 0;
    size_t capacity = 0;
};

bool AddressInsideCleanRange(
    uintptr_t address,
    const CleanScanRange& range)
{
    return
        range.begin &&
        address >= range.begin &&
        address < range.end;
}

CleanScanRange CurrentThreadStackRegion()
{
    CleanScanRange out{};

    uintptr_t marker =
        reinterpret_cast<uintptr_t>(
            &out
        );

    MEMORY_BASIC_INFORMATION mbi{};

    if (VirtualQuery(
            reinterpret_cast<const void*>(
                marker
            ),
            &mbi,
            sizeof(mbi)))
    {
        out.begin =
            reinterpret_cast<uintptr_t>(
                mbi.BaseAddress
            );

        out.end =
            out.begin +
            static_cast<uintptr_t>(
                mbi.RegionSize
            );
    }

    return out;
}

std::vector<uintptr_t>
FindExactPointerOccurrencesClean(
    uintptr_t needle,
    size_t maxHits = 8192)
{
    std::vector<uintptr_t> hits;

    if (!needle)
        return hits;

    const size_t chunkSize =
        4 * 1024 * 1024;

    void* scratchRaw =
        VirtualAlloc(
            nullptr,
            chunkSize,
            MEM_COMMIT | MEM_RESERVE,
            PAGE_READWRITE
        );

    if (!scratchRaw)
    {
        std::cout
            << "[CLEAN SCAN] VirtualAlloc scratch failed.\n";

        return hits;
    }

    auto* scratch =
        reinterpret_cast<uint8_t*>(
            scratchRaw
        );

    CleanScanRange scratchRange{
        reinterpret_cast<uintptr_t>(
            scratchRaw
        ),
        reinterpret_cast<uintptr_t>(
            scratchRaw
        ) +
        chunkSize
    };

    CleanScanRange stackRange =
        CurrentThreadStackRegion();

    auto regions =
        EnumerateTileHeapRegions();

    size_t scannedBytes = 0;

    for (const auto& region :
         regions)
    {
        uintptr_t regionEnd =
            region.base +
            region.size;

        if (region.base <
                scratchRange.end &&
            regionEnd >
                scratchRange.begin)
        {
            continue;
        }

        if (region.base <
                stackRange.end &&
            regionEnd >
                stackRange.begin)
        {
            continue;
        }

        uintptr_t cursor =
            region.base;

        while (cursor <
               regionEnd)
        {
            size_t want =
                static_cast<size_t>(
                    std::min<uintptr_t>(
                        chunkSize,
                        regionEnd -
                        cursor
                    )
                );

            SIZE_T got = 0;

            BOOL ok =
                ReadProcessMemory(
                    GetCurrentProcess(),
                    reinterpret_cast<const void*>(
                        cursor
                    ),
                    scratch,
                    want,
                    &got
                );

            if (!ok ||
                !got)
            {
                cursor +=
                    want;

                continue;
            }

            scannedBytes +=
                static_cast<size_t>(
                    got
                );

            uintptr_t aligned =
                (cursor + 7) &
                ~static_cast<uintptr_t>(7);

            size_t start =
                static_cast<size_t>(
                    aligned -
                    cursor
                );

            for (size_t off = start;
                 off + sizeof(uintptr_t) <=
                    static_cast<size_t>(got);
                 off += 8)
            {
                uintptr_t value = 0;

                std::memcpy(
                    &value,
                    scratch + off,
                    sizeof(value)
                );

                if (value !=
                    needle)
                {
                    continue;
                }

                uintptr_t address =
                    cursor +
                    off;

                if (AddressInsideCleanRange(
                        address,
                        scratchRange) ||
                    AddressInsideCleanRange(
                        address,
                        stackRange))
                {
                    continue;
                }

                hits.push_back(
                    address
                );

                if (hits.size() >=
                    maxHits)
                {
                    SecureZeroMemory(
                        scratch,
                        chunkSize
                    );

                    VirtualFree(
                        scratchRaw,
                        0,
                        MEM_RELEASE
                    );

                    return hits;
                }
            }

            cursor +=
                static_cast<uintptr_t>(
                    got
                );
        }
    }

    SecureZeroMemory(
        scratch,
        chunkSize
    );

    VirtualFree(
        scratchRaw,
        0,
        MEM_RELEASE
    );

    std::cout
        << "[CLEAN SCAN] scanned="
        << (
            scannedBytes /
            (1024 * 1024)
        )
        << " MB hits="
        << hits.size()
        << "\n";

    return hits;
}

bool LooksLikeSameTileClassObject(
    uintptr_t object,
    uintptr_t tileVtable)
{
    if (!object ||
        !tileVtable)
    {
        return false;
    }

    if (!IsReadableMonitorRange(
            object,
            0x10))
    {
        return false;
    }

    return
        ReadPtr(
            object
        ) ==
        tileVtable;
}

bool LooksLikeSharedPtrControlBlock(
    uintptr_t control)
{
    if (!control ||
        !IsReadableMonitorRange(
            control,
            sizeof(uintptr_t)))
    {
        return false;
    }

    uintptr_t vt =
        ReadPtr(
            control
        );

    if (!InsideExeImage(
            vt))
    {
        return false;
    }

    std::string rtti =
        LowerAscii(
            TryReadMsvcRttiTypeName(
                vt
            )
        );

    if (rtti.empty())
        return true;

    return
        rtti.find(
            "_ref_count") !=
            std::string::npos ||
        rtti.find(
            "tile") !=
            std::string::npos;
}

TilePointerRun ExpandTilePointerRunStrided(
    uintptr_t occurrence,
    uintptr_t tile,
    uintptr_t tileVtable,
    size_t stride)
{
    TilePointerRun run{};

    if (!occurrence ||
        !tile ||
        !tileVtable ||
        (
            stride != 8 &&
            stride != 16
        ))
    {
        return run;
    }

    const size_t maxSide =
        4096;

    auto sameTileAt =
        [&](
            uintptr_t address)
        {
            uintptr_t value =
                ReadPtr(
                    address
                );

            return
                LooksLikeSameTileClassObject(
                    value,
                    tileVtable
                );
        };

    uintptr_t begin =
        occurrence;

    uintptr_t end =
        occurrence +
        stride;

    size_t leftSteps = 0;

    while (leftSteps <
           maxSide &&
           begin >= stride)
    {
        uintptr_t previous =
            begin -
            stride;

        if (!sameTileAt(
                previous))
        {
            break;
        }

        begin =
            previous;

        ++leftSteps;
    }

    size_t rightSteps = 0;

    while (rightSteps <
           maxSide)
    {
        if (!sameTileAt(
                end))
        {
            break;
        }

        end +=
            stride;

        ++rightSteps;
    }

    size_t count = 0;
    size_t companionMatches = 0;

    for (uintptr_t p = begin;
         p < end;
         p += stride)
    {
        uintptr_t value =
            ReadPtr(
                p
            );

        if (!LooksLikeSameTileClassObject(
                value,
                tileVtable))
        {
            continue;
        }

        ++count;

        if (stride == 16)
        {
            uintptr_t control =
                ReadPtr(
                    p + 8
                );

            if (LooksLikeSharedPtrControlBlock(
                    control))
            {
                ++companionMatches;
            }
        }
    }

    if (count < 5)
    {
        return TilePointerRun{};
    }

    if (stride == 16)
    {
        size_t required =
            std::max<size_t>(
                3,
                count / 2
            );

        if (companionMatches <
            required)
        {
            return TilePointerRun{};
        }
    }

    run.begin =
        begin;

    run.end =
        end;

    run.occurrence =
        occurrence;

    run.slotIndex =
        static_cast<size_t>(
            (
                occurrence -
                begin
            ) /
            stride
        );

    run.tileCount =
        count;

    run.stride =
        stride;

    run.companionMatches =
        companionMatches;

    run.storageMode =
        stride == 16
            ? "shared_ptr_array"
            : "raw_pointer_array";

    return run;
}

std::vector<TilePointerRun>
FindTilePointerRuns(
    const std::vector<uintptr_t>& refs,
    uintptr_t tile,
    uintptr_t tileVtable)
{
    std::vector<TilePointerRun> out;

    for (uintptr_t ref :
         refs)
    {
        for (size_t stride :
             {
                 static_cast<size_t>(8),
                 static_cast<size_t>(16)
             })
        {
            TilePointerRun run =
                ExpandTilePointerRunStrided(
                    ref,
                    tile,
                    tileVtable,
                    stride
                );

            if (!run.begin ||
                !run.tileCount)
            {
                continue;
            }

            bool duplicate =
                false;

            for (const auto& existing :
                 out)
            {
                if (existing.begin ==
                        run.begin &&
                    existing.stride ==
                        run.stride)
                {
                    duplicate =
                        true;

                    break;
                }
            }

            if (!duplicate)
            {
                out.push_back(
                    run
                );
            }
        }
    }

    std::sort(
        out.begin(),
        out.end(),
        [](
            const TilePointerRun& a,
            const TilePointerRun& b)
        {
            if (a.tileCount !=
                b.tileCount)
            {
                return
                    a.tileCount >
                    b.tileCount;
            }

            if (a.storageMode !=
                b.storageMode)
            {
                return
                    a.storageMode ==
                    "shared_ptr_array";
            }

            return
                a.begin <
                b.begin;
        }
    );

    return out;
}


std::vector<TileArrayHeaderCandidate>
FindArrayHeadersForRun(
    const TilePointerRun& run)
{
    std::vector<TileArrayHeaderCandidate>
        out;

    auto beginRefs =
        FindExactPointerOccurrencesClean(
            run.begin,
            4096
        );

    for (uintptr_t ref :
         beginRefs)
    {
        uintptr_t begin =
            ReadPtr(
                ref
            );

        uintptr_t end =
            ReadPtr(
                ref + 8
            );

        uintptr_t cap =
            ReadPtr(
                ref + 16
            );

        if (begin !=
            run.begin)
        {
            continue;
        }

        if (!end ||
            end < begin ||
            !cap ||
            cap < end)
        {
            continue;
        }

        if ((begin & 7) ||
            (end & 7) ||
            (cap & 7))
        {
            continue;
        }

        uintptr_t used =
            end -
            begin;

        uintptr_t capacityBytes =
            cap -
            begin;

        if (!run.stride ||
            used %
                run.stride !=
            0 ||
            capacityBytes %
                run.stride !=
            0)
        {
            continue;
        }

        size_t count =
            static_cast<size_t>(
                used /
                run.stride
            );

        size_t capacity =
            static_cast<size_t>(
                capacityBytes /
                run.stride
            );

        if (count < run.tileCount ||
            capacity < count ||
            count > 20000 ||
            capacity > 40000)
        {
            continue;
        }

        TileArrayHeaderCandidate c{};

        c.header = ref;
        c.begin = begin;
        c.end = end;
        c.cap = cap;
        c.count = count;
        c.capacity = capacity;

        out.push_back(
            c
        );
    }

    std::sort(
        out.begin(),
        out.end(),
        [](
            const TileArrayHeaderCandidate& a,
            const TileArrayHeaderCandidate& b)
        {
            if (a.count != b.count)
                return a.count < b.count;

            if (a.capacity != b.capacity)
                return a.capacity < b.capacity;

            return a.header < b.header;
        }
    );

    return out;
}

std::vector<MapArrayProvenanceCandidate>
FindMapOwnersForArrayHeader(
    uintptr_t map,
    const TileArrayHeaderCandidate& header)
{
    std::vector<MapArrayProvenanceCandidate>
        out;

    const uintptr_t mapScan =
        0x340;

    const uintptr_t ownerWindow =
        0x1000;

    const uintptr_t childScan =
        0x300;

    for (uintptr_t mapOff = 0;
         mapOff + 8 <= mapScan;
         mapOff += 8)
    {
        uintptr_t first =
            ReadPtr(
                map +
                mapOff
            );

        if (!IsReadablePrivatePointer(
                first))
        {
            continue;
        }

        if (header.header >=
                first &&
            header.header -
                first <=
                ownerWindow)
        {
            MapArrayProvenanceCandidate c{};

            c.depth = 1;
            c.mapOffset = mapOff;
            c.owner = first;
            c.header = header.header;
            c.headerOffset =
                header.header -
                first;
            c.count = header.count;
            c.capacity = header.capacity;

            out.push_back(
                c
            );
        }

        if (first ==
            header.header)
        {
            MapArrayProvenanceCandidate c{};

            c.depth = 1;
            c.mapOffset = mapOff;
            c.owner = first;
            c.header = header.header;
            c.headerOffset = 0;
            c.count = header.count;
            c.capacity = header.capacity;

            out.push_back(
                c
            );
        }

        for (uintptr_t childOff = 0;
             childOff + 8 <=
                childScan;
             childOff += 8)
        {
            uintptr_t second =
                ReadPtr(
                    first +
                    childOff
                );

            if (!IsReadablePrivatePointer(
                    second))
            {
                continue;
            }

            if (header.header >=
                    second &&
                header.header -
                    second <=
                    ownerWindow)
            {
                MapArrayProvenanceCandidate c{};

                c.depth = 2;
                c.mapOffset = mapOff;
                c.childOffset = childOff;
                c.owner = second;
                c.header = header.header;
                c.headerOffset =
                    header.header -
                    second;
                c.count = header.count;
                c.capacity = header.capacity;

                out.push_back(
                    c
                );
            }

            if (second ==
                header.header)
            {
                MapArrayProvenanceCandidate c{};

                c.depth = 2;
                c.mapOffset = mapOff;
                c.childOffset = childOff;
                c.owner = second;
                c.header = header.header;
                c.headerOffset = 0;
                c.count = header.count;
                c.capacity = header.capacity;

                out.push_back(
                    c
                );
            }
        }
    }

    return out;
}


struct TilePathEvidence
{
    MapPosition position{};

    uintptr_t tile = 0;
    uintptr_t tileVtable = 0;

    TilePointerRun run{};
    TileArrayHeaderCandidate header{};
    MapArrayProvenanceCandidate provenance{};
};

bool SameTilePathSignature(
    const TilePathEvidence& a,
    const TilePathEvidence& b)
{
    if (a.run.stride !=
            b.run.stride ||
        a.run.storageMode !=
            b.run.storageMode)
    {
        return false;
    }

    if (a.provenance.depth !=
        b.provenance.depth)
    {
        return false;
    }

    if (a.provenance.mapOffset !=
        b.provenance.mapOffset)
    {
        return false;
    }

    if (a.provenance.headerOffset !=
        b.provenance.headerOffset)
    {
        return false;
    }

    if (a.provenance.depth == 2 &&
        a.provenance.childOffset !=
            b.provenance.childOffset)
    {
        return false;
    }

    return true;
}

std::string TilePathSignatureText(
    const TilePathEvidence& e)
{
    std::ostringstream out;

    out
        << "mode="
        << e.run.storageMode
        << " stride="
        << e.run.stride
        << " depth="
        << e.provenance.depth
        << " Map[+"
        << HexU64(
            e.provenance.mapOffset
        )
        << "]";

    if (e.provenance.depth == 2)
    {
        out
            << " -> [+"
            << HexU64(
                e.provenance.childOffset
            )
            << "]";
    }

    out
        << " headerOff=+"
        << HexU64(
            e.provenance.headerOffset
        );

    return
        out.str();
}

std::vector<TilePathEvidence>
CollectTilePathEvidence(
    uintptr_t map,
    uintptr_t tile,
    uintptr_t tileVtable,
    const MapPosition& position,
    bool verbose)
{
    std::vector<TilePathEvidence>
        evidence;

    auto refs =
        FindExactPointerOccurrencesClean(
            tile
        );

    auto runs =
        FindTilePointerRuns(
            refs,
            tile,
            tileVtable
        );

    if (verbose)
    {
        std::cout
            << "Clean Tile* refs     : "
            << refs.size()
            << "\n"
            << "Tile storage runs   : "
            << runs.size()
            << "\n";

        for (size_t r = 0;
             r < runs.size() &&
             r < 8;
             ++r)
        {
            std::cout
                << "  run#"
                << r
                << " mode="
                << runs[r].storageMode
                << " stride="
                << runs[r].stride
                << " tiles="
                << runs[r].tileCount
                << " companion="
                << runs[r].companionMatches
                << "\n";
        }
    }

    for (size_t i = 0;
         i < runs.size();
         ++i)
    {
        const auto& run =
            runs[i];

        auto headers =
            FindArrayHeadersForRun(
                run
            );

        for (const auto& header :
             headers)
        {
            // Strong runtime evidence: the header describes exactly the
            // contiguous Tile* run containing the current Tile.
            if (header.count <
                run.tileCount)
            {
                continue;
            }

            auto owners =
                FindMapOwnersForArrayHeader(
                    map,
                    header
                );

            for (const auto& owner :
                 owners)
            {
                TilePathEvidence e{};

                e.position =
                    position;

                e.tile =
                    tile;

                e.tileVtable =
                    tileVtable;

                e.run =
                    run;

                e.header =
                    header;

                e.provenance =
                    owner;

                evidence.push_back(
                    e
                );

                if (verbose)
                {
                    std::cout
                        << "  evidence: "
                        << TilePathSignatureText(
                            e
                        )
                        << " tiles="
                        << run.tileCount
                        << " index="
                        << run.slotIndex
                        << " owner="
                        << HexPtr(
                            owner.owner
                        )
                        << " header="
                        << HexPtr(
                            header.header
                        )
                        << "\n";
                }
            }
        }
    }

    // Deduplicate identical signatures within the same snapshot.
    std::vector<TilePathEvidence>
        unique;

    for (const auto& e :
         evidence)
    {
        bool duplicate =
            false;

        for (const auto& u :
             unique)
        {
            if (SameTilePathSignature(
                    e,
                    u))
            {
                duplicate = true;
                break;
            }
        }

        if (!duplicate)
        {
            unique.push_back(
                e
            );
        }
    }

    return
        unique;
}


bool ValidateTilePathTemplateAtCurrentTile(
    uintptr_t map,
    uintptr_t tile,
    uintptr_t tileVtable,
    const MapPosition& position,
    const TilePathEvidence& templateEvidence,
    TilePathEvidence& outEvidence,
    bool verbose)
{
    if (!map ||
        !tile ||
        !tileVtable)
    {
        return false;
    }

    const auto& t =
        templateEvidence.provenance;

    if (!t.depth ||
        !templateEvidence.run.stride)
    {
        return false;
    }

    uintptr_t first =
        ReadPtr(
            map +
            t.mapOffset
        );

    if (!IsReadablePrivatePointer(
            first))
    {
        return false;
    }

    uintptr_t owner =
        first;

    if (t.depth == 2)
    {
        owner =
            ReadPtr(
                first +
                t.childOffset
            );

        if (!IsReadablePrivatePointer(
                owner))
        {
            return false;
        }
    }

    uintptr_t headerAddress =
        owner +
        t.headerOffset;

    if (!IsReadableMonitorRange(
            headerAddress,
            3 * sizeof(uintptr_t)))
    {
        return false;
    }

    uintptr_t begin =
        ReadPtr(
            headerAddress
        );

    uintptr_t end =
        ReadPtr(
            headerAddress + 8
        );

    uintptr_t cap =
        ReadPtr(
            headerAddress + 16
        );

    if (!begin ||
        !end ||
        !cap ||
        end < begin ||
        cap < end ||
        (begin & 7) ||
        (end & 7) ||
        (cap & 7))
    {
        return false;
    }

    const size_t stride =
        templateEvidence.run.stride;

    uintptr_t used =
        end -
        begin;

    uintptr_t capacityBytes =
        cap -
        begin;

    if (!stride ||
        used % stride != 0 ||
        capacityBytes % stride != 0)
    {
        return false;
    }

    size_t count =
        static_cast<size_t>(
            used /
            stride
        );

    size_t capacity =
        static_cast<size_t>(
            capacityBytes /
            stride
        );

    if (count < 5 ||
        count > 20000 ||
        capacity < count ||
        capacity > 40000)
    {
        return false;
    }

    if (!IsReadableMonitorRange(
            begin,
            used))
    {
        return false;
    }

    uintptr_t occurrence = 0;
    size_t tileClassCount = 0;
    size_t companionMatches = 0;

    for (size_t i = 0;
         i < count;
         ++i)
    {
        uintptr_t entry =
            begin +
            i *
            stride;

        uintptr_t object =
            ReadPtr(
                entry
            );

        if (object == tile)
        {
            occurrence =
                entry;
        }

        if (!LooksLikeSameTileClassObject(
                object,
                tileVtable))
        {
            continue;
        }

        ++tileClassCount;

        if (stride == 16)
        {
            uintptr_t control =
                ReadPtr(
                    entry + 8
                );

            if (LooksLikeSharedPtrControlBlock(
                    control))
            {
                ++companionMatches;
            }
        }
    }

    if (!occurrence ||
        tileClassCount < 5)
    {
        return false;
    }

    if (stride == 16)
    {
        uintptr_t currentControl =
            ReadPtr(
                occurrence + 8
            );

        if (!LooksLikeSharedPtrControlBlock(
                currentControl))
        {
            return false;
        }

        size_t required =
            std::max<size_t>(
                3,
                tileClassCount / 2
            );

        if (companionMatches <
            required)
        {
            return false;
        }
    }

    TilePathEvidence e{};

    e.position =
        position;

    e.tile =
        tile;

    e.tileVtable =
        tileVtable;

    e.run.begin =
        begin;

    e.run.end =
        end;

    e.run.occurrence =
        occurrence;

    e.run.slotIndex =
        static_cast<size_t>(
            (
                occurrence -
                begin
            ) /
            stride
        );

    e.run.tileCount =
        tileClassCount;

    e.run.stride =
        stride;

    e.run.companionMatches =
        companionMatches;

    e.run.storageMode =
        templateEvidence.run.storageMode;

    e.header.header =
        headerAddress;

    e.header.begin =
        begin;

    e.header.end =
        end;

    e.header.cap =
        cap;

    e.header.count =
        count;

    e.header.capacity =
        capacity;

    e.provenance.depth =
        t.depth;

    e.provenance.mapOffset =
        t.mapOffset;

    e.provenance.childOffset =
        t.childOffset;

    e.provenance.owner =
        owner;

    e.provenance.header =
        headerAddress;

    e.provenance.headerOffset =
        t.headerOffset;

    e.provenance.count =
        count;

    e.provenance.capacity =
        capacity;

    outEvidence =
        e;

    if (verbose)
    {
        std::cout
            << "[TEMPLATE PASS] "
            << TilePathSignatureText(
                e
            )
            << " totalEntries="
            << count
            << " tileClassEntries="
            << tileClassCount
            << " currentIndex="
            << e.run.slotIndex
            << " owner="
            << HexPtr(
                owner
            )
            << " header="
            << HexPtr(
                headerAddress
            )
            << "\n";
    }

    return true;
}

bool CaptureTilePathSnapshotFromTemplates(
    DbProfile& profile,
    uintptr_t localPlayer,
    const char* label,
    const std::vector<TilePathEvidence>& templates,
    std::vector<TilePathEvidence>& out)
{
    out.clear();

    if (templates.empty())
        return false;

    std::cout
        << "\n============================================================\n"
        << "       MAP TILE TEMPLATE REVALIDATION "
        << label
        << "\n"
        << "============================================================\n"
        << "[MODE] Nao redescobre provenance do zero.\n"
        << "[MODE] Revalida diretamente os caminhos aprendidos no Snapshot A.\n";

    if (!WaitForTileWorldReady(
            profile,
            localPlayer))
    {
        return false;
    }

    MapPosition position{};

    uintptr_t tile =
        FindCurrentTileObjectReadOnly(
            profile,
            localPlayer,
            position
        );

    if (!tile)
    {
        std::cout
            << "[TEMPLATE] Current Tile nao foi resolvido.\n";

        return false;
    }

    uintptr_t tileVtable =
        ReadPtr(
            tile
        );

    uintptr_t map =
        g_exeBase +
        profile.mapRva;

    std::cout
        << "[TEMPLATE] Position="
        << position.x
        << ","
        << position.y
        << ","
        << static_cast<unsigned>(
            position.z
        )
        << " Tile="
        << HexPtr(
            tile
        )
        << "\n";

    for (const auto& t :
         templates)
    {
        TilePathEvidence current{};

        if (!ValidateTilePathTemplateAtCurrentTile(
                map,
                tile,
                tileVtable,
                position,
                t,
                current,
                true))
        {
            continue;
        }

        bool duplicate =
            false;

        for (const auto& existing :
             out)
        {
            if (SameTilePathSignature(
                    current,
                    existing))
            {
                duplicate =
                    true;

                break;
            }

            // Two different pointer paths can describe the exact same
            // runtime storage header (subobject/alias views). Keep both
            // signatures available for intersection, but do not duplicate
            // an identical signature.
        }

        if (!duplicate)
        {
            out.push_back(
                current
            );
        }
    }

    std::cout
        << "[TEMPLATE] Validated signatures="
        << out.size()
        << "\n";

    return
        !out.empty();
}


bool CaptureTilePathSnapshot(
    DbProfile& profile,
    uintptr_t localPlayer,
    const char* label,
    TilePathEvidence& chosen,
    std::vector<TilePathEvidence>& all)
{
    std::cout
        << "\n============================================================\n"
        << "              MAP TILE PATH SNAPSHOT "
        << label
        << "\n"
        << "============================================================\n";

    if (!WaitForTileWorldReady(
            profile,
            localPlayer))
    {
        return false;
    }

    MapPosition position =
        ReadDiscoveredPlayerPosition(
            localPlayer,
            profile
        );

    if (!MapPositionPlausible(
            position))
    {
        std::cout
            << "[STOP] Position atual invalida para provenance.\n";

        return false;
    }

    uintptr_t map =
        g_exeBase +
        profile.mapRva;

    // V3.7:
    // Do NOT require a unique current Tile before provenance.
    // Some builds keep multiple exact Tile mirrors containing the same
    // LocalPlayer. Let the real Map storage decide which mirror matters.
    if (profile.tileVtableRva)
    {
        auto typed =
            FindTileCandidatesByKnownVtableReadOnly(
                profile,
                localPlayer,
                position
            );

        std::vector<TileVectorCandidate>
            exact;

        uintptr_t expectedVtable =
            g_exeBase +
            profile.tileVtableRva;

        for (const auto& c :
             typed)
        {
            if (c.vectorOffset !=
                    profile.tileThingsBegin ||
                c.vtable !=
                    expectedVtable)
            {
                continue;
            }

            exact.push_back(
                c
            );
        }

        if (exact.size() > 1)
        {
            std::cout
                << "[MULTI TILE] "
                << exact.size()
                << " exact Tile mirrors remain.\n"
                << "[MULTI TILE] Resolving by Map provenance instead of guessing.\n";

            std::vector<TilePathEvidence>
                combined;

            for (size_t i = 0;
                 i < exact.size();
                 ++i)
            {
                const auto& c =
                    exact[i];

                auto evidence =
                    CollectTilePathEvidence(
                        map,
                        c.objectBase,
                        c.vtable,
                        position,
                        false
                    );

                std::cout
                    << "  candidate#"
                    << i
                    << " tile="
                    << HexPtr(
                        c.objectBase
                    )
                    << " things="
                    << c.count
                    << " provenance="
                    << evidence.size()
                    << "\n";

                for (const auto& e :
                     evidence)
                {
                    bool duplicate = false;

                    for (const auto& u :
                         combined)
                    {
                        if (SameTilePathSignature(
                                e,
                                u))
                        {
                            duplicate = true;
                            break;
                        }
                    }

                    if (!duplicate)
                    {
                        combined.push_back(
                            e
                        );
                    }
                }
            }

            all =
                combined;

            std::cout
                << "[MULTI TILE] Unique provenance signatures="
                << all.size()
                << "\n";

            if (all.empty())
            {
                std::cout
                    << "[CHECK] Mirrors encontrados, mas nenhum pertenceu "
                    << "a um storage forte do Map neste snapshot.\n";

                return false;
            }

            if (all.size() == 1)
            {
                chosen =
                    all[0];
            }

            return true;
        }

        if (exact.size() == 1)
        {
            uintptr_t tile =
                exact[0].objectBase;

            std::cout
                << "[TILE SEED] Resolver=known_tile_vtable_rtti\n"
                << "Position             : "
                << position.x
                << ","
                << position.y
                << ","
                << static_cast<unsigned>(
                    position.z
                )
                << "\n"
                << "Tile                 : "
                << HexPtr(
                    tile
                )
                << "\n";

            all =
                CollectTilePathEvidence(
                    map,
                    tile,
                    exact[0].vtable,
                    position,
                    true
                );

            std::cout
                << "Unique path signatures: "
                << all.size()
                << "\n";

            if (all.empty())
            {
                std::cout
                    << "[CHECK] Nenhum provenance forte neste snapshot.\n";

                return false;
            }

            if (all.size() == 1)
            {
                chosen =
                    all[0];
            }

            return true;
        }
    }

    // Legacy/raw fallback is retained for clients without typed RTTI data.
    uintptr_t tile =
        FindCurrentTileObjectReadOnly(
            profile,
            localPlayer,
            position
        );

    if (!tile)
    {
        std::cout
            << "[STOP] Tile atual nao foi resolvido nem por RTTI/provenance "
            << "nem pelo fallback legado.\n";

        return false;
    }

    uintptr_t tileVtable =
        ReadPtr(
            tile
        );

    std::cout
        << "Position             : "
        << position.x
        << ","
        << position.y
        << ","
        << static_cast<unsigned>(
            position.z
        )
        << "\n"
        << "Tile                 : "
        << HexPtr(
            tile
        )
        << "\n";

    all =
        CollectTilePathEvidence(
            map,
            tile,
            tileVtable,
            position,
            true
        );

    std::cout
        << "Unique path signatures: "
        << all.size()
        << "\n";

    if (all.empty())
    {
        std::cout
            << "[CHECK] Nenhum provenance forte neste snapshot.\n";

        return false;
    }

    if (all.size() == 1)
    {
        chosen =
            all[0];
    }

    return true;
}

void PrintTileArrayProvenance(
    uintptr_t map,
    uintptr_t tile,
    uintptr_t tileVtable)
{
    std::cout
        << "\n============================================================\n"
        << "          CLEAN TILE* REFERENCE SCAN\n"
        << "============================================================\n"
        << "Self-generated scan scratch and current stack are excluded.\n";

    auto refs =
        FindExactPointerOccurrencesClean(
            tile
        );

    std::cout
        << "Clean Tile* refs     : "
        << refs.size()
        << "\n";

    auto runs =
        FindTilePointerRuns(
            refs,
            tile,
            tileVtable
        );

    std::cout
        << "Tile* array runs     : "
        << runs.size()
        << "\n";

    if (runs.empty())
    {
        std::cout
            << "[CHECK] Nenhuma sequencia >=5 Tile* da mesma classe foi encontrada.\n";

        return;
    }

    for (size_t i = 0;
         i < runs.size() &&
         i < 16;
         ++i)
    {
        const auto& run =
            runs[i];

        std::cout
            << "\n[RUN #"
            << i
            << "] begin="
            << HexPtr(
                run.begin
            )
            << " end="
            << HexPtr(
                run.end
            )
            << " tiles="
            << run.tileCount
            << " currentIndex="
            << run.slotIndex
            << "\n";

        auto headers =
            FindArrayHeadersForRun(
                run
            );

        std::cout
            << "  vector-like headers: "
            << headers.size()
            << "\n";

        for (size_t h = 0;
             h < headers.size() &&
             h < 16;
             ++h)
        {
            const auto& header =
                headers[h];

            std::cout
                << "  header#"
                << h
                << " @"
                << HexPtr(
                    header.header
                )
                << " count="
                << header.count
                << " cap="
                << header.capacity
                << "\n";

            auto owners =
                FindMapOwnersForArrayHeader(
                    map,
                    header
                );

            if (owners.empty())
            {
                std::cout
                    << "    Map provenance: none within 2 targeted hops\n";

                continue;
            }

            for (size_t o = 0;
                 o < owners.size() &&
                 o < 16;
                 ++o)
            {
                const auto& owner =
                    owners[o];

                std::cout
                    << "    provenance#"
                    << o
                    << " depth="
                    << owner.depth
                    << " Map[+"
                    << HexU64(
                        owner.mapOffset
                    )
                    << "]";

                if (owner.depth == 2)
                {
                    std::cout
                        << " -> [+"
                        << HexU64(
                            owner.childOffset
                        )
                        << "]";
                }

                std::cout
                    << " owner="
                    << HexPtr(
                        owner.owner
                    )
                    << " headerOff=+"
                    << HexU64(
                        owner.headerOffset
                    )
                    << " count="
                    << owner.count
                    << " cap="
                    << owner.capacity
                    << "\n";
            }
        }
    }
}

bool RunMapTilePathRecon(
    DbProfile& profile)
{
    std::cout
        << "\n============================================================\n"
        << "   STAGE 5B - MAP TILE PATH TWO-POSITION VALIDATION\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "[NO WRITE] Nenhuma escrita em memoria do jogo\n"
        << "[NO HOOK] Nenhum hook\n"
        << "[NO CALL] Map::getTile e outras funcoes internas NAO serao chamadas\n"
        << "\n"
        << "Criterio para promover:\n"
        << "  - Snapshot A encontra provenance forte\n"
        << "  - voce muda para outro SQM no mesmo andar\n"
        << "  - Snapshot B revalida ou redescobre provenance forte\n"
        << "  - exatamente UMA assinatura estrutural aparece nos dois\n"
        << "  - Tile* precisa mudar entre A e B\n";

    const bool tileThingsConfirmed =
        profile.tileThingsStatus ==
            "discovered_runtime_selfcheck_pass" ||
        profile.tileThingsStatus ==
            "confirmed_runtime_localplayer_two_tiles";

    if (!profile.mapRva ||
        !profile.tileThingsBegin ||
        !tileThingsConfirmed)
    {
        std::cout
            << "[STOP] Map/Tile::things ainda nao estao confirmados.\n";

        return false;
    }

    uintptr_t localPlayer =
        WaitForDiscoveryLocalPlayer(
            profile,
            "STAGE 5B - MAP TILE PATH TWO-POSITION"
        );

    if (!localPlayer)
        return false;

    TilePathEvidence chosenA{};
    std::vector<TilePathEvidence>
        allA;

    if (!CaptureTilePathSnapshot(
            profile,
            localPlayer,
            "A",
            chosenA,
            allA))
    {
        profile.mapTilePathStatus =
            "unresolved_snapshot_A";

        return false;
    }

    MapPosition posA =
        allA[0].position;

    MapPosition posB{};

    while (true)
    {
        std::cout
            << "\nPASSO B - MUDE PARA OUTRO SQM\n"
            << "Ande para outro SQM, permanea no MESMO andar Z="
            << static_cast<unsigned>(
                posA.z
            )
            << ", pare e pressione ENTER.\n";

        WaitEnter(
            "Quando estiver parado no SQM B, pressione ENTER..."
        );

        posB =
            ReadDiscoveredPlayerPosition(
                localPlayer,
                profile
            );

        if (!MapPositionPlausible(
                posB))
        {
            std::cout
                << "[RETRY] Position B invalida.\n";

            continue;
        }

        if (posB.z !=
            posA.z)
        {
            std::cout
                << "[RETRY] Nao troque de andar. Z atual="
                << static_cast<unsigned>(
                    posB.z
                )
                << " esperado="
                << static_cast<unsigned>(
                    posA.z
                )
                << "\n";

            continue;
        }

        if (SameMapPosition(
                posA,
                posB))
        {
            std::cout
                << "[RETRY] Ainda esta no mesmo SQM.\n";

            continue;
        }

        break;
    }

    TilePathEvidence chosenB{};
    std::vector<TilePathEvidence>
        allB;

    if (!CaptureTilePathSnapshot(
            profile,
            localPlayer,
            "B",
            chosenB,
            allB))
    {
        std::cout
            << "[FALLBACK] Snapshot B nao redescobriu provenance.\n"
            << "[FALLBACK] Revalidando diretamente os caminhos estruturais do Snapshot A...\n";

        if (!CaptureTilePathSnapshotFromTemplates(
                profile,
                localPlayer,
                "B",
                allA,
                allB))
        {
            profile.mapTilePathStatus =
                "unresolved_snapshot_B";

            return false;
        }
    }

    std::vector<std::pair<
        TilePathEvidence,
        TilePathEvidence
    >> matches;

    for (const auto& a :
         allA)
    {
        for (const auto& b :
             allB)
        {
            if (!SameTilePathSignature(
                    a,
                    b))
            {
                continue;
            }

            if (a.tile ==
                b.tile)
            {
                continue;
            }

            matches.push_back(
                {
                    a,
                    b
                }
            );
        }
    }

    // Deduplicate signature matches.
    std::vector<std::pair<
        TilePathEvidence,
        TilePathEvidence
    >> uniqueMatches;

    for (const auto& pair :
         matches)
    {
        bool duplicate =
            false;

        for (const auto& existing :
             uniqueMatches)
        {
            if (SameTilePathSignature(
                    pair.first,
                    existing.first))
            {
                duplicate = true;
                break;
            }

            const bool sameRuntimeStorage =
                pair.first.run.stride ==
                    existing.first.run.stride &&
                pair.first.run.storageMode ==
                    existing.first.run.storageMode &&
                pair.first.header.header ==
                    existing.first.header.header &&
                pair.second.header.header ==
                    existing.second.header.header;

            if (sameRuntimeStorage)
            {
                duplicate = true;
                break;
            }
        }

        if (!duplicate)
        {
            uniqueMatches.push_back(
                pair
            );
        }
    }

    std::cout
        << "\n============================================================\n"
        << "            TWO-POSITION PATH INTERSECTION\n"
        << "============================================================\n"
        << "Snapshot A signatures : "
        << allA.size()
        << "\n"
        << "Snapshot B signatures : "
        << allB.size()
        << "\n"
        << "Common signatures     : "
        << uniqueMatches.size()
        << "\n";

    for (size_t i = 0;
         i < uniqueMatches.size();
         ++i)
    {
        const auto& a =
            uniqueMatches[i].first;

        const auto& b =
            uniqueMatches[i].second;

        std::cout
            << "#"
            << i
            << " "
            << TilePathSignatureText(
                a
            )
            << "\n"
            << "   A pos="
            << a.position.x
            << ","
            << a.position.y
            << ","
            << static_cast<unsigned>(
                a.position.z
            )
            << " tile="
            << HexPtr(
                a.tile
            )
            << " tiles="
            << a.run.tileCount
            << " index="
            << a.run.slotIndex
            << " owner="
            << HexPtr(
                a.provenance.owner
            )
            << " header="
            << HexPtr(
                a.header.header
            )
            << "\n"
            << "   B pos="
            << b.position.x
            << ","
            << b.position.y
            << ","
            << static_cast<unsigned>(
                b.position.z
            )
            << " tile="
            << HexPtr(
                b.tile
            )
            << " tiles="
            << b.run.tileCount
            << " index="
            << b.run.slotIndex
            << " owner="
            << HexPtr(
                b.provenance.owner
            )
            << " header="
            << HexPtr(
                b.header.header
            )
            << "\n";
    }

    if (uniqueMatches.empty())
    {
        std::cout
            << "[FALLBACK] Nenhuma assinatura comum pela redescoberta independente.\n"
            << "[FALLBACK] Fazendo validacao dirigida dos templates A no estado B atual...\n";

        std::vector<TilePathEvidence>
            templateB;

        if (CaptureTilePathSnapshotFromTemplates(
                profile,
                localPlayer,
                "B-DIRECT",
                allA,
                templateB))
        {
            for (const auto& a :
                 allA)
            {
                for (const auto& b :
                     templateB)
                {
                    if (!SameTilePathSignature(
                            a,
                            b))
                    {
                        continue;
                    }

                    if (a.tile ==
                        b.tile)
                    {
                        continue;
                    }

                    bool duplicate =
                        false;

                    for (const auto& existing :
                         uniqueMatches)
                    {
                        if (SameTilePathSignature(
                                a,
                                existing.first))
                        {
                            duplicate =
                                true;

                            break;
                        }

                        const bool sameRuntimeStorage =
                            a.run.stride ==
                                existing.first.run.stride &&
                            a.run.storageMode ==
                                existing.first.run.storageMode &&
                            a.header.header ==
                                existing.first.header.header &&
                            b.header.header ==
                                existing.second.header.header;

                        if (sameRuntimeStorage)
                        {
                            duplicate =
                                true;

                            break;
                        }
                    }

                    if (!duplicate)
                    {
                        uniqueMatches.push_back(
                            {
                                a,
                                b
                            }
                        );
                    }
                }
            }

            allB =
                templateB;

            std::cout
                << "[FALLBACK] Common signatures after directed validation: "
                << uniqueMatches.size()
                << "\n";
        }
    }

    if (uniqueMatches.empty())
    {
        profile.mapTilePathStatus =
            "unresolved_no_common_signature";

        std::cout
            << "[CHECK] Nenhuma assinatura estrutural sobreviveu A -> B.\n";

        return false;
    }

    if (uniqueMatches.size() != 1)
    {
        profile.mapTilePathStatus =
            "ambiguous_multiple_common_signatures";

        std::cout
            << "[CHECK] Mais de uma assinatura estrutural sobreviveu.\n"
            << "Nenhuma sera promovida.\n";

        return false;
    }

    const auto& winnerA =
        uniqueMatches[0].first;

    const auto& winnerB =
        uniqueMatches[0].second;

    profile.mapTilePathDepth =
        static_cast<uintptr_t>(
            winnerA.provenance.depth
        );

    profile.mapTilePathMapOffset =
        winnerA.provenance.mapOffset;

    profile.mapTilePathChildOffset =
        winnerA.provenance.childOffset;

    profile.mapTilePathHeaderOffset =
        winnerA.provenance.headerOffset;

    profile.mapTileStorageStride =
        static_cast<uintptr_t>(
            winnerA.run.stride
        );

    profile.mapTileStorageMode =
        winnerA.run.storageMode;

    profile.mapTilePathStatus =
        "confirmed_runtime_two_positions";

    std::cout
        << "\n============================================================\n"
        << "              MAP -> TILE PATH CONFIRMED\n"
        << "============================================================\n"
        << "Depth                : "
        << winnerA.provenance.depth
        << "\n"
        << "Map offset           : +"
        << HexU64(
            profile.mapTilePathMapOffset
        )
        << "\n"
        << "Child offset         : +"
        << HexU64(
            profile.mapTilePathChildOffset
        )
        << "\n"
        << "Array header offset  : +"
        << HexU64(
            profile.mapTilePathHeaderOffset
        )
        << "\n"
        << "Storage mode         : "
        << profile.mapTileStorageMode
        << "\n"
        << "Element stride       : "
        << profile.mapTileStorageStride
        << "\n"
        << "Evidence             : mesma assinatura estrutural em 2 SQMs\n"
        << "                       Tile* mudou entre A e B\n"
        << "Status               : "
        << profile.mapTilePathStatus
        << "\n"
        << "\n"
        << "[FEITO] STAGE 5B confirmou Map -> Tile storage sem chamar Map::getTile.\n";

    return true;
}


bool EnsureMapTilePathDiscovery(
    DbProfile& profile,
    std::vector<DbProfile>& database,
    int profileIndex,
    const std::string& databasePath)
{
    if (profile.mapTilePathStatus ==
            "confirmed_runtime_two_positions" &&
        profile.mapTilePathDepth &&
        profile.mapTilePathHeaderOffset)
    {
        if (!profile.mapTileStorageStride)
            profile.mapTileStorageStride = sizeof(uintptr_t);

        if (profile.mapTileStorageMode.empty() ||
            profile.mapTileStorageMode == "unknown")
        {
            profile.mapTileStorageMode =
                "raw_pointer_array";
        }

        std::cout
            << "\n[FEITO] STAGE 5B - Map -> Tile path ja esta confirmado.\n"
            << "Depth="
            << profile.mapTilePathDepth
            << " MapOff=+"
            << HexU64(
                profile.mapTilePathMapOffset
            )
            << " ChildOff=+"
            << HexU64(
                profile.mapTilePathChildOffset
            )
            << " HeaderOff=+"
            << HexU64(
                profile.mapTilePathHeaderOffset
            )
            << "\n";

        return true;
    }

    profile.mapTilePathDepth = 0;
    profile.mapTilePathMapOffset = 0;
    profile.mapTilePathChildOffset = 0;
    profile.mapTilePathHeaderOffset = 0;
    profile.mapTileStorageStride = 0;
    profile.mapTileStorageMode = "unknown";
    profile.mapTilePathStatus =
        "rediscovery_running";

    bool ok =
        RunMapTilePathRecon(
            profile
        );

    if (profileIndex >= 0 &&
        profileIndex <
            static_cast<int>(
                database.size()
            ))
    {
        database[
            static_cast<size_t>(
                profileIndex
            )
        ] = profile;

        SaveProfileDatabase(
            databasePath,
            database
        );
    }

    return ok;
}


// ============================================================
// DISCOVERY V2.5 - WORLD THING COHORTS + MONSTER SAMPLE
// Strict read-only. No virtual calls.
// ============================================================

struct V25ThingObservation
{
    uintptr_t pointer = 0;
    uintptr_t completeObject = 0;
    uintptr_t vtable = 0;
    uintptr_t vtableRva = 0;

    uint32_t rttiSubobjectOffset = 0;
    std::string rttiName;
    bool synthetic = false;

    uint32_t x = 0;
    uint32_t y = 0;
    uint8_t z = 0;

    uint32_t id = 0;
    uint8_t hpPercent = 0;
    uint32_t direction = 0;

    bool positionPlausible = false;
    bool hpPlausible = false;
    bool directionPlausible = false;
    bool highId = false;
};

struct V25ThingCohort
{
    uintptr_t vtable = 0;
    uintptr_t vtableRva = 0;

    std::string rttiName;

    size_t objects = 0;
    size_t plausiblePosition = 0;
    size_t plausibleHp = 0;
    size_t plausibleDirection = 0;
    size_t highId = 0;

    bool containsLocalPlayer = false;

    std::vector<uintptr_t> examples;
};

bool V25ResolveWorldTileArray(
    const DbProfile& profile,
    uintptr_t localPlayer,
    uintptr_t& begin,
    uintptr_t& end,
    uintptr_t& cap,
    uintptr_t& owner,
    uintptr_t& header)
{
    begin = 0;
    end = 0;
    cap = 0;
    owner = 0;
    header = 0;

    if (!profile.mapRva ||
        !profile.mapTilePathDepth ||
        profile.mapTilePathStatus !=
            "confirmed_runtime_two_positions")
    {
        return false;
    }

    uintptr_t map =
        g_exeBase +
        profile.mapRva;

    uintptr_t first =
        ReadPtr(
            map +
            profile.mapTilePathMapOffset
        );

    if (!first)
        return false;

    if (profile.mapTilePathDepth == 1)
    {
        owner = first;
    }
    else if (profile.mapTilePathDepth == 2)
    {
        owner =
            ReadPtr(
                first +
                profile.mapTilePathChildOffset
            );
    }
    else
    {
        return false;
    }

    if (!owner ||
        !IsReadableMonitorRange(
            owner,
            0x600))
    {
        return false;
    }

    const size_t tileStride =
        profile.mapTileStorageStride
            ? static_cast<size_t>(
                profile.mapTileStorageStride)
            : sizeof(uintptr_t);

    struct Candidate
    {
        uintptr_t offset = 0;
        uintptr_t header = 0;
        uintptr_t begin = 0;
        uintptr_t end = 0;
        uintptr_t cap = 0;

        size_t count = 0;
        size_t capacity = 0;
        size_t validTiles = 0;
        size_t dominantVtable = 0;
        size_t localPlayerHits = 0;

        int score = 0;
    };

    std::vector<Candidate>
        candidates;

    // Important correction:
    // previous Stage 5B proved the owner path, but the vector header itself
    // changes with floor. Scan the owner for the active floor's Tile* vector
    // instead of treating one observed header offset as global.
    for (uintptr_t off = 0;
         off + 3 * sizeof(uintptr_t) <= 0x600;
         off += 8)
    {
        uintptr_t h =
            owner +
            off;

        uintptr_t b =
            ReadPtr(
                h
            );

        uintptr_t e =
            ReadPtr(
                h +
                sizeof(uintptr_t)
            );

        uintptr_t c =
            ReadPtr(
                h +
                2 * sizeof(uintptr_t)
            );

        if (!b ||
            !e ||
            !c ||
            e < b ||
            c < e ||
            (b & 7) ||
            (e & 7) ||
            (c & 7))
        {
            continue;
        }

        uintptr_t used =
            e -
            b;

        uintptr_t capacityBytes =
            c -
            b;

        if (!tileStride ||
            used %
                tileStride !=
            0 ||
            capacityBytes %
                tileStride !=
            0)
        {
            continue;
        }

        size_t count =
            static_cast<size_t>(
                used /
                tileStride
            );

        size_t capacity =
            static_cast<size_t>(
                capacityBytes /
                tileStride
            );

        if (count < 16 ||
            count > 4000 ||
            capacity < count ||
            capacity > 8000)
        {
            continue;
        }

        if (!IsReadableMonitorRange(
                b,
                count *
                    tileStride))
        {
            continue;
        }

        size_t validTiles = 0;
        size_t localHits = 0;

        std::unordered_map<uintptr_t, size_t>
            vtableCounts;

        for (size_t i = 0;
             i < count;
             ++i)
        {
            uintptr_t tile =
                ReadPtr(
                    b +
                    i *
                    tileStride
                );

            if (!tile ||
                !IsReadableMonitorRange(
                    tile,
                    profile.tileThingsCap +
                        sizeof(uintptr_t)))
            {
                continue;
            }

            uintptr_t vt =
                ReadPtr(
                    tile
                );

            if (!InsideExeImage(
                    vt))
            {
                continue;
            }

            uintptr_t tb =
                ReadPtr(
                    tile +
                    profile.tileThingsBegin
                );

            uintptr_t te =
                ReadPtr(
                    tile +
                    profile.tileThingsEnd
                );

            uintptr_t tc =
                ReadPtr(
                    tile +
                    profile.tileThingsCap
                );

            if (!tb ||
                te < tb ||
                tc < te ||
                (tb & 7) ||
                (te & 7) ||
                (tc & 7))
            {
                continue;
            }

            uintptr_t thingUsed =
                te -
                tb;

            uintptr_t thingCapacityBytes =
                tc -
                tb;

            if (thingUsed %
                    sizeof(uintptr_t) !=
                0 ||
                thingCapacityBytes %
                    sizeof(uintptr_t) !=
                0)
            {
                continue;
            }

            size_t thingCount =
                static_cast<size_t>(
                    thingUsed /
                    sizeof(uintptr_t)
                );

            size_t thingCapacity =
                static_cast<size_t>(
                    thingCapacityBytes /
                    sizeof(uintptr_t)
                );

            if (thingCount > 64 ||
                thingCapacity > 256)
            {
                continue;
            }

            ++validTiles;
            ++vtableCounts[
                vt
            ];

            for (size_t t = 0;
                 t < thingCount;
                 ++t)
            {
                uintptr_t thing =
                    ReadPtr(
                        tb +
                        t *
                        sizeof(uintptr_t)
                    );

                if (thing ==
                    localPlayer)
                {
                    ++localHits;
                    break;
                }
            }
        }

        if (validTiles < 16 ||
            localHits != 1)
        {
            continue;
        }

        size_t dominant =
            0;

        for (const auto& kv :
             vtableCounts)
        {
            dominant =
                std::max(
                    dominant,
                    kv.second
                );
        }

        if (dominant * 100 <
                validTiles * 80 ||
            validTiles * 100 <
                count * 75)
        {
            continue;
        }

        Candidate candidate{};

        candidate.offset =
            off;

        candidate.header =
            h;

        candidate.begin =
            b;

        candidate.end =
            e;

        candidate.cap =
            c;

        candidate.count =
            count;

        candidate.capacity =
            capacity;

        candidate.validTiles =
            validTiles;

        candidate.dominantVtable =
            dominant;

        candidate.localPlayerHits =
            localHits;

        candidate.score =
            100000 +
            static_cast<int>(
                validTiles * 10
            ) +
            static_cast<int>(
                dominant * 5
            ) -
            static_cast<int>(
                capacity -
                count
            );

        candidates.push_back(
            candidate
        );
    }

    if (candidates.empty())
    {
        std::cout
            << "[WORLD PATH] Nenhum header dinamico de Tile* contendo LocalPlayer foi encontrado.\n";

        return false;
    }

    std::sort(
        candidates.begin(),
        candidates.end(),
        [](
            const Candidate& a,
            const Candidate& b)
        {
            if (a.score !=
                b.score)
            {
                return
                    a.score >
                    b.score;
            }

            if (a.validTiles !=
                b.validTiles)
            {
                return
                    a.validTiles >
                    b.validTiles;
            }

            return
                a.offset <
                b.offset;
        }
    );

    if (candidates.size() > 1)
    {
        const Candidate& a =
            candidates[0];

        const Candidate& b =
            candidates[1];

        bool clearlyBetter =
            a.score >=
                b.score + 200 ||
            a.validTiles >=
                b.validTiles + 20;

        if (!clearlyBetter)
        {
            std::cout
                << "[WORLD PATH] Mais de um floor-header forte permaneceu.\n";

            for (size_t i = 0;
                 i < candidates.size() &&
                 i < 8;
                 ++i)
            {
                std::cout
                    << "  #"
                    << i
                    << " off=+"
                    << HexU64(
                        candidates[i].offset
                    )
                    << " count="
                    << candidates[i].count
                    << " cap="
                    << candidates[i].capacity
                    << " validTiles="
                    << candidates[i].validTiles
                    << " dominant="
                    << candidates[i].dominantVtable
                    << " localHits="
                    << candidates[i].localPlayerHits
                    << " score="
                    << candidates[i].score
                    << "\n";
            }

            return false;
        }
    }

    const Candidate& winner =
        candidates[0];

    header =
        winner.header;

    begin =
        winner.begin;

    end =
        winner.end;

    cap =
        winner.cap;

    uint8_t currentZ =
        ReadU8(
            localPlayer +
            profile.z
        );

    g_floorHeaderObservations[
        static_cast<unsigned>(
            currentZ)
    ] = winner.offset;

    std::cout
        << "[WORLD PATH] Dynamic floor header resolved.\n"
        << "  Z                    : "
        << static_cast<unsigned>(
            currentZ
        )
        << "\n"
        << "  Runtime header off   : +"
        << HexU64(
            winner.offset
        )
        << "\n"
        << "  Saved header off     : +"
        << HexU64(
            profile.mapTilePathHeaderOffset
        )
        << "\n"
        << "  Tile count           : "
        << winner.count
        << "\n"
        << "  Storage mode         : "
        << (
            profile.mapTileStorageMode.empty()
                ? "unknown"
                : profile.mapTileStorageMode
        )
        << "\n"
        << "  Element stride       : "
        << tileStride
        << "\n"
        << "  Valid Tile vectors   : "
        << winner.validTiles
        << "\n"
        << "  Dominant Tile vtable : "
        << winner.dominantVtable
        << "/"
        << winner.validTiles
        << "\n";

    if (profile.mapTilePathHeaderOffset &&
        winner.offset !=
            profile.mapTilePathHeaderOffset)
    {
        std::cout
            << "[WORLD PATH] Header offset varia com o floor; usando o runtime atual.\n";
    }

    return true;
}


struct V33ThingStorageProbe
{
    size_t stride = sizeof(uintptr_t);
    std::string mode = "raw_pointer_array";

    size_t sampledTiles = 0;
    size_t sampledEntries = 0;
    size_t objectLike = 0;
    size_t controlLike = 0;
    size_t localPlayerObjectHits = 0;

    int score = 0;
};

V33ThingStorageProbe
V33ProbeThingStorage(
    const DbProfile& profile,
    uintptr_t localPlayer,
    uintptr_t tileBegin,
    uintptr_t tileEnd,
    size_t tileStride)
{
    V33ThingStorageProbe raw{};
    raw.stride = 8;
    raw.mode = "raw_pointer_array";

    V33ThingStorageProbe shared{};
    shared.stride = 16;
    shared.mode = "shared_ptr_array";

    if (!tileBegin ||
        tileEnd <= tileBegin ||
        !tileStride)
    {
        return raw;
    }

    size_t tileCount =
        static_cast<size_t>(
            (
                tileEnd -
                tileBegin
            ) /
            tileStride
        );

    tileCount =
        std::min<size_t>(
            tileCount,
            512
        );

    for (size_t ti = 0;
         ti < tileCount;
         ++ti)
    {
        uintptr_t tile =
            ReadPtr(
                tileBegin +
                ti *
                tileStride
            );

        if (!tile ||
            !IsReadableMonitorRange(
                tile,
                profile.tileThingsCap +
                    sizeof(uintptr_t)))
        {
            continue;
        }

        uintptr_t begin =
            ReadPtr(
                tile +
                profile.tileThingsBegin
            );

        uintptr_t end =
            ReadPtr(
                tile +
                profile.tileThingsEnd
            );

        uintptr_t cap =
            ReadPtr(
                tile +
                profile.tileThingsCap
            );

        if (!begin ||
            end < begin ||
            cap < end ||
            (begin & 7) ||
            (end & 7) ||
            (cap & 7))
        {
            continue;
        }

        uintptr_t used =
            end -
            begin;

        if (!used ||
            used > 0x4000)
        {
            continue;
        }

        // RAW Thing* probe.
        if (used % 8 == 0)
        {
            size_t count =
                static_cast<size_t>(
                    used / 8
                );

            if (count <= 128)
            {
                ++raw.sampledTiles;

                for (size_t i = 0;
                     i < count;
                     ++i)
                {
                    uintptr_t object =
                        ReadPtr(
                            begin +
                            i * 8
                        );

                    ++raw.sampledEntries;

                    if (!object ||
                        !IsReadableMonitorRange(
                            object,
                            sizeof(uintptr_t)))
                    {
                        continue;
                    }

                    uintptr_t vt =
                        ReadPtr(
                            object
                        );

                    if (!InsideExeImage(
                            vt))
                    {
                        continue;
                    }

                    ++raw.objectLike;

                    if (object ==
                        localPlayer)
                    {
                        ++raw.localPlayerObjectHits;
                    }
                }
            }
        }

        // MSVC shared_ptr<Thing> probe:
        // [object*][control-block*] repeated.
        if (used % 16 == 0)
        {
            size_t count =
                static_cast<size_t>(
                    used / 16
                );

            if (count <= 128)
            {
                ++shared.sampledTiles;

                for (size_t i = 0;
                     i < count;
                     ++i)
                {
                    uintptr_t entry =
                        begin +
                        i * 16;

                    uintptr_t object =
                        ReadPtr(
                            entry
                        );

                    uintptr_t control =
                        ReadPtr(
                            entry + 8
                        );

                    ++shared.sampledEntries;

                    if (object &&
                        IsReadableMonitorRange(
                            object,
                            sizeof(uintptr_t)))
                    {
                        uintptr_t vt =
                            ReadPtr(
                                object
                            );

                        if (InsideExeImage(
                                vt))
                        {
                            ++shared.objectLike;

                            if (object ==
                                localPlayer)
                            {
                                ++shared.localPlayerObjectHits;
                            }
                        }
                    }

                    if (LooksLikeSharedPtrControlBlock(
                            control))
                    {
                        ++shared.controlLike;
                    }
                }
            }
        }
    }

    if (raw.sampledEntries)
    {
        raw.score =
            static_cast<int>(
                raw.objectLike * 3
            ) +
            static_cast<int>(
                raw.localPlayerObjectHits * 200
            );
    }

    if (shared.sampledEntries)
    {
        shared.score =
            static_cast<int>(
                shared.objectLike * 4
            ) +
            static_cast<int>(
                shared.controlLike * 8
            ) +
            static_cast<int>(
                shared.localPlayerObjectHits * 250
            );

        const bool strongControlPattern =
            shared.controlLike >= 8 &&
            shared.controlLike * 100 >=
                shared.sampledEntries * 70;

        const bool strongObjectPattern =
            shared.objectLike >= 8 &&
            shared.objectLike * 100 >=
                shared.sampledEntries * 70;

        if (!strongControlPattern ||
            !strongObjectPattern)
        {
            shared.score /= 4;
        }
    }

    if (shared.score >
            raw.score &&
        shared.controlLike >= 8)
    {
        return shared;
    }

    return raw;
}

V33ThingStorageProbe
V33ResolveCurrentThingStorage(
    const DbProfile& profile,
    uintptr_t localPlayer,
    uintptr_t tileBegin,
    uintptr_t tileEnd,
    size_t tileStride,
    bool verbose)
{
    V33ThingStorageProbe probe =
        V33ProbeThingStorage(
            profile,
            localPlayer,
            tileBegin,
            tileEnd,
            tileStride
        );

    // A confirmed profile value remains preferred when runtime shape still
    // supports it. New/unknown profiles use the semantic probe.
    if (profile.thingStorageStride == 16 &&
        profile.thingStorageMode ==
            "shared_ptr_array")
    {
        probe.stride = 16;
        probe.mode = "shared_ptr_array";
    }
    else if (profile.thingStorageStride == 8 &&
             profile.thingStorageMode ==
                "raw_pointer_array")
    {
        // Do not force RAW if the live probe strongly proves shared_ptr.
        if (probe.mode !=
            "shared_ptr_array")
        {
            probe.stride = 8;
            probe.mode = "raw_pointer_array";
        }
    }

    if (verbose)
    {
        std::cout
            << "[THING STORAGE] mode="
            << probe.mode
            << " stride="
            << probe.stride
            << " sampledTiles="
            << probe.sampledTiles
            << " entries="
            << probe.sampledEntries
            << " objectLike="
            << probe.objectLike
            << " controlLike="
            << probe.controlLike
            << " localHits="
            << probe.localPlayerObjectHits
            << "\n";
    }

    return probe;
}

bool V33PersistThingStorage(
    DbProfile& profile,
    uintptr_t localPlayer)
{
    uintptr_t tileBegin = 0;
    uintptr_t tileEnd = 0;
    uintptr_t tileCap = 0;
    uintptr_t owner = 0;
    uintptr_t header = 0;

    if (!V25ResolveWorldTileArray(
            profile,
            localPlayer,
            tileBegin,
            tileEnd,
            tileCap,
            owner,
            header))
    {
        return false;
    }

    const size_t tileStride =
        profile.mapTileStorageStride
            ? static_cast<size_t>(
                profile.mapTileStorageStride)
            : sizeof(uintptr_t);

    auto probe =
        V33ResolveCurrentThingStorage(
            profile,
            localPlayer,
            tileBegin,
            tileEnd,
            tileStride,
            true
        );

    if (probe.stride != 8 &&
        probe.stride != 16)
    {
        return false;
    }

    profile.thingStorageStride =
        static_cast<uintptr_t>(
            probe.stride
        );

    profile.thingStorageMode =
        probe.mode;

    std::cout
        << "[THING STORAGE] persisted mode="
        << profile.thingStorageMode
        << " stride="
        << profile.thingStorageStride
        << "\n";

    return true;
}


std::vector<V25ThingObservation>
V25CollectWorldThings(
    const DbProfile& profile,
    uintptr_t localPlayer)
{
    std::vector<V25ThingObservation>
        out;

    uintptr_t tileBegin = 0;
    uintptr_t tileEnd = 0;
    uintptr_t tileCap = 0;
    uintptr_t owner = 0;
    uintptr_t header = 0;

    if (!V25ResolveWorldTileArray(
            profile,
            localPlayer,
            tileBegin,
            tileEnd,
            tileCap,
            owner,
            header))
    {
        std::cout
            << "[WORLD] Map->Tile array nao validou neste snapshot.\n";

        return out;
    }

    const size_t tileStride =
        profile.mapTileStorageStride
            ? static_cast<size_t>(
                profile.mapTileStorageStride)
            : sizeof(uintptr_t);

    if (!tileStride ||
        (
            tileEnd -
            tileBegin
        ) %
            tileStride !=
        0)
    {
        std::cout
            << "[WORLD] Tile storage stride invalido neste snapshot.\n";

        return out;
    }

    size_t tileCount =
        static_cast<size_t>(
            (
                tileEnd -
                tileBegin
            ) /
            tileStride
        );

    V33ThingStorageProbe thingStorage =
        V33ResolveCurrentThingStorage(
            profile,
            localPlayer,
            tileBegin,
            tileEnd,
            tileStride,
            true
        );

    const size_t thingStride =
        thingStorage.stride
            ? thingStorage.stride
            : sizeof(uintptr_t);

    std::cout
        << "\n============================================================\n"
        << "                WORLD TILE ARRAY\n"
        << "============================================================\n"
        << "Owner                : "
        << HexPtr(
            owner
        )
        << "\n"
        << "Header               : "
        << HexPtr(
            header
        )
        << "\n"
        << "Tile begin/end/cap   : "
        << HexPtr(
            tileBegin
        )
        << " / "
        << HexPtr(
            tileEnd
        )
        << " / "
        << HexPtr(
            tileCap
        )
        << "\n"
        << "Tile count           : "
        << tileCount
        << "\n";

    std::unordered_set<uintptr_t>
        seenThings;

    size_t validTiles = 0;
    size_t rejectedThingVectors = 0;

    for (size_t ti = 0;
         ti < tileCount;
         ++ti)
    {
        uintptr_t tile =
            ReadPtr(
                tileBegin +
                ti *
                tileStride
            );

        if (!tile ||
            !IsReadableMonitorRange(
                tile,
                profile.tileThingsCap +
                    sizeof(uintptr_t)))
        {
            continue;
        }

        uintptr_t thingsBegin =
            ReadPtr(
                tile +
                profile.tileThingsBegin
            );

        uintptr_t thingsEnd =
            ReadPtr(
                tile +
                profile.tileThingsEnd
            );

        uintptr_t thingsCap =
            ReadPtr(
                tile +
                profile.tileThingsCap
            );

        if (!thingsBegin ||
            thingsEnd < thingsBegin ||
            thingsCap < thingsEnd ||
            (thingsBegin & 7) ||
            (thingsEnd & 7) ||
            (thingsCap & 7))
        {
            ++rejectedThingVectors;
            continue;
        }

        uintptr_t used =
            thingsEnd -
            thingsBegin;

        uintptr_t capacityBytes =
            thingsCap -
            thingsBegin;

        if (!thingStride ||
            used %
                thingStride !=
            0 ||
            capacityBytes %
                thingStride !=
            0)
        {
            ++rejectedThingVectors;
            continue;
        }

        size_t thingCount =
            static_cast<size_t>(
                used /
                thingStride
            );

        size_t thingCapacity =
            static_cast<size_t>(
                capacityBytes /
                thingStride
            );

        if (thingCount > 64 ||
            thingCapacity > 256)
        {
            ++rejectedThingVectors;
            continue;
        }

        ++validTiles;

        for (size_t i = 0;
             i < thingCount;
             ++i)
        {
            uintptr_t thing =
                ReadPtr(
                    thingsBegin +
                    i *
                    thingStride
                );

            if (!thing)
                continue;

            V35MsvcObjectIdentity identity{};

            const bool identityOk =
                V35DescribeMsvcObject(
                    thing,
                    identity
                );

            uintptr_t identityKey =
                identityOk
                    ? identity.completeObject
                    : thing;

            if (!seenThings.insert(
                    identityKey).second)
            {
                continue;
            }

            uintptr_t need =
                std::max<uintptr_t>(
                    profile.direction +
                        sizeof(uint32_t),
                    profile.hpPercent +
                        sizeof(uint8_t)
                );

            uintptr_t fieldBase =
                identityOk
                    ? identity.completeObject
                    : thing;

            if (!IsReadableMonitorRange(
                    fieldBase,
                    need))
            {
                continue;
            }

            uintptr_t vt =
                identityOk
                    ? identity.vtable
                    : ReadPtr(
                        thing
                    );

            if (!InsideExeImage(
                    vt))
            {
                continue;
            }

            V25ThingObservation o{};

            o.pointer =
                thing;

            o.completeObject =
                identityKey;

            o.vtable =
                vt;

            o.vtableRva =
                vt -
                g_exeBase;

            o.rttiSubobjectOffset =
                identityOk
                    ? identity.subobjectOffset
                    : 0;

            o.rttiName =
                identityOk
                    ? identity.rttiName
                    : TryReadMsvcRttiTypeName(
                        vt
                    );

            if (o.rttiName.empty())
                o.rttiName = "<unavailable>";

            o.x =
                ReadU32(
                    fieldBase +
                    profile.x
                );

            o.y =
                ReadU32(
                    fieldBase +
                    profile.y
                );

            o.z =
                ReadU8(
                    fieldBase +
                    profile.z
                );

            o.id =
                ReadU32(
                    fieldBase +
                    profile.id
                );

            o.hpPercent =
                ReadU8(
                    fieldBase +
                    profile.hpPercent
                );

            o.direction =
                ReadU32(
                    fieldBase +
                    profile.direction
                );

            o.positionPlausible =
                PositionPlausible(
                    o.x,
                    o.y,
                    o.z
                );

            o.hpPlausible =
                o.hpPercent <= 100;

            o.directionPlausible =
                o.direction <= 7;

            // Diagnostic only. This is not used to promote a class.
            o.highId =
                o.id > 0xFFFFu &&
                o.id != 0xFFFFFFFFu;

            out.push_back(
                o
            );
        }
    }

    std::cout
        << "Valid Tile vectors   : "
        << validTiles
        << "\n"
        << "Rejected vectors     : "
        << rejectedThingVectors
        << "\n"
        << "Unique Thing objects : "
        << out.size()
        << "\n"
        << "Thing storage mode   : "
        << thingStorage.mode
        << "\n"
        << "Thing element stride : "
        << thingStride
        << "\n";

    return out;
}

std::vector<V25ThingCohort>
V25BuildCohorts(
    const std::vector<V25ThingObservation>& observations,
    uintptr_t localPlayer)
{
    std::unordered_map<uintptr_t, V25ThingCohort>
        byVtable;

    for (const auto& o :
         observations)
    {
        auto& c =
            byVtable[
                o.vtable
            ];

        c.vtable =
            o.vtable;

        c.vtableRva =
            o.vtableRva;

        if (c.rttiName.empty())
        {
            c.rttiName =
                o.rttiName.empty()
                    ? TryReadMsvcRttiTypeName(
                        o.vtable
                    )
                    : o.rttiName;

            if (c.rttiName.empty())
                c.rttiName = "<unavailable>";
        }

        ++c.objects;

        if (o.positionPlausible)
            ++c.plausiblePosition;

        if (o.hpPlausible)
            ++c.plausibleHp;

        if (o.directionPlausible)
            ++c.plausibleDirection;

        if (o.highId)
            ++c.highId;

        if (
            o.completeObject ==
                V35CompleteObjectPointer(
                    localPlayer) ||
            V35SameCompleteObject(
                o.pointer,
                localPlayer)
        )
        {
            c.containsLocalPlayer =
                true;
        }

        if (c.examples.size() <
            5)
        {
            c.examples.push_back(
                o.pointer
            );
        }
    }

    std::vector<V25ThingCohort>
        out;

    out.reserve(
        byVtable.size()
    );

    for (auto& kv :
         byVtable)
    {
        out.push_back(
            std::move(
                kv.second
            )
        );
    }

    std::sort(
        out.begin(),
        out.end(),
        [](
            const V25ThingCohort& a,
            const V25ThingCohort& b)
        {
            if (a.objects !=
                b.objects)
            {
                return
                    a.objects >
                    b.objects;
            }

            return
                a.vtableRva <
                b.vtableRva;
        }
    );

    return out;
}

void V25PrintCohorts(
    const std::vector<V25ThingCohort>& cohorts)
{
    std::cout
        << "\n============================================================\n"
        << "                WORLD THING VTABLE COHORTS\n"
        << "============================================================\n"
        << "Nenhuma classe e inferida apenas por estes contadores.\n";

    for (size_t i = 0;
         i < cohorts.size();
         ++i)
    {
        const auto& c =
            cohorts[i];

        std::cout
            << "#"
            << i
            << " vtRva="
            << HexU64(
                c.vtableRva
            )
            << " objects="
            << c.objects
            << " pos="
            << c.plausiblePosition
            << " hp<=100="
            << c.plausibleHp
            << " dir<=7="
            << c.plausibleDirection
            << " highId="
            << c.highId
            << " rtti=\""
            << c.rttiName
            << "\"";

        if (c.containsLocalPlayer)
        {
            std::cout
                << " <LOCALPLAYER COHORT>";
        }

        std::cout
            << "\n";
    }
}

const V25ThingObservation*
V25FindObservation(
    const std::vector<V25ThingObservation>& observations,
    uintptr_t pointer)
{
    if (!pointer)
        return nullptr;

    uintptr_t complete =
        V35CompleteObjectPointer(
            pointer
        );

    for (const auto& o :
         observations)
    {
        if (o.pointer ==
                pointer ||
            (
                o.completeObject &&
                o.completeObject ==
                    complete
            ))
        {
            return
                &o;
        }
    }

    return nullptr;
}

bool V25WaitAttackTargetClear(
    const DbProfile& profile)
{
    uintptr_t game =
        g_exeBase +
        profile.gameRva;

    for (;;)
    {
        uintptr_t target =
            ReadPtr(
                game +
                profile.gameAttackTarget
            );

        if (!target)
            return true;

        std::cout
            << "\n[CLEAR TARGET] AttackTarget ainda esta em "
            << HexPtr(
                target
            )
            << ".\n"
            << "Pare de atacar/limpe o target e pressione ENTER.\n";

        WaitEnter(
            "Depois de limpar o target, pressione ENTER..."
        );
    }
}

uintptr_t V25CaptureMonsterTarget(
    const DbProfile& profile,
    std::vector<V25ThingObservation>& observations,
    uintptr_t localPlayer,
    uintptr_t forbidden,
    const char* label)
{
    uintptr_t game =
        g_exeBase +
        profile.gameRva;

    constexpr size_t kMaxAttempts = 5;
    size_t failedAttempts = 0;

    for (;;)
    {
        std::cout
            << "\n============================================================\n"
            << "             MONSTER SAMPLE "
            << label
            << "\n"
            << "============================================================\n"
            << "Ataque/selecione UM MONSTRO visivel pelo cliente normal.\n"
            << "O Lab apenas lera Game.AttackTarget depois.\n";

        WaitEnter(
            "Com o MONSTRO atacado, pressione ENTER..."
        );

        uintptr_t target =
            ReadPtr(
                game +
                profile.gameAttackTarget
            );

        if (!target)
        {
            ++failedAttempts;

            std::cout
                << "[RETRY] AttackTarget esta NULL. tentativa="
                << failedAttempts
                << "/"
                << kMaxAttempts
                << "\n";

            if (failedAttempts >=
                kMaxAttempts)
            {
                std::cout
                    << "[CALIBRATE] Limite desta rodada atingido. "
                    << "Voltando ao orquestrador para permitir R/S/Q.\n";

                return 0;
            }

            continue;
        }

        if (target ==
            localPlayer)
        {
            ++failedAttempts;

            std::cout
                << "[RETRY] AttackTarget nao pode ser LocalPlayer. tentativa="
                << failedAttempts
                << "/"
                << kMaxAttempts
                << "\n";

            if (failedAttempts >=
                kMaxAttempts)
            {
                return 0;
            }

            continue;
        }

        if (forbidden &&
            target ==
                forbidden)
        {
            ++failedAttempts;

            std::cout
                << "[RETRY] Escolha um SEGUNDO monstro diferente. tentativa="
                << failedAttempts
                << "/"
                << kMaxAttempts
                << "\n";

            if (failedAttempts >=
                kMaxAttempts)
            {
                std::cout
                    << "[CALIBRATE] Nao conseguimos um segundo objeto distinto nesta rodada.\n";

                return 0;
            }

            continue;
        }

        // IMPORTANT:
        // The old V2.2 refreshed the world BEFORE the user selected Sample B.
        // If the creature moved meanwhile, the new AttackTarget pointer was
        // compared against a stale world snapshot and the wizard could loop
        // forever. Refresh only AFTER AttackTarget is captured.
        std::cout
            << "[REFRESH] Atualizando world snapshot DEPOIS de capturar AttackTarget...\n";

        observations =
            V25CollectWorldThings(
                profile,
                localPlayer
            );

        const V25ThingObservation* o =
            V25FindObservation(
                observations,
                target
            );

        // Guided fallback:
        // AttackTarget itself is already a confirmed Game semantic field.
        // If the current Tile snapshot omitted the target because it moved
        // during the refresh, validate the target object directly and add a
        // synthetic observation. This is still read-only and is later
        // cross-checked against a second distinct target/vtable.
        if (!o &&
            IsReadableMonitorRange(
                target,
                0x100))
        {
            V25ThingObservation direct{};

            direct.pointer =
                target;

            direct.synthetic =
                true;

            V35MsvcObjectIdentity directIdentity{};

            const bool directIdentityOk =
                V35DescribeMsvcObject(
                    target,
                    directIdentity
                );

            direct.completeObject =
                directIdentityOk
                    ? directIdentity.completeObject
                    : target;

            direct.rttiSubobjectOffset =
                directIdentityOk
                    ? directIdentity.subobjectOffset
                    : 0;

            direct.rttiName =
                directIdentityOk
                    ? directIdentity.rttiName
                    : std::string();

            direct.vtable =
                directIdentityOk
                    ? directIdentity.vtable
                    : ReadPtr(
                        target
                    );

            if (InsideExeImage(
                    direct.vtable))
            {
                direct.vtableRva =
                    direct.vtable -
                    g_exeBase;

                uintptr_t directFieldBase =
                    direct.completeObject
                        ? direct.completeObject
                        : target;

                direct.x =
                    ReadU32(
                        directFieldBase +
                        profile.x
                    );

                direct.y =
                    ReadU32(
                        directFieldBase +
                        profile.y
                    );

                direct.z =
                    ReadU8(
                        directFieldBase +
                        profile.z
                    );

                direct.id =
                    ReadU32(
                        directFieldBase +
                        profile.id
                    );

                direct.hpPercent =
                    ReadU8(
                        directFieldBase +
                        profile.hpPercent
                    );

                direct.direction =
                    ReadU32(
                        directFieldBase +
                        profile.direction
                    );

                direct.positionPlausible =
                    PositionPlausible(
                        direct.x,
                        direct.y,
                        direct.z
                    );

                direct.hpPlausible =
                    direct.hpPercent <= 100;

                direct.directionPlausible =
                    direct.direction <= 7;

                direct.highId =
                    direct.id > 0xFFFFu &&
                    direct.id != 0xFFFFFFFFu;

                if (direct.positionPlausible &&
                    direct.hpPlausible &&
                    direct.directionPlausible)
                {
                    observations.push_back(
                        direct
                    );

                    o =
                        &observations.back();

                    if (direct.rttiName.empty())
                    {
                        direct.rttiName =
                            TryReadMsvcRttiTypeName(
                                direct.vtable
                            );

                        if (direct.rttiName.empty())
                            direct.rttiName = "<unavailable>";
                    }

                    std::cout
                        << "[DIRECT TARGET FALLBACK] "
                        << "Target nao fechou por complete-object identity no Tile snapshot; "
                        << "fallback direto aceito. RTTI=\""
                        << direct.rttiName
                        << "\" subOff="
                        << direct.rttiSubobjectOffset
                        << "\n";
                }
            }
        }

        if (!o)
        {
            ++failedAttempts;

            std::cout
                << "[RETRY] Target nao apareceu no snapshot atual "
                << "e tambem nao passou o fallback direto. tentativa="
                << failedAttempts
                << "/"
                << kMaxAttempts
                << "\n";

            V25WaitAttackTargetClear(
                profile
            );

            if (failedAttempts >=
                kMaxAttempts)
            {
                std::cout
                    << "[CALIBRATE] Limite desta rodada atingido. "
                    << "Voltando ao orquestrador para permitir R/S/Q.\n";

                return 0;
            }

            continue;
        }

        if (!o->positionPlausible ||
            !o->hpPlausible ||
            !o->directionPlausible)
        {
            ++failedAttempts;

            std::cout
                << "[RETRY] Target nao passou o shape basico de Creature-like. tentativa="
                << failedAttempts
                << "/"
                << kMaxAttempts
                << "\n";

            V25WaitAttackTargetClear(
                profile
            );

            if (failedAttempts >=
                kMaxAttempts)
            {
                return 0;
            }

            continue;
        }

        std::cout
            << "[SAMPLE] ptr="
            << HexPtr(
                target
            )
            << " vtableRva="
            << HexU64(
                o->vtableRva
            )
            << " pos="
            << o->x
            << ","
            << o->y
            << ","
            << static_cast<unsigned>(
                o->z
            )
            << " id="
            << o->id
            << " hp%="
            << static_cast<unsigned>(
                o->hpPercent
            )
            << " rtti=\""
            << o->rttiName
            << "\" subOff="
            << o->rttiSubobjectOffset
            << " complete="
            << HexPtr(
                o->completeObject
            )
            << (
                o->synthetic
                    ? " source=direct-fallback"
                    : " source=world-identity"
            )
            << "\n";

        return target;
    }
}

bool V25DecodeConstantBool(
    uintptr_t function,
    bool& value)
{
    value = false;

    if (function <
            g_textBegin ||
        function >=
            g_textEnd)
    {
        return false;
    }

    uint8_t b[8]{};

    for (size_t i = 0;
         i < sizeof(b);
         ++i)
    {
        if (!SafeRead(
                function + i,
                b[i]))
        {
            return false;
        }
    }

    // mov al, imm8 ; ret
    if (b[0] == 0xB0 &&
        (b[1] == 0x00 ||
         b[1] == 0x01) &&
        b[2] == 0xC3)
    {
        value =
            b[1] != 0;

        return true;
    }

    // mov eax, imm32 ; ret
    if (b[0] == 0xB8 &&
        b[5] == 0xC3)
    {
        uint32_t imm = 0;

        std::memcpy(
            &imm,
            &b[1],
            sizeof(imm)
        );

        if (imm <= 1)
        {
            value =
                imm != 0;

            return true;
        }
    }

    // xor eax,eax ; ret
    if (((b[0] == 0x33 &&
          b[1] == 0xC0) ||
         (b[0] == 0x31 &&
          b[1] == 0xC0)) &&
        b[2] == 0xC3)
    {
        value = false;
        return true;
    }

    // xor al,al ; ret
    if (b[0] == 0x32 &&
        b[1] == 0xC0 &&
        b[2] == 0xC3)
    {
        value = false;
        return true;
    }

    return false;
}

void V25PrintVtableBoolMatrix(
    uintptr_t localPlayerVtable,
    uintptr_t monsterVtable)
{
    std::cout
        << "\n============================================================\n"
        << "          STATIC VTABLE CONSTANT-BOOL MATRIX\n"
        << "============================================================\n"
        << "[MODE] somente leitura de ponteiros/bytes da .text\n"
        << "[NO CALL] nenhuma virtual e executada\n"
        << "LP=true / Monster=true pode conter isCreature-like.\n"
        << "LP=false / Monster=true pode conter isMonster-like.\n"
        << "LP=true / Monster=false pode conter isPlayer-like.\n"
        << "Ainda NAO vamos promover slots nesta etapa.\n";

    size_t decoded =
        0;

    for (uintptr_t slot = 0;
         slot <= 0x100;
         slot += 8)
    {
        uintptr_t lpFn =
            ReadPtr(
                localPlayerVtable +
                slot
            );

        uintptr_t monsterFn =
            ReadPtr(
                monsterVtable +
                slot
            );

        bool lpValue = false;
        bool monsterValue = false;

        bool lpConstant =
            V25DecodeConstantBool(
                lpFn,
                lpValue
            );

        bool monsterConstant =
            V25DecodeConstantBool(
                monsterFn,
                monsterValue
            );

        if (!lpConstant ||
            !monsterConstant)
        {
            continue;
        }

        ++decoded;

        std::cout
            << "slot +"
            << HexU64(
                slot
            )
            << " | LP="
            << (
                lpValue
                    ? "true"
                    : "false"
            )
            << " | Monster="
            << (
                monsterValue
                    ? "true"
                    : "false"
            )
            << " | lpFnRva=";

        if (InsideExeImage(
                lpFn))
        {
            std::cout
                << HexU64(
                    lpFn -
                    g_exeBase
                );
        }
        else
        {
            std::cout
                << HexPtr(
                    lpFn
                );
        }

        std::cout
            << " | monsterFnRva=";

        if (InsideExeImage(
                monsterFn))
        {
            std::cout
                << HexU64(
                    monsterFn -
                    g_exeBase
                );
        }
        else
        {
            std::cout
                << HexPtr(
                    monsterFn
                );
        }

        if (lpValue &&
            monsterValue)
        {
            std::cout
                << "  <BOTH TRUE>";
        }
        else if (!lpValue &&
                 monsterValue)
        {
            std::cout
                << "  <MONSTER TRUE>";
        }
        else if (lpValue &&
                 !monsterValue)
        {
            std::cout
                << "  <PLAYER TRUE>";
        }

        std::cout
            << "\n";
    }

    std::cout
        << "Decoded constant-bool slots: "
        << decoded
        << "\n";
}

bool RunStage6AMonsterDiscovery(
    DbProfile& profile)
{
    std::cout
        << "\n============================================================\n"
        << "       STAGE 6A - WORLD THING COHORTS + MONSTER\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "[NO WRITE] nenhuma escrita em memoria do jogo\n"
        << "[NO HOOK] nenhum hook\n"
        << "[NO CALL] nenhuma funcao/virtual interna sera chamada\n"
        << "\n"
        << "Objetivo:\n"
        << "  1. usar o Map->Tile path confirmado\n"
        << "  2. enumerar Tile::things do world\n"
        << "  3. agrupar Things por vtable\n"
        << "  4. capturar DOIS monstros distintos via AttackTarget\n"
        << "  5. exigir mesma vtable nos dois monstros\n"
        << "  6. mapear estaticamente slots constant-bool da vtable\n";

    if (profile.mapTilePathStatus !=
            "confirmed_runtime_two_positions" ||
        !profile.mapTilePathDepth ||
        !profile.mapTilePathHeaderOffset)
    {
        std::cout
            << "[STOP] Stage 5B ainda nao esta confirmada.\n";

        return false;
    }

    uintptr_t localPlayer =
        WaitForDiscoveryLocalPlayer(
            profile,
            "STAGE 6A - WORLD THING COHORTS + MONSTER"
        );

    if (!localPlayer)
        return false;

    if (!WaitForTileWorldReady(
            profile,
            localPlayer))
    {
        return false;
    }

    auto observations =
        V25CollectWorldThings(
            profile,
            localPlayer
        );

    if (observations.empty())
    {
        profile.monsterVtableStatus =
            "unresolved_world_empty";

        return false;
    }

    auto cohorts =
        V25BuildCohorts(
            observations,
            localPlayer
        );

    V25PrintCohorts(
        cohorts
    );

    if (!V25WaitAttackTargetClear(
            profile))
    {
        return false;
    }

    uintptr_t monsterA =
        V25CaptureMonsterTarget(
            profile,
            observations,
            localPlayer,
            0,
            "A"
        );

    if (!monsterA)
    {
        profile.monsterVtableStatus =
            "pending_sample_A_retry";

        return false;
    }

    const V25ThingObservation* obsA =
        V25FindObservation(
            observations,
            monsterA
        );

    if (!obsA)
    {
        profile.monsterVtableStatus =
            "unresolved_sample_A";

        return false;
    }

    uintptr_t vtableA =
        obsA->vtable;

    if (!V25WaitAttackTargetClear(
            profile))
    {
        return false;
    }

    // V2.3: do NOT snapshot before the user selects Sample B.
    // V25CaptureMonsterTarget refreshes immediately after reading AttackTarget.
    auto observationsB =
        observations;

    uintptr_t monsterB =
        V25CaptureMonsterTarget(
            profile,
            observationsB,
            localPlayer,
            monsterA,
            "B"
        );

    if (!monsterB)
    {
        profile.monsterVtableStatus =
            "pending_sample_B_retry";

        return false;
    }

    const V25ThingObservation* obsB =
        V25FindObservation(
            observationsB,
            monsterB
        );

    if (!obsB)
    {
        profile.monsterVtableStatus =
            "unresolved_sample_B";

        return false;
    }

    uintptr_t vtableB =
        obsB->vtable;

    std::cout
        << "\n============================================================\n"
        << "               MONSTER SAMPLE CROSS-CHECK\n"
        << "============================================================\n"
        << "Monster A            : "
        << HexPtr(
            monsterA
        )
        << " vtableRva="
        << HexU64(
            vtableA -
            g_exeBase
        )
        << "\n"
        << "Monster B            : "
        << HexPtr(
            monsterB
        )
        << " vtableRva="
        << HexU64(
            vtableB -
            g_exeBase
        )
        << "\n";

    if (monsterA ==
        monsterB)
    {
        profile.monsterVtableStatus =
            "unresolved_same_monster_pointer";

        std::cout
            << "[CHECK] Os dois samples apontam para o mesmo objeto.\n";

        return false;
    }

    if (vtableA !=
        vtableB)
    {
        profile.monsterVtableStatus =
            "ambiguous_multiple_monster_vtables";

        std::cout
            << "[CHECK] Os dois monstros possuem vtables diferentes.\n"
            << "Nenhuma vtable sera promovida nesta rodada.\n";

        return false;
    }

    if (!InsideExeImage(
            vtableA))
    {
        profile.monsterVtableStatus =
            "unresolved_monster_vtable_outside_module";

        return false;
    }

    profile.monsterVtableRva =
        vtableA -
        g_exeBase;

    profile.monsterVtableStatus =
        "confirmed_runtime_two_attack_samples";

    std::cout
        << "\n============================================================\n"
        << "               MONSTER VTABLE CONFIRMED\n"
        << "============================================================\n"
        << "Monster VTable RVA   : "
        << HexU64(
            profile.monsterVtableRva
        )
        << "\n"
        << "Evidence             : dois AttackTarget distintos\n"
        << "                       complete-object identity / RTTI cross-check\n"
        << "                       mesma world Thing vtable\n"
        << "Status               : "
        << profile.monsterVtableStatus
        << "\n";

    const V25ThingObservation* localWorldObs =
        V25FindObservation(
            observationsB,
            localPlayer
        );

    uintptr_t localPlayerVtable =
        localWorldObs
            ? localWorldObs->vtable
            : g_exeBase +
                profile.vtableRva;

    std::cout
        << "[IDENTITY] LocalPlayer complete="
        << HexPtr(
            V35CompleteObjectPointer(
                localPlayer)
        )
        << " worldThingVtableRva="
        << HexU64(
            localPlayerVtable -
            g_exeBase
        )
        << "\n";

    V25PrintVtableBoolMatrix(
        localPlayerVtable,
        vtableA
    );

    std::cout
        << "\n[FEITO] STAGE 6A confirmou a vtable de Monster semanticamente.\n"
        << "[PROXIMO] Usar os cohorts + bool matrix para fechar Creature/NPC/Player classification.\n";

    return true;
}

bool EnsureStage6AMonsterDiscovery(
    DbProfile& profile,
    std::vector<DbProfile>& database,
    int profileIndex,
    const std::string& databasePath)
{
    if (profile.monsterVtableStatus.find(
            "confirmed_") == 0 &&
        profile.monsterVtableRva)
    {
        std::cout
            << "\n[FEITO] STAGE 6A - Monster VTable ja esta confirmada.\n"
            << "Monster VTable RVA: "
            << HexU64(
                profile.monsterVtableRva
            )
            << "\n";

        return true;
    }

    profile.monsterVtableRva = 0;
    profile.monsterVtableStatus =
        "rediscovery_running";

    bool ok =
        RunStage6AMonsterDiscovery(
            profile
        );

    if (profileIndex >= 0 &&
        profileIndex <
            static_cast<int>(
                database.size()
            ))
    {
        database[
            static_cast<size_t>(
                profileIndex
            )
        ] = profile;

        SaveProfileDatabase(
            databasePath,
            database
        );
    }

    return ok;
}


// ============================================================
// DISCOVERY V2.6 - CLASSIFICATION CORE + REMOTE PLAYER
// Strict read-only. Static decoding only; no virtual calls.
// ============================================================

struct V26BoolRow
{
    uintptr_t slot = 0;

    bool itemKnown = false;
    bool itemValue = false;

    bool localKnown = false;
    bool localValue = false;

    bool playerKnown = false;
    bool playerValue = false;

    bool monsterKnown = false;
    bool monsterValue = false;
};

const V25ThingCohort*
V26FindCohortByVtable(
    const std::vector<V25ThingCohort>& cohorts,
    uintptr_t vtable)
{
    for (const auto& c :
         cohorts)
    {
        if (c.vtable ==
            vtable)
        {
            return &c;
        }
    }

    return nullptr;
}

const V25ThingCohort*
V26SelectLowIdTileThingCohort(
    const std::vector<V25ThingCohort>& cohorts,
    uintptr_t localPlayerVtable,
    uintptr_t monsterVtable)
{
    std::vector<const V25ThingCohort*>
        candidates;

    for (const auto& c :
         cohorts)
    {
        if (!c.vtable ||
            c.vtable ==
                localPlayerVtable ||
            c.vtable ==
                monsterVtable)
        {
            continue;
        }

        if (c.objects < 8)
            continue;

        if (c.highId != 0)
            continue;

        if (c.plausiblePosition !=
            c.objects)
        {
            continue;
        }

        candidates.push_back(
            &c
        );
    }

    if (candidates.empty())
        return nullptr;

    std::sort(
        candidates.begin(),
        candidates.end(),
        [](
            const V25ThingCohort* a,
            const V25ThingCohort* b)
        {
            if (a->objects !=
                b->objects)
            {
                return
                    a->objects >
                    b->objects;
            }

            return
                a->vtableRva <
                b->vtableRva;
        }
    );

    if (candidates.size() > 1)
    {
        size_t first =
            candidates[0]->objects;

        size_t second =
            candidates[1]->objects;

        // Require clear dominance. We do not want to call a random
        // low-ID cohort "Item" when multiple families are similarly common.
        if (first <
            second * 3)
        {
            return nullptr;
        }
    }

    return
        candidates[0];
}


bool V33RttiLooksLikeControlBlock(
    const std::string& rttiName)
{
    std::string rtti =
        LowerAscii(
            rttiName
        );

    return
        rtti.find(
            "_ref_count") !=
            std::string::npos ||
        rtti.find(
            "shared_ptr") !=
            std::string::npos;
}

bool V33RttiContainsClassToken(
    const std::string& rttiName,
    const std::string& token)
{
    std::string rtti =
        LowerAscii(
            rttiName
        );

    std::string wanted =
        LowerAscii(
            token
        );

    return
        rtti.find(
            wanted
        ) !=
        std::string::npos;
}

const V25ThingCohort*
V33SelectItemCohortSemantic(
    const std::vector<V25ThingCohort>& cohorts,
    uintptr_t localPlayerVtable,
    uintptr_t monsterVtable,
    std::string& method)
{
    method.clear();

    std::vector<const V25ThingCohort*>
        exactRtti;

    std::vector<const V25ThingCohort*>
        structural;

    for (const auto& c :
         cohorts)
    {
        if (!c.vtable ||
            c.vtable ==
                localPlayerVtable ||
            c.vtable ==
                monsterVtable)
        {
            continue;
        }

        if (V33RttiLooksLikeControlBlock(
                c.rttiName))
        {
            continue;
        }

        if (V33RttiContainsClassToken(
                c.rttiName,
                "item"))
        {
            exactRtti.push_back(
                &c
            );

            continue;
        }

        if (c.objects < 4)
            continue;

        // Thing-derived objects on the tested clients keep positional state.
        // No ID assumption is used here.
        if (c.plausiblePosition * 100 <
                c.objects * 85)
        {
            continue;
        }

        // Explicit creature RTTI is not an Item candidate.
        if (V33RttiContainsClassToken(
                c.rttiName,
                "player") ||
            V33RttiContainsClassToken(
                c.rttiName,
                "monster") ||
            V33RttiContainsClassToken(
                c.rttiName,
                "npc") ||
            V33RttiContainsClassToken(
                c.rttiName,
                "creature"))
        {
            continue;
        }

        structural.push_back(
            &c
        );
    }

    if (exactRtti.size() == 1)
    {
        method =
            "rtti_item_class";

        return
            exactRtti[0];
    }

    if (exactRtti.size() > 1)
    {
        std::sort(
            exactRtti.begin(),
            exactRtti.end(),
            [](
                const V25ThingCohort* a,
                const V25ThingCohort* b)
            {
                return
                    a->objects >
                    b->objects;
            }
        );

        if (exactRtti[0]->objects >
            exactRtti[1]->objects * 2)
        {
            method =
                "rtti_item_class_dominant";

            return
                exactRtti[0];
        }

        return nullptr;
    }

    if (structural.empty())
        return nullptr;

    std::sort(
        structural.begin(),
        structural.end(),
        [](
            const V25ThingCohort* a,
            const V25ThingCohort* b)
        {
            if (a->objects !=
                b->objects)
            {
                return
                    a->objects >
                    b->objects;
            }

            return
                a->vtableRva <
                b->vtableRva;
        }
    );

    if (structural.size() > 1)
    {
        const size_t first =
            structural[0]->objects;

        const size_t second =
            structural[1]->objects;

        if (first <
            second * 3)
        {
            return nullptr;
        }
    }

    method =
        "dominant_noncreature_world_cohort";

    return
        structural[0];
}


std::vector<V26BoolRow>
V26BuildBoolMatrix(
    uintptr_t itemVtable,
    uintptr_t localPlayerVtable,
    uintptr_t playerVtable,
    uintptr_t monsterVtable)
{
    std::vector<V26BoolRow>
        rows;

    for (uintptr_t slot = 0;
         slot <= 0x100;
         slot += 8)
    {
        V26BoolRow row{};
        row.slot = slot;

        uintptr_t itemFn =
            itemVtable
                ? ReadPtr(
                    itemVtable +
                    slot
                )
                : 0;

        uintptr_t localFn =
            localPlayerVtable
                ? ReadPtr(
                    localPlayerVtable +
                    slot
                )
                : 0;

        uintptr_t playerFn =
            playerVtable
                ? ReadPtr(
                    playerVtable +
                    slot
                )
                : 0;

        uintptr_t monsterFn =
            monsterVtable
                ? ReadPtr(
                    monsterVtable +
                    slot
                )
                : 0;

        row.itemKnown =
            itemVtable &&
            V25DecodeConstantBool(
                itemFn,
                row.itemValue
            );

        row.localKnown =
            localPlayerVtable &&
            V25DecodeConstantBool(
                localFn,
                row.localValue
            );

        row.playerKnown =
            playerVtable &&
            V25DecodeConstantBool(
                playerFn,
                row.playerValue
            );

        row.monsterKnown =
            monsterVtable &&
            V25DecodeConstantBool(
                monsterFn,
                row.monsterValue
            );

        if (row.itemKnown ||
            row.localKnown ||
            row.playerKnown ||
            row.monsterKnown)
        {
            rows.push_back(
                row
            );
        }
    }

    return rows;
}

void V26PrintBoolMatrix(
    const std::vector<V26BoolRow>& rows,
    bool hasRemotePlayer)
{
    std::cout
        << "\n============================================================\n"
        << "             FOUR-CLASS STATIC BOOL MATRIX\n"
        << "============================================================\n"
        << "[NO CALL] vtable functions are NOT executed.\n";

    for (const auto& r :
         rows)
    {
        if (!r.itemKnown ||
            !r.localKnown ||
            !r.monsterKnown ||
            (hasRemotePlayer &&
             !r.playerKnown))
        {
            continue;
        }

        std::cout
            << "slot +"
            << HexU64(
                r.slot
            )
            << " | Item="
            << (
                r.itemValue
                    ? "T"
                    : "F"
            )
            << " | LocalPlayer="
            << (
                r.localValue
                    ? "T"
                    : "F"
            );

        if (hasRemotePlayer)
        {
            std::cout
                << " | Player="
                << (
                    r.playerValue
                        ? "T"
                        : "F"
                );
        }

        std::cout
            << " | Monster="
            << (
                r.monsterValue
                    ? "T"
                    : "F"
            )
            << "\n";
    }
}

std::vector<uintptr_t>
V26MatchSlots(
    const std::vector<V26BoolRow>& rows,
    bool item,
    bool local,
    bool player,
    bool monster,
    bool requirePlayer)
{
    std::vector<uintptr_t>
        out;

    for (const auto& r :
         rows)
    {
        if (!r.itemKnown ||
            !r.localKnown ||
            !r.monsterKnown)
        {
            continue;
        }

        if (requirePlayer &&
            !r.playerKnown)
        {
            continue;
        }

        if (r.itemValue != item ||
            r.localValue != local ||
            r.monsterValue != monster)
        {
            continue;
        }

        if (requirePlayer &&
            r.playerValue != player)
        {
            continue;
        }

        out.push_back(
            r.slot
        );
    }

    return out;
}

bool V26WaitFollowTargetClear(
    const DbProfile& profile)
{
    uintptr_t game =
        g_exeBase +
        profile.gameRva;

    for (;;)
    {
        uintptr_t follow =
            ReadPtr(
                game +
                profile.gameFollowTarget
            );

        if (!follow)
            return true;

        std::cout
            << "\n[CLEAR FOLLOW] FollowTarget ainda esta em "
            << HexPtr(
                follow
            )
            << ".\n"
            << "Desative o Follow pelo cliente e pressione ENTER.\n";

        WaitEnter(
            "Depois de limpar FollowTarget, pressione ENTER..."
        );
    }
}

bool V26CaptureRemotePlayer(
    const DbProfile& profile,
    uintptr_t localPlayer,
    uintptr_t monsterVtable,
    uintptr_t& remotePlayer,
    uintptr_t& remotePlayerVtable)
{
    remotePlayer = 0;
    remotePlayerVtable = 0;

    uintptr_t game =
        g_exeBase +
        profile.gameRva;

    const int maxCaptureRounds = 3;
    int captureRound = 0;

    for (;;)
    {
        ++captureRound;

        std::cout
            << "\n[PLAYER SAMPLE ROUND] "
            << captureRound
            << "/"
            << maxCaptureRounds
            << "\n";
        std::cout
            << "\n============================================================\n"
            << "                REMOTE PLAYER SAMPLE\n"
            << "============================================================\n"
            << "Use o FOLLOW normal do cliente em OUTRO PLAYER humano visivel.\n"
            << "Nao use Monster/NPC e nao use seu proprio personagem.\n"
            << "O Lab vai SALVAR o FollowTarget primeiro.\n"
            << "Depois voce vai DESATIVAR o Follow antes do scan do world.\n";

        WaitEnter(
            "Com o OUTRO PLAYER em Follow, pressione ENTER..."
        );

        uintptr_t follow =
            ReadPtr(
                game +
                profile.gameFollowTarget
            );

        if (!follow)
        {
            std::cout
                << "[RETRY] FollowTarget esta NULL.\n";

            if (captureRound >= maxCaptureRounds)
            {
                std::cout
                    << "[CALIBRATE] Limite de 3 amostras atingido. Voltando ao orquestrador para R/S/Q.\n";
                return false;
            }

            continue;
        }

        if (follow ==
            localPlayer)
        {
            std::cout
                << "[RETRY] FollowTarget e o proprio LocalPlayer.\n";

            if (captureRound >= maxCaptureRounds)
            {
                std::cout
                    << "[CALIBRATE] Limite de 3 amostras atingido. Voltando ao orquestrador para R/S/Q.\n";
                return false;
            }

            continue;
        }

        if (!IsReadableMonitorRange(
                follow,
                0x100))
        {
            std::cout
                << "[RETRY] FollowTarget unreadable.\n";

            if (captureRound >= maxCaptureRounds)
            {
                std::cout
                    << "[CALIBRATE] Limite de 3 amostras atingido. Voltando ao orquestrador para R/S/Q.\n";
                return false;
            }

            continue;
        }

        uintptr_t vt =
            ReadPtr(
                follow
            );

        if (!InsideExeImage(
                vt))
        {
            std::cout
                << "[RETRY] FollowTarget vtable fora do modulo.\n";

            if (captureRound >= maxCaptureRounds)
            {
                std::cout
                    << "[CALIBRATE] Limite de 3 amostras atingido. Voltando ao orquestrador para R/S/Q.\n";
                return false;
            }

            continue;
        }

        std::string followRtti =
            TryReadMsvcRttiTypeName(
                vt
            );

        if (
            vt ==
                monsterVtable ||
            V33RttiContainsClassToken(
                followRtti,
                "monster") ||
            V33RttiContainsClassToken(
                followRtti,
                "npc")
        )
        {
            std::cout
                << "[RETRY] FollowTarget RTTI/vtable nao representa Player humano. RTTI=\""
                << followRtti
                << "\"\n";

            V26WaitFollowTargetClear(
                profile
            );

            if (captureRound >= maxCaptureRounds)
            {
                std::cout
                    << "[CALIBRATE] Limite de 3 amostras atingido. Voltando ao orquestrador para R/S/Q.\n";
                return false;
            }

            continue;
        }

        MapPosition p =
            ReadDiscoveredPlayerPosition(
                follow,
                profile
            );

        uint32_t id =
            ReadU32(
                follow +
                profile.id
            );

        uint8_t hp =
            ReadU8(
                follow +
                profile.hpPercent
            );

        uint32_t direction =
            ReadU32(
                follow +
                profile.direction
            );

        if (!MapPositionPlausible(
                p))
        {
            std::cout
                << "[RETRY] FollowTarget nao possui Position plausivel.\n";

            V26WaitFollowTargetClear(
                profile
            );

            if (captureRound >= maxCaptureRounds)
            {
                std::cout
                    << "[CALIBRATE] Limite de 3 amostras atingido. Voltando ao orquestrador para R/S/Q.\n";
                return false;
            }

            continue;
        }

        // ID/HP/direction layouts can drift independently between builds.
        // They are printed as diagnostics but are NOT prerequisites for
        // semantic Player capture. The later world-membership test is the
        // stronger invariant.

        // Save the semantic sample BEFORE asking the user to stop following.
        uintptr_t capturedPlayer =
            follow;

        uintptr_t capturedVtable =
            vt;

        MapPosition capturedPosition =
            p;

        uint32_t capturedId =
            id;

        uint8_t capturedHp =
            hp;

        std::cout
            << "\n[CAPTURED FOLLOWTARGET]\n"
            << "ptr                  : "
            << HexPtr(
                capturedPlayer
            )
            << "\n"
            << "vtableRva            : "
            << HexU64(
                capturedVtable -
                g_exeBase
            )
            << "\n"
            << "pos                  : "
            << capturedPosition.x
            << ","
            << capturedPosition.y
            << ","
            << static_cast<unsigned>(
                capturedPosition.z
            )
            << "\n"
            << "id                   : "
            << capturedId
            << "\n"
            << "hp%                  : "
            << static_cast<unsigned>(
                capturedHp
            )
            << "\n"
            << "\n"
            << "AGORA DESATIVE O FOLLOW pelo cliente.\n"
            << "Mantenha o outro Player visivel e fique parado.\n";

        // Follow movement can mutate/rebuild the current map storage while the
        // Lab scans it. Clear Follow first, but keep the captured pointer locally.
        V26WaitFollowTargetClear(
            profile
        );

        std::cout
            << "\n[SYNC] FollowTarget limpo. Aguardando world estabilizar novamente...\n";

        if (!WaitForTileWorldReady(
                profile,
                localPlayer))
        {
            std::cout
                << "[RETRY] World nao estabilizou apos limpar Follow.\n";

            if (captureRound >= maxCaptureRounds)
            {
                std::cout
                    << "[CALIBRATE] Limite de 3 amostras atingido. Voltando ao orquestrador para R/S/Q.\n";
                return false;
            }

            continue;
        }

        const int maxWorldAttempts =
            4;

        bool verifiedInWorld =
            false;

        for (int attempt = 1;
             attempt <= maxWorldAttempts;
             ++attempt)
        {
            std::cout
                << "\n[WORLD VERIFY] tentativa "
                << attempt
                << "/"
                << maxWorldAttempts
                << "\n";

            // Revalidate the captured object before every world pass.
            if (!IsReadableMonitorRange(
                    capturedPlayer,
                    0x100) ||
                ReadPtr(
                    capturedPlayer
                ) !=
                    capturedVtable)
            {
                std::cout
                    << "[WORLD VERIFY] Player capturado nao esta mais valido.\n";

                break;
            }

            auto world =
                V25CollectWorldThings(
                    profile,
                    localPlayer
                );

            if (world.empty())
            {
                std::cout
                    << "[WORLD VERIFY] World array temporariamente indisponivel.\n";

                Sleep(400);

                WaitForTileWorldReady(
                    profile,
                    localPlayer
                );

                continue;
            }

            const V25ThingObservation* obs =
                V25FindObservation(
                    world,
                    capturedPlayer
                );

            if (!obs)
            {
                // Some MSVC shared_ptr layouts expose a FollowTarget wrapper/control
                // object while Tile::things stores the actual Player Thing*.  Do not
                // require raw pointer equality in that case.  Rebind only when there
                // is exactly ONE non-local Player RTTI world object at the captured
                // position.  This mirrors the Monster identity-rebind policy while
                // remaining conservative on ambiguous scenes.
                const V25ThingObservation* rebound = nullptr;
                size_t reboundMatches = 0;

                for (const auto& candidate : world)
                {
                    const bool samePosition =
                        candidate.positionPlausible &&
                        candidate.x == capturedPosition.x &&
                        candidate.y == capturedPosition.y &&
                        candidate.z == capturedPosition.z;

                    const bool playerRtti =
                        V33RttiContainsClassToken(candidate.rttiName, "player") &&
                        !V33RttiContainsClassToken(candidate.rttiName, "localplayer");

                    const bool notLocal =
                        candidate.completeObject != V35CompleteObjectPointer(localPlayer) &&
                        candidate.pointer != localPlayer;

                    if (samePosition && playerRtti && notLocal)
                    {
                        rebound = &candidate;
                        ++reboundMatches;
                    }
                }

                if (reboundMatches == 1 && rebound)
                {
                    remotePlayer = rebound->pointer;
                    remotePlayerVtable = rebound->vtable;

                    std::cout
                        << "\n[PLAYER FOLLOW REBIND][PASS]\n"
                        << "FollowTarget raw ptr : " << HexPtr(capturedPlayer) << "\n"
                        << "World Player ptr     : " << HexPtr(remotePlayer) << "\n"
                        << "Captured position    : "
                        << capturedPosition.x << "," << capturedPosition.y << ","
                        << static_cast<unsigned>(capturedPosition.z) << "\n"
                        << "World Player vtable  : "
                        << HexU64(remotePlayerVtable - g_exeBase) << "\n"
                        << "RTTI                 : " << rebound->rttiName << "\n"
                        << "Evidence             : unique Player RTTI at captured FollowTarget position\n";

                    verifiedInWorld = true;
                    break;
                }

                std::cout
                    << "[WORLD VERIFY] FollowTarget raw ptr nao apareceu em Tile::things; "
                    << "Player positional rebind matches="
                    << reboundMatches
                    << ".\n";

                Sleep(350);

                continue;
            }

            const bool sameIdentity =
                obs->completeObject ==
                    V35CompleteObjectPointer(
                        capturedPlayer
                    );

            const std::string capturedRtti =
                TryReadMsvcRttiTypeName(
                    capturedVtable
                );

            const bool playerRtti =
                V33RttiContainsClassToken(
                    obs->rttiName,
                    "player") ||
                V33RttiContainsClassToken(
                    capturedRtti,
                    "player");

            if (!sameIdentity ||
                !playerRtti)
            {
                std::cout
                    << "[WORLD VERIFY] Complete-object identity / Player RTTI nao fechou.\n";

                break;
            }

            remotePlayer =
                capturedPlayer;

            // Keep the vtable used by Tile::things. It belongs to the same
            // complete Player object and is the correct semantic comparator
            // against Item/Monster/NPC world cohorts.
            remotePlayerVtable =
                obs->vtable;

            std::cout
                << "\n[PLAYER SAMPLE VERIFIED]\n"
                << "ptr                  : "
                << HexPtr(
                    remotePlayer
                )
                << "\n"
                << "vtableRva            : "
                << HexU64(
                    remotePlayerVtable -
                    g_exeBase
                )
                << "\n"
                << "captured vtable RVA  : "
                << HexU64(
                    capturedVtable -
                    g_exeBase
                )
                << "\n"
                << "world Thing vtable   : "
                << HexU64(
                    remotePlayerVtable -
                    g_exeBase
                )
                << "\n"
                << "RTTI                 : "
                << obs->rttiName
                << "\n"
                << "subobject offset     : "
                << obs->rttiSubobjectOffset
                << "\n"
                << "complete identity    : PASS\n"
                << "FollowTarget capture : PASS\n"
                << "world stable         : PASS\n";

            verifiedInWorld =
                true;

            break;
        }

        if (verifiedInWorld)
        {
            return true;
        }

        std::cout
            << "\n[RETRY] Nao foi possivel confirmar o Player capturado no world estavel.\n"
            << "Escolha um Player que continue VISIVEL, ative Follow novamente e repita.\n";

        if (captureRound >= maxCaptureRounds)
        {
            std::cout
                << "[CALIBRATE] 3 rodadas de Player remoto sem confirmacao. "
                << "Voltando ao orquestrador para R/S/Q; nao ficara preso em loop.\n";
            return false;
        }
    }
}

bool RunStage6BClassification(
    DbProfile& profile)
{
    std::cout
        << "\n============================================================\n"
        << "     STAGE 6B - SEMANTIC CLASSIFICATION + PLAYER\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "[NO WRITE] nenhuma escrita em memoria do jogo\n"
        << "[NO HOOK] nenhum hook\n"
        << "[NO CALL] nenhuma funcao/virtual interna sera chamada\n"
        << "\n"
        << "Objetivo:\n"
        << "  1. detectar RAW Thing* ou shared_ptr<Thing>\n"
        << "  2. remover control-blocks da enumeracao\n"
        << "  3. usar Monster e LocalPlayer como anchors conhecidos\n"
        << "  4. resolver Item por RTTI/estrutura, sem depender de ID\n"
        << "  5. capturar Player humano via FollowTarget\n"
        << "  6. tentar slots constant-bool; se a build nao usar esse padrao,\n"
        << "     preservar as vtables semanticas e deixar slots pending\n";

    if (profile.monsterVtableStatus.find(
            "confirmed_") != 0 ||
        !profile.monsterVtableRva)
    {
        std::cout
            << "[STOP] Monster VTable ainda nao esta confirmada.\n";

        return false;
    }

    uintptr_t localPlayer =
        WaitForDiscoveryLocalPlayer(
            profile,
            "STAGE 6B - SEMANTIC CLASSIFICATION + PLAYER"
        );

    if (!localPlayer)
        return false;

    if (!WaitForTileWorldReady(
            profile,
            localPlayer))
    {
        return false;
    }

    V33PersistThingStorage(
        profile,
        localPlayer
    );

    auto observations =
        V25CollectWorldThings(
            profile,
            localPlayer
        );

    if (observations.empty())
    {
        profile.classificationStatus =
            "unresolved_world_empty";

        return false;
    }

    auto cohorts =
        V25BuildCohorts(
            observations,
            localPlayer
        );

    V25PrintCohorts(
        cohorts
    );


    // V3.5: AttackTarget may point at the complete/primary object while
    // Tile::things stores a secondary Thing subobject. RTTI identifies both
    // as the same most-derived Monster class. Prefer the world Thing vtable
    // for class comparisons after the complete-object identity bridge.
    std::vector<const V25ThingCohort*>
        monsterRttiCohorts;

    for (const auto& cohort :
         cohorts)
    {
        if (V33RttiContainsClassToken(
                cohort.rttiName,
                "monster") &&
            !V33RttiLooksLikeControlBlock(
                cohort.rttiName))
        {
            monsterRttiCohorts.push_back(
                &cohort
            );
        }
    }

    if (monsterRttiCohorts.size() == 1)
    {
        uintptr_t worldMonsterRva =
            monsterRttiCohorts[0]->vtableRva;

        if (profile.monsterVtableRva !=
            worldMonsterRva)
        {
            std::cout
                << "[IDENTITY REBIND] Monster AttackTarget vtable RVA "
                << HexU64(
                    profile.monsterVtableRva
                )
                << " -> world Thing vtable RVA "
                << HexU64(
                    worldMonsterRva
                )
                << " RTTI=\\\""
                << monsterRttiCohorts[0]->rttiName
                << "\\\"\\n";

            profile.monsterVtableRva =
                worldMonsterRva;

            profile.monsterVtableStatus =
                "confirmed_semantic_rtti_world_cohort";
        }
    }

    const V25ThingObservation* localWorldObs =
        V25FindObservation(
            observations,
            localPlayer
        );

    uintptr_t localPlayerVtable =
        localWorldObs
            ? localWorldObs->vtable
            : g_exeBase +
                profile.vtableRva;

    uintptr_t monsterVtable =
        g_exeBase +
        profile.monsterVtableRva;

    std::string itemMethod;

    const V25ThingCohort* itemCohort =
        V33SelectItemCohortSemantic(
            cohorts,
            localPlayerVtable,
            monsterVtable,
            itemMethod
        );

    if (!itemCohort)
    {
        profile.itemVtableStatus =
            "unresolved_semantic_item_cohort";

        profile.classificationStatus =
            "unresolved_item_anchor";

        std::cout
            << "[CHECK] Item nao ficou semanticamente unico por RTTI/estrutura.\n";

        return false;
    }

    uintptr_t itemVtable =
        itemCohort->vtable;

    profile.itemVtableRva =
        itemCohort->vtableRva;

    profile.itemVtableStatus =
        itemMethod.find(
            "rtti_") == 0
            ? "confirmed_semantic_rtti_item"
            : "confirmed_semantic_dominant_world_item";

    std::cout
        << "\n============================================================\n"
        << "                 ITEM ANCHOR CONFIRMED\n"
        << "============================================================\n"
        << "VTable RVA           : "
        << HexU64(
            itemCohort->vtableRva
        )
        << "\n"
        << "RTTI                 : "
        << itemCohort->rttiName
        << "\n"
        << "Objects              : "
        << itemCohort->objects
        << "\n"
        << "Method               : "
        << itemMethod
        << "\n"
        << "Status               : "
        << profile.itemVtableStatus
        << "\n";

    // V3.8: when another Player is already present in the world,
    // RTTI itself can close the semantic class without requiring a Follow
    // interaction. FollowTarget remains the stronger fallback.
    std::vector<const V25ThingCohort*>
        rttiPlayers;

    for (const auto& cohort :
         cohorts)
    {
        if (!cohort.vtable ||
            cohort.vtable ==
                localPlayerVtable ||
            cohort.vtable ==
                monsterVtable ||
            cohort.vtable ==
                itemVtable)
        {
            continue;
        }

        std::string rtti =
            LowerAscii(
                cohort.rttiName
            );

        if (rtti.find(
                "localplayer") !=
                std::string::npos)
        {
            continue;
        }

        if (rtti.find(
                "player") !=
                std::string::npos &&
            rtti.find(
                "_ref_count") ==
                std::string::npos &&
            rtti.find(
                "shared_ptr") ==
                std::string::npos)
        {
            rttiPlayers.push_back(
                &cohort
            );
        }
    }

    if (rttiPlayers.size() == 1)
    {
        profile.playerVtableRva =
            rttiPlayers[0]->vtableRva;

        profile.playerVtableStatus =
            "confirmed_semantic_rtti_player_world";

        profile.classificationStatus =
            "confirmed_semantic_vtables_slots_pending";

        std::cout
            << "\n[PLAYER RTTI AUTO-CONFIRMED]\n"
            << "VTable RVA : "
            << HexU64(
                profile.playerVtableRva
            )
            << "\n"
            << "RTTI       : "
            << rttiPlayers[0]->rttiName
            << "\n"
            << "Evidence   : unique non-local Player RTTI cohort\n";

        return true;
    }

    if (!V26WaitFollowTargetClear(
            profile))
    {
        return false;
    }

    uintptr_t remotePlayer = 0;
    uintptr_t remotePlayerVtable = 0;

    const bool haveVisiblePlayer =
        AskYesNo(
            "Existe OUTRO PLAYER humano visivel para fazer FOLLOW agora? [S/N]: "
        );

    if (!haveVisiblePlayer)
    {
        profile.playerVtableRva = 0;

        profile.playerVtableStatus =
            "pending_no_visible_player_sample";

        profile.slotIsItem = 0;
        profile.slotIsCreature = 0;
        profile.slotIsMonster = 0;
        profile.slotIsPlayer = 0;
        profile.slotIsLocalPlayer = 0;

        profile.classificationStatus =
            "partial_semantic_item_monster_player_pending";

        std::cout
            << "\n[PARTIAL PASS] Nao ha Player humano disponivel agora.\n"
            << "[FEITO] Item e Monster permanecem como anchors semanticas.\n"
            << "[PENDING] Player sera fechado depois por FollowTarget.\n"
            << "[CONTINUE] Liberando Inventory / Item / Containers que nao dependem "
            << "da amostra Player.\n";

        return true;
    }

    if (!V26CaptureRemotePlayer(
            profile,
            localPlayer,
            monsterVtable,
            remotePlayer,
            remotePlayerVtable))
    {
        profile.playerVtableStatus =
            "unresolved_follow_sample";

        return false;
    }

    profile.playerVtableRva =
        remotePlayerVtable -
        g_exeBase;

    profile.playerVtableStatus =
        "confirmed_runtime_followtarget_world_member";

    std::string playerRtti =
        TryReadMsvcRttiTypeName(
            remotePlayerVtable
        );

    if (playerRtti.empty())
        playerRtti = "<unavailable>";

    std::cout
        << "\n============================================================\n"
        << "                PLAYER ANCHOR CONFIRMED\n"
        << "============================================================\n"
        << "VTable RVA           : "
        << HexU64(
            profile.playerVtableRva
        )
        << "\n"
        << "RTTI                 : "
        << playerRtti
        << "\n"
        << "Evidence             : FollowTarget + world membership\n";

    // Static bool slots are useful on the old OpenGL/DX family, but newer
    // clients can implement these predicates as non-constant functions.
    // Treat slots as an optional semantic accelerator, not a prerequisite
    // for identifying Item/Player/Monster classes.
    auto rows =
        V26BuildBoolMatrix(
            itemVtable,
            localPlayerVtable,
            remotePlayerVtable,
            monsterVtable
        );

    V26PrintBoolMatrix(
        rows,
        true
    );

    auto isItem =
        V26MatchSlots(
            rows,
            true,
            false,
            false,
            false,
            true
        );

    auto isCreature =
        V26MatchSlots(
            rows,
            false,
            true,
            true,
            true,
            true
        );

    auto isMonster =
        V26MatchSlots(
            rows,
            false,
            false,
            false,
            true,
            true
        );

    auto isPlayer =
        V26MatchSlots(
            rows,
            false,
            true,
            true,
            false,
            true
        );

    auto isLocalPlayer =
        V26MatchSlots(
            rows,
            false,
            true,
            false,
            false,
            true
        );

    std::cout
        << "\n============================================================\n"
        << "              CLASSIFICATION SLOT RESOLUTION\n"
        << "============================================================\n"
        << "isItem candidates       : "
        << isItem.size()
        << "\n"
        << "isCreature candidates   : "
        << isCreature.size()
        << "\n"
        << "isMonster candidates    : "
        << isMonster.size()
        << "\n"
        << "isPlayer candidates     : "
        << isPlayer.size()
        << "\n"
        << "isLocalPlayer candidates: "
        << isLocalPlayer.size()
        << "\n";

    const bool slotsComplete =
        isItem.size() == 1 &&
        isCreature.size() == 1 &&
        isMonster.size() == 1 &&
        isPlayer.size() == 1;

    if (slotsComplete)
    {
        profile.slotIsItem =
            isItem[0];

        profile.slotIsCreature =
            isCreature[0];

        profile.slotIsMonster =
            isMonster[0];

        profile.slotIsPlayer =
            isPlayer[0];

        profile.slotIsLocalPlayer =
            isLocalPlayer.size() == 1
                ? isLocalPlayer[0]
                : 0;

        profile.classificationStatus =
            "confirmed_runtime_four_class_static_bool";
    }
    else
    {
        profile.slotIsItem = 0;
        profile.slotIsCreature = 0;
        profile.slotIsMonster = 0;
        profile.slotIsPlayer = 0;
        profile.slotIsLocalPlayer = 0;

        profile.classificationStatus =
            "confirmed_semantic_vtables_slots_pending";

        std::cout
            << "[INFO] Esta build nao expoe uma matriz constant-bool unica.\n"
            << "[INFO] Item/Player/Monster continuam CONFIRMADOS semanticamente.\n";
    }

    std::cout
        << "\n============================================================\n"
        << "              CLASSIFICATION CORE CONFIRMED\n"
        << "============================================================\n"
        << "Item VTable RVA      : "
        << HexU64(
            profile.itemVtableRva
        )
        << "\n"
        << "Player VTable RVA    : "
        << HexU64(
            profile.playerVtableRva
        )
        << "\n"
        << "Monster VTable RVA   : "
        << HexU64(
            profile.monsterVtableRva
        )
        << "\n"
        << "Thing storage        : "
        << profile.thingStorageMode
        << " stride="
        << profile.thingStorageStride
        << "\n"
        << "Status               : "
        << profile.classificationStatus
        << "\n"
        << "\n"
        << "[FEITO] STAGE 6B confirmou as classes por anchors semanticas.\n"
        << "[PROXIMO] NPC / Inventory / Item / Containers.\n";

    return true;
}

bool EnsureStage6BClassification(
    DbProfile& profile,
    std::vector<DbProfile>& database,
    int profileIndex,
    const std::string& databasePath)
{
    if (
        (
            profile.classificationStatus ==
                "confirmed_runtime_four_class_static_bool" &&
            profile.slotIsItem &&
            profile.slotIsCreature &&
            profile.slotIsMonster &&
            profile.slotIsPlayer
        ) ||
        (
            profile.classificationStatus ==
                "confirmed_semantic_vtables_slots_pending" &&
            profile.itemVtableRva &&
            profile.playerVtableRva &&
            profile.monsterVtableRva
        )
    )
    {
        std::cout
            << "\n[FEITO] STAGE 6B - Classification core ja esta confirmada.\n"
            << "isItem=+"
            << HexU64(
                profile.slotIsItem
            )
            << " isCreature=+"
            << HexU64(
                profile.slotIsCreature
            )
            << " isMonster=+"
            << HexU64(
                profile.slotIsMonster
            )
            << " isPlayer=+"
            << HexU64(
                profile.slotIsPlayer
            )
            << "\n";

        return true;
    }

    profile.itemVtableRva = 0;
    profile.itemVtableStatus =
        "rediscovery_running";

    profile.playerVtableRva = 0;
    profile.playerVtableStatus =
        "rediscovery_running";

    profile.slotIsItem = 0;
    profile.slotIsCreature = 0;
    profile.slotIsMonster = 0;
    profile.slotIsPlayer = 0;
    profile.slotIsLocalPlayer = 0;

    profile.classificationStatus =
        "rediscovery_running";

    bool ok =
        RunStage6BClassification(
            profile
        );

    if (profileIndex >= 0 &&
        profileIndex <
            static_cast<int>(
                database.size()
            ))
    {
        database[
            static_cast<size_t>(
                profileIndex
            )
        ] = profile;

        SaveProfileDatabase(
            databasePath,
            database
        );
    }

    return ok;
}


// ============================================================
// BUILDMIGRATOR V4.6.1 - FINAL DATA COMPLETION
// NPC / INVENTORY / ITEM / CONTAINERS
// Strict read-only.
// ============================================================

bool BMIsGoldenOpenGlBuild(
    const DbProfile& p)
{
    return
        p.timestamp == 0x6AA9FA57ULL &&
        p.sizeOfImage == 0x017BF000ULL &&
        p.textHash == 0x89D3D35243890EA2ULL;
}

bool BMDecodeVtableBool(
    uintptr_t vtable,
    uintptr_t slot,
    bool& value)
{
    value = false;

    if (!vtable ||
        !slot ||
        !IsReadableMonitorRange(
            vtable + slot,
            sizeof(uintptr_t)))
    {
        return false;
    }

    uintptr_t fn =
        ReadPtr(
            vtable +
            slot
        );

    return
        V25DecodeConstantBool(
            fn,
            value
        );
}

bool BMDiscoverNpcFromCurrentWorld(
    DbProfile& profile,
    uintptr_t localPlayer,
    bool verbose)
{
    if (!profile.itemVtableRva ||
        !profile.monsterVtableRva)
    {
        return false;
    }

    auto observations =
        V25CollectWorldThings(
            profile,
            localPlayer
        );

    if (observations.empty())
        return false;

    auto cohorts =
        V25BuildCohorts(
            observations,
            localPlayer
        );

    uintptr_t itemVt =
        g_exeBase +
        profile.itemVtableRva;

    uintptr_t localVt =
        g_exeBase +
        profile.vtableRva;

    uintptr_t playerVt =
        profile.playerVtableRva
            ? g_exeBase +
                profile.playerVtableRva
            : 0;

    uintptr_t monsterVt =
        g_exeBase +
        profile.monsterVtableRva;

    std::vector<const V25ThingCohort*>
        rttiNpc;

    for (const auto& cohort :
         cohorts)
    {
        uintptr_t vt =
            cohort.vtable;

        if (!vt ||
            vt == itemVt ||
            vt == localVt ||
            vt == playerVt ||
            vt == monsterVt)
        {
            continue;
        }

        if (V33RttiLooksLikeControlBlock(
                cohort.rttiName))
        {
            continue;
        }

        if (V33RttiContainsClassToken(
                cohort.rttiName,
                "npc"))
        {
            rttiNpc.push_back(
                &cohort
            );
        }
    }

    if (rttiNpc.size() == 1)
    {
        profile.npcVtableRva =
            rttiNpc[0]->vtableRva;

        profile.slotIsNpc = 0;

        profile.npcStatus =
            "confirmed_semantic_rtti_npc";

        std::cout
            << "\n[FEITO] NPC classification por RTTI\n"
            << "NPC VTable RVA       : "
            << HexU64(
                profile.npcVtableRva
            )
            << "\n"
            << "NPC RTTI             : "
            << rttiNpc[0]->rttiName
            << "\n";

        return true;
    }

    // Older client family fallback: static constant-bool matrix.
    if (!profile.slotIsCreature ||
        !profile.slotIsMonster ||
        !profile.slotIsPlayer ||
        !profile.slotIsItem)
    {
        if (verbose)
        {
            std::cout
                << "\n[NPC] RTTI nao fechou e esta build nao possui "
                << "slots constant-bool suficientes.\n";
        }

        return false;
    }

    struct NpcCandidate
    {
        uintptr_t vtable = 0;
        uintptr_t slot = 0;
        size_t objects = 0;
        int score = 0;
    };

    std::vector<NpcCandidate>
        candidates;

    for (const auto& cohort :
         cohorts)
    {
        uintptr_t vt =
            cohort.vtable;

        if (!vt ||
            vt == itemVt ||
            vt == localVt ||
            vt == playerVt ||
            vt == monsterVt)
        {
            continue;
        }

        bool isItem = false;
        bool isCreature = false;
        bool isMonster = false;
        bool isPlayer = false;

        if (!BMDecodeVtableBool(
                vt,
                profile.slotIsItem,
                isItem) ||
            !BMDecodeVtableBool(
                vt,
                profile.slotIsCreature,
                isCreature) ||
            !BMDecodeVtableBool(
                vt,
                profile.slotIsMonster,
                isMonster) ||
            !BMDecodeVtableBool(
                vt,
                profile.slotIsPlayer,
                isPlayer))
        {
            continue;
        }

        if (isItem ||
            !isCreature ||
            isMonster ||
            isPlayer)
        {
            continue;
        }

        for (uintptr_t slot = 0;
             slot <= 0x100;
             slot += 8)
        {
            if (slot ==
                    profile.slotIsItem ||
                slot ==
                    profile.slotIsCreature ||
                slot ==
                    profile.slotIsMonster ||
                slot ==
                    profile.slotIsPlayer ||
                slot ==
                    profile.slotIsLocalPlayer)
            {
                continue;
            }

            bool npcValue = false;
            bool itemValue = false;
            bool localValue = false;
            bool playerValue = false;
            bool monsterValue = false;

            if (!BMDecodeVtableBool(
                    vt,
                    slot,
                    npcValue) ||
                !BMDecodeVtableBool(
                    itemVt,
                    slot,
                    itemValue) ||
                !BMDecodeVtableBool(
                    localVt,
                    slot,
                    localValue) ||
                !BMDecodeVtableBool(
                    playerVt,
                    slot,
                    playerValue) ||
                !BMDecodeVtableBool(
                    monsterVt,
                    slot,
                    monsterValue))
            {
                continue;
            }

            if (!npcValue ||
                itemValue ||
                localValue ||
                playerValue ||
                monsterValue)
            {
                continue;
            }

            NpcCandidate c{};

            c.vtable =
                vt;

            c.slot =
                slot;

            c.objects =
                cohort.objects;

            c.score =
                1000 +
                static_cast<int>(
                    cohort.objects * 10
                );

            // Golden-reference tiebreak only. It never creates a
            // candidate; it only prefers the already-semantic pattern.
            if (slot == 0x48)
                c.score += 25;

            candidates.push_back(
                c
            );
        }
    }

    if (verbose)
    {
        std::cout
            << "\n============================================================\n"
            << "               NPC STATIC-BOOL DISCOVERY\n"
            << "============================================================\n"
            << "Creature-like residual candidates: "
            << candidates.size()
            << "\n";

        for (size_t i = 0;
             i < candidates.size();
             ++i)
        {
            std::cout
                << "#"
                << i
                << " vtRva="
                << HexU64(
                    candidates[i].vtable -
                    g_exeBase
                )
                << " slot=+"
                << HexU64(
                    candidates[i].slot
                )
                << " objects="
                << candidates[i].objects
                << " score="
                << candidates[i].score
                << "\n";
        }
    }

    if (candidates.empty())
        return false;

    std::sort(
        candidates.begin(),
        candidates.end(),
        [](
            const NpcCandidate& a,
            const NpcCandidate& b)
        {
            return a.score > b.score;
        }
    );

    if (candidates.size() > 1 &&
        candidates[0].score ==
            candidates[1].score)
    {
        return false;
    }

    profile.npcVtableRva =
        candidates[0].vtable -
        g_exeBase;

    profile.slotIsNpc =
        candidates[0].slot;

    profile.npcStatus =
        "confirmed_runtime_residual_creature_static_bool";

    std::cout
        << "\n[FEITO] NPC classification\n"
        << "NPC VTable RVA       : "
        << HexU64(
            profile.npcVtableRva
        )
        << "\n"
        << "isNpc slot           : +"
        << HexU64(
            profile.slotIsNpc
        )
        << "\n";

    return true;
}


bool V36IsRealSemanticItem(
    uintptr_t pointer)
{
    V35MsvcObjectIdentity id{};

    if (!V35DescribeMsvcObject(
            pointer,
            id))
    {
        return false;
    }

    std::string rtti =
        LowerAscii(
            id.rttiName
        );

    if (rtti.find(
            "_ref_count") !=
            std::string::npos ||
        rtti.find(
            "shared_ptr") !=
            std::string::npos)
    {
        return false;
    }

    return
        rtti.find(
            "item") !=
        std::string::npos;
}

struct V36InventoryRecord
{
    uintptr_t object = 0;
    uintptr_t companion = 0;
};

std::vector<V36InventoryRecord>
V36CaptureInventoryRecords(
    uintptr_t localPlayer,
    uintptr_t baseOffset,
    size_t stride)
{
    std::vector<V36InventoryRecord>
        out;

    if (stride != 8 &&
        stride != 16)
    {
        return out;
    }

    for (size_t slot = 1;
         slot <= 10;
         ++slot)
    {
        uintptr_t address =
            localPlayer +
            baseOffset +
            slot *
            stride;

        V36InventoryRecord r{};

        r.object =
            ReadPtr(
                address
            );

        if (stride == 16)
        {
            r.companion =
                ReadPtr(
                    address + 8
                );
        }

        out.push_back(
            r
        );
    }

    return out;
}

size_t V36CountChangedInventoryRecords(
    const std::vector<V36InventoryRecord>& a,
    const std::vector<V36InventoryRecord>& b)
{
    size_t changed = 0;

    size_t n =
        std::min(
            a.size(),
            b.size()
        );

    for (size_t i = 0;
         i < n;
         ++i)
    {
        if (a[i].object !=
                b[i].object ||
            a[i].companion !=
                b[i].companion)
        {
            ++changed;
        }
    }

    return changed;
}


struct BMInventoryCandidate
{
    uintptr_t baseOffset = 0;
    size_t slotStride = sizeof(uintptr_t);
    std::string storageMode = "raw_pointer_array";
    size_t itemHits = 0;
    size_t nullSlots = 0;
    size_t badSlots = 0;
    size_t companionHits = 0;

    // V3.7: inventory windows overlap heavily. The true 10-slot base
    // should normally have non-Item values immediately outside the window.
    bool leadingBoundaryIsItem = false;
    bool trailingBoundaryIsItem = false;
    int boundaryScore = 0;

    int score = 0;
};


bool V37InventoryObjectAt(
    uintptr_t localPlayer,
    uintptr_t baseOffset,
    size_t slotStride,
    long long logicalSlot,
    uintptr_t itemVtable)
{
    if (slotStride != 8 &&
        slotStride != 16)
    {
        return false;
    }

    long long byteDelta =
        logicalSlot *
        static_cast<long long>(
            slotStride
        );

    uintptr_t address =
        logicalSlot >= 0
            ? localPlayer +
                baseOffset +
                static_cast<uintptr_t>(
                    byteDelta
                )
            : localPlayer +
                baseOffset -
                static_cast<uintptr_t>(
                    -byteDelta
                );

    uintptr_t ptr =
        ReadPtr(
            address
        );

    if (!ptr ||
        !IsReadableMonitorRange(
            ptr,
            sizeof(uintptr_t)))
    {
        return false;
    }

    uintptr_t vt =
        ReadPtr(
            ptr
        );

    return
        vt == itemVtable ||
        V36IsRealSemanticItem(
            ptr
        );
}


BMInventoryCandidate BMScoreInventoryBase(
    uintptr_t localPlayer,
    uintptr_t itemVtable,
    uintptr_t baseOffset,
    size_t slotStride)
{
    BMInventoryCandidate out{};

    out.baseOffset =
        baseOffset;

    out.slotStride =
        slotStride;

    out.storageMode =
        slotStride == 16
            ? "shared_ptr_array"
            : "raw_pointer_array";

    if (slotStride != 8 &&
        slotStride != 16)
    {
        out.badSlots = 100;
        return out;
    }

    for (size_t slot = 1;
         slot <= 10;
         ++slot)
    {
        uintptr_t slotAddress =
            localPlayer +
            baseOffset +
            slot *
            slotStride;

        uintptr_t ptr =
            ReadPtr(
                slotAddress
            );

        if (!ptr)
        {
            ++out.nullSlots;
            continue;
        }

        if (!IsReadableMonitorRange(
                ptr,
                sizeof(uintptr_t)))
        {
            ++out.badSlots;
            continue;
        }

        uintptr_t vt =
            ReadPtr(
                ptr
            );

        const bool itemLike =
            vt ==
                itemVtable ||
            V36IsRealSemanticItem(
                ptr);

        if (!itemLike)
        {
            ++out.badSlots;
            continue;
        }

        ++out.itemHits;

        if (slotStride == 16)
        {
            uintptr_t control =
                ReadPtr(
                    slotAddress + 8
                );

            if (LooksLikeSharedPtrControlBlock(
                    control))
            {
                ++out.companionHits;
            }
            else
            {
                ++out.badSlots;
            }
        }
    }

    out.leadingBoundaryIsItem =
        V37InventoryObjectAt(
            localPlayer,
            baseOffset,
            slotStride,
            0,
            itemVtable
        );

    out.trailingBoundaryIsItem =
        V37InventoryObjectAt(
            localPlayer,
            baseOffset,
            slotStride,
            11,
            itemVtable
        );

    // A shifted 10-slot window commonly ties with the real one because
    // nine of the ten entries overlap. Boundaries break that alias.
    out.boundaryScore = 0;

    out.boundaryScore +=
        out.leadingBoundaryIsItem
            ? -550
            : 320;

    out.boundaryScore +=
        out.trailingBoundaryIsItem
            ? -550
            : 320;

    out.score =
        static_cast<int>(
            out.itemHits * 120
        ) -
        static_cast<int>(
            out.badSlots * 220
        ) +
        static_cast<int>(
            out.companionHits * 30
        ) +
        out.boundaryScore;

    return out;
}


bool V39ResolveInventoryByLogicalSlot(
    uintptr_t localPlayer,
    uintptr_t itemVtable,
    const std::vector<BMInventoryCandidate>& input,
    BMInventoryCandidate& winner)
{
    if (input.empty())
        return false;

    std::cout
        << "\n============================================================\n"
        << "       V4.6.1 INVENTORY LOGICAL-SLOT VALIDATION\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "As janelas +offset podem estar deslocadas por exatamente 1 shared_ptr.\n"
        << "Agora o indice LOGICO do slot decide a base.\n\n"
        << "ATENCAO: aqui e SLOT DE EQUIPAMENTO do personagem, NAO slot dentro da backpack aberta.\n"
        << "Slots 1..10 correspondem a ordem interna do inventario.\n"
        << "Referencia visual comum: 1=head, 2=neck, 3=backpack equipada, 4=armor,\n"
        << "5/6=hands, 7=legs, 8=feet, 9=ring, 10=ammo.\n"
        << "Se houver duvida, a V4.6 imprime changedSlots para diagnostico.\n";

    unsigned logicalSlot =
        AskUnsignedRange(
            "Qual slot 1..10 voce vai ALTERAR agora? ",
            1,
            10
        );

    struct Probe
    {
        BMInventoryCandidate candidate;
        std::vector<V36InventoryRecord> before;
        size_t totalChanged = 0;
        bool selectedChanged = false;
        std::vector<size_t> changedIndices;
        int score = 0;
    };

    std::vector<Probe> probes;

    size_t limit =
        std::min<size_t>(
            input.size(),
            12
        );

    for (size_t i = 0;
         i < limit;
         ++i)
    {
        Probe p{};
        p.candidate = input[i];
        p.before =
            V36CaptureInventoryRecords(
                localPlayer,
                p.candidate.baseOffset,
                p.candidate.slotStride
            );
        probes.push_back(
            p
        );
    }

    std::cout
        << "\n[ACTION - INVENTORY SLOT "
        << logicalSlot
        << "]\n"
        << "Mude SOMENTE esse slot: equipe, retire ou troque o item desse slot.\n"
        << "Nao altere os outros slots ate pressionar ENTER.\n";

    WaitEnter(
        "Depois da mudanca desse unico slot, pressione ENTER..."
    );

    for (auto& p :
         probes)
    {
        auto after =
            V36CaptureInventoryRecords(
                localPlayer,
                p.candidate.baseOffset,
                p.candidate.slotStride
            );

        p.totalChanged =
            V36CountChangedInventoryRecords(
                p.before,
                after
            );

        for (size_t changedIndex = 0;
             changedIndex < p.before.size() &&
             changedIndex < after.size();
             ++changedIndex)
        {
            if (
                p.before[changedIndex].object != after[changedIndex].object ||
                p.before[changedIndex].companion != after[changedIndex].companion
            )
            {
                p.changedIndices.push_back(changedIndex + 1);
            }
        }

        size_t index =
            static_cast<size_t>(
                logicalSlot - 1
            );

        if (index < p.before.size() &&
            index < after.size())
        {
            p.selectedChanged =
                p.before[index].object !=
                    after[index].object ||
                p.before[index].companion !=
                    after[index].companion;
        }

        auto rescored =
            BMScoreInventoryBase(
                localPlayer,
                itemVtable,
                p.candidate.baseOffset,
                p.candidate.slotStride
            );

        p.candidate =
            rescored;

        if (p.selectedChanged)
            p.score += 2500;
        else
            p.score -= 2500;

        if (p.totalChanged == 1)
            p.score += 1000;
        else if (p.totalChanged == 2)
            p.score += 200;
        else if (p.totalChanged == 0)
            p.score -= 1200;
        else
            p.score -=
                static_cast<int>(
                    p.totalChanged * 250
                );

        p.score +=
            p.candidate.score;
    }

    std::sort(
        probes.begin(),
        probes.end(),
        [](
            const Probe& a,
            const Probe& b)
        {
            if (a.score != b.score)
                return a.score > b.score;

            if (a.selectedChanged !=
                b.selectedChanged)
            {
                return a.selectedChanged;
            }

            return
                a.candidate.baseOffset <
                b.candidate.baseOffset;
        }
    );

    std::cout
        << "\n[INVENTORY LOGICAL-SLOT CANDIDATES]\n";

    for (size_t i = 0;
         i < probes.size() &&
         i < 10;
         ++i)
    {
        const auto& p =
            probes[i];

        std::cout
            << "#"
            << i
            << " base=+"
            << HexU64(
                p.candidate.baseOffset
            )
            << " stride="
            << p.candidate.slotStride
            << " selectedChanged="
            << (
                p.selectedChanged
                    ? "YES"
                    : "NO"
            )
            << " totalChanged="
            << p.totalChanged
            << " changedSlots=[";

        for (size_t k = 0; k < p.changedIndices.size(); ++k)
        {
            if (k) std::cout << ",";
            std::cout << p.changedIndices[k];
        }

        std::cout
            << "] score="
            << p.score
            << "\n";
    }

    if (probes.empty())
    {
        return false;
    }

    // V4.6: even a structurally unique window must prove that the
    // user-selected logical equipment slot is the entry that changed.
    if (
        probes.size() == 1 &&
        probes[0].selectedChanged &&
        probes[0].totalChanged == 1 &&
        probes[0].changedIndices.size() == 1 &&
        probes[0].changedIndices[0] == logicalSlot &&
        probes[0].candidate.badSlots == 0
    )
    {
        winner =
            probes[0].candidate;

        std::cout
            << "\n[INVENTORY CONFIRMED BY LOGICAL SLOT]\n"
            << "Base offset : +"
            << HexU64(
                winner.baseOffset
            )
            << "\n"
            << "Stride      : "
            << winner.slotStride
            << "\n"
            << "Evidence    : requested logical slot changed and no other slot changed\n";

        return true;
    }

    // V4.6: shifted 10-slot windows can hide the true base outside the
    // highest scoring candidates.  A single physical entry may appear as
    // slot 7 in +0x510, slot 6 in +0x520, slot 5 in +0x530, etc.
    // If the user says the changed equipment slot is 4, all of those
    // observations project to the same base: +0x540.
    std::map<uintptr_t, size_t>
        projectedVotes;

    std::map<uintptr_t, size_t>
        projectedStride;

    for (const auto& p :
         probes)
    {
        if (
            p.totalChanged != 1 ||
            p.changedIndices.size() != 1
        )
        {
            continue;
        }

        const long long observedSlot =
            static_cast<long long>(
                p.changedIndices[0]
            );

        const long long wantedSlot =
            static_cast<long long>(
                logicalSlot
            );

        const long long stride =
            static_cast<long long>(
                p.candidate.slotStride
            );

        const long long projectedSigned =
            static_cast<long long>(
                p.candidate.baseOffset
            ) +
            (
                observedSlot -
                wantedSlot
            ) *
            stride;

        if (
            projectedSigned < 0x280 ||
            projectedSigned > 0xA00
        )
        {
            continue;
        }

        uintptr_t projectedBase =
            static_cast<uintptr_t>(
                projectedSigned
            );

        ++projectedVotes[
            projectedBase
        ];

        projectedStride[
            projectedBase
        ] =
            p.candidate.slotStride;
    }

    if (!projectedVotes.empty())
    {
        std::vector<std::pair<uintptr_t, size_t>>
            rankedProjection(
                projectedVotes.begin(),
                projectedVotes.end()
            );

        std::sort(
            rankedProjection.begin(),
            rankedProjection.end(),
            [](
                const auto& a,
                const auto& b)
            {
                if (a.second != b.second)
                    return a.second > b.second;

                return a.first < b.first;
            }
        );

        std::cout
            << "\n[INVENTORY PROJECTED BASE CANDIDATES]\n";

        for (size_t i = 0;
             i < rankedProjection.size() &&
             i < 8;
             ++i)
        {
            std::cout
                << "#"
                << i
                << " base=+"
                << HexU64(
                    rankedProjection[i].first
                )
                << " votes="
                << rankedProjection[i].second
                << " stride="
                << projectedStride[
                    rankedProjection[i].first
                ]
                << "\n";
        }

        const bool uniqueProjection =
            rankedProjection.size() == 1 ||
            rankedProjection[0].second >
                rankedProjection[1].second;

        if (
            uniqueProjection &&
            rankedProjection[0].second >= 2
        )
        {
            uintptr_t projectedBase =
                rankedProjection[0].first;

            size_t stride =
                projectedStride[
                    projectedBase
                ];

            BMInventoryCandidate projected =
                BMScoreInventoryBase(
                    localPlayer,
                    itemVtable,
                    projectedBase,
                    stride
                );

            if (
                projected.badSlots == 0 &&
                projected.itemHits >= 1
            )
            {
                winner =
                    projected;

                std::cout
                    << "\n[INVENTORY CONFIRMED BY LOGICAL PROJECTION]\n"
                    << "Base offset : +"
                    << HexU64(
                        winner.baseOffset
                    )
                    << "\n"
                    << "Stride      : "
                    << winner.slotStride
                    << "\n"
                    << "Votes       : "
                    << rankedProjection[0].second
                    << "\n"
                    << "Evidence    : same physical change projected to requested logical slot\n";

                return true;
            }
        }
    }

    if (
        !probes[0].selectedChanged ||
        probes[0].totalChanged == 0
    )
    {
        std::cout
            << "[INVENTORY] O slot informado nao correspondeu diretamente ao indice do top candidate.\\n"
            << "[INVENTORY] A V4.1 tentou projetar a base real usando changedSlots.\\n"
            << "[INVENTORY] Nenhum offset foi promovido sem convergencia estrutural.\\n";
        return false;
    }

    if (probes.size() > 1 &&
        probes[0].score ==
            probes[1].score)
    {
        std::cout
            << "[INVENTORY] Logical-slot probe ainda empatou; nenhum offset promovido.\n";
        return false;
    }

    winner =
        probes[0].candidate;

    return true;
}


bool BMDiscoverInventory(
    DbProfile& profile,
    uintptr_t localPlayer)
{
    if (!profile.itemVtableRva)
        return false;

    uintptr_t itemVtable =
        g_exeBase +
        profile.itemVtableRva;

    std::vector<BMInventoryCandidate>
        candidates;

    for (size_t stride :
         {
             static_cast<size_t>(8),
             static_cast<size_t>(16)
         })
    {
        for (uintptr_t off = 0x280;
             off <= 0xA00;
             off += 8)
        {
            auto c =
                BMScoreInventoryBase(
                    localPlayer,
                    itemVtable,
                    off,
                    stride
                );

            const bool companionOk =
                stride == 8 ||
                c.companionHits ==
                    c.itemHits;

            if (c.itemHits >= 2 &&
                c.badSlots == 0 &&
                companionOk)
            {
                candidates.push_back(
                    c
                );
            }
        }
    }

    std::sort(
        candidates.begin(),
        candidates.end(),
        [](
            const BMInventoryCandidate& a,
            const BMInventoryCandidate& b)
        {
            if (a.score !=
                b.score)
            {
                return
                    a.score >
                    b.score;
            }

            if (a.itemHits !=
                b.itemHits)
            {
                return
                    a.itemHits >
                    b.itemHits;
            }

            if (a.slotStride !=
                b.slotStride)
            {
                return
                    a.slotStride >
                    b.slotStride;
            }

            return
                a.baseOffset <
                b.baseOffset;
        }
    );

    if (candidates.empty())
    {
        std::cout
            << "[INVENTORY] Nenhum raw/shared_ptr Item-slot array confirmado.\n";

        return false;
    }

    std::cout
        << "\n[INVENTORY CANDIDATES]\n";

    for (size_t i = 0;
         i < candidates.size() &&
         i < 8;
         ++i)
    {
        const auto& c =
            candidates[i];

        std::cout
            << "#"
            << i
            << " base=+"
            << HexU64(
                c.baseOffset
            )
            << " mode="
            << c.storageMode
            << " stride="
            << c.slotStride
            << " itemHits="
            << c.itemHits
            << " null="
            << c.nullSlots
            << " companion="
            << c.companionHits
            << " leadItem="
            << (
                c.leadingBoundaryIsItem
                    ? "YES"
                    : "NO"
            )
            << " tailItem="
            << (
                c.trailingBoundaryIsItem
                    ? "YES"
                    : "NO"
            )
            << " boundary="
            << c.boundaryScore
            << " score="
            << c.score
            << "\n";
    }

    // V4.6 rule:
    // Structural scores are discovery hints only.  Sliding 10-slot windows
    // can look valid at +0x520/+0x530/+0x540/etc.  A new/unverified build is
    // not allowed to persist Inventory until a user-selected logical
    // equipment slot proves the base.
    const bool alreadyLogicalValidated =
        profile.inventoryBaseOffset != 0 &&
        profile.inventorySlotStride != 0 &&
        (
            profile.inventoryStatus ==
                "confirmed_runtime_logical_slot" ||
            profile.inventoryStatus ==
                "confirmed_runtime_logical_projection"
        );

    if (alreadyLogicalValidated)
    {
        auto check =
            BMScoreInventoryBase(
                localPlayer,
                itemVtable,
                profile.inventoryBaseOffset,
                static_cast<size_t>(
                    profile.inventorySlotStride
                )
            );

        const bool companionOk =
            check.slotStride == 8 ||
            check.companionHits ==
                check.itemHits;

        if (
            check.badSlots == 0 &&
            check.itemHits >= 1 &&
            companionOk
        )
        {
            candidates.clear();
            candidates.push_back(
                check
            );

            std::cout
                << "[INVENTORY FAST CHECK] logical-validated base +"
                << HexU64(
                    profile.inventoryBaseOffset
                )
                << " remains structurally valid.\n";
        }
        else
        {
            std::cout
                << "[INVENTORY DRIFT] previously logical-validated base failed structural check; recalibrating.\n";

            profile.inventoryBaseOffset = 0;
            profile.inventorySlotStride = 0;
            profile.inventoryStorageMode =
                "unknown";
            profile.inventoryStatus =
                "pending_inventory_drift";
        }
    }

    if (!alreadyLogicalValidated ||
        profile.inventoryBaseOffset == 0)
    {
        // Keep the most relevant overlapping family around the strongest
        // storage mode/stride.  Logical projection can infer a base that was
        // not itself the top scoring window.
        std::vector<BMInventoryCandidate>
            logicalCandidates;

        const auto& seed =
            candidates[0];

        for (const auto& c :
             candidates)
        {
            if (
                c.slotStride !=
                    seed.slotStride ||
                c.storageMode !=
                    seed.storageMode
            )
            {
                continue;
            }

            long long distance =
                std::llabs(
                    static_cast<long long>(
                        c.baseOffset
                    ) -
                    static_cast<long long>(
                        seed.baseOffset
                    )
                );

            if (distance > 0x100)
                continue;

            if (
                c.itemHits + 3 <
                    seed.itemHits
            )
            {
                continue;
            }

            logicalCandidates.push_back(
                c
            );

            if (logicalCandidates.size() >= 12)
                break;
        }

        if (logicalCandidates.empty())
        {
            logicalCandidates.push_back(
                seed
            );
        }

        std::cout
            << "[INVENTORY] V4.6 exige validacao de slot logico antes de promover a base.\n";

        BMInventoryCandidate logicalWinner{};

        if (!V39ResolveInventoryByLogicalSlot(
                localPlayer,
                itemVtable,
                logicalCandidates,
                logicalWinner))
        {
            std::cout
                << "[INVENTORY] Slot logico nao convergiu; nenhum offset sera salvo como confirmed.\n";

            profile.inventoryStatus =
                "pending_inventory_logical_validation";

            return false;
        }

        candidates.clear();
        candidates.push_back(
            logicalWinner
        );

        // Distinguish direct logical proof from projected window proof.
        // If the selected base was present as an input candidate and the
        // requested slot changed directly, this is logical_slot; otherwise
        // it was recovered by projection.
        bool exactWindowPresent = false;

        for (const auto& c :
             logicalCandidates)
        {
            if (
                c.baseOffset ==
                    logicalWinner.baseOffset &&
                c.slotStride ==
                    logicalWinner.slotStride
            )
            {
                exactWindowPresent = true;
                break;
            }
        }

        profile.inventoryStatus =
            exactWindowPresent
                ? "confirmed_runtime_logical_slot"
                : "confirmed_runtime_logical_projection";
    }

    const auto& winner =
        candidates[0];

    profile.inventoryBaseOffset =
        winner.baseOffset;

    profile.inventorySlotStride =
        static_cast<uintptr_t>(
            winner.slotStride
        );

    profile.inventoryStorageMode =
        winner.storageMode;

    if (
        profile.inventoryStatus !=
            "confirmed_runtime_logical_slot" &&
        profile.inventoryStatus !=
            "confirmed_runtime_logical_projection"
    )
    {
        profile.inventoryStatus =
            "confirmed_runtime_logical_slot";
    }

    std::cout
        << "\n[INVENTORY CONFIRMED]\n"
        << "Base offset          : +"
        << HexU64(
            profile.inventoryBaseOffset
        )
        << "\n"
        << "Storage mode         : "
        << profile.inventoryStorageMode
        << "\n"
        << "Slot stride          : "
        << profile.inventorySlotStride
        << "\n"
        << "Item hits            : "
        << winner.itemHits
        << "\n";

    return true;
}

bool BMTryReadMsvcString(
    uintptr_t address,
    std::string& out)
{
    out.clear();

    if (!address ||
        !IsReadableMonitorRange(
            address,
            0x20))
    {
        return false;
    }

    uint64_t size = 0;
    uint64_t capacity = 0;

    if (!SafeRead(
            address + 0x10,
            size) ||
        !SafeRead(
            address + 0x18,
            capacity))
    {
        return false;
    }

    if (size == 0 ||
        size > 127 ||
        capacity > 0x10000)
    {
        return false;
    }

    uintptr_t data =
        address;

    if (capacity >= 16)
    {
        data =
            ReadPtr(
                address
            );
    }

    if (!data ||
        !IsReadableMonitorRange(
            data,
            static_cast<size_t>(
                size)))
    {
        return false;
    }

    std::string value;
    value.resize(
        static_cast<size_t>(
            size)
    );

    std::memcpy(
        &value[0],
        reinterpret_cast<const void*>(
            data),
        static_cast<size_t>(
            size)
    );

    size_t printable = 0;

    for (unsigned char ch :
         value)
    {
        if (ch >= 0x20 &&
            ch <= 0x7E)
        {
            ++printable;
        }
    }

    if (printable * 100 <
        value.size() * 85)
    {
        return false;
    }

    out =
        value;

    return true;
}


std::vector<uintptr_t>
V36FindHeapObjectsByExactRtti(
    const std::string& exactRtti,
    size_t maxObjects = 512)
{
    std::vector<uintptr_t>
        out;

    auto vtables =
        FindMsvcVtablesByExactRttiName(
            exactRtti
        );

    if (vtables.empty())
        return out;

    std::unordered_set<uintptr_t>
        wanted(
            vtables.begin(),
            vtables.end()
        );

    auto regions =
        EnumerateTileHeapRegions();

    const size_t chunkSize =
        4 * 1024 * 1024;

    std::vector<uint8_t>
        buffer(
            chunkSize
        );

    for (const auto& region :
         regions)
    {
        uintptr_t cursor =
            region.base;

        uintptr_t end =
            region.base +
            region.size;

        while (cursor < end)
        {
            size_t want =
                static_cast<size_t>(
                    std::min<uintptr_t>(
                        chunkSize,
                        end - cursor
                    )
                );

            size_t got = 0;

            if (!ReadProcessChunk(
                    cursor,
                    buffer.data(),
                    want,
                    got))
            {
                cursor += want;
                continue;
            }

            uintptr_t aligned =
                (cursor + 7) &
                ~static_cast<uintptr_t>(7);

            size_t start =
                static_cast<size_t>(
                    aligned - cursor
                );

            for (size_t off = start;
                 off + sizeof(uintptr_t) <= got;
                 off += 8)
            {
                uintptr_t vt = 0;

                std::memcpy(
                    &vt,
                    buffer.data() + off,
                    sizeof(vt)
                );

                if (wanted.find(vt) ==
                    wanted.end())
                {
                    continue;
                }

                uintptr_t object =
                    cursor + off;

                V35MsvcObjectIdentity id{};

                if (!V35DescribeMsvcObject(
                        object,
                        id))
                {
                    continue;
                }

                if (id.rttiName !=
                    exactRtti)
                {
                    continue;
                }

                out.push_back(
                    object
                );

                if (out.size() >=
                    maxObjects)
                {
                    break;
                }
            }

            if (out.size() >=
                maxObjects)
            {
                break;
            }

            cursor += got;
        }

        if (out.size() >=
            maxObjects)
        {
            break;
        }
    }

    std::sort(
        out.begin(),
        out.end()
    );

    out.erase(
        std::unique(
            out.begin(),
            out.end()
        ),
        out.end()
    );

    return out;
}

struct V36ContainerReferencePath
{
    uintptr_t gameOffset = 0;
    uintptr_t owner = 0;
    uintptr_t innerOffset = 0;
    uintptr_t child = 0;
    uintptr_t childOffset = 0;
    int depth = 0;
};

std::vector<V36ContainerReferencePath>
V36FindGamePathsToContainer(
    uintptr_t game,
    uintptr_t container)
{
    std::vector<V36ContainerReferencePath>
        paths;

    if (!game ||
        !container)
    {
        return paths;
    }

    uintptr_t target =
        V35CompleteObjectPointer(
            container
        );

    auto sameTarget =
        [&](
            uintptr_t p)
        {
            return
                p &&
                V35CompleteObjectPointer(
                    p
                ) ==
                target;
        };

    for (uintptr_t go = 0;
         go <= 0x600;
         go += 8)
    {
        uintptr_t p1 =
            ReadPtr(
                game + go
            );

        if (!p1)
            continue;

        if (sameTarget(
                p1))
        {
            V36ContainerReferencePath path{};
            path.gameOffset = go;
            path.depth = 1;
            paths.push_back(path);
            continue;
        }

        if (!IsReadableMonitorRange(
                p1,
                0x100))
        {
            continue;
        }

        for (uintptr_t a = 0;
             a <= 0x80;
             a += 8)
        {
            uintptr_t p2 =
                ReadPtr(
                    p1 + a
                );

            if (!p2)
                continue;

            if (sameTarget(
                    p2))
            {
                V36ContainerReferencePath path{};
                path.gameOffset = go;
                path.owner = p1;
                path.innerOffset = a;
                path.depth = 2;
                paths.push_back(path);
                continue;
            }

            if (!IsReadableMonitorRange(
                    p2,
                    0x80))
            {
                continue;
            }

            for (uintptr_t b = 0;
                 b <= 0x50;
                 b += 8)
            {
                uintptr_t p3 =
                    ReadPtr(
                        p2 + b
                    );

                if (!sameTarget(
                        p3))
                {
                    continue;
                }

                V36ContainerReferencePath path{};
                path.gameOffset = go;
                path.owner = p1;
                path.innerOffset = a;
                path.child = p2;
                path.childOffset = b;
                path.depth = 3;
                paths.push_back(path);
            }
        }
    }

    return paths;
}

void V36PrintContainerObjectHints(
    uintptr_t object,
    uintptr_t itemVtable)
{
    std::cout
        << "  object="
        << HexPtr(
            object
        )
        << " vtRva="
        << HexU64(
            ReadPtr(object) -
            g_exeBase
        )
        << " rtti=\\\""
        << TryReadMsvcRttiTypeName(
            ReadPtr(object)
        )
        << "\\\"\n";

    std::cout
        << "    strings:";

    bool anyString = false;

    for (uintptr_t off = 0x10;
         off <= 0xA0;
         off += 8)
    {
        std::string value;

        if (BMTryReadMsvcString(
                object + off,
                value))
        {
            anyString = true;

            std::cout
                << " +"
                << HexU64(off)
                << "=\\\""
                << value
                << "\\\"";
        }
    }

    if (!anyString)
        std::cout << " <none>";

    std::cout << "\n";

    struct ItemVectorHint
    {
        uintptr_t offset = 0;
        size_t stride = 0;
        size_t count = 0;
        size_t itemHits = 0;
        size_t companions = 0;
    };

    std::vector<ItemVectorHint>
        hints;

    for (uintptr_t off = 0x10;
         off <= 0xC0;
         off += 8)
    {
        uintptr_t begin =
            ReadPtr(
                object + off
            );

        uintptr_t end =
            ReadPtr(
                object + off + 8
            );

        uintptr_t cap =
            ReadPtr(
                object + off + 16
            );

        if (!begin ||
            end < begin ||
            cap < end ||
            (begin & 7) ||
            (end & 7) ||
            (cap & 7))
        {
            continue;
        }

        uintptr_t used =
            end - begin;

        if (!used ||
            used > 0x4000)
        {
            continue;
        }

        for (size_t stride :
             {
                 static_cast<size_t>(8),
                 static_cast<size_t>(16)
             })
        {
            if (used % stride != 0)
                continue;

            size_t count =
                static_cast<size_t>(
                    used / stride
                );

            if (!count ||
                count > 128)
            {
                continue;
            }

            size_t itemHits = 0;
            size_t companions = 0;
            bool bad = false;

            for (size_t i = 0;
                 i < count;
                 ++i)
            {
                uintptr_t entry =
                    begin +
                    i * stride;

                uintptr_t item =
                    ReadPtr(
                        entry
                    );

                if (!item)
                    continue;

                uintptr_t vt =
                    ReadPtr(
                        item
                    );

                if (
                    vt != itemVtable &&
                    !V36IsRealSemanticItem(
                        item)
                )
                {
                    bad = true;
                    break;
                }

                ++itemHits;

                if (stride == 16)
                {
                    uintptr_t control =
                        ReadPtr(
                            entry + 8
                        );

                    if (LooksLikeSharedPtrControlBlock(
                            control))
                    {
                        ++companions;
                    }
                    else
                    {
                        bad = true;
                        break;
                    }
                }
            }

            if (bad ||
                !itemHits)
            {
                continue;
            }

            ItemVectorHint h{};
            h.offset = off;
            h.stride = stride;
            h.count = count;
            h.itemHits = itemHits;
            h.companions = companions;
            hints.push_back(h);
        }
    }

    if (!hints.empty())
    {
        std::cout
            << "    item-vectors:";

        for (size_t i = 0;
             i < hints.size() &&
             i < 6;
             ++i)
        {
            std::cout
                << " [off=+"
                << HexU64(
                    hints[i].offset
                )
                << " stride="
                << hints[i].stride
                << " count="
                << hints[i].count
                << " items="
                << hints[i].itemHits
                << " companion="
                << hints[i].companions
                << "]";
        }

        std::cout << "\n";
    }
}

bool V37ContainerHasNameToken(
    uintptr_t object,
    const std::string& token)
{
    std::string wanted =
        LowerAscii(
            token
        );

    for (uintptr_t off = 0x10;
         off <= 0xA0;
         off += 8)
    {
        std::string value;

        if (!BMTryReadMsvcString(
                object + off,
                value))
        {
            continue;
        }

        if (LowerAscii(
                value).find(
                    wanted) !=
            std::string::npos)
        {
            return true;
        }
    }

    return false;
}

std::set<uintptr_t>
V37CollectContainerOwnerOffsets(
    uintptr_t game,
    const std::vector<uintptr_t>& closed,
    const std::vector<uintptr_t>& opened,
    uintptr_t itemVtable,
    const char* label)
{
    std::unordered_set<uintptr_t>
        closedSet(
            closed.begin(),
            closed.end()
        );

    std::vector<uintptr_t>
        newObjects;

    for (uintptr_t object :
         opened)
    {
        if (closedSet.find(
                object) ==
            closedSet.end())
        {
            newObjects.push_back(
                object
            );
        }
    }

    const auto& baseInspect =
        newObjects.empty()
            ? opened
            : newObjects;

    std::vector<uintptr_t>
        named;

    for (uintptr_t object :
         baseInspect)
    {
        if (V37ContainerHasNameToken(
                object,
                "backpack"))
        {
            named.push_back(
                object
            );
        }
    }

    const auto& inspect =
        named.empty()
            ? baseInspect
            : named;

    std::set<uintptr_t>
        offsets;

    std::cout
        << "\n[CONTAINER CYCLE "
        << label
        << "] closed="
        << closed.size()
        << " opened="
        << opened.size()
        << " new="
        << newObjects.size()
        << " inspect="
        << inspect.size()
        << "\n";

    size_t shown = 0;

    for (uintptr_t object :
         inspect)
    {
        if (shown < 8)
        {
            V36PrintContainerObjectHints(
                object,
                itemVtable
            );
        }

        auto paths =
            V36FindGamePathsToContainer(
                game,
                object
            );

        std::set<uintptr_t>
            objectOffsets;

        for (const auto& path :
             paths)
        {
            objectOffsets.insert(
                path.gameOffset
            );
        }

        std::cout
            << "    canonical Game offsets:";

        if (objectOffsets.empty())
        {
            std::cout
                << " <none>";
        }
        else
        {
            for (uintptr_t off :
                 objectOffsets)
            {
                std::cout
                    << " +"
                    << HexU64(
                        off
                    );

                offsets.insert(
                    off
                );
            }
        }

        std::cout
            << "\n";

        ++shown;
    }

    return offsets;
}


struct V39ContainerOwnerState
{
    uintptr_t gameOffset = 0;
    uintptr_t ownerPointer = 0;
    size_t linkedContainers = 0;
    size_t namedContainers = 0;
    std::vector<uint8_t> ownerBytes;
};

V39ContainerOwnerState
V39CaptureContainerOwnerState(
    uintptr_t game,
    uintptr_t gameOffset)
{
    V39ContainerOwnerState out{};
    out.gameOffset = gameOffset;
    out.ownerPointer =
        ReadPtr(
            game + gameOffset
        );

    if (out.ownerPointer &&
        IsReadableMonitorRange(
            out.ownerPointer,
            0x100))
    {
        out.ownerBytes.resize(
            0x100
        );

        std::memcpy(
            out.ownerBytes.data(),
            reinterpret_cast<const void*>(
                out.ownerPointer),
            out.ownerBytes.size()
        );
    }

    auto objects =
        V36FindHeapObjectsByExactRtti(
            ".?AVContainer@@"
        );

    for (uintptr_t object :
         objects)
    {
        auto paths =
            V36FindGamePathsToContainer(
                game,
                object
            );

        bool linked = false;

        for (const auto& p :
             paths)
        {
            if (p.gameOffset ==
                gameOffset)
            {
                linked = true;
                break;
            }
        }

        if (!linked)
            continue;

        ++out.linkedContainers;

        if (V37ContainerHasNameToken(
                object,
                "backpack") ||
            V37ContainerHasNameToken(
                object,
                "bag"))
        {
            ++out.namedContainers;
        }
    }

    return out;
}

size_t V39CountMonotonicOwnerCounters(
    const V39ContainerOwnerState& zero,
    const V39ContainerOwnerState& one,
    const V39ContainerOwnerState& two)
{
    if (zero.ownerBytes.size() < 0x100 ||
        one.ownerBytes.size() < 0x100 ||
        two.ownerBytes.size() < 0x100)
    {
        return 0;
    }

    size_t hits = 0;

    for (size_t off = 0;
         off + sizeof(uint64_t) <= 0x100;
         off += 8)
    {
        uint64_t a = 0;
        uint64_t b = 0;
        uint64_t c = 0;

        std::memcpy(
            &a,
            zero.ownerBytes.data() + off,
            sizeof(a)
        );
        std::memcpy(
            &b,
            one.ownerBytes.data() + off,
            sizeof(b)
        );
        std::memcpy(
            &c,
            two.ownerBytes.data() + off,
            sizeof(c)
        );

        if (a <= 64 &&
            b <= 64 &&
            c <= 64 &&
            b == a + 1 &&
            c == b + 1)
        {
            ++hits;
        }
    }

    for (size_t off = 0;
         off + sizeof(uint32_t) <= 0x100;
         off += 4)
    {
        uint32_t a = 0;
        uint32_t b = 0;
        uint32_t c = 0;

        std::memcpy(
            &a,
            zero.ownerBytes.data() + off,
            sizeof(a)
        );
        std::memcpy(
            &b,
            one.ownerBytes.data() + off,
            sizeof(b)
        );
        std::memcpy(
            &c,
            two.ownerBytes.data() + off,
            sizeof(c)
        );

        if (a <= 64 &&
            b <= 64 &&
            c <= 64 &&
            b == a + 1 &&
            c == b + 1)
        {
            ++hits;
        }
    }

    return hits;
}

bool V39DisambiguateContainerOwnerByCollection(
    DbProfile& profile,
    const std::vector<uintptr_t>& candidates)
{
    if (candidates.size() < 2 ||
        !profile.gameRva)
    {
        return false;
    }

    uintptr_t game =
        g_exeBase +
        profile.gameRva;

    std::cout
        << "\n============================================================\n"
        << "       V3.9 CONTAINER OWNER COLLECTION PROVENANCE\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "Dois Game offsets chegam na mesma Backpack.\n"
        << "Agora vamos observar a COLECAO em 0 -> 1 -> 2 containers abertos.\n";

    std::cout
        << "\n[ACTION C0]\nFeche TODOS os containers.\n";
    WaitEnter(
        "Com todos fechados, pressione ENTER..."
    );

    std::vector<V39ContainerOwnerState>
        zero;

    for (uintptr_t off :
         candidates)
    {
        zero.push_back(
            V39CaptureContainerOwnerState(
                game,
                off
            )
        );
    }

    std::cout
        << "\n[ACTION C1]\nAbra SOMENTE a Backpack principal.\n";
    WaitEnter(
        "Com somente 1 container aberto, pressione ENTER..."
    );

    std::vector<V39ContainerOwnerState>
        one;

    for (uintptr_t off :
         candidates)
    {
        one.push_back(
            V39CaptureContainerOwnerState(
                game,
                off
            )
        );
    }

    std::cout
        << "\n[ACTION C2]\nMantenha a Backpack aberta e abra UMA SEGUNDA bag/container.\n";
    WaitEnter(
        "Com exatamente 2 containers abertos, pressione ENTER..."
    );

    std::vector<V39ContainerOwnerState>
        two;

    for (uintptr_t off :
         candidates)
    {
        two.push_back(
            V39CaptureContainerOwnerState(
                game,
                off
            )
        );
    }

    struct Ranked
    {
        uintptr_t offset = 0;
        size_t linked0 = 0;
        size_t linked1 = 0;
        size_t linked2 = 0;
        size_t counterHits = 0;
        int score = 0;
    };

    std::vector<Ranked>
        ranked;

    for (size_t i = 0;
         i < candidates.size();
         ++i)
    {
        Ranked r{};
        r.offset = candidates[i];
        r.linked0 = zero[i].linkedContainers;
        r.linked1 = one[i].linkedContainers;
        r.linked2 = two[i].linkedContainers;
        r.counterHits =
            V39CountMonotonicOwnerCounters(
                zero[i],
                one[i],
                two[i]
            );

        if (r.linked1 > r.linked0)
            r.score += 900;

        if (r.linked2 > r.linked1)
            r.score += 900;

        if (r.linked0 == 0)
            r.score += 250;

        r.score +=
            static_cast<int>(
                r.counterHits * 1400
            );

        if (zero[i].ownerPointer &&
            zero[i].ownerPointer ==
                one[i].ownerPointer &&
            one[i].ownerPointer ==
                two[i].ownerPointer)
        {
            r.score += 150;
        }

        ranked.push_back(
            r
        );
    }

    std::sort(
        ranked.begin(),
        ranked.end(),
        [](
            const Ranked& a,
            const Ranked& b)
        {
            if (a.score != b.score)
                return a.score > b.score;

            if (a.counterHits !=
                b.counterHits)
            {
                return
                    a.counterHits >
                    b.counterHits;
            }

            return
                a.offset <
                b.offset;
        }
    );

    std::cout
        << "\n[CONTAINER OWNER COLLECTION CANDIDATES]\n";

    for (size_t i = 0;
         i < ranked.size();
         ++i)
    {
        std::cout
            << "#"
            << i
            << " Game[+"
            << HexU64(
                ranked[i].offset
            )
            << "] linked="
            << ranked[i].linked0
            << "->"
            << ranked[i].linked1
            << "->"
            << ranked[i].linked2
            << " counters="
            << ranked[i].counterHits
            << " score="
            << ranked[i].score
            << "\n";
    }

    if (ranked.empty() ||
        ranked[0].score <= 0)
    {
        return false;
    }

    if (ranked.size() > 1)
    {
        const int gap =
            ranked[0].score -
            ranked[1].score;

        if (gap < 700)
        {
            std::cout
                << "[CONTAINER] Collection provenance ainda nao separou os aliases.\n";
            return false;
        }
    }

    profile.gameContainersOffset =
        ranked[0].offset;

    profile.containersStatus =
        "confirmed_runtime_container_owner_collection_provenance_layout_pending";

    std::cout
        << "\n[CONTAINER OWNER CONFIRMED BY COLLECTION]\n"
        << "Game.Containers owner: +"
        << HexU64(
            profile.gameContainersOffset
        )
        << "\n";

    return true;
}


bool V36ContainerTransitionRecon(
    DbProfile& profile)
{
    if (!profile.gameRva ||
        !profile.itemVtableRva)
    {
        return false;
    }

    uintptr_t game =
        g_exeBase +
        profile.gameRva;

    uintptr_t itemVtable =
        g_exeBase +
        profile.itemVtableRva;

    std::cout
        << "\n============================================================\n"
        << "        V3.9 CONTAINER TWO-CYCLE RTTI CONFIRMATION\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "Vamos confirmar o mesmo owner de Containers em DUAS aberturas.\n"
        << "As duas aliases internas (+0/+8, por exemplo) contam como UM owner\n"
        << "quando terminam no mesmo Game[+offset].\n";

    std::cout
        << "\n[ACTION 1/4]\n"
        << "Feche TODOS os containers no cliente.\n";
    WaitEnter(
        "Quando estiver tudo fechado, pressione ENTER..."
    );

    auto closedA =
        V36FindHeapObjectsByExactRtti(
            ".?AVContainer@@"
        );

    std::cout
        << "\n[ACTION 2/4]\n"
        << "Abra SOMENTE a Backpack principal.\n";
    WaitEnter(
        "Quando a Backpack estiver aberta, pressione ENTER..."
    );

    auto openedA =
        V36FindHeapObjectsByExactRtti(
            ".?AVContainer@@"
        );

    auto offsetsA =
        V37CollectContainerOwnerOffsets(
            game,
            closedA,
            openedA,
            itemVtable,
            "A"
        );

    if (offsetsA.empty())
    {
        std::cout
            << "[CONTAINER] Ciclo A nao encontrou owner ligado ao Game.\n";

        profile.containersStatus =
            "pending_container_cycle_a_no_owner";

        return false;
    }

    std::cout
        << "\n[ACTION 3/4]\n"
        << "Feche novamente TODOS os containers.\n";
    WaitEnter(
        "Quando estiver tudo fechado, pressione ENTER..."
    );

    auto closedB =
        V36FindHeapObjectsByExactRtti(
            ".?AVContainer@@"
        );

    std::cout
        << "\n[ACTION 4/4]\n"
        << "Abra novamente SOMENTE a mesma Backpack principal.\n";
    WaitEnter(
        "Quando a Backpack estiver aberta, pressione ENTER..."
    );

    auto openedB =
        V36FindHeapObjectsByExactRtti(
            ".?AVContainer@@"
        );

    auto offsetsB =
        V37CollectContainerOwnerOffsets(
            game,
            closedB,
            openedB,
            itemVtable,
            "B"
        );

    std::vector<uintptr_t>
        common;

    for (uintptr_t off :
         offsetsA)
    {
        if (offsetsB.find(
                off) !=
            offsetsB.end())
        {
            common.push_back(
                off
            );
        }
    }

    std::cout
        << "\n[CONTAINER OWNER INTERSECTION]\n"
        << "Cycle A candidates : "
        << offsetsA.size()
        << "\n"
        << "Cycle B candidates : "
        << offsetsB.size()
        << "\n"
        << "Common offsets     : "
        << common.size()
        << "\n";

    for (size_t i = 0;
         i < common.size();
         ++i)
    {
        std::cout
            << "  #"
            << i
            << " Game[+"
            << HexU64(
                common[i]
            )
            << "]\n";
    }

    if (common.empty())
    {
        profile.containersStatus =
            "pending_container_owner_no_common_offset";

        return false;
    }

    if (common.size() > 1)
    {
        profile.containersStatus =
            "pending_container_owner_multiple_common_offsets";

        if (!V39DisambiguateContainerOwnerByCollection(
                profile,
                common))
        {
            return false;
        }

        return true;
    }

    profile.gameContainersOffset =
        common[0];

    // Owner is confirmed. Container internal deque/layout still has its own
    // validation stage, so consumer-ready must not treat this as full layout.
    profile.containersStatus =
        "confirmed_runtime_container_owner_two_open_cycles_layout_pending";

    std::cout
        << "\n[CONTAINER OWNER CONFIRMED]\n"
        << "Game.Containers owner: +"
        << HexU64(
            profile.gameContainersOffset
        )
        << "\n"
        << "Evidence             : same Game offset in 2 close/open cycles\n"
        << "Status               : "
        << profile.containersStatus
        << "\n";

    return true;
}


struct BMContainerMapCandidate
{
    uintptr_t gameOffset = 0;
    uintptr_t mapAddress = 0;
    uintptr_t header = 0;
    uintptr_t root = 0;
    size_t reportedSize = 0;
    size_t visitedNodes = 0;
    size_t validContainers = 0;
    size_t validItems = 0;
    int score = 0;
};

bool BMValidateContainerMapCandidate(
    uintptr_t game,
    uintptr_t gameOffset,
    uintptr_t itemVtable,
    BMContainerMapCandidate& out,
    bool verbose)
{
    out = {};

    uintptr_t map =
        game +
        gameOffset;

    if (!IsReadableMonitorRange(
            map,
            0x10))
    {
        return false;
    }

    uintptr_t header =
        ReadPtr(
            map
        );

    uint64_t reportedSize = 0;

    if (!SafeRead(
            map + 0x08,
            reportedSize))
    {
        return false;
    }

    if (!header ||
        reportedSize == 0 ||
        reportedSize > 32 ||
        !IsReadableMonitorRange(
            header,
            0x30))
    {
        return false;
    }

    uintptr_t root =
        ReadPtr(
            header +
            0x08
        );

    if (!root ||
        root == header ||
        !IsReadableMonitorRange(
            root,
            0x30))
    {
        return false;
    }

    std::vector<uintptr_t>
        stack;

    std::unordered_set<uintptr_t>
        visited;

    stack.push_back(
        root
    );

    size_t validContainers = 0;
    size_t validItems = 0;

    while (!stack.empty() &&
           visited.size() < 128)
    {
        uintptr_t node =
            stack.back();

        stack.pop_back();

        if (!node ||
            node == header ||
            !IsReadableMonitorRange(
                node,
                0x30))
        {
            continue;
        }

        if (!visited.insert(
                node).second)
        {
            continue;
        }

        uint8_t nil =
            ReadU8(
                node +
                0x19
            );

        if (nil != 0)
            continue;

        uintptr_t left =
            ReadPtr(
                node +
                0x00
            );

        uintptr_t right =
            ReadPtr(
                node +
                0x10
            );

        if (left &&
            left != header)
        {
            stack.push_back(
                left
            );
        }

        if (right &&
            right != header)
        {
            stack.push_back(
                right
            );
        }

        uint32_t key =
            ReadU32(
                node +
                0x20
            );

        uintptr_t container =
            ReadPtr(
                node +
                0x28
            );

        if (!container ||
            !IsReadableMonitorRange(
                container,
                0x80))
        {
            continue;
        }

        uint32_t id =
            ReadU32(
                container +
                0x18
            );

        uint32_t capacity =
            ReadU32(
                container +
                0x1C
            );

        uint32_t itemCount =
            ReadU32(
                container +
                0x78
            );

        std::string name;

        bool nameOk =
            BMTryReadMsvcString(
                container +
                0x28,
                name
            );

        if (id != key ||
            capacity == 0 ||
            capacity > 200 ||
            itemCount > 1000 ||
            !nameOk)
        {
            continue;
        }

        ++validContainers;

        uintptr_t dequeMap =
            ReadPtr(
                container +
                0x60
            );

        uint64_t dequeMapSize = 0;
        uint64_t dequeOffset = 0;

        SafeRead(
            container +
                0x68,
            dequeMapSize
        );

        SafeRead(
            container +
                0x70,
            dequeOffset
        );

        if (itemCount &&
            dequeMap &&
            dequeMapSize &&
            (dequeMapSize &
             (dequeMapSize - 1)) == 0 &&
            dequeMapSize <= 0x10000)
        {
            size_t limit =
                std::min<size_t>(
                    itemCount,
                    64
                );

            for (size_t i = 0;
                 i < limit;
                 ++i)
            {
                uint64_t logical =
                    dequeOffset +
                    i;

                uint64_t block =
                    (logical >> 1) &
                    (dequeMapSize - 1);

                uint64_t cell =
                    logical &
                    1ULL;

                uintptr_t blockPtr =
                    ReadPtr(
                        dequeMap +
                        block *
                        sizeof(uintptr_t)
                    );

                if (!blockPtr ||
                    !IsReadableMonitorRange(
                        blockPtr,
                        2 *
                        sizeof(uintptr_t)))
                {
                    continue;
                }

                uintptr_t item =
                    ReadPtr(
                        blockPtr +
                        cell *
                        sizeof(uintptr_t)
                    );

                if (!item ||
                    !IsReadableMonitorRange(
                        item,
                        0x40))
                {
                    continue;
                }

                uintptr_t itemVt =
                    ReadPtr(
                        item
                    );

                if (
                    itemVt ==
                        itemVtable ||
                    V36IsRealSemanticItem(
                        item)
                )
                {
                    ++validItems;
                }
            }
        }

        if (verbose)
        {
            std::cout
                << "  Container key="
                << key
                << " name=\""
                << name
                << "\" cap="
                << capacity
                << " items="
                << itemCount
                << "\n";
        }
    }

    if (!validContainers)
        return false;

    out.gameOffset =
        gameOffset;

    out.mapAddress =
        map;

    out.header =
        header;

    out.root =
        root;

    out.reportedSize =
        static_cast<size_t>(
            reportedSize
        );

    out.visitedNodes =
        visited.size();

    out.validContainers =
        validContainers;

    out.validItems =
        validItems;

    out.score =
        1000 +
        static_cast<int>(
            validContainers * 100
        ) +
        static_cast<int>(
            validItems * 10
        );

    if (gameOffset == 0x20)
        out.score += 10;

    return true;
}


struct V38DequeCandidate
{
    uintptr_t mapOffset = 0;
    uintptr_t mapSizeOffset = 0;
    uintptr_t dequeOffsetOffset = 0;
    uintptr_t countOffset = 0;

    size_t elementStride = 0;
    size_t blockElements = 0;
    std::string mode;

    size_t count = 0;
    size_t validItems = 0;
    size_t validCompanions = 0;
    int score = 0;
};

bool V38IsExactContainerObject(
    uintptr_t object)
{
    if (!object ||
        !IsReadableMonitorRange(
            object,
            sizeof(uintptr_t)))
    {
        return false;
    }

    uintptr_t vt =
        ReadPtr(
            object
        );

    if (!InsideExeImage(
            vt))
    {
        return false;
    }

    std::string rtti =
        TryReadMsvcRttiTypeName(
            vt
        );

    return
        LowerAscii(
            rtti
        ).find(
            "container") !=
            std::string::npos &&
        LowerAscii(
            rtti
        ).find(
            "_ref_count") ==
            std::string::npos;
}

std::vector<uintptr_t>
V38FindContainersLinkedToConfirmedOwner(
    const DbProfile& profile)
{
    std::vector<uintptr_t>
        out;

    if (!profile.gameRva ||
        !profile.gameContainersOffset)
    {
        return out;
    }

    uintptr_t game =
        g_exeBase +
        profile.gameRva;

    auto objects =
        V36FindHeapObjectsByExactRtti(
            ".?AVContainer@@"
        );

    for (uintptr_t object :
         objects)
    {
        auto paths =
            V36FindGamePathsToContainer(
                game,
                object
            );

        bool linked = false;

        for (const auto& p :
             paths)
        {
            if (p.gameOffset ==
                profile.gameContainersOffset)
            {
                linked = true;
                break;
            }
        }

        if (linked)
        {
            out.push_back(
                object
            );
        }
    }

    std::sort(
        out.begin(),
        out.end()
    );

    out.erase(
        std::unique(
            out.begin(),
            out.end()
        ),
        out.end()
    );

    return out;
}

bool V38InferContainerTreeLayout(
    DbProfile& profile,
    const std::vector<uintptr_t>& containers)
{
    if (containers.empty() ||
        !profile.gameRva ||
        !profile.gameContainersOffset)
    {
        return false;
    }

    uintptr_t game =
        g_exeBase +
        profile.gameRva;

    std::set<uintptr_t>
        innerOffsets;

    std::set<uintptr_t>
        valueOffsets;

    for (uintptr_t object :
         containers)
    {
        auto paths =
            V36FindGamePathsToContainer(
                game,
                object
            );

        for (const auto& p :
             paths)
        {
            if (p.gameOffset !=
                    profile.gameContainersOffset ||
                p.depth != 3)
            {
                continue;
            }

            innerOffsets.insert(
                p.innerOffset
            );

            valueOffsets.insert(
                p.childOffset
            );
        }
    }

    if (valueOffsets.size() != 1 ||
        innerOffsets.empty())
    {
        return false;
    }

    profile.containerMapHeaderOffset =
        0x00;

    profile.containerMapSizeOffset =
        0x08;

    profile.containerNodeLeftOffset =
        *innerOffsets.begin();

    profile.containerNodeRightOffset =
        innerOffsets.size() >= 2
            ? *innerOffsets.rbegin()
            : *innerOffsets.begin();

    profile.containerNodeValueOffset =
        *valueOffsets.begin();

    // Find a common std::string field on named Container objects.
    std::map<uintptr_t, size_t>
        nameVotes;

    for (uintptr_t object :
         containers)
    {
        for (uintptr_t off = 0x10;
             off <= 0xA0;
             off += 8)
        {
            std::string value;

            if (!BMTryReadMsvcString(
                    object + off,
                    value))
            {
                continue;
            }

            if (!value.empty())
            {
                ++nameVotes[
                    off
                ];
            }
        }
    }

    if (!nameVotes.empty())
    {
        auto best =
            std::max_element(
                nameVotes.begin(),
                nameVotes.end(),
                [](
                    const auto& a,
                    const auto& b)
                {
                    return
                        a.second <
                        b.second;
                }
            );

        profile.containerNameOffset =
            best->first;
    }

    std::cout
        << "\n[CONTAINER TREE LAYOUT]\n"
        << "Game owner      : +"
        << HexU64(
            profile.gameContainersOffset
        )
        << "\n"
        << "Header field    : +"
        << HexU64(
            profile.containerMapHeaderOffset
        )
        << "\n"
        << "Size field      : +"
        << HexU64(
            profile.containerMapSizeOffset
        )
        << "\n"
        << "Node links      : +"
        << HexU64(
            profile.containerNodeLeftOffset
        )
        << " / +"
        << HexU64(
            profile.containerNodeRightOffset
        )
        << "\n"
        << "Node value      : +"
        << HexU64(
            profile.containerNodeValueOffset
        )
        << "\n"
        << "Container name  : +"
        << HexU64(
            profile.containerNameOffset
        )
        << "\n";

    return true;
}

V38DequeCandidate
V38ScoreContainerDeque(
    uintptr_t container,
    uintptr_t itemVtable,
    uintptr_t mapOffset,
    size_t elementStride,
    size_t blockElements,
    const std::string& mode)
{
    V38DequeCandidate out{};

    out.mapOffset =
        mapOffset;

    out.mapSizeOffset =
        mapOffset + 0x08;

    out.dequeOffsetOffset =
        mapOffset + 0x10;

    out.countOffset =
        mapOffset + 0x18;

    out.elementStride =
        elementStride;

    out.blockElements =
        blockElements;

    out.mode =
        mode;

    uintptr_t dequeMap =
        ReadPtr(
            container +
            out.mapOffset
        );

    uint64_t dequeMapSize = 0;
    uint64_t dequeOffset = 0;
    uint32_t itemCount = 0;

    SafeRead(
        container +
            out.mapSizeOffset,
        dequeMapSize
    );

    SafeRead(
        container +
            out.dequeOffsetOffset,
        dequeOffset
    );

    SafeRead(
        container +
            out.countOffset,
        itemCount
    );

    if (!dequeMap ||
        dequeMapSize == 0 ||
        (dequeMapSize &
         (dequeMapSize - 1)) != 0 ||
        dequeMapSize > 0x10000 ||
        itemCount == 0 ||
        itemCount > 200 ||
        !IsReadableMonitorRange(
            dequeMap,
            static_cast<size_t>(
                std::min<uint64_t>(
                    dequeMapSize,
                    64
                )
            ) *
            sizeof(uintptr_t)))
    {
        return out;
    }

    out.count =
        itemCount;

    for (size_t i = 0;
         i < itemCount;
         ++i)
    {
        uint64_t logical =
            dequeOffset +
            i;

        uint64_t block =
            (
                logical /
                blockElements
            ) &
            (
                dequeMapSize -
                1
            );

        uint64_t cell =
            logical %
            blockElements;

        uintptr_t blockPtr =
            ReadPtr(
                dequeMap +
                block *
                sizeof(uintptr_t)
            );

        if (!blockPtr ||
            !IsReadableMonitorRange(
                blockPtr,
                blockElements *
                    elementStride))
        {
            continue;
        }

        uintptr_t entry =
            blockPtr +
            cell *
            elementStride;

        uintptr_t item =
            ReadPtr(
                entry
            );

        if (!item ||
            !IsReadableMonitorRange(
                item,
                sizeof(uintptr_t)))
        {
            continue;
        }

        uintptr_t vt =
            ReadPtr(
                item
            );

        if (
            vt != itemVtable &&
            !V36IsRealSemanticItem(
                item)
        )
        {
            continue;
        }

        ++out.validItems;

        if (mode ==
                "deque_shared_ptr_item")
        {
            uintptr_t control =
                ReadPtr(
                    entry + 8
                );

            if (LooksLikeSharedPtrControlBlock(
                    control))
            {
                ++out.validCompanions;
            }
        }
    }

    if (!out.validItems ||
        out.validItems * 100 <
            out.count * 80)
    {
        out.score = 0;
        return out;
    }

    out.score =
        static_cast<int>(
            out.validItems *
            200
        );

    if (out.validItems ==
        out.count)
    {
        out.score += 500;
    }

    if (mode ==
            "deque_shared_ptr_item")
    {
        if (out.validCompanions !=
            out.validItems)
        {
            out.score = 0;
            return out;
        }

        out.score +=
            static_cast<int>(
                out.validCompanions *
                40
            );
    }

    return out;
}

bool V38DiscoverContainerDequeLayout(
    DbProfile& profile,
    const std::vector<uintptr_t>& containers)
{
    if (containers.empty() ||
        !profile.itemVtableRva)
    {
        return false;
    }

    uintptr_t itemVtable =
        g_exeBase +
        profile.itemVtableRva;

    std::vector<V38DequeCandidate>
        candidates;

    for (uintptr_t container :
         containers)
    {
        for (uintptr_t off = 0x10;
             off <= 0xC0;
             off += 8)
        {
            auto raw =
                V38ScoreContainerDeque(
                    container,
                    itemVtable,
                    off,
                    8,
                    2,
                    "deque_raw_item_ptr"
                );

            if (raw.score)
            {
                candidates.push_back(
                    raw
                );
            }

            auto shared =
                V38ScoreContainerDeque(
                    container,
                    itemVtable,
                    off,
                    16,
                    1,
                    "deque_shared_ptr_item"
                );

            if (shared.score)
            {
                candidates.push_back(
                    shared
                );
            }
        }
    }

    if (candidates.empty())
        return false;

    std::sort(
        candidates.begin(),
        candidates.end(),
        [](
            const V38DequeCandidate& a,
            const V38DequeCandidate& b)
        {
            if (a.score !=
                b.score)
            {
                return
                    a.score >
                    b.score;
            }

            if (a.validItems !=
                b.validItems)
            {
                return
                    a.validItems >
                    b.validItems;
            }

            return
                a.mapOffset <
                b.mapOffset;
        }
    );

    std::cout
        << "\n[CONTAINER DEQUE CANDIDATES]\n";

    for (size_t i = 0;
         i < candidates.size() &&
         i < 10;
         ++i)
    {
        const auto& c =
            candidates[i];

        std::cout
            << "#"
            << i
            << " map=+"
            << HexU64(
                c.mapOffset
            )
            << " mode="
            << c.mode
            << " count="
            << c.count
            << " items="
            << c.validItems
            << " companion="
            << c.validCompanions
            << " score="
            << c.score
            << "\n";
    }

    if (candidates.size() > 1)
    {
        const auto& a =
            candidates[0];

        const auto& b =
            candidates[1];

        if (a.score ==
                b.score &&
            a.mapOffset !=
                b.mapOffset)
        {
            return false;
        }
    }

    const auto& winner =
        candidates[0];

    profile.containerDequeMapOffset =
        winner.mapOffset;

    profile.containerDequeMapSizeOffset =
        winner.mapSizeOffset;

    profile.containerDequeOffsetOffset =
        winner.dequeOffsetOffset;

    profile.containerItemCountOffset =
        winner.countOffset;

    profile.containerItemElementStride =
        winner.elementStride;

    profile.containerItemStorageMode =
        winner.mode;

    profile.containersStatus =
        "confirmed_runtime_container_owner_and_layout";

    std::cout
        << "\n[CONTAINER ITEM STORAGE CONFIRMED]\n"
        << "Deque map       : +"
        << HexU64(
            profile.containerDequeMapOffset
        )
        << "\n"
        << "Map size        : +"
        << HexU64(
            profile.containerDequeMapSizeOffset
        )
        << "\n"
        << "Deque offset    : +"
        << HexU64(
            profile.containerDequeOffsetOffset
        )
        << "\n"
        << "Item count      : +"
        << HexU64(
            profile.containerItemCountOffset
        )
        << "\n"
        << "Storage mode    : "
        << profile.containerItemStorageMode
        << "\n"
        << "Element stride  : "
        << profile.containerItemElementStride
        << "\n";

    return true;
}

std::vector<uintptr_t>
V38CollectContainerItems(
    const DbProfile& profile,
    const std::vector<uintptr_t>& containers)
{
    std::vector<uintptr_t>
        out;

    if (!profile.itemVtableRva ||
        !profile.containerDequeMapOffset ||
        !profile.containerDequeMapSizeOffset ||
        !profile.containerDequeOffsetOffset ||
        !profile.containerItemCountOffset)
    {
        return out;
    }

    uintptr_t itemVtable =
        g_exeBase +
        profile.itemVtableRva;

    const bool shared =
        profile.containerItemStorageMode ==
            "deque_shared_ptr_item";

    const size_t elementStride =
        shared
            ? 16
            : 8;

    const size_t blockElements =
        shared
            ? 1
            : 2;

    for (uintptr_t container :
         containers)
    {
        uintptr_t dequeMap =
            ReadPtr(
                container +
                profile.containerDequeMapOffset
            );

        uint64_t mapSize = 0;
        uint64_t dequeOffset = 0;
        uint32_t count = 0;

        SafeRead(
            container +
                profile.containerDequeMapSizeOffset,
            mapSize
        );

        SafeRead(
            container +
                profile.containerDequeOffsetOffset,
            dequeOffset
        );

        SafeRead(
            container +
                profile.containerItemCountOffset,
            count
        );

        if (!dequeMap ||
            !mapSize ||
            (mapSize &
             (mapSize - 1)) != 0 ||
            mapSize > 0x10000 ||
            count > 200)
        {
            continue;
        }

        for (size_t i = 0;
             i < count;
             ++i)
        {
            uint64_t logical =
                dequeOffset +
                i;

            uint64_t block =
                (
                    logical /
                    blockElements
                ) &
                (
                    mapSize -
                    1
                );

            uint64_t cell =
                logical %
                blockElements;

            uintptr_t blockPtr =
                ReadPtr(
                    dequeMap +
                    block *
                    sizeof(uintptr_t)
                );

            if (!blockPtr)
                continue;

            uintptr_t entry =
                blockPtr +
                cell *
                elementStride;

            uintptr_t item =
                ReadPtr(
                    entry
                );

            if (!item)
                continue;

            uintptr_t vt =
                ReadPtr(
                    item
                );

            if (
                vt == itemVtable ||
                V36IsRealSemanticItem(
                    item)
            )
            {
                out.push_back(
                    item
                );
            }
        }
    }

    std::sort(
        out.begin(),
        out.end()
    );

    out.erase(
        std::unique(
            out.begin(),
            out.end()
        ),
        out.end()
    );

    return out;
}

bool V38DiscoverSemanticContainerLayout(
    DbProfile& profile)
{
    if (!profile.gameContainersOffset)
        return false;

    auto containers =
        V38FindContainersLinkedToConfirmedOwner(
            profile
        );

    if (containers.empty())
    {
        std::cout
            << "[CONTAINER LAYOUT] Owner confirmado, mas nenhum Container "
            << "aberto esta ligado a ele agora.\n";

        return false;
    }

    std::cout
        << "\n[CONTAINER LAYOUT] linked containers="
        << containers.size()
        << "\n";

    bool treeOk =
        V38InferContainerTreeLayout(
            profile,
            containers
        );

    bool dequeOk =
        V38DiscoverContainerDequeLayout(
            profile,
            containers
        );

    return
        treeOk &&
        dequeOk;
}


bool BMDiscoverContainers(
    DbProfile& profile,
    uintptr_t localPlayer)
{
    (void)localPlayer;

    if (!profile.gameRva ||
        !profile.itemVtableRva)
    {
        return false;
    }

    uintptr_t game =
        g_exeBase +
        profile.gameRva;

    uintptr_t itemVtable =
        g_exeBase +
        profile.itemVtableRva;

    std::vector<BMContainerMapCandidate>
        candidates;

    for (uintptr_t off = 0;
         off <= 0x400;
         off += 8)
    {
        BMContainerMapCandidate c{};

        if (BMValidateContainerMapCandidate(
                game,
                off,
                itemVtable,
                c,
                false))
        {
            candidates.push_back(
                c
            );
        }
    }

    std::sort(
        candidates.begin(),
        candidates.end(),
        [](
            const BMContainerMapCandidate& a,
            const BMContainerMapCandidate& b)
        {
            if (a.score !=
                b.score)
            {
                return a.score > b.score;
            }

            return
                a.gameOffset <
                b.gameOffset;
        }
    );

    if (candidates.empty())
        return false;

    if (candidates.size() > 1 &&
        candidates[0].score ==
            candidates[1].score)
    {
        return false;
    }

    BMContainerMapCandidate winner =
        candidates[0];

    std::cout
        << "\n============================================================\n"
        << "               CONTAINER STORAGE DISCOVERED\n"
        << "============================================================\n"
        << "Game member          : +"
        << HexU64(
            winner.gameOffset
        )
        << "\n"
        << "Reported map size    : "
        << winner.reportedSize
        << "\n"
        << "Tree nodes visited   : "
        << winner.visitedNodes
        << "\n"
        << "Valid containers     : "
        << winner.validContainers
        << "\n"
        << "Validated Item ptrs  : "
        << winner.validItems
        << "\n";

    BMValidateContainerMapCandidate(
        game,
        winner.gameOffset,
        itemVtable,
        winner,
        true
    );

    profile.gameContainersOffset =
        winner.gameOffset;

    profile.containerMapHeaderOffset =
        0x00;

    profile.containerMapSizeOffset =
        0x08;

    profile.containerNodeLeftOffset =
        0x00;

    profile.containerNodeRightOffset =
        0x10;

    profile.containerNodeNilOffset =
        0x19;

    profile.containerNodeKeyOffset =
        0x20;

    profile.containerNodeValueOffset =
        0x28;

    profile.containerIdOffset =
        0x18;

    profile.containerCapacityOffset =
        0x1C;

    profile.containerItemOffset =
        0x20;

    profile.containerNameOffset =
        0x28;

    profile.containerHasParentOffset =
        0x48;

    profile.containerClosedOffset =
        0x49;

    profile.containerUnlockedOffset =
        0x4A;

    profile.containerPagesOffset =
        0x4B;

    profile.containerSizeOffset =
        0x4C;

    profile.containerFirstIndexOffset =
        0x50;

    profile.containerDequeMapOffset =
        0x60;

    profile.containerDequeMapSizeOffset =
        0x68;

    profile.containerDequeOffsetOffset =
        0x70;

    profile.containerItemCountOffset =
        0x78;

    profile.containerItemElementStride =
        8;

    profile.containerItemStorageMode =
        "deque_raw_item_ptr";

    profile.containersStatus =
        "confirmed_runtime_open_container_tree_and_items";

    // Item layout is cross-checked while enumerating container Items.
    if (winner.validItems)
    {
        profile.itemIdOffset =
            0x38;

        profile.itemCountOffset =
            0x3C;

        profile.itemCountWidth =
            2;

        profile.itemLayoutStatus =
            "confirmed_runtime_container_items_item_vtable";
    }

    return true;
}

struct V38ItemSnapshot
{
    uintptr_t pointer = 0;
    std::vector<uint8_t> bytes;
};

struct V46ContainerLogicalSlot
{
    uintptr_t container = 0;
    size_t index = 0;
    uintptr_t item = 0;
    uintptr_t companion = 0;
};

std::vector<V46ContainerLogicalSlot>
V46CollectContainerLogicalSlots(
    const DbProfile& profile,
    const std::vector<uintptr_t>& containers)
{
    std::vector<V46ContainerLogicalSlot>
        out;

    if (
        !profile.containerDequeMapOffset ||
        !profile.containerDequeMapSizeOffset ||
        !profile.containerDequeOffsetOffset ||
        !profile.containerItemCountOffset
    )
    {
        return out;
    }

    const bool shared =
        profile.containerItemStorageMode ==
            "deque_shared_ptr_item";

    const size_t elementStride =
        shared
            ? 16
            : 8;

    const size_t blockElements =
        shared
            ? 1
            : 2;

    for (uintptr_t container :
         containers)
    {
        uintptr_t dequeMap =
            ReadPtr(
                container +
                profile.containerDequeMapOffset
            );

        uint64_t mapSize = 0;
        uint64_t dequeOffset = 0;
        uint32_t count = 0;

        SafeRead(
            container +
                profile.containerDequeMapSizeOffset,
            mapSize
        );

        SafeRead(
            container +
                profile.containerDequeOffsetOffset,
            dequeOffset
        );

        SafeRead(
            container +
                profile.containerItemCountOffset,
            count
        );

        if (
            !dequeMap ||
            !mapSize ||
            (mapSize & (mapSize - 1)) != 0 ||
            mapSize > 0x10000 ||
            count > 200
        )
        {
            continue;
        }

        for (size_t i = 0;
             i < count;
             ++i)
        {
            uint64_t logical =
                dequeOffset +
                i;

            uint64_t block =
                (
                    logical /
                    blockElements
                ) &
                (
                    mapSize -
                    1
                );

            uint64_t cell =
                logical %
                blockElements;

            uintptr_t blockPtr =
                ReadPtr(
                    dequeMap +
                    block *
                    sizeof(uintptr_t)
                );

            if (!blockPtr)
                continue;

            uintptr_t entry =
                blockPtr +
                cell *
                elementStride;

            uintptr_t item =
                ReadPtr(
                    entry
                );

            uintptr_t companion =
                shared
                    ? ReadPtr(
                          entry +
                          sizeof(uintptr_t)
                      )
                    : 0;

            V46ContainerLogicalSlot slot{};
            slot.container =
                container;
            slot.index =
                i;
            slot.item =
                item;
            slot.companion =
                companion;

            out.push_back(
                slot
            );
        }
    }

    std::sort(
        out.begin(),
        out.end(),
        [](
            const V46ContainerLogicalSlot& a,
            const V46ContainerLogicalSlot& b)
        {
            if (a.container != b.container)
                return a.container < b.container;

            return a.index < b.index;
        }
    );

    return out;
}

struct V46ContainerSlotSnapshot
{
    uintptr_t container = 0;
    size_t index = 0;
    uintptr_t item = 0;
    uintptr_t companion = 0;
    V38ItemSnapshot snapshot;
};

std::vector<V46ContainerSlotSnapshot>
V46CaptureContainerSlotSnapshots(
    const DbProfile& profile)
{
    std::vector<V46ContainerSlotSnapshot>
        out;

    auto containers =
        V38FindContainersLinkedToConfirmedOwner(
            profile
        );

    auto slots =
        V46CollectContainerLogicalSlots(
            profile,
            containers
        );

    for (const auto& slot :
         slots)
    {
        if (
            !slot.item ||
            !V36IsRealSemanticItem(
                slot.item) ||
            !IsReadableMonitorRange(
                slot.item,
                0x180)
        )
        {
            continue;
        }

        V46ContainerSlotSnapshot s{};
        s.container =
            slot.container;
        s.index =
            slot.index;
        s.item =
            slot.item;
        s.companion =
            slot.companion;
        s.snapshot.pointer =
            slot.item;
        s.snapshot.bytes.resize(
            0x180
        );

        std::memcpy(
            s.snapshot.bytes.data(),
            reinterpret_cast<const void*>(
                slot.item),
            s.snapshot.bytes.size()
        );

        out.push_back(
            std::move(
                s
            )
        );
    }

    return out;
}



bool BMValidateReferenceItemLayout(
    DbProfile& profile,
    uintptr_t localPlayer)
{
    if (!profile.itemVtableRva)
        return false;

    auto observations =
        V25CollectWorldThings(
            profile,
            localPlayer
        );

    uintptr_t itemVtable =
        g_exeBase +
        profile.itemVtableRva;

    size_t checked = 0;
    size_t plausible = 0;

    for (const auto& o :
         observations)
    {
        if (
            o.vtable !=
                itemVtable &&
            !V33RttiContainsClassToken(
                o.rttiName,
                "item")
        )
        {
            continue;
        }

        if (!IsReadableMonitorRange(
                o.pointer,
                0x40))
        {
            continue;
        }

        uint16_t id = 0;
        uint16_t count = 0;

        SafeRead(
            o.pointer +
                0x38,
            id
        );

        SafeRead(
            o.pointer +
                0x3C,
            count
        );

        ++checked;

        if (id > 0 &&
            id < 65000 &&
            count < 10000)
        {
            ++plausible;
        }

        if (checked >= 128)
            break;
    }

    if (checked < 8 ||
        plausible * 100 <
            checked * 90)
    {
        return false;
    }

    profile.itemIdOffset =
        0x38;

    profile.itemCountOffset =
        0x3C;

    profile.itemLayoutStatus =
        "confirmed_runtime_item_cohort_reference_layout";

    return true;
}


std::vector<uintptr_t>
V38CollectInventoryItemPointers(
    const DbProfile& profile,
    uintptr_t localPlayer)
{
    std::vector<uintptr_t>
        out;

    if (!profile.inventoryBaseOffset ||
        !profile.inventorySlotStride)
    {
        return out;
    }

    for (size_t slot = 1;
         slot <= 10;
         ++slot)
    {
        uintptr_t address =
            localPlayer +
            profile.inventoryBaseOffset +
            slot *
            profile.inventorySlotStride;

        uintptr_t item =
            ReadPtr(
                address
            );

        if (!item)
            continue;

        if (V36IsRealSemanticItem(
                item))
        {
            out.push_back(
                item
            );
        }
    }

    std::sort(
        out.begin(),
        out.end()
    );

    out.erase(
        std::unique(
            out.begin(),
            out.end()
        ),
        out.end()
    );

    return out;
}

std::vector<V38ItemSnapshot>
V38CaptureItemSnapshots(
    const std::vector<uintptr_t>& items)
{
    std::vector<V38ItemSnapshot>
        out;

    for (uintptr_t item :
         items)
    {
        if (!IsReadableMonitorRange(
                item,
                0x180))
        {
            continue;
        }

        V38ItemSnapshot snap{};
        snap.pointer = item;
        snap.bytes.resize(
            0x180
        );

        std::memcpy(
            snap.bytes.data(),
            reinterpret_cast<const void*>(
                item),
            snap.bytes.size()
        );

        out.push_back(
            std::move(
                snap
            )
        );
    }

    return out;
}


uint64_t V39ReadUnsignedWidth(
    const std::vector<uint8_t>& bytes,
    size_t offset,
    size_t width)
{
    if (offset + width >
        bytes.size())
    {
        return 0;
    }

    uint64_t value = 0;

    std::memcpy(
        &value,
        bytes.data() + offset,
        width
    );

    return value;
}

double V39ItemSimilarityExcluding(
    const V38ItemSnapshot& a,
    const V38ItemSnapshot& b,
    size_t excludeOffset,
    size_t excludeWidth)
{
    const size_t begin = 0x10;
    const size_t end =
        std::min<size_t>(
            0x160,
            std::min(
                a.bytes.size(),
                b.bytes.size()
            )
        );

    size_t compared = 0;
    size_t equal = 0;

    for (size_t i = begin;
         i < end;
         ++i)
    {
        if (i >= excludeOffset &&
            i < excludeOffset +
                excludeWidth)
        {
            continue;
        }

        ++compared;

        if (a.bytes[i] ==
            b.bytes[i])
        {
            ++equal;
        }
    }

    return
        compared
            ? static_cast<double>(
                  equal) /
              static_cast<double>(
                  compared)
            : 0.0;
}

std::vector<uintptr_t>
V39CollectAllCurrentItems(
    const DbProfile& profile,
    uintptr_t localPlayer)
{
    std::vector<uintptr_t> out =
        V38CollectInventoryItemPointers(
            profile,
            localPlayer
        );

    if (profile.gameContainersOffset &&
        profile.containerDequeMapOffset &&
        profile.containerItemCountOffset)
    {
        auto containers =
            V38FindContainersLinkedToConfirmedOwner(
                profile
            );

        auto containerItems =
            V38CollectContainerItems(
                profile,
                containers
            );

        out.insert(
            out.end(),
            containerItems.begin(),
            containerItems.end()
        );
    }

    std::sort(
        out.begin(),
        out.end()
    );

    out.erase(
        std::unique(
            out.begin(),
            out.end()
        ),
        out.end()
    );

    return out;
}

struct V39CountTransitionCandidate
{
    uintptr_t offset = 0;
    size_t width = 0;
    uintptr_t beforePointer = 0;
    uintptr_t afterPointer = 0;
    uint64_t oldValue = 0;
    uint64_t newValue = 0;
    double similarity = 0.0;
    int score = 0;
};


