std::string V47AskLine(
    const char* label)
{
    std::cout << label;

    std::string value;
    std::getline(
        std::cin,
        value
    );

    return value;
}

bool V47CaptureVisualContainerSlot(
    const DbProfile& profile,
    size_t visualSlot,
    V38ItemSnapshot& out,
    uintptr_t& outContainer,
    size_t& outLogicalIndex)
{
    auto slots =
        V46CaptureContainerSlotSnapshots(
            profile
        );

    std::vector<const V46ContainerSlotSnapshot*>
        matches;

    for (const auto& s :
         slots)
    {
        if (s.index + 1 ==
            visualSlot)
        {
            matches.push_back(
                &s
            );
        }
    }

    if (matches.empty())
    {
        std::cout
            << "[ITEM ID] Nenhum Item encontrado no slot visual "
            << visualSlot
            << ".\n";

        return false;
    }

    if (matches.size() != 1)
    {
        std::cout
            << "[ITEM ID] O mesmo slot visual apareceu em "
            << matches.size()
            << " containers abertos.\n"
            << "[ITEM ID] Feche os outros containers e deixe SOMENTE o container do teste aberto.\n";

        return false;
    }

    out =
        matches[0]->snapshot;

    outContainer =
        matches[0]->container;

    outLogicalIndex =
        matches[0]->index;

    return
        out.pointer != 0 &&
        !out.bytes.empty();
}

bool V47ResolveItemIdFromTwoKnownSamples(
    DbProfile& profile,
    unsigned expectedA,
    const V38ItemSnapshot& sampleA,
    unsigned expectedB,
    const V38ItemSnapshot& sampleB,
    const char* confirmationMethod)
{
    if (!profile.itemCountOffset ||
        !profile.itemCountWidth)
    {
        std::cout
            << "[ITEM ID] Count/Subtype ainda nao esta confirmado.\n";

        return false;
    }

    if (!expectedA ||
        !expectedB ||
        expectedA == expectedB)
    {
        std::cout
            << "[ITEM ID] As duas amostras precisam ter IDs conhecidos, validos e DIFERENTES.\n";

        return false;
    }

    struct Match
    {
        uintptr_t offset = 0;
        size_t width = 0;
        uint64_t a = 0;
        uint64_t b = 0;
    };

    std::vector<Match>
        matches;

    const intptr_t beginOff =
        std::max<intptr_t>(
            0x10,
            static_cast<intptr_t>(
                profile.itemCountOffset
            ) - 0x20
        );

    const intptr_t endOff =
        std::min<intptr_t>(
            0x180,
            static_cast<intptr_t>(
                profile.itemCountOffset
            ) + 0x20
        );

    for (size_t width :
         {
             static_cast<size_t>(2),
             static_cast<size_t>(4)
         })
    {
        if (width == 2 &&
            (expectedA > 0xFFFFu ||
             expectedB > 0xFFFFu))
        {
            continue;
        }

        for (intptr_t signedOff =
                 beginOff;
             signedOff +
                     static_cast<intptr_t>(
                         width
                     ) <=
                 endOff;
             ++signedOff)
        {
            const uintptr_t off =
                static_cast<uintptr_t>(
                    signedOff
                );

            const uintptr_t countBegin =
                profile.itemCountOffset;

            const uintptr_t countEnd =
                profile.itemCountOffset +
                profile.itemCountWidth;

            const uintptr_t idBegin =
                off;

            const uintptr_t idEnd =
                off + width;

            if (idBegin < countEnd &&
                idEnd > countBegin)
            {
                continue;
            }

            const uint64_t a =
                V39ReadUnsignedWidth(
                    sampleA.bytes,
                    off,
                    width
                );

            const uint64_t b =
                V39ReadUnsignedWidth(
                    sampleB.bytes,
                    off,
                    width
                );

            if (a != expectedA ||
                b != expectedB)
            {
                continue;
            }

            Match m{};
            m.offset = off;
            m.width = width;
            m.a = a;
            m.b = b;

            matches.push_back(
                m
            );
        }
    }

    std::cout
        << "\n[ITEM ID EXACT SEMANTIC MATCHES]\n";

    for (size_t i = 0;
         i < matches.size();
         ++i)
    {
        std::cout
            << "#"
            << i
            << " off=+"
            << HexU64(
                matches[i].offset
            )
            << " width="
            << matches[i].width
            << " A="
            << matches[i].a
            << " B="
            << matches[i].b
            << "\n";
    }

    if (matches.empty())
    {
        std::cout
            << "[ITEM ID] Nenhum campo bateu com os dois IDs conhecidos. Nenhum offset sera promovido.\n";

        return false;
    }

    std::set<uintptr_t>
        uniqueOffsets;

    for (const auto& m :
         matches)
    {
        uniqueOffsets.insert(
            m.offset
        );
    }

    if (uniqueOffsets.size() != 1)
    {
        std::cout
            << "[ITEM ID] Mais de um offset distinto bateu nas duas amostras.\n"
            << "[ITEM ID] Ambiguidade mantida; nenhum offset sera promovido.\n";

        return false;
    }

    const uintptr_t confirmedOffset =
        *uniqueOffsets.begin();

    size_t confirmedWidth = 0;

    for (const auto& m :
         matches)
    {
        if (m.offset !=
            confirmedOffset)
        {
            continue;
        }

        if (!confirmedWidth ||
            m.width < confirmedWidth)
        {
            confirmedWidth =
                m.width;
        }
    }

    profile.itemIdOffset =
        confirmedOffset;

    profile.itemLayoutStatus =
        confirmationMethod;

    std::cout
        << "\n============================================================\n"
        << "                ITEM ID CONFIRMED V4.8\n"
        << "============================================================\n"
        << "Item ID offset       : +"
        << HexU64(
            profile.itemIdOffset
        )
        << "\n"
        << "Observed width       : "
        << confirmedWidth
        << " byte(s)\n"
        << "Count/Subtype offset : +"
        << HexU64(
            profile.itemCountOffset
        )
        << "\n"
        << "Evidence             : two different known Item IDs / same logical container slot\n"
        << "Status               : "
        << profile.itemLayoutStatus
        << "\n";

    return true;
}

bool V47ConfirmItemIdNormal(
    DbProfile& profile)
{
    std::cout
        << "\n============================================================\n"
        << "          V4.8 ITEM ID - NORMAL / MANUAL ORACLE\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "[NO HOOK] nenhuma funcao interna sera chamada\n"
        << "Regra: duas amostras de ITENS DIFERENTES no MESMO slot visual.\n"
        << "Voce informa o ID conhecido de cada item; o Lab apenas compara memoria.\n\n"
        << "Antes de comecar:\n"
        << "  1. deixe SOMENTE um container aberto\n"
        << "  2. escolha um slot visual que possa trocar sem mudar de posicao\n"
        << "  3. use dois itens de IDs conhecidos e DIFERENTES\n";

    const unsigned visualSlot =
        AskUnsignedRange(
            "Slot visual do container (1..200): ",
            1,
            200
        );

    WaitEnter(
        "Coloque o ITEM A nesse slot e pressione ENTER..."
    );

    V38ItemSnapshot sampleA{};
    uintptr_t containerA = 0;
    size_t logicalA = 0;

    if (!V47CaptureVisualContainerSlot(
            profile,
            visualSlot,
            sampleA,
            containerA,
            logicalA))
    {
        return false;
    }

    const unsigned expectedA =
        AskUnsignedRange(
            "ID conhecido do ITEM A: ",
            1,
            std::numeric_limits<unsigned>::max()
        );

    std::cout
        << "[SAMPLE A] container="
        << HexPtr(
            containerA
        )
        << " logicalIndex="
        << logicalA
        << " item="
        << HexPtr(
            sampleA.pointer
        )
        << " expectedId="
        << expectedA
        << "\n";

    WaitEnter(
        "Troque SOMENTE esse slot pelo ITEM B (ID diferente) e pressione ENTER..."
    );

    V38ItemSnapshot sampleB{};
    uintptr_t containerB = 0;
    size_t logicalB = 0;

    if (!V47CaptureVisualContainerSlot(
            profile,
            visualSlot,
            sampleB,
            containerB,
            logicalB))
    {
        return false;
    }

    const unsigned expectedB =
        AskUnsignedRange(
            "ID conhecido do ITEM B: ",
            1,
            std::numeric_limits<unsigned>::max()
        );

    std::cout
        << "[SAMPLE B] container="
        << HexPtr(
            containerB
        )
        << " logicalIndex="
        << logicalB
        << " item="
        << HexPtr(
            sampleB.pointer
        )
        << " expectedId="
        << expectedB
        << "\n";

    if (containerA !=
            containerB ||
        logicalA !=
            logicalB)
    {
        std::cout
            << "[ITEM ID] O container/slot logico mudou entre A e B. Teste rejeitado.\n";

        return false;
    }

    return
        V47ResolveItemIdFromTwoKnownSamples(
            profile,
            expectedA,
            sampleA,
            expectedB,
            sampleB,
            "confirmed_runtime_two_known_item_ids_manual"
        );
}

bool V39DiscoverItemLayoutGuided(
    DbProfile& profile,
    uintptr_t localPlayer)
{
    std::cout
        << "\n============================================================\n"
        << "      V4.7 CONTAINER-SLOT EXACT ITEM COUNT RESOLVER\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "Identity rule: SAME Container* + SAME logical slot index.\n"
        << "No all-to-all Item pairing is allowed.\n";

    const bool countAlreadyConfirmed =
        profile.itemCountOffset != 0 &&
        profile.itemCountWidth != 0 &&
        (
            profile.itemLayoutStatus.find(
                "partial_count_confirmed_container_slot") == 0 ||
            profile.itemLayoutStatus.find(
                "confirmed_") == 0
        );

    V39CountTransitionCandidate count{};

    if (!countAlreadyConfirmed)
    {
        if (
            !profile.gameContainersOffset ||
            !profile.containerDequeMapOffset ||
            !profile.containerDequeMapSizeOffset ||
            !profile.containerDequeOffsetOffset ||
            !profile.containerItemCountOffset
        )
        {
            std::cout
                << "[ITEM] Container layout ainda nao esta confirmado; "
                << "nao e seguro aprender Count sem provenance.\n";
            return false;
        }

        std::cout
            << "\nPrepare o teste assim:\n"
            << "  1. deixe aberta a Backpack/container que contem a pilha\n"
            << "  2. NAO mova a pilha de slot\n"
            << "  3. use/adicione/retire exatamente UMA unidade\n"
            << "  4. a pilha deve continuar no MESMO slot logico\n";

        WaitEnter(
            "Com a pilha visivel no container aberto, pressione ENTER..."
        );

        auto beforeSlots =
            V46CaptureContainerSlotSnapshots(
                profile
            );

        if (beforeSlots.empty())
        {
            std::cout
                << "[ITEM] Nenhum Item de container aberto foi capturado.\n";
            return false;
        }

        if (!AskYesNo(
                "Existe uma pilha VISIVEL nesse container com quantidade >=2? [S/N]: "))
        {
            return false;
        }

        unsigned visibleBefore =
            AskUnsignedRange(
                "Quantidade VISIVEL da pilha ANTES da acao: ",
                2,
                100000000
            );

        std::cout
            << "\n[ACTION - SAME CONTAINER SLOT]\n"
            << "Altere exatamente UMA unidade da pilha.\n"
            << "NAO mova a pilha para outro slot/container.\n"
            << "Exemplo correto: 18 -> 17 ou 17 -> 18.\n";

        WaitEnter(
            "Depois da mudanca de UMA unidade, pressione ENTER..."
        );

        unsigned visibleAfter =
            AskUnsignedRange(
                "Quantidade VISIVEL da MESMA pilha AGORA: ",
                0,
                100000000
            );

        unsigned delta =
            visibleBefore > visibleAfter
                ? visibleBefore - visibleAfter
                : visibleAfter - visibleBefore;

        if (delta != 1)
        {
            std::cout
                << "[ITEM] A quantidade informada nao mudou exatamente UMA unidade.\n";
            return false;
        }

        auto afterSlots =
            V46CaptureContainerSlotSnapshots(
                profile
            );

        if (afterSlots.empty())
        {
            std::cout
                << "[ITEM] O container/slot nao permaneceu observavel apos a acao.\n";
            return false;
        }

        using SlotKey =
            std::pair<uintptr_t, size_t>;

        std::map<SlotKey, const V46ContainerSlotSnapshot*>
            afterByKey;

        for (const auto& s :
             afterSlots)
        {
            afterByKey[
                {
                    s.container,
                    s.index
                }
            ] =
                &s;
        }

        struct ExactAggregate
        {
            V39CountTransitionCandidate best;
            size_t evidence = 0;
            size_t slotMatches = 0;
        };

        std::map<
            std::pair<uintptr_t, size_t>,
            ExactAggregate>
            aggregate;

        const size_t widths[] =
        {
            1,
            2,
            4
        };

        const size_t minimalWidth =
            std::max(
                visibleBefore,
                visibleAfter
            ) <= 0xFF
                ? 1
                : (
                    std::max(
                        visibleBefore,
                        visibleAfter
                    ) <= 0xFFFF
                        ? 2
                        : 4
                  );

        size_t sameSlotPairs = 0;
        size_t exactTransitionPairs = 0;

        for (const auto& aSlot :
             beforeSlots)
        {
            auto it =
                afterByKey.find(
                    {
                        aSlot.container,
                        aSlot.index
                    }
                );

            if (it ==
                afterByKey.end())
            {
                continue;
            }

            const auto& bSlot =
                *it->second;

            if (
                !aSlot.item ||
                !bSlot.item
            )
            {
                continue;
            }

            ++sameSlotPairs;

            const auto& a =
                aSlot.snapshot;
            const auto& b =
                bSlot.snapshot;

            bool pairHadExact =
                false;

            for (size_t width :
                 widths)
            {
                if (width <
                    minimalWidth)
                {
                    continue;
                }

                size_t limit =
                    std::min(
                        a.bytes.size(),
                        b.bytes.size()
                    );

                for (size_t off = 0x10;
                     off + width <= limit;
                     ++off)
                {
                    uint64_t oldValue =
                        V39ReadUnsignedWidth(
                            a.bytes,
                            off,
                            width
                        );

                    if (oldValue !=
                        visibleBefore)
                    {
                        continue;
                    }

                    uint64_t newValue =
                        V39ReadUnsignedWidth(
                            b.bytes,
                            off,
                            width
                        );

                    if (newValue !=
                        visibleAfter)
                    {
                        continue;
                    }

                    double similarity =
                        V39ItemSimilarityExcluding(
                            a,
                            b,
                            off,
                            width
                        );

                    // Same logical slot is the provenance anchor.  The object
                    // itself may be rebuilt, but it still must remain broadly
                    // similar after excluding the count field.
                    const double threshold =
                        a.pointer ==
                            b.pointer
                            ? 0.45
                            : 0.60;

                    if (similarity <
                        threshold)
                    {
                        continue;
                    }

                    pairHadExact =
                        true;

                    V39CountTransitionCandidate c{};
                    c.offset =
                        off;
                    c.width =
                        width;
                    c.beforePointer =
                        a.pointer;
                    c.afterPointer =
                        b.pointer;
                    c.oldValue =
                        oldValue;
                    c.newValue =
                        newValue;
                    c.similarity =
                        similarity;

                    c.score =
                        5000 +
                        static_cast<int>(
                            similarity *
                            1000.0
                        );

                    // SAME container + SAME logical slot is much stronger
                    // evidence than pointer equality.
                    c.score +=
                        1200;

                    if (
                        a.pointer ==
                        b.pointer
                    )
                    {
                        c.score +=
                            250;
                    }

                    if (width ==
                        minimalWidth)
                    {
                        c.score +=
                            260;
                    }

                    if ((off % width) == 0)
                    {
                        c.score +=
                            40;
                    }

                    auto key =
                        std::make_pair(
                            static_cast<uintptr_t>(
                                off),
                            width
                        );

                    auto& e =
                        aggregate[
                            key
                        ];

                    ++e.evidence;
                    ++e.slotMatches;

                    if (
                        e.best.score == 0 ||
                        c.score >
                            e.best.score
                    )
                    {
                        e.best =
                            c;
                    }
                }
            }

            if (pairHadExact)
            {
                ++exactTransitionPairs;
            }
        }

        struct Ranked
        {
            V39CountTransitionCandidate c;
            size_t evidence = 0;
            size_t slotMatches = 0;
        };

        std::vector<Ranked>
            ranked;

        for (const auto& kv :
             aggregate)
        {
            Ranked r{};
            r.c =
                kv.second.best;
            r.evidence =
                kv.second.evidence;
            r.slotMatches =
                kv.second.slotMatches;

            r.c.score +=
                static_cast<int>(
                    std::min<size_t>(
                        r.slotMatches,
                        4
                    ) *
                    100
                );

            ranked.push_back(
                r
            );
        }

        std::sort(
            ranked.begin(),
            ranked.end(),
            [](
                const Ranked& a,
                const Ranked& b)
            {
                if (a.c.score !=
                    b.c.score)
                {
                    return
                        a.c.score >
                        b.c.score;
                }

                if (a.slotMatches !=
                    b.slotMatches)
                {
                    return
                        a.slotMatches >
                        b.slotMatches;
                }

                if (a.c.width !=
                    b.c.width)
                {
                    return
                        a.c.width <
                        b.c.width;
                }

                return
                    a.c.offset <
                    b.c.offset;
            }
        );

        std::cout
            << "\n[ITEM CONTAINER-SLOT PROVENANCE]\n"
            << "Before slots           : "
            << beforeSlots.size()
            << "\n"
            << "After slots            : "
            << afterSlots.size()
            << "\n"
            << "Same container/index   : "
            << sameSlotPairs
            << "\n"
            << "Pairs with exact value : "
            << exactTransitionPairs
            << "\n";

        std::cout
            << "\n[ITEM EXACT COUNT CANDIDATES / SAME SLOT]\n";

        for (size_t i = 0;
             i < ranked.size() &&
             i < 12;
             ++i)
        {
            const auto& r =
                ranked[i];

            std::cout
                << "#"
                << i
                << " off=+"
                << HexU64(
                    r.c.offset
                )
                << " width="
                << r.c.width
                << " value="
                << r.c.oldValue
                << "->"
                << r.c.newValue
                << " slotEvidence="
                << r.slotMatches
                << " similarity="
                << std::fixed
                << std::setprecision(3)
                << r.c.similarity
                << " ptr="
                << (
                    r.c.beforePointer ==
                        r.c.afterPointer
                        ? "same"
                        : "rebuilt"
                )
                << " score="
                << r.c.score
                << "\n";
        }

        if (ranked.empty())
        {
            std::cout
                << "[ITEM] Nenhum SAME container/slot apresentou "
                << visibleBefore
                << " -> "
                << visibleAfter
                << ".\n"
                << "[ITEM] Nenhum offset sera adivinhado.\n";

            return false;
        }

        if (
            ranked.size() > 1 &&
            ranked[0].c.offset !=
                ranked[1].c.offset &&
            ranked[0].c.score -
                ranked[1].c.score <
                120
        )
        {
            std::cout
                << "[ITEM] Mais de um offset continua forte no MESMO slot; Count permanece pending.\n";

            return false;
        }

        count =
            ranked[0].c;

        profile.itemCountOffset =
            count.offset;

        profile.itemCountWidth =
            count.width;

        profile.itemIdOffset =
            0;

        profile.itemLayoutStatus =
            "partial_count_confirmed_container_slot_id_pending";

        std::cout
            << "\n[ITEM COUNT CONFIRMED BY CONTAINER SLOT]\n"
            << "Count/Subtype offset : +"
            << HexU64(
                profile.itemCountOffset
            )
            << "\n"
            << "Count width          : "
            << profile.itemCountWidth
            << " byte(s)\n"
            << "Visible transition   : "
            << visibleBefore
            << " -> "
            << visibleAfter
            << "\n"
            << "Identity             : SAME Container* + SAME logical index\n"
            << "Status               : partial_count_confirmed_container_slot_id_pending\n";
    }
    else
    {
        count.offset =
            profile.itemCountOffset;

        count.width =
            profile.itemCountWidth;

        std::cout
            << "[ITEM COUNT] Container-slot provenance ja confirmou Count em +"
            << HexU64(
                profile.itemCountOffset
            )
            << " width="
            << profile.itemCountWidth
            << ". Nao repetiremos o consumo da pilha.\n";
    }

    // V4.6 intentionally does NOT promote Item ID from a "nearest diverse
    // field" heuristic.  The clean Scape run demonstrated that Count must be
    // tied to logical provenance; ID requires an independent semantic proof.
    auto currentItems =
        V39CollectAllCurrentItems(
            profile,
            localPlayer
        );

    auto snapshots =
        V38CaptureItemSnapshots(
            currentItems
        );

    struct IdCandidate
    {
        uintptr_t offset = 0;
        size_t width = 0;
        size_t nonZero = 0;
        size_t distinct = 0;
        int score = 0;
    };

    std::vector<IdCandidate>
        ids;

    for (size_t width :
         {
             static_cast<size_t>(2),
             static_cast<size_t>(4)
         })
    {
        intptr_t beginOff =
            static_cast<intptr_t>(
                count.offset
            ) -
            0x20;

        intptr_t endOff =
            static_cast<intptr_t>(
                count.offset
            ) +
            0x20;

        for (intptr_t signedOff =
                 std::max<intptr_t>(
                     0x10,
                     beginOff
                 );
             signedOff +
                     static_cast<intptr_t>(
                         width
                     ) <=
                 std::min<intptr_t>(
                     0x180,
                     endOff
                 );
             ++signedOff)
        {
            uintptr_t off =
                static_cast<uintptr_t>(
                    signedOff
                );

            if (
                off <=
                    count.offset +
                    count.width -
                    1 &&
                off + width - 1 >=
                    count.offset
            )
            {
                continue;
            }

            std::set<uint64_t>
                values;

            size_t nonZero = 0;

            for (const auto& snap :
                 snapshots)
            {
                uint64_t value =
                    V39ReadUnsignedWidth(
                        snap.bytes,
                        off,
                        width
                    );

                if (!value)
                    continue;

                ++nonZero;
                values.insert(
                    value
                );
            }

            if (
                snapshots.empty() ||
                nonZero * 100 <
                    snapshots.size() *
                    65 ||
                values.size() < 2
            )
            {
                continue;
            }

            IdCandidate id{};
            id.offset =
                off;
            id.width =
                width;
            id.nonZero =
                nonZero;
            id.distinct =
                values.size();

            long long distance =
                std::llabs(
                    static_cast<long long>(
                        off
                    ) -
                    static_cast<long long>(
                        count.offset
                    )
                );

            id.score =
                static_cast<int>(
                    nonZero * 18 +
                    values.size() * 22
                ) +
                static_cast<int>(
                    std::max<long long>(
                        0,
                        220 -
                        distance * 10
                    )
                );

            if (width == 2)
                id.score += 40;

            ids.push_back(
                id
            );
        }
    }

    std::sort(
        ids.begin(),
        ids.end(),
        [](
            const IdCandidate& a,
            const IdCandidate& b)
        {
            if (a.score !=
                b.score)
                return a.score > b.score;

            if (a.distinct !=
                b.distinct)
                return a.distinct > b.distinct;

            if (a.width !=
                b.width)
                return a.width < b.width;

            return a.offset < b.offset;
        }
    );

    std::cout
        << "\n[ITEM ID CANDIDATES - EVIDENCE ONLY]\n";

    for (size_t i = 0;
         i < ids.size() &&
         i < 10;
         ++i)
    {
        std::cout
            << "#"
            << i
            << " off=+"
            << HexU64(
                ids[i].offset
            )
            << " width="
            << ids[i].width
            << " nonZero="
            << ids[i].nonZero
            << " distinct="
            << ids[i].distinct
            << " score="
            << ids[i].score
            << "\n";
    }

    std::cout
        << "[ITEM ID] Candidatos estruturais encontrados; iniciando prova semantica V4.7 NORMAL.\n";

    if (V47ConfirmItemIdNormal(
            profile))
    {
        return true;
    }

    profile.itemIdOffset =
        0;

    profile.itemLayoutStatus =
        "partial_count_confirmed_container_slot_id_pending";

    return false;
}


bool V38DiscoverItemLayoutGuided(
    DbProfile& profile,
    uintptr_t localPlayer)
{
    std::vector<uintptr_t>
        items =
            V38CollectInventoryItemPointers(
                profile,
                localPlayer
            );

    auto containers =
        V38FindContainersLinkedToConfirmedOwner(
            profile
        );

    auto containerItems =
        V38CollectContainerItems(
            profile,
            containers
        );

    items.insert(
        items.end(),
        containerItems.begin(),
        containerItems.end()
    );

    std::sort(
        items.begin(),
        items.end()
    );

    items.erase(
        std::unique(
            items.begin(),
            items.end()
        ),
        items.end()
    );

    if (items.size() < 2)
        return false;

    std::cout
        << "\\n============================================================\\n"
        << "           V3.8 ITEM COUNT / ID GUIDED RESOLVER\\n"
        << "============================================================\\n"
        << "[MODE] READ-ONLY\\n"
        << "Item objects available: "
        << items.size()
        << "\\n";

    if (!AskYesNo(
            "Existe uma PILHA com quantidade >=2 que voce consegue alterar em EXATAMENTE 1 unidade agora? [S/N]: "))
    {
        return false;
    }

    auto before =
        V38CaptureItemSnapshots(
            items
        );

    std::cout
        << "\\n[ACTION - ITEM STACK]\\n"
        << "Escolha UMA pilha existente.\\n"
        << "Adicione OU retire UMA unidade (ex.: 36 -> 35; NAO 36 -> 1).\\n"
        << "Nao troque o tipo do item e, se possivel, mantenha a pilha no mesmo lugar.\\n";

    WaitEnter(
        "Depois da quantidade mudar em exatamente 1, pressione ENTER..."
    );

    struct CountCandidate
    {
        uintptr_t offset = 0;
        size_t deltaOne = 0;
        size_t otherChanges = 0;
        int score = 0;
    };

    std::vector<CountCandidate>
        countCandidates;

    for (uintptr_t off = 0x10;
         off + sizeof(uint16_t) <= 0xA0;
         off += 2)
    {
        CountCandidate c{};
        c.offset = off;

        for (const auto& snap :
             before)
        {
            if (!IsReadableMonitorRange(
                    snap.pointer,
                    0xA0))
            {
                continue;
            }

            uint16_t oldValue = 0;
            uint16_t newValue = 0;

            std::memcpy(
                &oldValue,
                snap.bytes.data() + off,
                sizeof(oldValue)
            );

            SafeRead(
                snap.pointer + off,
                newValue
            );

            if (oldValue ==
                newValue)
            {
                continue;
            }

            int delta =
                static_cast<int>(
                    newValue) -
                static_cast<int>(
                    oldValue);

            if (
                std::abs(
                    delta) == 1 &&
                oldValue <= 10000 &&
                newValue <= 10000
            )
            {
                ++c.deltaOne;
            }
            else
            {
                ++c.otherChanges;
            }
        }

        if (!c.deltaOne)
            continue;

        c.score =
            static_cast<int>(
                c.deltaOne * 300
            ) -
            static_cast<int>(
                c.otherChanges * 400
            );

        if ((off & 3) == 0)
            c.score += 30;

        countCandidates.push_back(
            c
        );
    }

    std::sort(
        countCandidates.begin(),
        countCandidates.end(),
        [](
            const CountCandidate& a,
            const CountCandidate& b)
        {
            if (a.score !=
                b.score)
            {
                return
                    a.score >
                    b.score;
            }

            return
                a.offset <
                b.offset;
        }
    );

    std::cout
        << "\\n[ITEM COUNT CANDIDATES]\\n";

    for (size_t i = 0;
         i < countCandidates.size() &&
         i < 12;
         ++i)
    {
        std::cout
            << "#"
            << i
            << " off=+"
            << HexU64(
                countCandidates[i].offset
            )
            << " deltaOne="
            << countCandidates[i].deltaOne
            << " other="
            << countCandidates[i].otherChanges
            << " score="
            << countCandidates[i].score
            << "\\n";
    }

    if (countCandidates.empty() ||
        countCandidates[0].score <= 0)
    {
        return false;
    }

    if (countCandidates.size() > 1 &&
        countCandidates[0].score ==
            countCandidates[1].score)
    {
        return false;
    }

    uintptr_t countOffset =
        countCandidates[0].offset;

    struct IdCandidate
    {
        uintptr_t offset = 0;
        size_t nonZero = 0;
        size_t distinct = 0;
        int score = 0;
    };

    std::vector<IdCandidate>
        ids;

    const intptr_t deltas[] =
    {
        -8,
        -6,
        -4,
        -2,
        2,
        4,
        6,
        8
    };

    for (intptr_t delta :
         deltas)
    {
        intptr_t signedOff =
            static_cast<intptr_t>(
                countOffset) +
            delta;

        if (signedOff < 0x10 ||
            signedOff + 2 >
                0xA0)
        {
            continue;
        }

        uintptr_t off =
            static_cast<uintptr_t>(
                signedOff
            );

        std::set<uint16_t>
            values;

        size_t nonZero = 0;

        for (const auto& snap :
             before)
        {
            uint16_t value = 0;

            std::memcpy(
                &value,
                snap.bytes.data() + off,
                sizeof(value)
            );

            if (value)
            {
                ++nonZero;
                values.insert(
                    value
                );
            }
        }

        if (nonZero * 100 <
                before.size() * 80 ||
            values.empty())
        {
            continue;
        }

        IdCandidate c{};
        c.offset = off;
        c.nonZero = nonZero;
        c.distinct = values.size();

        c.score =
            static_cast<int>(
                nonZero * 20 +
                values.size() * 12
            );

        if (delta == -4)
            c.score += 120;

        if ((off & 1) == 0)
            c.score += 10;

        ids.push_back(
            c
        );
    }

    std::sort(
        ids.begin(),
        ids.end(),
        [](
            const IdCandidate& a,
            const IdCandidate& b)
        {
            if (a.score !=
                b.score)
            {
                return
                    a.score >
                    b.score;
            }

            return
                a.offset <
                b.offset;
        }
    );

    std::cout
        << "\\n[ITEM ID NEIGHBOR CANDIDATES]\\n";

    for (size_t i = 0;
         i < ids.size() &&
         i < 8;
         ++i)
    {
        std::cout
            << "#"
            << i
            << " off=+"
            << HexU64(
                ids[i].offset
            )
            << " nonZero="
            << ids[i].nonZero
            << " distinct="
            << ids[i].distinct
            << " score="
            << ids[i].score
            << "\\n";
    }

    if (ids.empty())
        return false;

    if (ids.size() > 1 &&
        ids[0].score ==
            ids[1].score)
    {
        return false;
    }

    profile.itemCountOffset =
        countOffset;

    profile.itemIdOffset =
        ids[0].offset;

    profile.itemLayoutStatus =
        "confirmed_runtime_stack_transition_id_neighbor";

    std::cout
        << "\\n[ITEM LAYOUT CONFIRMED]\\n"
        << "Item ID offset       : +"
        << HexU64(
            profile.itemIdOffset
        )
        << "\\n"
        << "Count/Subtype offset : +"
        << HexU64(
            profile.itemCountOffset
        )
        << "\\n"
        << "Evidence             : exact +/-1 stack transition + structural neighbor\\n";

    return true;
}


bool EnsureBuildMigratorDataCompletion(
    DbProfile& profile,
    std::vector<DbProfile>& database,
    int profileIndex,
    const std::string& databasePath)
{
    std::cout
        << "\n============================================================\n"
        << "       BUILDMIGRATOR V4.7 NORMAL - NPC / ITEM / CONTAINERS\n"
        << "============================================================\n"
        << "[MODE] READ-ONLY\n"
        << "[NO CALL] nenhuma funcao interna sera chamada\n";

    // V4.6 migration safety:
    // The old all-to-all relocated Item pairing could produce a false Count/ID
    // confirmation.  Never consume that legacy status as authoritative.
    if (
        profile.itemLayoutStatus ==
            "confirmed_runtime_exact_visible_count_and_structural_id"
    )
    {
        std::cout
            << "[ITEM MIGRATION] Legacy all-to-all Count/ID confirmation invalidated; "
            << "recalibrating with container-slot provenance.\n";

        profile.itemIdOffset = 0;
        profile.itemCountOffset = 0;
        profile.itemCountWidth = 0;
        profile.itemLayoutStatus =
            "pending_container_slot_provenance";
    }

    uintptr_t localPlayer =
        WaitForDiscoveryLocalPlayer(
            profile,
            "BUILDMIGRATOR V4.6.1 - FINAL DATA"
        );

    if (!localPlayer)
        return false;

    if (!WaitForTileWorldReady(
            profile,
            localPlayer))
    {
        return false;
    }

    if (profile.npcStatus.find(
            "confirmed_") != 0)
    {
        if (!BMDiscoverNpcFromCurrentWorld(
                profile,
                localPlayer,
                true))
        {
            std::cout
                << "\n[NPC] Nenhum NPC semanticamente unico esta visivel agora.\n";

            if (AskYesNo(
                    "Ir para perto de um NPC visivel e tentar agora? [S/N]: "))
            {
                WaitEnter(
                    "Com o NPC visivel e voce parado, pressione ENTER..."
                );

                WaitForTileWorldReady(
                    profile,
                    localPlayer
                );

                if (!BMDiscoverNpcFromCurrentWorld(
                        profile,
                        localPlayer,
                        true))
                {
                    profile.npcStatus =
                        "pending_npc_not_uniquely_visible";
                }
            }
            else
            {
                profile.npcStatus =
                    "pending_user_skipped_npc";
            }
        }
    }

    if (!BMDiscoverInventory(
            profile,
            localPlayer))
    {
        std::cout
            << "\n[INVENTORY] Ainda nao ficou unico.\n";

        if (AskYesNo(
                "Deixar Backpack/equipamentos ocupando pelo menos 2 slots e tentar novamente? [S/N]: "))
        {
            WaitEnter(
                "Depois de ajustar os equipamentos, pressione ENTER..."
            );

            if (!BMDiscoverInventory(
                    profile,
                    localPlayer))
            {
                profile.inventoryStatus =
                    "pending_inventory_ambiguous";
            }
        }
        else
        {
            profile.inventoryStatus =
                "pending_user_skipped_inventory";
        }
    }

    const bool countConfirmedByContainerSlot =
        profile.itemLayoutStatus.find(
            "partial_count_confirmed_container_slot") == 0;

    if (
        profile.itemLayoutStatus.find(
            "confirmed_") != 0 &&
        !countConfirmedByContainerSlot
    )
    {
        if (!BMValidateReferenceItemLayout(
                profile,
                localPlayer))
        {
            profile.itemLayoutStatus =
                "candidate_reference_offsets_need_container_crosscheck";
        }
    }

    if (
        profile.containersStatus !=
            "confirmed_runtime_open_container_tree_and_items" &&
        profile.containersStatus !=
            "confirmed_runtime_container_owner_and_layout"
    )
    {
        if (!BMDiscoverContainers(
                profile,
                localPlayer))
        {
            std::cout
                << "\n[CONTAINER] Layout legado nao validou nesta build.\n";

            if (!profile.gameContainersOffset)
            {
                if (AskYesNo(
                        "Executar reconhecimento RTTI por transicao fechar/abrir Backpack? [S/N]: "))
                {
                    if (!V36ContainerTransitionRecon(
                            profile))
                    {
                        profile.containersStatus =
                            "pending_container_rtti_transition_no_object";
                    }
                }
                else
                {
                    profile.containersStatus =
                        "pending_user_skipped_containers";
                }
            }

            if (
                profile.gameContainersOffset &&
                profile.containersStatus !=
                    "confirmed_runtime_container_owner_and_layout"
            )
            {
                std::cout
                    << "\n[CONTAINER] Owner conhecido. Tentando aprender tree/deque semanticamente...\n";

                if (!V38DiscoverSemanticContainerLayout(
                        profile))
                {
                    profile.containersStatus =
                        "candidate_container_owner_confirmed_layout_pending";
                }
            }
        }
    }

    if (
        profile.itemLayoutStatus.find(
            "confirmed_") != 0 &&
        profile.inventoryStatus.find(
            "confirmed_") == 0)
    {
        if (!V39DiscoverItemLayoutGuided(
                profile,
                localPlayer))
        {
            std::cout
                << "[ITEM] Layout ID/Count continua pending; nenhum offset foi adivinhado.\n";
        }
    }

    if (profileIndex >= 0 &&
        profileIndex <
            static_cast<int>(
                database.size()))
    {
        database[
            static_cast<size_t>(
                profileIndex)
        ] = profile;

        SaveProfileDatabase(
            databasePath,
            database
        );
    }

    std::cout
        << "\n[DATA COMPLETION]\n"
        << "NPC        : "
        << profile.npcStatus
        << "\n"
        << "Inventory  : "
        << profile.inventoryStatus
        << "\n"
        << "Item       : "
        << profile.itemLayoutStatus
        << "\n"
        << "Containers : "
        << profile.containersStatus
        << "\n";

    return true;
}


// ============================================================
// BUILDMIGRATOR V4.6.1 - STATIC FUNCTION SIGNATURES
// Current exact OpenGL build captures reference signatures.
// Other builds search those signatures in .text.
// Strict read-only.
// ============================================================

std::string BMMakeMaskedSignature(
    uintptr_t address,
    size_t length)
{
    if (!address ||
        address < g_textBegin ||
        address + length > g_textEnd)
    {
        return {};
    }

    std::vector<uint8_t>
        bytes(
            length
        );

    std::memcpy(
        bytes.data(),
        reinterpret_cast<const void*>(
            address),
        length
    );

    std::vector<uint8_t>
        literal(
            length,
            1
        );

    for (size_t i = 0;
         i < length;
         ++i)
    {
        uint8_t op =
            bytes[i];

        if ((op == 0xE8 ||
             op == 0xE9) &&
            i + 4 < length)
        {
            for (size_t j = 1;
                 j <= 4;
                 ++j)
            {
                literal[
                    i + j
                ] = 0;
            }

            i += 4;
            continue;
        }

        if (op == 0x0F &&
            i + 5 < length &&
            bytes[i + 1] >= 0x80 &&
            bytes[i + 1] <= 0x8F)
        {
            for (size_t j = 2;
                 j <= 5;
                 ++j)
            {
                literal[
                    i + j
                ] = 0;
            }

            i += 5;
            continue;
        }

        if (op >= 0x40 &&
            op <= 0x4F &&
            i + 2 < length)
        {
            uint8_t opcode =
                bytes[
                    i + 1
                ];

            if ((opcode == 0x8B ||
                 opcode == 0x8D ||
                 opcode == 0x89 ||
                 opcode == 0x39 ||
                 opcode == 0x3B) &&
                i + 6 < length)
            {
                uint8_t modrm =
                    bytes[
                        i + 2
                    ];

                if ((modrm & 0xC7) ==
                    0x05)
                {
                    for (size_t j = 3;
                         j <= 6;
                         ++j)
                    {
                        literal[
                            i + j
                        ] = 0;
                    }
                }
            }

            if (opcode >= 0xB8 &&
                opcode <= 0xBF &&
                i + 9 < length)
            {
                for (size_t j = 2;
                     j <= 9;
                     ++j)
                {
                    literal[
                        i + j
                    ] = 0;
                }
            }
        }
        else if ((op == 0x8B ||
                  op == 0x8D ||
                  op == 0x89 ||
                  op == 0x39 ||
                  op == 0x3B) &&
                 i + 5 < length)
        {
            uint8_t modrm =
                bytes[
                    i + 1
                ];

            if ((modrm & 0xC7) ==
                0x05)
            {
                for (size_t j = 2;
                     j <= 5;
                     ++j)
                {
                    literal[
                        i + j
                    ] = 0;
                }
            }
        }
    }

    std::ostringstream out;

    out
        << std::uppercase
        << std::hex
        << std::setfill('0');

    for (size_t i = 0;
         i < length;
         ++i)
    {
        if (i)
            out << ' ';

        if (!literal[i])
        {
            out << "??";
        }
        else
        {
            out
                << std::setw(2)
                << static_cast<unsigned>(
                    bytes[i]
                );
        }
    }

    return out.str();
}

bool BMParseSignature(
    const std::string& text,
    std::vector<int>& pattern)
{
    pattern.clear();

    std::istringstream in(
        text
    );

    std::string token;

    while (in >> token)
    {
        if (token == "??")
        {
            pattern.push_back(
                -1
            );

            continue;
        }

        if (token.size() != 2)
            return false;

        unsigned value = 0;

        std::istringstream hex(
            token
        );

        hex
            >> std::hex
            >> value;

        if (!hex)
            return false;

        pattern.push_back(
            static_cast<int>(
                value & 0xFF
            )
        );
    }

    return
        pattern.size() >= 24;
}

uintptr_t BMScanUniqueSignature(
    const std::string& signature,
    size_t* outMatches)
{
    if (outMatches)
        *outMatches = 0;

    std::vector<int>
        pattern;

    if (!BMParseSignature(
            signature,
            pattern))
    {
        return 0;
    }

    size_t textSize =
        static_cast<size_t>(
            g_textEnd -
            g_textBegin
        );

    if (textSize <
        pattern.size())
    {
        return 0;
    }

    std::vector<uint8_t>
        textBytes(
            textSize
        );

    std::memcpy(
        textBytes.data(),
        reinterpret_cast<const void*>(
            g_textBegin),
        textSize
    );

    size_t bestRunStart = 0;
    size_t bestRunLength = 0;

    size_t currentStart = 0;
    size_t currentLength = 0;

    for (size_t i = 0;
         i < pattern.size();
         ++i)
    {
        if (pattern[i] >= 0)
        {
            if (!currentLength)
                currentStart = i;

            ++currentLength;

            if (currentLength >
                bestRunLength)
            {
                bestRunLength =
                    currentLength;

                bestRunStart =
                    currentStart;
            }
        }
        else
        {
            currentLength = 0;
        }
    }

    if (bestRunLength < 6)
        return 0;

    std::vector<uint8_t>
        anchor;

    anchor.reserve(
        bestRunLength
    );

    for (size_t i = 0;
         i < bestRunLength;
         ++i)
    {
        anchor.push_back(
            static_cast<uint8_t>(
                pattern[
                    bestRunStart +
                    i
                ]
            )
        );
    }

    size_t matches = 0;
    uintptr_t unique = 0;

    auto it =
        textBytes.begin();

    while (it !=
           textBytes.end())
    {
        it =
            std::search(
                it,
                textBytes.end(),
                anchor.begin(),
                anchor.end()
            );

        if (it ==
            textBytes.end())
        {
            break;
        }

        size_t anchorPos =
            static_cast<size_t>(
                it -
                textBytes.begin()
            );

        if (anchorPos >=
            bestRunStart)
        {
            size_t start =
                anchorPos -
                bestRunStart;

            if (start +
                    pattern.size() <=
                textBytes.size())
            {
                bool ok = true;

                for (size_t j = 0;
                     j < pattern.size();
                     ++j)
                {
                    if (pattern[j] >= 0 &&
                        textBytes[
                            start + j
                        ] !=
                            static_cast<uint8_t>(
                                pattern[j]))
                    {
                        ok = false;
                        break;
                    }
                }

                if (ok)
                {
                    ++matches;

                    unique =
                        g_textBegin +
                        start;

                    if (matches > 1)
                    {
                        if (outMatches)
                            *outMatches =
                                matches;

                        return 0;
                    }
                }
            }
        }

        ++it;
    }

    if (outMatches)
        *outMatches =
            matches;

    return
        matches == 1
            ? unique
            : 0;
}

