    W("mapTilePathChildOffset", p.mapTilePathChildOffset); W("mapTilePathHeaderOffset", p.mapTilePathHeaderOffset);
    W("mapTileStorageStride", p.mapTileStorageStride); WS("mapTileStorageMode", p.mapTileStorageMode); WS("mapTilePathStatus", p.mapTilePathStatus);
